window.DEATHS_DATA = [{"id":"20261114-richard-sterban","date":"2026-11-14","name":"理查·斯特班","nameOrig":"Richard Sterban","country":"美国","age":83,"fields":["文艺"],"identity":"乡村歌手 · 橡树岭男孩合唱团男低音","summary":"那句低到地板里的「oom-pah-pah-oom-pah-pah」，让一首歌在电台里唱了四十多年。","bio":"斯特班是美国乡村音乐组合「橡树岭男孩」（The Oak Ridge Boys）的男低音。这个组合从南方福音音乐起家，在 1970 年代末转向乡村流行，1981 年的《Elvira》成为他们最成功的单曲——副歌那串极低沉的拟声吟唱正是斯特班的声音，也是流行音乐史上最容易被人模仿的一段贝斯人声。他在这个位置上站了近六十年，直到生命最后阶段。","facts":["「橡树岭男孩」男低音歌手，参与录制乐队多张乡村榜冠军专辑","《Elvira》中标志性的低音段落由他演唱，成为该曲的记忆点","死因为支气管炎与肺炎并发症","乐队与他本人均于 2015 年前后入选乡村音乐名人堂体系相关荣誉"],"obit":null,"portrait":"assets/portraits/20261114-richard-sterban.webp","source":"维基百科 2026 年 11 月逝世人物列表 / ABC7 New York","region":"","verified":"demo","causeOfDeath":"癌症","wikipedia":"https://en.wikipedia.org/wiki/Richard_Sterban"},{"id":"20261114-giri-babu","date":"2026-11-14","name":"吉里·巴布","nameOrig":"Giri Babu","country":"印度","age":83,"fields":["影视"],"identity":"泰卢固语电影演员 · 制片人 · 导演","summary":"南印度银幕上从不缺席的那张脸，演了半个世纪，也拍过、导过。","bio":"吉里·巴布是泰卢固语电影（托莱坞）的资深演员，长期活跃于南印度电影工业，出演大量影片，同时兼做制片与导演工作。在印度多语种电影版图里，这类跨幕前幕后的老兵构成了产业真正的底座：观众未必记得名字，但认得那张脸。","facts":["泰卢固语电影资深演员，出演数量众多的南印度影片","兼任制片人与导演","晚年仍出现在银幕上"],"obit":null,"portrait":"assets/portraits/20261114-giri-babu.webp","source":"维基百科 2026 年 11 月逝世人物列表","region":"","verified":"demo","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Giri_Babu"},{"id":"20261113-masaaki-yamazaki","date":"2026-11-13","name":"山崎正昭","nameOrig":"山崎 正昭 / Masaaki Yamazaki","country":"日本","age":84,"fields":["军政"],"identity":"日本自民党参议员 · 第30代参议院议长","summary":"从福井县大野市的市议员一路走到参议院议长席，最后倒在任上。","bio":"山崎正昭 1942 年生于福井县大野市，日本大学法学部毕业后从地方政治起步，1975 年当选大野市议员，1979 年进入福井县议会并历任副议长、议长。1992 年首次当选参议员，此后连续六届连任。小泉纯一郎执政期间，他于 2003 至 2005 年担任内阁官房副长官；2013 至 2016 年出任参议院议长。去世时他仍是现任参议员，也是在职最年长的一位。","facts":["1942 年生于福井县大野市，日本大学法学部毕业","1992 年首度当选参议员，连续当选 6 届","2003—2005 年任小泉内阁官房副长官","2013—2016 年任参议院议长（第30代）","去世时为在职最年长参议员；福井选区补选定于 2027 年 4 月 25 日举行"],"obit":null,"portrait":"assets/portraits/20261113-masaaki-yamazaki.webp","source":"中央社 / 日本经济新闻 / 朝日新闻","region":"","verified":"demo","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Masaaki_Yamazaki"},{"id":"20261113-kevin-murray","date":"2026-11-13","name":"凯文·默里","nameOrig":"Kevin Murray","country":"美国","age":66,"fields":["军政"],"identity":"前加利福尼亚州州参议员","summary":"他留下的不是演讲，是洛杉矶人能走进去的那片山。","bio":"凯文·默里曾任加利福尼亚州州参议员，代表洛杉矶地区。他的政绩集中在城市公共空间与弱势者服务上：推动太阳能发展、促成鲍德温山（Baldwin Hills）大片土地的保护——如今那里是洛杉矶人看全景的徒步去处，也长期为无家可归者争取服务资源。","facts":["曾任加州州参议员，代表洛杉矶地区","推动太阳能政策与鲍德温山土地保护","长期关注无家可归者服务"],"obit":null,"portrait":null,"source":"洛杉矶时报","region":"","verified":"demo","portraitStatus":"no-source","causeOfDeath":null},{"id":"20261112-jean-puech","date":"2026-11-12","name":"让·布埃什","nameOrig":"Jean Puech","country":"法国","age":84,"fields":["军政"],"identity":"法国前农业部长 · 前公务员事务部长","summary":"第五共和国换了几任总理，他在内阁里一直管着土地和公职人员。","bio":"让·布埃什是法国中右翼政治人物，长期担任参议员，并数度入阁，出任农业部长与公务员事务部长。在法国的政治结构里，这类从地方选区起家、又在中央部委掌过实权的角色，往往是农业政策与地方利益之间真正的连接点。","facts":["曾任法国农业部长","曾任公务员事务部长","长期担任参议员"],"obit":null,"portrait":null,"source":"维基百科 2026 年 11 月逝世人物列表","region":"","verified":"demo","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Jean_Puech"},{"id":"20261112-hwang-jung-lee","date":"2026-11-12","name":"黄正利","nameOrig":"황정리 / Hwang Jang Lee","country":"韩国","age":81,"fields":["影视"],"identity":"武打演员 · 跆拳道黑带九段 · 「一代腿王」","summary":"他没演过几个好人，却用一双腿改写了港式功夫片的动作美学。","bio":"黄正利 1944 年 12 月 13 日生于日本大阪，战后随家人回到韩国，14 岁开始练跆拳道。1970 年代他应吴思远之邀赴港拍片，从《南拳北腿》的反派「银狐」起家。1978 年，他在袁和平执导、成龙主演的《蛇形刁手》里演鹰爪门掌门上官逸云，在《醉拳》里演阎铁心——此前的港式武打以「拳法」为主流，是他把高踢、旋踢、连环穿心腿带进银幕，被影迷封为「腿王」。拍摄《蛇形刁手》时他曾一脚踢掉成龙一颗门牙，此事他晚年亲口证实。2003 年他取得跆拳道黑带九段。","facts":["代表作：《南拳北腿》《蛇形刁手》《醉拳》《鹰爪铁布衫》《死亡塔》","与谭道良、刘忠良、卡萨伐并称「四大腿王」，公认为腿法成就最高者","《蛇形刁手》中的长发白袍造型，是《龙珠》角色「桃白白」的原型","2003 年获跆拳道黑带九段认证","11 月 12 日上午在首尔家中摔倒送医，于江南圣母医院离世，15 日出殡"],"obit":null,"portrait":"assets/portraits/20261112-hwang-jung-lee.webp","source":"澎湃新闻 / 光明网 / 韩联社 / 星岛头条","region":"","verified":"demo","causeOfDeath":null,"wikipedia":null},{"id":"20261112-dan-hicks","date":"2026-11-12","name":"丹·希克斯","nameOrig":"Dan Hicks","country":"美国","age":64,"fields":["体育"],"identity":"NBC 体育解说 · 高尔夫与奥运「声音」","summary":"美国人听高尔夫、听奥运、听圣母大学橄榄球，耳朵里都是他。","bio":"丹·希克斯是 NBC 体育的标志性解说员，长期担任高尔夫、奥运会与圣母大学橄榄球赛事的现场主播，被视为这几个项目的「官方声音」。他与 ESPN 主播汉娜·斯托姆（Hannah Storm）结婚 32 年，离世消息由妻子在社交平台发布，属突然去世。","facts":["NBC 体育高尔夫、奥运会、圣母大学橄榄球首席解说之一","与 ESPN 主播汉娜·斯托姆结婚 32 年","死讯由其妻子在社交媒体公布"],"obit":null,"portrait":"assets/portraits/20261112-dan-hicks.webp","source":"洛杉矶时报 / NBC Sports","region":"","verified":"demo","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Dan_Hicks_(singer)"},{"id":"20261111-richard-posner","date":"2026-11-11","name":"理查德·波斯纳","nameOrig":"Richard A. Posner","country":"美国","age":87,"fields":["社科"],"identity":"联邦第七巡回上诉法院法官 · 法律经济学奠基人","summary":"他把经济学搬进法庭，让法官开始问「后果是什么」，而不只是「词语是什么意思」。","bio":"波斯纳 1939 年 1 月 11 日生于纽约，1959 年毕业于耶鲁，1962 年毕业于哈佛法学院，1969 年起任教于芝加哥大学法学院。1973 年出版的《法律的经济分析》开创了法律经济学这一领域。1981 年由里根总统任命为联邦第七巡回上诉法院法官，任职 36 年（1993—2000 年任首席法官），写下约 3300 份司法意见，2017 年退休。2000 年一项引证研究将他列为 20 世纪被引用最多的法学家。他一生出版近 60 部著作，晚年被披露罹患阿尔茨海默病。","facts":["1939.1.11—2026.11.10，享年 87 岁，芝加哥大学法学院于 11 月 11 日公布消息","《法律的经济分析》（1973）奠定法律经济学学科","1981—2017 年任联邦第七巡回上诉法院法官，其中 1993—2000 年任首席法官","写下约 3300 份司法意见，著书近 60 部","被公认为 20 世纪被引用最多的法律学者","生前最后几年为无律师代理的当事人提供免费上诉服务"],"obit":null,"portrait":"assets/portraits/20261111-richard-posner.webp","source":"华盛顿邮报 / 华尔街日报 / 芝加哥大学法学院 / 澎湃新闻","region":"","verified":"demo","causeOfDeath":null,"wikipedia":null},{"id":"20261111-regina-torne","date":"2026-11-11","name":"雷吉纳·托尔内","nameOrig":"Regina Torné","country":"墨西哥","age":82,"fields":["影视"],"identity":"演员 · 电视情节剧","summary":"拉美电视情节剧里那种把命运喊出来的母亲，多半有她的影子。","bio":"雷吉纳·托尔内是墨西哥演员，以电视剧与舞台剧见长，长期活跃于西语世界的情节剧（telenovela）体系中。这一类型在拉美是最具群众基础的大众叙事形式，她属于其中被观众记住的那一批表演者。","facts":["墨西哥电视与舞台演员","长期出演西语情节剧（telenovela）"],"obit":null,"portrait":"assets/portraits/20261111-regina-torne.webp","source":"维基百科 2026 年 11 月逝世人物列表","region":"","verified":"demo","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Regina_Torn%C3%A9"},{"id":"20261111-ni-runfeng","date":"2026-11-11","name":"倪润峰","nameOrig":"Ni Runfeng","country":"中国","age":82,"fields":["商业"],"identity":"长虹集团原党委书记 · 董事局主席 ·「中国彩电大王」","summary":"他让中国老百姓提前十年看上大彩电，也让国产家电第一次赢下了价格战。","bio":"倪润峰 1944 年 2 月生于山东荣成，1984 年起历任国营长虹机器厂副厂长、厂长，后任长虹公司总经理、董事长、党委书记。他把军工技术、工艺与质量控制手段移植到民品研发上，完成了从单一军品生产到军民品结合的战略转移，让长虹成为「中国彩电大王」。1990 年代他主导了中国家电业第一次价格战，1994 年长虹在上交所上市，成为沪市第一蓝筹股。到他离任时，长虹净资产从 1.2 亿元增至 117.32 亿元，增长 97 倍。","facts":["1944 年 2 月生，山东荣成人，中共党员","1985 年起任国营长虹机器厂厂长，带领企业走通「军转民」道路","1994 年 3 月长虹在上交所挂牌，成为沪市第一蓝筹股","任主要负责人近 20 年，长虹累计产销彩电近 8000 万台，净资产由 1.2 亿元增至 117.32 亿元","2018 年 12 月获「改革先锋」称号；第十五届中央候补委员、第十届全国政协常委","2026 年 11 月 11 日 15 时 55 分于绵阳市中心医院逝世"],"obit":null,"portrait":"assets/portraits/20261111-ni-runfeng.webp","source":"长虹控股集团官网 / 四川日报 / 新华社 / 上海证券报","region":"","verified":"demo","causeOfDeath":null,"wikipedia":null},{"id":"20261111-li-shuangyuan","date":"2026-11-11","name":"李双元","nameOrig":"Li Shuangyuan","country":"中国","age":99,"fields":["社科"],"identity":"国际私法学家 · 法学教授","summary":"中国国际私法从教科书到立法，都绕不过他的名字。","bio":"李双元是中国国际私法学的代表性学者，长期从事国际私法、比较民商法的教学与研究，其教材与理论体系影响了几代中国法科学生，也参与了中国涉外民事关系法律适用立法的学术准备。他享年 99 岁，几乎跨越了中国法学重建的整个周期。","facts":["中国国际私法学界重要学者，长期从事教学与研究","著述与教材影响数代法学学生","享年 99 岁，为本期记录中最年长者"],"obit":null,"portrait":"assets/portraits/20261111-li-shuangyuan.webp","source":"维基百科 2026 年 11 月逝世人物列表","region":"","verified":"demo","causeOfDeath":null,"wikipedia":null},{"id":"20261111-irma-p-hall","date":"2026-11-11","name":"厄玛·P·霍尔","nameOrig":"Irma P. Hall","country":"美国","age":91,"fields":["影视"],"identity":"演员 ·《灵魂食物》《老妇杀手》","summary":"她当了半辈子老师，六十岁以后才成为美国电影里最难忘的那位老太太。","bio":"厄玛·P·霍尔在成为职业演员之前是一名教师，长期在芝加哥的戏剧舞台工作。1997 年她在《灵魂食物》（Soul Food）中饰演家族的母亲，2004 年在科恩兄弟的《老妇杀手》（The Ladykillers）中与汤姆·汉克斯对戏，凭此片获得广泛赞誉。她常在六十岁之后才被主流电影工业看见，却几乎每一场戏都把片子往下钉牢一寸。","facts":["代表作：《灵魂食物》（1997）、《老妇杀手》（2004）","早年职业为教师，长年在芝加哥剧场演出","以配角身份成为美国独立电影与黑人题材影片中的重要面孔"],"obit":null,"portrait":"assets/portraits/20261111-irma-p-hall.webp","source":"洛杉矶时报 / ABC7 New York","region":"","verified":"demo","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Irma_P._Hall"},{"id":"20261111-eljko-matu","date":"2026-11-11","name":"热利科·马图什","nameOrig":"Željko Matuš","country":"克罗地亚","age":91,"fields":["体育"],"identity":"足球运动员 · 1960 年罗马奥运金牌成员","summary":"他踢球，也看牙；一枚奥运金牌，和一间诊所，构成了他的一生。","bio":"马图什是南斯拉夫与克罗地亚足球运动员，长期效力于萨格勒布迪纳摩，1960 年随意大利罗马奥运会男足金牌队夺冠——那是南斯拉夫足球黄金一代的高点。退役后他成为牙医。死讯由其家属对外发布。","facts":["1960 年罗马奥运会男子足球金牌成员","长期效力于萨格勒布迪纳摩","退役后从事牙医职业"],"obit":null,"portrait":null,"source":"维基百科 2026 年 11 月逝世人物列表","region":"","verified":"demo","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/%C5%BDeljko_Matu%C5%A1"},{"id":"20261111-anthony-clark","date":"2026-11-11","name":"安东尼·克拉克","nameOrig":"Anthony Clark","country":"美国","age":62,"fields":["影视"],"identity":"喜剧演员 · 情景喜剧《Yes, Dear》主演","summary":"在情景喜剧最热闹的那些年，他是那个把尴尬演得让人心软的人。","bio":"安东尼·克拉克是美国单口喜剧演员与电视剧演员，主演 CBS 情景喜剧《Yes, Dear》（2000—2006），此前出演《Boston Common》。他的表演带着单口喜剧出身的节奏感，擅长把家庭生活里的小摩擦演成笑话。","facts":["主演 CBS 情景喜剧《Yes, Dear》（2000—2006）","出演《Boston Common》等剧集","出身单口喜剧舞台"],"obit":null,"portrait":"assets/portraits/20261111-anthony-clark.webp","source":"洛杉矶时报 / ABC7 New York","region":"","verified":"demo","causeOfDeath":null,"wikipedia":null},{"id":"20261111-","date":"2026-11-11","name":"亚历山大·达尔奇耶夫","nameOrig":"Александр Дарчиев","country":"俄罗斯","age":66,"fields":["军政"],"identity":"俄罗斯外交官 · 驻美国大使","summary":"他递交国书的那一年，两国关系正处在最难解释的时刻。","bio":"达尔奇耶夫是俄罗斯职业外交官，曾任俄罗斯驻加拿大大使，后出任俄罗斯驻美国大使。俄罗斯外交部于 11 月 11 日公布其去世消息。在俄美关系持续紧张的背景下，大使这一职位本身即是一根随时会绷断的线。","facts":["曾任俄罗斯驻加拿大大使","去世时担任俄罗斯驻美国大使","死讯由俄罗斯外交部公布"],"obit":null,"portrait":"assets/portraits/20261111-.webp","source":"洛杉矶时报 / 俄罗斯外交部","region":"","verified":"demo","causeOfDeath":null,"wikipedia":null},{"id":"20261110-steve-harvey-columnist","date":"2026-11-10","name":"史蒂夫·哈维","nameOrig":"Steve Harvey (columnist)","country":"美国","age":80,"fields":["文艺"],"identity":"《洛杉矶时报》专栏作家 ·「Only in L.A.」","summary":"他写了四十年洛杉矶的怪事，证明一座城市最真实的部分总是荒诞的。","bio":"这位史蒂夫·哈维与同名的喜剧演员并非一人。他是《洛杉矶时报》的专栏作家，以「Only in L.A.」专栏闻名，几十年里记录这座城市的奇人异事、荒唐新闻与街头细节——一种介于新闻与都市传说之间的文体，也是洛杉矶自我认知的一部分。","facts":["《洛杉矶时报》「Only in L.A.」专栏作家","长期记录洛杉矶的城市奇闻与街头生活","与同名喜剧演员 Steve Harvey 为不同人物"],"obit":null,"portrait":null,"source":"洛杉矶时报","region":"","verified":"demo","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":null},{"id":"20261110-stacey-keach","date":"2026-11-10","name":"斯泰西·基奇","nameOrig":"Stacy Keach","country":"美国","age":85,"fields":["影视"],"identity":"演员 ·《越狱》典狱长 ·《麦克·哈默》","summary":"中国观众记得他，是狐狸河监狱那间办公室里，一个用牙签搭泰姬陵的典狱长。","bio":"基奇是美国舞台与银幕双栖演员，以硬汉与侦探角色闻名，1984 至 1987 年主演电视剧《麦克·哈默》（Mike Hammer）。对全球观众而言，他更广为人知的形象是《越狱》（Prison Break）里的典狱长亨利·波普——在一个靠暴力和等级运转的监狱里，他是唯一还愿意相信人可以改造的人。他 2017 年曾在芝加哥古德曼剧院舞台上演出独角戏时突发心脏病；晚年长期与严重心脏病和心力衰竭抗争。他在波兰家中离世，妻子玛尔戈西亚发布讣告，称他「战斗了很久」。","facts":["电视剧《麦克·哈默》（1984—1987）主演","《越狱》中饰典狱长亨利·波普（2005 年起）","百老汇与地区剧院常客，以独角戏与莎士比亚角色著称","2017 年在舞台演出中突发心脏病，晚年与心力衰竭长期抗争","于波兰家中离世，葬礼细节未公开"],"obit":null,"portrait":"assets/portraits/20261110-stacey-keach.webp","source":"中国新闻周刊 / 美联社 / ABC7 New York","region":"","verified":"demo","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Stacy_Keach"},{"id":"20261110-fr-d-ric-boilet","date":"2026-11-10","name":"弗雷德里克·博瓦莱","nameOrig":"Frédéric Boilet","country":"法国","age":66,"fields":["文艺"],"identity":"漫画家 ·「新漫画」运动发起人","summary":"他想让漫画不再只是给孩子的冒险，而是成年人自己的日子。","bio":"博瓦莱 1960 年生于法国，1990 年代移居日本，是日欧漫画交流中最关键的桥梁人物之一。2001 年他发起「新漫画」（Nouvelle Manga）宣言，主张漫画应当描写成年人的日常生活与情感，而不是只服务于类型冒险。他的作品以自传体、纪实的笔触处理亲密关系与异乡生活。","facts":["1960 年生于法国，后长期定居日本","2001 年发起「新漫画」（Nouvelle Manga）宣言","作品以自传体与生活纪实笔法书写亲密关系与异乡经验","日欧漫画交流的重要推动者"],"obit":null,"portrait":"assets/portraits/20261110-fr-d-ric-boilet.webp","source":"维基百科 2026 年 11 月逝世人物列表","region":"","verified":"demo","causeOfDeath":null,"wikipedia":null},{"id":"20261110-bunker-roy","date":"2026-11-10","name":"邦克·罗伊","nameOrig":"Bunker Roy","country":"印度","age":81,"fields":["军政"],"identity":"社会运动家 · 赤脚大学创始人","summary":"他相信文盲的农村妇女能成为太阳能工程师，然后用五十年证明这件事。","bio":"邦克·罗伊 1972 年在拉贾斯坦邦的蒂洛尼亚（Tilonia）创办赤脚大学（Barefoot College），把农村的文盲女性、尤其是祖母辈的妇女训练成太阳能工程师、水泵技师与助产士，再让她们回到自己的村庄供电、供水。这套「不靠文凭靠能力」的模式后来被数十个国家复制，他也因此被《时代》周刊列入 2010 年全球百大影响力人物。","facts":["1972 年创办赤脚大学（Barefoot College），位于拉贾斯坦邦蒂洛尼亚","主张以技能而非学历认证农村女性，培训其成为太阳能工程师与技师","模式被多国引入；2010 年入选《时代》全球百大影响力人物"],"obit":null,"portrait":"assets/portraits/20261110-bunker-roy.webp","source":"维基百科 2026 年 11 月逝世人物列表 / Barefoot College","region":"","verified":"demo","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Bunker_Roy"},{"id":"20261109-arpita-singh","date":"2026-11-09","name":"阿尔皮塔·辛格","nameOrig":"Arpita Singh","country":"印度","age":89,"fields":["文艺"],"identity":"当代画家","summary":"她把女性的日常、迁徙与暴力画进同一张画布，然后让它们安静地互相挤压。","bio":"阿尔皮塔·辛格 1937 年生于英属印度孟加拉地区，长期在德里生活与创作，是印度当代绘画最重要的代表人物之一。她的画面常把女性日常物件、家庭场景与政治暴力并置——床、枪、花、火车、人群堆在同一个平面里，用一种近乎刺绣般的细密笔触处理创伤。","facts":["1937 年生于孟加拉地区，长期在德里创作","印度当代绘画代表人物之一","作品常将女性日常、家庭场景与政治暴力并置","以细密、近乎织物的笔触著称"],"obit":null,"portrait":"assets/portraits/20261109-arpita-singh.webp","source":"维基百科 2026 年 11 月逝世人物列表","region":"","verified":"demo","causeOfDeath":null,"wikipedia":null},{"id":"2026-11-05-207","date":"2026-11-05","name":"马昌钰","nameOrig":"","country":"中国","region":"中国大陆","age":82,"fields":["影视"],"identity":"一级演员 · 江苏省话剧院演员，《狄仁杰断案传奇》狄仁杰扮演者","summary":"《狄仁杰断案传奇》后 39 集的狄公是他，为接下这个角色，他等了十一年。","bio":"马昌钰 1945 年生于江苏南京，1963 年考入江苏省戏剧学校话剧表演专业，1965 年进入南京市话剧团，从演员做到编剧、副团长，1998 年调入江苏省话剧团，2005 年起任副团长。\n\n他的根在话剧舞台：在《甲申纪事》里演李岩，获第 3 届文华奖；主演《艰难的抉择》获第 10 届金鹰奖最佳主角提名，该剧拿下「五个一工程奖」；还获中国话剧金狮奖。1996 年《狄仁杰断案传奇》剧组中途换角，他推掉片约赶到太原救场，接演后 39 集的狄仁杰，该剧 1999 年在央视播出。\n\n2026 年 11 月 5 日 12 时 40 分，他在南京去世，遵其遗愿家中不设灵堂。","facts":["《甲申纪事》饰李岩，获第 3 届文华奖","《艰难的抉择》获第 10 届金鹰奖最佳主角提名","1996 年临危救场，接演《狄仁杰断案传奇》后 39 集"],"obit":true,"portrait":"assets/portraits/2026-11-05-207.webp","source":"搜狐娱乐","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-11-04-206","date":"2026-11-04","name":"丁度·巴拉斯","nameOrig":"Tinto Brass","country":"意大利","region":"","age":93,"fields":["影视"],"identity":"意大利电影导演 · 《罗马帝国艳情史》导演","summary":"他一生拍了 27 部电影，26 部挨过剪刀；《罗马帝国艳情史》他要求撤掉自己的名字。","bio":"丁度·巴拉斯 1933 年 3 月生于米兰，本名乔瓦尼·巴拉斯，「丁度」是当画家的祖父给他起的绰号。他学过法律，1950 年代末到巴黎在法国电影资料馆工作，做过罗西里尼的助手。\n\n1963 年他以《工作的人是失败者》完成导演首作，因触及反法西斯一代的价值危机遭审查；1960 年代作品先锋实验，《嚎叫》入围柏林电影节。1976 年《凯蒂夫人》标志他转向情色，1979 年的《罗马帝国艳情史》让他举世闻名——但制片人在后期加入硬色情镜头，他要求撤下自己的署名。他一生执导 27 部电影，26 部曾遭审查。\n\n2026 年 11 月 4 日上午，他在罗马家中因突发心脏病去世。","facts":["1976 年《凯蒂夫人》后转向情色电影创作","1979 年《罗马帝国艳情史》因制片方私自加戏而要求撤署名","执导 27 部电影，其中 26 部曾遭审查"],"obit":null,"portrait":"assets/portraits/2026-11-04-206.webp","source":"Pantheon","verified":"confirmed","causeOfDeath":"心脏病","wikipedia":"https://en.wikipedia.org/wiki/Tinto_Brass"},{"id":"2026-11-03-203","date":"2026-11-03","name":"谢莹莹","nameOrig":"","country":"中国","region":"中国大陆","age":88,"fields":["社科"],"identity":"翻译家 · 北京外国语大学德语学院教授","summary":"病床上躺了三十七年，她把卡夫卡和黑塞译成中文，也把病床当成了讲台。","bio":"谢莹莹 1938 年 1 月生于广东汕头，1946 年随家人迁居台湾。1963 年获台湾大学历史研究所硕士学位，1969 年获柏林自由大学日耳曼学硕士学位，此后在比勒菲尔德大学任讲师。\n\n1976 年她与丈夫陈家鼐放弃德国的一切回到北京，执教于北京外国语学院，直至八十高龄仍登台授课。她是国内第一批介绍、研究和翻译卡夫卡的学者，参加翻译的《卡夫卡小说全集》成为中文世界的基础文本，其中《变形记》译文出自她手；她同时是重要的黑塞译者，译有《德米安》《盖特露德》《温泉疗养客》。1989 年她罹患脊髓恶性肿瘤，手术后一直卧床，仍坚持教学科研。\n\n2026 年 11 月 3 日，她在北京病逝。","facts":["参加翻译《卡夫卡小说全集》，《变形记》译文出自她手","译有《德米安》《盖特露德》《温泉疗养客》等黑塞作品","1989 年患脊髓恶性肿瘤后仍卧床坚持教学科研"],"obit":true,"portrait":"assets/portraits/2026-11-03-203.webp","source":"维基百科逝世人物列表","verified":"corrected","causeOfDeath":null,"wikipedia":null},{"id":"2026-11-01-205","date":"2026-11-01","name":"江小鱼","nameOrig":"","country":"中国","region":"中国大陆","age":56,"fields":["影视"],"identity":"导演 · 乐评人，《真唱运动宣言》执笔者","summary":"2002 年他执笔写下《真唱运动宣言》，那句「真唱是一种权力」传遍整个摇滚圈。","bio":"江小鱼本名江熙，福建龙岩永定人，客家人。他先后就读于南京大学中文系与北京电影学院导演系，做过文化部《音乐生活报》等媒体记者，后长期做文化策划，被圈里称为「京城第一文化策划人」。\n\n他执导《因水之名》《屋顶上的青春》《超萌小月老》，著有《秦淮八艳》与诗集《用你的背叛拯救我》。2002 年他与崔健一同发起真唱运动，《真唱运动宣言》由他执笔，「真唱是一种权力」传遍摇滚圈；这场持续数年的签名与演出，推动 2005 年新版《营业性演出管理条例》明确对假唱作出处罚。\n\n2026 年 11 月 1 日，他在北京病逝。23 天前，他刚为 85 岁的母亲写下《祭慈母文》。","facts":["2002 年执笔《真唱运动宣言》，与崔健共同发起真唱运动","执导《因水之名》《屋顶上的青春》《超萌小月老》","《因水之名》获台北影视节两岸文化交流特别贡献奖"],"obit":true,"portrait":"assets/portraits/2026-11-01-205.webp","source":"维基百科逝世人物列表","verified":"corrected","causeOfDeath":null,"wikipedia":null},{"id":"2026-11-01-204","date":"2026-11-01","name":"吕齐","nameOrig":"","country":"中国","region":"中国大陆","age":101,"fields":["文艺"],"identity":"北京人艺表演艺术家 · 一级演员","summary":"《编辑部的故事》里那位戴眼镜、慢条斯理听年轻人吵架的陈主编，走了。","bio":"吕齐原名吕常祺，1925 年 8 月生于山东黄县（今龙口）。1949 年毕业于南京国立戏剧专科学校表演专业，同年加入解放军第三十五军文工团，凭话剧《保尔·柯察金》中的朱赫莱获三等功臣称号。\n\n1954 年他调入北京人民艺术剧院，出演《伊索》《王昭君》《贵妇还乡》《祸起萧墙》《李白》《雷雨》《野人》《上帝的宠儿》等七十余部剧目。退休后转向影视，1992 年在《编辑部的故事》里演陈主编，1993 年在《霸王别姬》里演戏班关师傅。\n\n2026 年 11 月 1 日，他在北京病逝，享年 101 岁。","facts":["1954 年调入北京人艺，出演《伊索》《李白》等七十余部话剧","《编辑部的故事》饰陈主编、《霸王别姬》饰关师傅","1982 年凭《谁是强者》获文化部剧目创作优秀奖"],"obit":true,"portrait":"assets/portraits/2026-11-01-204.webp","source":"北京人民艺术剧院讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-10-31-张中载","date":"2026-10-31","name":"张中载","nameOrig":"","country":"中国","region":"浙江奉化","age":93,"fields":["社科"],"identity":"英国文学研究专家 · 新中国哈代研究奠基者","summary":"他写出新中国第一部系统评介哈代的专著，也把《西方古典文论选读》交到一代研究生手里。","bio":"张中载 1933 年 1 月生于浙江奉化。1950 年考入北京外国语学院英语系，1957 年留校任教，此后一生都在那里。\n\n早年他投身国家外事翻译，多次在重大国际会议和对外交往中任翻译，曾在国家领导人身边工作；1970 年参与组织新中国第一部汉英大辞典的编撰，1980 年任联合国开发署与教科文组织代表团团长赴日考察，还担任过联合国首次援华项目主任。\n\n他的《托马斯·哈代——思想与创作》是新中国第一部系统评介哈代的学术著作，《当代英国文学》是我国首部系统评介当代英国文学的专著。2026 年 10 月 31 日凌晨在北京去世，享年 93 岁。","facts":["《托马斯·哈代——思想与创作》是新中国首部哈代研究专著","1970 年参与组织新中国第一部汉英大辞典的编撰","《西方古典文论选读》被教育部列为研究生教学用书"],"obit":null,"portrait":"assets/portraits/2026-10-31-张中载.webp","source":"北京外国语大学英语学院讣告 · 澎湃新闻","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-10-31-202","date":"2026-10-31","name":"迟金声","nameOrig":"","country":"中国","region":"中国大陆","age":104,"fields":["文艺"],"identity":"京剧艺术家 · 一级导演，马连良亲传弟子","summary":"他给几百出戏做音配像，脑子里存着马连良的冷戏，业内叫他京剧的「活辞典」。","bio":"迟金声 1922 年生于北京，祖籍山东蓬莱，出身梨园世家，祖上是清代「昆弋十三绝」之一的迟财官。他十岁学戏，十一岁登台，十六七岁起私淑马派，近三十岁正式拜在马连良门下；后来嗓音受损，转往科班授艺。\n\n1956 年他随马连良加入北京京剧团任导演，1965 年入中央戏剧学院导演进修班深造，与肖甲合导《芦荡火种》（后来的《沙家浜》），又导《红岩》《三打陶三春》。1994 至 2006 年他担任中国京剧音配像总导演，录制剧目 460 部，2011 年获中国戏曲表演学会终身成就奖，著有《马连良》。\n\n2026 年 10 月 31 日凌晨，他在家中安详离世。","facts":["1994 至 2006 年任中国京剧音配像总导演，录制剧目 460 部","与肖甲合导《芦荡火种》，即后来的《沙家浜》","2011 年获中国戏曲表演学会终身成就奖"],"obit":true,"portrait":"assets/portraits/2026-10-31-202.webp","source":"搜狐娱乐","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-10-30-让-克洛德·帕赛龙","date":"2026-10-30","name":"让-克洛德·帕赛龙","nameOrig":"Jean-Claude Passeron","country":"法国","region":"","age":95,"fields":["社科"],"identity":"法国社会学家 · 《继承人》《再生产》合著者","summary":"他和布尔迪厄一起指出，学校表面的平等其实在悄悄复制不平等——这句话改写了教育社会学。","bio":"帕赛龙 1930 年 11 月生于法国尼斯，毕业于巴黎高等师范学院，1958 年获哲学教师资格后转向社会学。\n\n1960 年代他与布尔迪厄搭档，1964 年出版《继承人》，1970 年出版《再生产》，用调查数据说明教育系统表面的民主化多半虚幻，不同阶级的学生并不站在同一起点。这两本书成了文化再生产理论的核心文本。\n\n1966 年他创建南特大学社会学系，参与创建万塞讷中心，后长期任法国社会科学高等研究院研究主任；1970 年代起与布尔迪厄渐行渐远，1991 年以《社会学推理》另定社会科学的真理体制。2026 年 10 月 30 日去世，享年 95 岁。","facts":["1964 年与布尔迪厄合著《继承人》，1970 年合著《再生产》","1966 年创建南特大学社会学系，1968 年参与创建万塞讷中心","1991 年出版《社会学推理》，另定社会科学的真理体制"],"obit":null,"portrait":null,"source":"法国社会科学高等研究院（EHESS）· 法国媒体报道","verified":"added","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Jean-Claude_Passeron"},{"id":"2026-10-30-威廉·诺德豪斯","date":"2026-10-30","name":"威廉·诺德豪斯","nameOrig":"William D. Nordhaus","country":"美国","region":"","age":85,"fields":["社科"],"identity":"美国经济学家 · 2018 年诺贝尔经济学奖得主","summary":"他把气候变暖折算成一笔账，让每一吨二氧化碳在经济学里第一次有了价格。","bio":"诺德豪斯 1941 年生于新墨西哥州阿尔伯克基，1967 年获麻省理工学院经济学博士，师从萨缪尔森与索洛，同年回耶鲁任教，1986 年至 1988 年任教务长。\n\n上世纪 70 年代，多数经济学家还没把气候当回事，他已琢磨怎样把碳排放、气候系统与经济增长装进同一个量化框架。1990 年代初他做出 DICE 模型，成为权衡减排成本与收益的标准工具，并由此推出污染者付费的碳税主张。\n\n2018 年，瑞典皇家科学院以「将气候变化整合进长期宏观经济分析」授予他诺贝尔经济学奖。2026 年 10 月 30 日，他因胶质母细胞瘤在纽黑文去世。","facts":["1990 年代初做出 DICE 模型，成为气候经济学的标准工具","2018 年获诺贝尔经济学奖，理由是气候与宏观分析的整合","与萨缪尔森合著《经济学》，自第 12 版起接手修订"],"obit":null,"portrait":"assets/portraits/2026-10-30-威廉·诺德豪斯.webp","source":"耶鲁大学讣告 · 美国经济学会（AEA）","verified":"added","causeOfDeath":"脑癌","wikipedia":null},{"id":"2026-10-30-201","date":"2026-10-30","name":"邵万林","nameOrig":"Wanlin Shao","country":"中国","region":"中国大陆","age":87,"fields":["文艺"],"identity":"电影表演艺术家 · 北京电影制片厂演员","summary":"「851，851，我是延安」——那个在《英雄儿女》里背着电台呼叫的排长，是他。","bio":"邵万林 1939 年 1 月生于山东莱州，1958 年考入长春电影制片厂演员剧团，1960 年代在《昆仑铁骑》里演张德发，后因《艳阳天》里的马连福被全国观众记住，1974 年调入北京电影制片厂演员剧团。\n\n他参演《英雄儿女》《海上明珠》《泪痕》《戴手铐的旅客》《杨贵妃》《唐明皇》等二十余部影视作品，在《戴手铐的旅客》里演潜伏特务苏哲；1993 年 62 岁时在《倚天屠龙记之魔教教主》里演白眉鹰王，2006 年在《神探狄仁杰 2》里演袁天罡。2011 年他为照顾母亲停戏，2015 年获评北京市「孝星」。\n\n2026 年 10 月 30 日，他在北京家中睡梦中离世。","facts":["《英雄儿女》中饰通讯排长，《艳阳天》中饰马连福","1993 年在《倚天屠龙记之魔教教主》中饰白眉鹰王","2011 年为照顾母亲停戏，2015 年获北京市「孝星」"],"obit":true,"portrait":"assets/portraits/2026-10-30-201.webp","source":"搜狐娱乐","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-10-30-200","date":"2026-10-30","name":"刘盛纲","nameOrig":"","country":"中国","region":"中国大陆","age":92,"fields":["科技"],"identity":"中国科学院院士 · 真空及微波电子学家、电子科技大学原校长","summary":"七十岁那年他换赛道扎进太赫兹，国际同行叫他「太赫兹先驱」，国内叫他奠基人。","bio":"刘盛纲 1933 年 12 月生于安徽合肥，1955 年毕业于南京工学院无线电系电真空专业并留校，1956 年调至成都电讯工程学院，1958 年获副博士学位，1980 年当选中国科学院学部委员。\n\n他在微波电子学、相对论电子学、太赫兹领域做了一系列奠基工作：创立以电子回旋中心坐标系为基础的动力学理论，带领团队研制出我国第一支回旋管与第一支太赫兹回旋管，2000 年前后率先向国家建议发展太赫兹科学技术。2003 年获国际红外毫米波太赫兹领域最高奖 K. J. Button 奖。\n\n1986 至 2001 年他任电子科技大学校长。2026 年 10 月 30 日 7 时 26 分在成都病逝。","facts":["1980 年当选中国科学院学部委员（院士）","2003 年获国际红外毫米波太赫兹领域最高奖 K. J. Button 奖","带领团队研制我国第一支回旋管与第一支太赫兹回旋管"],"obit":true,"portrait":"assets/portraits/2026-10-30-200.webp","source":"科学网","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-10-28-帕特里克·斯图尔特","date":"2026-10-28","name":"帕特里克·斯图尔特","nameOrig":"Patrick Stewart","country":"英国","region":"","age":86,"fields":["影视"],"identity":"英国演员 · 《星际迷航》皮卡德舰长","summary":"一句「就这么办」，让企业号驶向未知；他把莎士比亚练出的嗓音，借给了星舰与变种人。","bio":"帕特里克·斯图尔特 1940 年生于英格兰约克郡的工人家庭，12 岁加入业余剧团，后入布里斯托老维克戏剧学院，1966 年加入皇家莎士比亚剧团。\n\n1987 年，他在《星际迷航：下一代》里出演皮卡德舰长，七季剧集让这个角色成为科幻坐标。2000 年，他在《X 战警》中首演查尔斯·泽维尔教授，二十余年间九次回归。\n\n2004 年至 2015 年兼任哈德斯菲尔德大学校长。晚年罹患阿尔茨海默病与路易体失智症，2026 年 10 月 28 日在洛杉矶家中去世，享年 86 岁；12 月上映的《复仇者联盟 5》成其银幕绝唱。","facts":["1987 年起在《星际迷航：下一代》饰皮卡德舰长，共七季","2000 年首演 X 教授，二十余年间前后九次出演","2004 年至 2015 年兼任英国哈德斯菲尔德大学校长"],"obit":null,"portrait":"assets/portraits/2026-10-28-帕特里克·斯图尔特.webp","source":"家属声明 · 界面新闻、中国新闻网报道","verified":"added","causeOfDeath":"阿尔茨海默病","wikipedia":"https://en.wikipedia.org/wiki/Patrick_Stewart"},{"id":"2026-10-28-199","date":"2026-10-28","name":"刘延东","nameOrig":"","country":"中国","region":"中国大陆","age":81,"fields":["军政"],"identity":"国务院原副总理 · 中共十七届、十八届中央政治局委员","summary":"她是中共十七届、十八届中央政治局委员，也是国务院少见的女性副总理。","bio":"刘延东 1945 年 11 月生于江苏淮安，祖籍江苏南通。1964 年入清华大学工程化学系学习，毕业后在唐山开平化工厂、北京化工实验厂工作十年，1980 年调入北京市委组织部，1981 年任朝阳区委副书记。\n\n1982 年起她任共青团中央书记处书记、常务书记，全国青联主席；后历任中央统战部部长、全国政协副主席、国务委员，2008 至 2018 年任国务院副总理，并长期担任国务院妇女儿童工作委员会主任。\n\n2026 年 10 月 28 日 14 时 53 分，她在北京病逝，享年 81 岁；11 月 3 日遗体在八宝山革命公墓火化。","facts":["中共第十七届、十八届中央政治局委员","2008 至 2018 年任国务院副总理","曾任全国青联主席、中央统战部部长、全国政协副主席"],"obit":true,"portrait":"assets/portraits/2026-10-28-199.webp","source":"人民网·中国共产党新闻网讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-10-26-197","date":"2026-10-26","name":"班弨","nameOrig":"","country":"中国","region":"中国大陆","age":64,"fields":["社科"],"identity":"语言学家 · 暨南大学华文学院原院长","summary":"他为壮语写出第一部系统的描写词汇学，也替正在变弱的村寨土话留下存档。","bio":"班弨 1962 年 9 月生于广西邕宁，壮族。1983 年毕业于广西民族学院，1987 年获中央民族大学文学硕士，师从马学良、张元生，2004 年获中山大学文学博士。\n\n1988 年他进入暨南大学任教，1995 年破格晋升副教授，2001 年晋升教授，历任华文学院院长、汉语国际推广中心主任。他在汉台语比较、壮语描写词汇学与社会语言学领域造诣深厚，著有《论汉语中的台语底层》《壮语描写词汇学》《中国语言文字学通史》，其中《壮语描写词汇学》是对壮语词汇首次系统的共时研究。\n\n2026 年 10 月 26 日，他在广州病逝。","facts":["《壮语描写词汇学》为壮语词汇首次系统性的共时研究","曾任暨南大学华文学院院长、汉语国际推广中心主任","师从马学良、张元生、唐钰明，2001 年晋升教授"],"obit":true,"portrait":null,"source":"维基百科逝世人物列表","verified":"confirmed","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":null},{"id":"2026-10-26-196","date":"2026-10-26","name":"戈治均","nameOrig":"","country":"中国","region":"中国大陆","age":90,"fields":["文艺"],"identity":"人民表演艺术家 · 一级演员，第 21 届金鸡奖最佳男主角","summary":"六十五岁那年，他凭《押解的故事》拿下金鸡影帝；片里那个角色，还是叫李公安。","bio":"戈治均 1936 年 8 月生于山西运城。1956 年他考入西安交通大学水利系，1960 年毕业后进西安电影制片厂演员剧团，1964 年调入陕西人民艺术剧院，在话剧舞台演过《雷雨》《一双绣花鞋》等剧目，兼做编剧与导演。\n\n1992 年他在《秋菊打官司》里演李公安，此后接连出演《二嫫》《背靠背，脸对脸》。2001 年，65 岁的他凭《押解的故事》获第 21 届中国电影金鸡奖最佳男主角。电视剧里他演过《走向共和》的荣禄、《大宋提刑官》的和魁，81 岁在《白鹿原》里演鹿泰恒，称那是封箱之作。\n\n2026 年 10 月 26 日，他在北京病逝。","facts":["2001 年凭《押解的故事》获第 21 届中国电影金鸡奖最佳男主角","1964 年调入陕西人民艺术剧院，深耕话剧舞台数十年","81 岁在《白鹿原》中饰鹿泰恒，称其为封箱之作"],"obit":true,"portrait":"assets/portraits/2026-10-26-196.webp","source":"中国山东网","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-10-22-198","date":"2026-10-22","name":"福田康夫","nameOrig":"Fukuda Yasuo","country":"日本","region":"","age":90,"fields":["军政"],"identity":"日本第 91 任首相 · 前首相福田赳夫长子","summary":"他是 1885 年以来日本唯一一对父子首相中的儿子，任内签下中日第四份政治文件。","bio":"福田康夫 1936 年 7 月生于群马县高崎市，是前首相福田赳夫的长子，毕业于早稻田大学，先在丸善石油做了十七年上班族，1976 年辞职给父亲当秘书，一当十三年。\n\n1990 年他首次当选众议员，2000 至 2004 年在森喜朗、小泉纯一郎内阁任官房长官，2007 年 9 月接替安倍晋三出任第 91 任首相，2008 年 9 月辞职，任内签下中日第四份政治文件。2012 年退出政坛后仍致力于日中友好，2018 年参观侵华日军南京大屠杀遇难同胞纪念馆，还长期担任博鳌亚洲论坛理事长。\n\n2026 年 10 月 22 日，他因心力衰竭在东京去世。","facts":["2007 年 9 月至 2008 年 9 月任日本第 91 任首相","与父亲福田赳夫是 1885 年以来日本唯一一对父子首相","曾任博鳌亚洲论坛理事长，2018 年参观南京大屠杀纪念馆"],"obit":null,"portrait":"assets/portraits/2026-10-22-198.webp","source":"财新讣闻","verified":"corrected","causeOfDeath":"心力衰竭","wikipedia":null},{"id":"2026-10-18-195","date":"2026-10-18","name":"吴康民","nameOrig":"Ng Hong-mun","country":"中国","region":"香港","age":100,"fields":["社科"],"identity":"香港教育家 · 培侨中学前校长、港区全国人大代表","summary":"他执掌培侨校政二十八年，连续七届当全国人大代表，前后当了三十三年。","bio":"吴康民 1926 年 4 月生于广东惠来，1947 年毕业于中山大学化学工程系，同年赴港到培侨中学任教，1958 年至 1985 年任校长，其后任校监、校董会董事长，2005 年起任培侨教育机构董事会主席，执掌校政二十八年。\n\n1975 年他筹组香港教育工作者联会并任创会会长。他历任第四至第十届全国人大代表，连续七届、长达三十三年，曾任港区全国人大代表团团长、香港特区筹委会委员，1998 年获颁大紫荆勋章。\n\n2026 年 10 月 18 日上午，他在家人陪伴下安详辞世，享寿百岁。","facts":["连续七届、三十三年担任港区全国人大代表","1975 年筹组香港教育工作者联会并任创会会长","1998 年获颁香港特区最高荣誉大紫荆勋章"],"obit":true,"portrait":"assets/portraits/2026-10-18-195.webp","source":"维基百科逝世人物列表","verified":"confirmed","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Ng_Hong-mun"},{"id":"2026-10-17-194","date":"2026-10-17","name":"吕彦庆","nameOrig":"Lu Yen-ching","country":"中国","region":"台湾","age":48,"fields":["文艺"],"identity":"台湾指挥家 · 低音长号演奏家、逢甲大学管乐团指挥","summary":"住院期间他躺在床上挥着双手练指挥，六月请假出院那次，成了最后一次登台。","bio":"吕彦庆是台湾的指挥家与低音长号演奏家，人称「大吕老师」，长年投入管乐教育，担任逢甲大学管乐团指挥，也在建国中学、大安国中等校带团。\n\n2026 年 5 月他因白血病住院，6 月底仍请医师准假一周，回台上指挥「秋山纪夫老师纪念音乐会」，演完再回医院。8 月中旬他接受骨髓移植，慈济骨髓资料库找到十项位点全相符的捐赠者，血球一度恢复良好；随后出现骨髓移植后极罕见的「肝窦阻塞症候群」，肝指数飙到 1200，又并发菌血症。\n\n2026 年 10 月 17 日深夜，他病逝，年仅 48 岁。","facts":["曾任逢甲大学管乐团指挥，长年投入台湾管乐教育","2026 年 5 月确诊白血病，8 月接受骨髓移植","6 月底请假出院，完成生前最后一次公开指挥"],"obit":true,"portrait":null,"source":"维基百科逝世人物列表","verified":"confirmed","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":null},{"id":"2026-10-16-193","date":"2026-10-16","name":"隋桂凤","nameOrig":"","country":"中国","region":"中国大陆","age":85,"fields":["影视"],"identity":"长影演员 · 译制片配音演员","summary":"她是《你的名字》里三叶的祖母、《小偷家族》里的奶奶，声音藏在几百部译制片背后。","bio":"隋桂凤 1941 年生于辽宁沈阳，1959 年考入长影演员剧团，在《十级浪》《特快列车》《炉火正红》《黄河少年》《苦难的心》《狼犬历险记》等影片中扮演各类女性角色。\n\n1987 年她调入长影译制片厂转为配音，为《罗马假日》《卞卡》《落水姻缘》等数百部外国译制片配音。晚年她的声音被更多观众记住：《邻居托托罗》（龙猫）里的老奶奶、《你的名字》里三叶的祖母宫水一叶、《小偷家族》里的柴田初枝、《天堂电影院》里老年的玛丽亚。\n\n2026 年 10 月 16 日 1 时 40 分，她在长春病逝。","facts":["为《你的名字》《龙猫》《小偷家族》《天堂电影院》等片配音","1959 年考入长影演员剧团，1987 年转入译制片厂","先后为《罗马假日》《卞卡》等数百部译制片配音"],"obit":true,"portrait":"assets/portraits/2026-10-16-193.webp","source":"维基百科逝世人物列表","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-10-15-192","date":"2026-10-15","name":"陈羲明","nameOrig":"","country":"中国","region":"中国大陆","age":71,"fields":["文艺"],"identity":"书法家 · 中国书协原理事、湖南省书协原驻会副主席","summary":"他把《九成宫醴泉铭》一字一字重刻上石，又在遗愿里写下不发讣告、不留骨灰。","bio":"陈羲明 1955 年 6 月生于福建南平，号九闲道人，国家一级美术师。他早年从军，在空军服役二十余年，1993 年转业到湖南省文联，此后三十年为书法奔忙。\n\n他诸体兼修，师从沈鹏，2000 年起连任四届中国书协理事，曾任湖南省书协驻会副主席兼秘书长、草书委员会主任，是湖南书法家进入全国重要展评委席的第一人。2017 年「书堂山房」入驻长沙望城欧阳询文化园，由他主持重刻的《九成宫醴泉铭》碑 2024 年落成。\n\n他留下「六不」遗愿：不发讣告、不办仪式、不置墓地、不留骨灰。2026 年 10 月 15 日夜在长沙病逝。","facts":["主持重刻的《九成宫醴泉铭》碑 2024 年在长沙望城落成","中国书协第四至七届理事，湖南省书协原驻会副主席兼秘书长","辞世前立「六不」遗愿：不发讣告、不办仪式、不留骨灰"],"obit":true,"portrait":"assets/portraits/2026-10-15-192.webp","source":"湖南省书法家协会","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-10-15-191","date":"2026-10-15","name":"张瓦城","nameOrig":"","country":"中国","region":"中国大陆","age":97,"fields":["医药"],"identity":"神经外科专家 · 首都医科大学宣武医院神经外科教授","summary":"他在国内第一次把患者自己的肾上腺髓质移植进脑内，让重症帕金森病人重新站稳。","bio":"张瓦城 1928 年 10 月生于福建惠安，1955 年毕业于福建医学院医疗系，此后在北京天坛医院、宣武医院神经外科工作五十余年，曾任宣武医院神经外科副主任，1992 年退休。\n\n他毕生研究颅内肿瘤，对桥脑小脑角区、颈静脉孔区肿瘤造诣尤深，著有《桥脑小脑角肿瘤》。1986 年他在国内率先开展「自体肾上腺髓质脑内移植治疗重症帕金森氏病」手术并成功，属国内首例，为宣武医院赢得国家科学技术进步二等奖。\n\n2026 年 10 月 15 日，他在北京病逝，享年 97 岁。","facts":["国内首例自体肾上腺髓质脑内移植治疗帕金森手术的实施者","著有《桥脑小脑角肿瘤》，发表论文 45 篇","1985 年国内率先开展尿激酶在颅内治疗中的应用研究"],"obit":true,"portrait":null,"source":"首都医科大学宣武医院讣告","verified":"confirmed","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":null},{"id":"2026-10-13-王镕","date":"2026-10-13","name":"王镕","nameOrig":"","country":"中国","region":"江苏常州","age":103,"fields":["社科"],"identity":"经济法学家 · 安徽大学「法学五老」之一","summary":"1979 年他走进刚复建的安大法律系，把民法与经济法的种子，撒在一间几乎空着的教室。","bio":"王镕 1923 年 1 月生于江苏常州金坛，1949 年毕业于北平朝阳大学法律系，那所学校与东吴大学并称「南东吴、北朝阳」。此后他进中国人民大学法律系任教十年。\n\n1960 年至 1979 年，他在内蒙古包头钢铁学院任教，法学教育最萧索的岁月就在那里度过。1979 年他调入安徽大学法学院，那年安大率先恢复重建法律系，他是重建队伍里少数受过完整法科训练的人。\n\n他与陈盛清、周枏、朱学山、陈安明并称安大「法学五老」，参编全国高校教材《经济法学》，主编《新编经济法概论》，多年为地方立法建言。2026 年 10 月 13 日在合肥去世，享年 103 岁。","facts":["1949 年毕业于北平朝阳大学法律系司法专业","与陈盛清、周枏等并称安徽大学「法学五老」","1981 年起参与招收经济法学硕士，为省级重点学科奠基"],"obit":null,"portrait":null,"source":"安徽大学法学院讣告 · 澎湃新闻","verified":"added","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":null},{"id":"2026-10-12-黑井千次","date":"2026-10-12","name":"黑井千次","nameOrig":"Kuroi Senji","country":"日本","region":"","age":94,"fields":["文艺"],"identity":"日本小说家 · 「内向的一代」代表作家","summary":"在富士重工做了十五年职员，他把办公室里的沉默写成小说，替不肯喊出口的一代人找到了声音。","bio":"黑井千次本名长部舜二郎，1932 年生于东京杉并。父亲是法学家，他却写信问作家野间宏该学什么，得一句「要研究资本主义构造中的人，就去学经济」，于是考进东京大学经济学部。\n\n1955 年毕业后他进富士重工，一待十五年，边上班边写作，1970 年以《时间》获艺术选奖新人赏才辞职专事创作。他与古井由吉等人被称作「内向的一代」，不相信对社会说三道四的知识分子，只把非现实搬进日常。\n\n《群栖》获 1984 年谷崎润一郎奖，《窗帘 call》获 1995 年读卖文学奖；2014 年至 2020 年任日本艺术院院长。2026 年 10 月 12 日因肺炎在东京去世。","facts":["在富士重工工作十五年后，1970 年转为专业作家","《群栖》获谷崎润一郎奖，《窗帘 call》获读卖文学奖","1987 年至 2012 年担任芥川奖选考委员","2014 年至 2020 年出任日本艺术院院长"],"obit":null,"portrait":null,"source":"时事通信、四国新闻报道 · 日本文艺家协会","verified":"added","portraitStatus":"no-source","causeOfDeath":"肺炎","wikipedia":"https://en.wikipedia.org/wiki/Kuroi_Senji"},{"id":"2026-10-12-杰弗里·戈德斯通","date":"2026-10-12","name":"杰弗里·戈德斯通","nameOrig":"Jeffrey Goldstone","country":"英国","region":"","age":93,"fields":["科技"],"identity":"理论物理学家 · 戈德斯通定理提出者","summary":"他证明对称性一旦自发破缺，必然留下无质量的粒子。标准模型的地基里，有他放下的一块砖。","bio":"杰弗里·戈德斯通 1933 年生于英国曼彻斯特，1958 年在剑桥三一学院获博士学位，师从汉斯·贝特研究核物质理论，此后在剑桥、哈佛与哥本哈根做博士后，1962 年回剑桥任教，1977 年赴麻省理工学院。\n\n1961 年，他提出连续对称性自发破缺必然伴随无质量、无自旋粒子的结论，即戈德斯通定理与戈德斯通玻色子，后经萨拉姆与温伯格形式化，成为粒子物理标准模型的基石之一。他的研究横跨量子场论、弦论与量子计算。\n\n他 1981 年获海涅曼奖、1991 年获国际理论物理中心狄拉克奖章,是英国皇家学会会士。2026 年 10 月 12 日去世，享年 93 岁。","facts":["1961 年提出戈德斯通定理，无质量粒子以其姓氏命名","1977 年起任教于麻省理工学院理论物理中心并曾主持该中心","1991 年获国际理论物理中心狄拉克奖章"],"obit":null,"portrait":null,"source":"麻省理工学院物理系讣告 · 剑桥三一学院","verified":"added","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Jeffrey_Goldstone"},{"id":"2026-10-11-车洪才","date":"2026-10-11","name":"车洪才","nameOrig":"","country":"中国","region":"黑龙江海伦","age":90,"fields":["社科"],"identity":"普什图语专家 · 《普什图语汉语词典》主编","summary":"接下一桩国家任务，用三十六年编一部词典，只为兑现 1978 年那句「党的需要就是个人志愿」。","bio":"车洪才 1936 年生于黑龙江海伦。1957 年入北京外国语学院学英语，大三时被外交部选派到阿富汗喀布尔大学学普什图语，成为新中国第一代普什图语留学生。回国后他参与筹建中央人民广播电台普什图语组，后到北京广播学院任教。\n\n1978 年，商务印书馆把《普什图语汉语词典》交给他。他用三年手工做出十万张卡片，随后因工作调动屡屡中断，助手宋强民 2000 年去世，2008 年退休后他才全力重启，2012 年交出初稿。\n\n2015 年词典出版，二百三十余万字、五万余词条，是中国第一部大型普什图语汉语词典。2026 年 10 月 11 日在北京去世，享年 90 岁。","facts":["1978 年承接《普什图语汉语词典》国家任务，历时 36 年","词典 2015 年出版，收录词条五万余个、二百三十余万字","2015 年获阿富汗总统授予的杰出贡献勋章"],"obit":null,"portrait":"assets/portraits/2026-10-11-车洪才.webp","source":"中国传媒大学讣告 · 澎湃新闻","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-10-11-董祖诒","date":"2026-10-11","name":"董祖诒","nameOrig":"","country":"中国","region":"北京","age":92,"fields":["文艺"],"identity":"雕塑家 · 首代中国电影金鸡奖奖杯设计者","summary":"三十多年里，无数影人举过头顶的那只金鸡，出自他的刀下；他的名字，很少有人念起。","bio":"董祖诒 1934 年生于北京。1951 年入伍参加抗美援朝文艺宣传队，同年进鲁迅艺术学院音乐系，次年转入鲁迅美术学院雕塑系。1957 年赴苏联列宾美术学院攻读雕塑，1963 年获「艺术家」称号后回国，任教于中央美术学院。\n\n他是苏派雕塑教学在中国落地的关键人物之一，任雕塑系第三工作室主任，学生中隋建国、孙伟、王中后来都成了中国雕塑界的中坚。作品有《放哨》《刘胡兰》《高君宇与石评梅》《唐山地震纪念碑》等。\n\n1981 年金鸡奖创办，恰逢农历鸡年，奖杯取「金鸡啼晓」之意，由他设计，此后沿用三十余年。2026 年 10 月 11 日在北京病逝，享年 92 岁。","facts":["1981 年设计首代金鸡奖奖杯，沿用至 2018 年","1957 年赴列宾美术学院学雕塑，1963 年获艺术家称号","学生隋建国、孙伟、王中皆为中国雕塑界中坚"],"obit":null,"portrait":"assets/portraits/2026-10-11-董祖诒.webp","source":"中央美术学院讣告 · 扬子晚报、极目新闻","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-10-10-190","date":"2026-10-10","name":"李仁科","nameOrig":"Ren-Ke Li","country":"中国","region":"中国大陆","age":65,"fields":["医药"],"identity":"心脏再生医学科学家 · 港中大（深圳）医学院副院长","summary":"他让干细胞移植治疗心衰第一次拿到 FDA 批准，最后倒在西安一场学术会议的间隙。","bio":"李仁科 1961 年生于黑龙江哈尔滨，先后毕业于哈尔滨医科大学、山西医科大学与加拿大多伦多大学，1993 年起执教多伦多大学医学院，2002 年晋升终身教授。\n\n他做心脏再生医学与组织工程，是全球首位获 FDA 批准把干细胞移植用于心力衰竭治疗、并把导电生物材料用于心律失常研究的科学家。2011 年当选加拿大健康科学院院士，2024 年当选加拿大皇家科学院院士，2025 年 5 月当选加拿大工程院院士。\n\n2025 年 3 月他全职加入香港中文大学（深圳），任医学院副院长。2026 年 10 月 10 日在西安出席学术会议期间辞世。","facts":["全球首位获 FDA 批准用干细胞移植治疗心力衰竭的科学家","加拿大皇家科学院、工程院、健康科学院三院院士","2025 年 3 月全职加入港中大（深圳），任医学院副院长"],"obit":true,"portrait":"assets/portraits/2026-10-10-190.webp","source":"香港中文大学（深圳）讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-10-09-189","date":"2026-10-09","name":"楼宇烈","nameOrig":"","country":"中国","region":"中国大陆","age":92,"fields":["社科"],"identity":"哲学家 · 北京大学哲学系教授、宗教文化研究院名誉院长","summary":"「《老子》才不过五千言」——他给学生的作业上限是五千字，自己在燕园站了六十六年讲台。","bio":"楼宇烈 1934 年 12 月生于杭州，祖籍浙江嵊县。1955 年考入北京大学哲学系，师从冯友兰、汤用彤等，1960 年毕业留校，执教六十六年。\n\n他从魏晋玄学入手，贯通儒释道。代表作《王弼集校释》初稿 1964 年完成，1980 年由中华书局出版，被视为当代中国学术经典；他主持编纂《中国佛教思想资料选编》四卷十册，晚年提倡「国艺」，力推昆曲、古琴、书法与中医，2025 年出版八卷九册《楼宇烈文集》。\n\n2026 年 10 月 9 日 2 时 18 分，他在北京病逝，享年 92 岁。","facts":["《王弼集校释》1980 年由中华书局出版，为魏晋玄学研究权威文本","1955 年考入北大哲学系，师从冯友兰、汤用彤等","2025 年出版八卷九册《楼宇烈文集》"],"obit":true,"portrait":"assets/portraits/2026-10-09-189.webp","source":"维基百科逝世人物列表","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-10-09-187","date":"2026-10-09","name":"方艳华","nameOrig":"","country":"中国","region":"中国大陆","age":87,"fields":["文艺"],"identity":"上海滑稽「双字辈」独脚戏演员 · 一级演员","summary":"她一张口就是九腔十八调，《各派越剧》唱了七十多年，上海人的笑声里有她一半。","bio":"方艳华原名方菊芳，1940 年生于浙江宁波，十四岁投身曲艺，1961 年进入海燕滑稽剧团，师从「金嗓子」田丽丽，是田丽丽唯一的女传人。\n\n1980 年她与郭明敏搭档，拜姚慕双、周柏春门下，归入上海滑稽「双字辈」，是这一辈里不多的女性。两人留下近百个独脚戏与上海说唱作品，《各派越剧》《戏迷嫂嫂》《家乡好》是招牌，她熟稔各派唱腔，以「以唱驭戏、以唱带做」自成一路。\n\n她还是国家级非遗「独脚戏」项目市级传承人。2026 年 10 月 9 日上午 6 时 57 分在上海病逝。","facts":["独脚戏《各派越剧》《戏迷嫂嫂》《家乡好》为其代表作","1980 年拜姚慕双、周柏春为师，归入「双字辈」","国家级非遗「独脚戏」项目市级传承人，曾获上海市三八红旗手"],"obit":true,"portrait":"assets/portraits/2026-10-09-187.webp","source":"维基百科逝世人物列表","verified":"corrected","causeOfDeath":null,"wikipedia":null},{"id":"2026-10-08-188","date":"2026-10-08","name":"李兆熊","nameOrig":"","country":"中国","region":"香港","age":89,"fields":["影视"],"identity":"香港电视监制 · 前丽的电视戏剧制作总监，「丽的三雄」之一","summary":"《大地恩情》播到一半，对手台第一次腰斩自己的重头剧，香港电视史上只此一回。","bio":"李兆熊 1940 年生于香港演艺世家，父亲是粤语片导演李晨风，母亲是演员李月清。他八岁以童星入行，1960 年代转做编剧，常与父亲一编一导，拍出《金粉世家》《苏小小》《李后主》。\n\n1973 年他加入丽的电视，1977 年升任剧集监制，1981 年任戏剧制作总监，与麦当雄、屠用雄并称「丽的三雄」，监制《电视人》《变色龙》《浮生六劫》和 1980 年与徐小明合监的《大地恩情》系列。1990 年代淡出影视圈。\n\n妻子王心慰同为金牌监制。2026 年 10 月 5 日他病情转急，10 月 8 日清晨因器官衰竭在医院离世。","facts":["监制《变色龙》《浮生六劫》《大地恩情》系列","1980 年《大地恩情》令 TVB 首次腰斩同期剧集《轮流传》","与麦当雄、屠用雄并称「丽的三雄」，妻为监制王心慰"],"obit":true,"portrait":"assets/portraits/2026-10-08-188.webp","source":"维基百科逝世人物列表","verified":"corrected","causeOfDeath":null,"wikipedia":null},{"id":"2026-10-07-彭玉","date":"2026-10-07","name":"彭玉","nameOrig":"","country":"中国","region":"黑龙江哈尔滨","age":93,"fields":["影视"],"identity":"影视表演艺术家 · 《东北一家人》牛大妈","summary":"六十岁才北上跑组，一句「给钱」演活看电话亭的大妈，此后二十年她成了全国观众的妈。","bio":"彭玉 1934 年生于哈尔滨的铁路工人家庭，瞒着父亲考进业余话剧团，17 岁因《钢铁是怎样炼成的》里的红军妹妹被哈尔滨话剧院看中。1964 年出演《千万不要忘记》，29 岁就贴上皱纹演老太太，也因此被下放农场十年。\n\n1988 年丈夫赵文欣脑溢血瘫痪，她推掉全部戏约提前退休，照料八年。1995 年丈夫去世后，64 岁的她进京成了老年北漂，第一个角色是看电话亭的大妈，台词只有两个字：给钱。\n\n2001 年，她凭《月圆今宵》获金爵奖影后与金鸡奖最佳女配角；同年在《东北一家人》里演牛大妈陈久香，成了几代观众最亲的奶奶。2026 年 10 月 7 日在珠海离世。","facts":["67 岁凭《月圆今宵》获金爵奖影后与金鸡奖最佳女配角","丈夫瘫痪后推掉全部戏约，亲自照料八年","64 岁进京成老年北漂，首个角色台词只有「给钱」二字"],"obit":null,"portrait":"assets/portraits/2026-10-07-彭玉.webp","source":"中国视协演员工作委员会 · 新京报、极目新闻","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-10-05-郑学勤","date":"2026-10-05","name":"郑学勤","nameOrig":"","country":"中国","region":"安徽歙县","age":97,"fields":["科技"],"identity":"天然橡胶育种专家 · 中国热作「两院」拓荒人","summary":"23 岁那年他把志愿填成海南岛，此后七十余年，中国橡胶的产量里一直长着他的胶苗。","bio":"郑学勤 1929 年 7 月生于安徽歙县。1948 年入北京大学植物学系。1952 年毕业，23 岁的他填了第一志愿：奔赴海南岛。儋县没有宿舍也没有实验室，众人割茅草搭屋，在胶林里架铁锅烧水消毒试管，徒手爬上十几米高的橡胶树授粉。\n\n1981 年他随探险队深入亚马孙雨林，带回 5000 株野生胶树苗，杂交后海南橡胶树产量提升五倍。他参与主持的橡胶优良无性系选育与推广获国家科技进步一等奖。\n\n年近古稀他又转向无核荔枝，把嫁接成活率从不足 1% 提到 85%，2006 年获何梁何利基金区域创新奖。2026 年 10 月 5 日凌晨在海口去世，享年 97 岁。","facts":["1981 年深入亚马孙雨林，带回 5000 株野生胶树苗","橡胶优良无性系选育与推广获国家科技进步一等奖","把无核荔枝嫁接成活率从不足 1% 提高到 85%"],"obit":null,"portrait":"assets/portraits/2026-10-05-郑学勤.webp","source":"海南大学讣告 · 海南日报、北京日报","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-10-03-胡宁娜","date":"2026-10-03","name":"胡宁娜","nameOrig":"","country":"中国","region":"江苏南京","age":68,"fields":["文艺"],"identity":"工笔人物画家 · 江苏省国画院原副院长","summary":"她留下一句「不要惊动我的远去」，然后像自己画过的那只蝴蝶，不设灵堂、不留墓碑地飞走了。","bio":"胡宁娜 1958 年 5 月生于南京。15 岁被选进鼓楼区文化馆创作组，1978 年考入江苏省国画院学员班，次年由亚明安排赴敦煌莫高窟临摹壁画近两个月，1982 年留院人物画研究所。\n\n她以工笔人物画见长，笔下莲花慈容与佛像庄严，达摩却常睁一只眼闭一只眼；仕女童子元气淋漓，红绿互补色用得大胆。她还以中国画笔墨画过埃及壁画与希腊换岗仪式。《清风赏花图》获第八届全国美展优秀奖。\n\n晚年她完成巨幅《八十七神仙卷》，2023 年捐给江苏大剧院。2026 年 10 月 3 日深夜因胆囊癌去世，享年 68 岁，遵其遗愿不设灵堂、不设告别仪式、不留墓碑。","facts":["《清风赏花图》获第八届全国美展优秀奖","2023 年将巨幅《八十七神仙卷》捐给江苏大剧院","遗愿丧事从简：不设灵堂、不设告别仪式、不留墓碑"],"obit":null,"portrait":"assets/portraits/2026-10-03-胡宁娜.webp","source":"江苏省国画院讣告 · 扬子晚报、腾讯新闻","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-09-30-186","date":"2026-09-30","name":"玛格丽特·汉密尔顿","nameOrig":"Margaret Hamilton","country":"美国","region":"","age":90,"fields":["科技"],"identity":"美国计算机科学家 · 阿波罗登月舱飞行软件负责人，软件工程命名者","summary":"阿波罗 11 号着陆前那几分钟，是她写的程序决定忽略哪些警报，人类才没有掉头回去。","bio":"1936 年生于美国印第安纳州保利，大学读数学与哲学。1965 年加入麻省理工学院仪器实验室，成为阿波罗计划聘用的第一位程序员，后领导登月舱与指令舱飞行软件的开发团队。\n\n她坚持「防御性编程」，让软件在出错和过载时仍能保住最要紧的任务。1969 年 7 月 20 日阿波罗 11 号着陆前几分钟，交会雷达数据涌入导致制导计算机过载，正是她的优先级中断设计让程序丢掉次要任务、保住着陆，任务才没有中止。她后来把这种做法命名为「软件工程」。\n\n2026 年 9 月 30 日在马萨诸塞州剑桥去世，享年 90 岁。","facts":["麻省理工阿波罗计划聘用的第一位程序员","1969 年阿波罗 11 号着陆危机中，其优先级设计避免任务中止","2003 年获NASA杰出空间法案奖，2016 年获总统自由勋章","推动并推广「软件工程」这一学科名称"],"obit":null,"portrait":"assets/portraits/2026-09-30-186.webp","source":"Pantheon","verified":"confirmed","causeOfDeath":null},{"id":"2026-09-27-185","date":"2026-09-27","name":"鲜学福","nameOrig":"","country":"中国","region":"中国大陆","age":97,"fields":["科技"],"identity":"中国工程院院士 · 矿山安全技术专家，重庆大学教授","summary":"他在国际上第一次完整建立煤层瓦斯渗流理论，把「瓦斯突出」这个杀人的词变成了可预测的力学问题。","bio":"1929 年 1 月生于四川阆中。1950 年至 1956 年在北京矿业学院（今中国矿业大学）学习，1956 年 3 月起在重庆大学任教，1960 年至 1964 年赴苏联莫斯科矿业学院深造并获副博士学位，1999 年当选中国工程院院士。\n\n他长期研究煤层瓦斯基础理论：在国际上首次完整建立地球物理场中煤层瓦斯渗流理论，创立煤与瓦斯突出潜在危险区预测的力学方法，攻克近距离煤层群保护层开采及瓦斯抽放这一世界性难题。进入 21 世纪他转向页岩气，指导实施全球首次超临界二氧化碳压裂现场试验。\n\n2026 年 9 月 27 日 13 时 50 分在重庆逝世，享年 97 岁。","facts":["1999 年当选中国工程院院士，矿山安全专家","在国际上首次完整建立地球物理场中煤层瓦斯渗流理论","指导实施全球首次超临界二氧化碳压裂现场试验","获全国「最美奋斗者」、全国优秀教师称号"],"obit":true,"portrait":"assets/portraits/2026-09-27-185.webp","source":"重庆大学讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-09-25-183","date":"2026-09-25","name":"刘欢","nameOrig":"","country":"中国","region":"中国大陆","age":63,"fields":["文艺"],"identity":"歌唱家 · 对外经济贸易大学副教授，《我和你》演唱者","summary":"2008 年 8 月 8 日鸟巢，他和莎拉·布莱曼唱《我和你》，那是几亿人同时听见的八分钟。","bio":"1963 年 8 月生于天津，毕业于北京国际关系学院法国文学专业。1980 年代凭《雪城》主题曲《心中的太阳》、《便衣警察》主题曲《少年壮志不言愁》红遍全国，《弯弯的月亮》《好汉歌》《从头再来》传唱不衰；2008 年 8 月 8 日在北京奥运会开幕式与莎拉·布莱曼演唱主题歌《我和你》。\n\n1991 年 7 月到对外经济贸易大学工作，任艺术教研室教师、副教授，主讲《西方音乐史》，为校歌《UIBE之歌》作曲，2023 年 9 月退休。\n\n2026 年 9 月 25 日上午 9 时 52 分在上海于家人陪伴下病逝，享年 63 岁。遵其遗愿，丧事从简，不举行遗体告别仪式和追悼会。","facts":["2008 年北京奥运会开幕式与莎拉·布莱曼演唱《我和你》","1991 年起在对外经济贸易大学任教三十余年","代表作《好汉歌》《弯弯的月亮》《少年壮志不言愁》","为对外经济贸易大学校歌《UIBE之歌》作曲"],"obit":true,"portrait":"assets/portraits/2026-09-25-183.webp","source":"对外经济贸易大学讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-09-24-182","date":"2026-09-24","name":"游本昌","nameOrig":"","country":"中国","region":"中国大陆","age":93,"fields":["文艺"],"identity":"中国国家话剧院一级演员 · 电视剧《济公》主演，《繁花》爷叔","summary":"「鞋儿破，帽儿破」，52 岁才演到第 80 个角色；90 岁在《繁花》里，他还是那个爷叔。","bio":"1933 年 9 月生于江苏南京。1956 年从上海戏剧学院毕业后进入中央实验话剧院（现中国国家话剧院），此后二十年演的多是没有台词的小角色，「没有小角色，只有小演员」是他的信条。\n\n1984 年他带哑剧《淋浴》登上央视春晚，随后主演电视剧《济公》，「鞋儿破，帽儿破」唱遍全国，他凭此获金鹰奖最佳男主角。2023 年在电视剧《繁花》中饰爷叔，是他最后一部作品。2025 年 5 月被批准为中共预备党员。\n\n2026 年 9 月 24 日凌晨 1 时 40 分在北京逝世，享年 93 岁。女儿说他睡着走的，最后一句话是「我很舒服」。","facts":["1985 年主演电视剧《济公》，获金鹰奖最佳男主角","90 岁出演电视剧《繁花》饰爷叔，为最后一部作品","2025 年 5 月被批准为中共预备党员","告别仪式 2026 年 9 月 30 日在八宝山举行"],"obit":true,"portrait":"assets/portraits/2026-09-24-182.webp","source":"中国国家话剧院讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-09-19-181","date":"2026-09-19","name":"李爱琴","nameOrig":"","country":"中国","region":"中国大陆","age":87,"fields":["文艺"],"identity":"秦腔表演艺术家 · 国家级非遗秦腔代表性传承人，「活周仁」","summary":"《周仁回府》她演了三千多场，加了闪帽翅和长水袖，陕西人从此只认她这一个周仁。","bio":"1939 年生于陕西西安，六岁学艺，早年在西安、凤翔、兴平、泾阳一带搭班演戏，1954 年进入陕西省军区五一剧团（后更名西安市五一剧团），曾任团长，一级演员，国家级非物质文化遗产秦腔项目代表性传承人。\n\n她嗓音浑厚，戏路宽泛，除小生外兼演须生、正旦、老旦，代表作《周仁回府》《生死牌》《孙安动本》《三世仇》。在《周仁回府》中她加入闪帽翅绝技，把短水袖改为长水袖，唱腔融入滚白，此剧演出三千余场，获誉「活周仁」；1991 年徽班进京二百周年纪念演出，她以《悔路》一折被评「一人满台戏」。\n\n2026 年 9 月 19 日与世长辞，享年 87 岁。","facts":["国家级非物质文化遗产秦腔项目代表性传承人","《周仁回府》演出三千余场，获誉「活周仁」","1954 年入陕西省军区五一剧团，后任团长","1991 年徽班进京二百周年献演《悔路》一折"],"obit":true,"portrait":"assets/portraits/2026-09-19-181.webp","source":"今日头条盘点汇编","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-09-19-180","date":"2026-09-19","name":"刘宝珺","nameOrig":"","country":"中国","region":"中国大陆","age":96,"fields":["科技"],"identity":"中国科学院院士 · 沉积地质学家，成都理工大学名誉校长","summary":"他把「风暴流」这个概念第一次带进中国地质学，也把南方的岩相古地理一张一张画了出来。","bio":"1931 年 9 月 13 日生于天津。1953 年毕业于北京地质学院，同年进入地质部 641 地质队；1958 年起在成都地质学院任教，1982 年至 1997 年任地矿部成都地质矿产研究所所长，1991 年当选中国科学院学部委员（院士）。\n\n他把沉积成岩、岩相、构造分析与物理化学热力学相结合，提出「沉积期后分异作用与成矿作用」理论；将流体力学引入沉积学，首先把风暴流概念引入我国，提出扬子地台陆缘寒武纪磷矿风暴岩沉积模式。曾获首届李四光地质科学奖，1996 年获「斯潘迪亚洛夫奖」，是我国首位获此奖的地质学家。\n\n2026 年 9 月 19 日 23 时 14 分在成都逝世，享年 96 岁。","facts":["1991 年当选中国科学院学部委员（院士）","我国首位「斯潘迪亚洛夫奖」获得者","首先把风暴流概念引入我国沉积学研究","著有《岩相古地理基础及方法》《中国南方岩相古地理图集》"],"obit":true,"portrait":"assets/portraits/2026-09-19-180.webp","source":"成都理工大学讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-09-17-179","date":"2026-09-17","name":"邱中建","nameOrig":"","country":"中国","region":"中国大陆","age":93,"fields":["科技"],"identity":"中国工程院院士 · 石油地质专家，大庆油田发现者之一","summary":"1959 年 9 月 26 日松基三井喷出工业油流，井位是他力排众议敲定的，那年他 26 岁。","bio":"1933 年生于江苏南京，原籍四川广安。1953 年从重庆大学地质系毕业，分配到燃料工业部西安地质局。1957 年初，24 岁的他任松辽平原地质专题研究队（116 队）队长，率七人首次进入松辽盆地系统调查，执笔报告判定「松辽盆地是一个含油远景极有希望的地区」。\n\n他力主敲定松基三井井位，1959 年 9 月 26 日该井喷出工业油流，大庆油田由此发现；1982 年「大庆油田发现过程中的地球科学工作」获国家自然科学奖一等奖，他是主要参与者。1974 年他首次提出「复式油气聚集区」理论，1999 年当选中国工程院院士。\n\n2026 年 9 月 17 日在北京逝世，享年 93 岁。","facts":["1957 年率 116 队首次进入松辽盆地系统调查","力主敲定松基三井井位，1959 年 9 月 26 日喷油","1974 年首次提出「复式油气聚集区」理论","2026 年 7 月获光华工程科技成就奖"],"obit":true,"portrait":"assets/portraits/2026-09-17-179.webp","source":"今日头条盘点汇编","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-09-16-178","date":"2026-09-16","name":"胡之璧","nameOrig":"","country":"中国","region":"中国大陆","age":91,"fields":["医药"],"identity":"中国工程院院士 · 中药生物工程学家，上海中医药大学终身教授","summary":"她把植物细胞工程搬进本草里，培育出国际上转化得率最高的洋地黄细胞株——「胡氏细胞株」。","bio":"1934 年 11 月 3 日生于江苏南京，祖籍安徽潜山。1963 年进入中国科学院上海药物研究所，1984 年获德国图宾根大学植物细胞工程专业理学博士；1985 年受聘上海中医学院，同年创建上海中医药大学中药研究所，1994 年当选中国工程院院士，2015 年获聘终身教授。\n\n她是我国中药现代化事业开拓者之一和中药生物工程研究奠基人，率先把基因工程、细胞工程引入中药研究，培育出国际上转化得率最高的洋地黄细胞株即「胡氏细胞株」，主编我国首部《中药现代生物技术》研究生教材。\n\n2026 年 9 月 16 日 17 时 56 分在上海逝世，享年 91 岁。","facts":["1994 年当选中国工程院院士，中药学家","培育出国际上转化得率最高的洋地黄「胡氏细胞株」","主编我国首部《中药现代生物技术》研究生教材","1985 年创建上海中医药大学中药研究所"],"obit":true,"portrait":"assets/portraits/2026-09-16-178.webp","source":"今日头条盘点汇编","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-09-16-177","date":"2026-09-16","name":"吴文伦","nameOrig":"","country":"中国","region":"中国大陆","age":88,"fields":["影视"],"identity":"上影演员剧团演员 · 配音艺术家，《功夫熊猫》乌龟大师国语配音","summary":"「昨天是段历史，明天是个谜团」，这句台词念完，乌龟大师的声音也成了历史。","bio":"1938 年生于上海，籍贯天津。1963 年毕业于上海电影专科学校表演系，进入上海电影制片厂演员剧团，1998 年退休，为上影演员剧团二级演员、上海电影家协会会员。\n\n1962 年进入上海电影译制厂，与邱岳峰、苏秀等同为上译第一代配音演员。银幕上他是上影的「黄金绿叶」，参演《战船台》《秋瑾》《曙光》及电视剧《粉红女郎》，多饰反派；配音作品有《乱世佳人》白瑞德、《生死恋》野岛、《姿三四郎》等。晚年他为《功夫熊猫》乌龟大师献声，「昨天是段历史，明天是个谜团」由此成为一代观众的银幕记忆。\n\n2026 年 9 月 16 日凌晨 3 时 40 分在上海逝世，享年 88 岁。","facts":["上译第一代配音演员之一，与邱岳峰、苏秀同事","《乱世佳人》中白瑞德的国语配音演员","为《功夫熊猫》乌龟大师配音，晚年代表作","上影集团 2026 年 9 月 18 日发布讣告，丧事从简"],"obit":true,"portrait":"assets/portraits/2026-09-16-177.webp","source":"今日头条盘点汇编","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-09-13-176","date":"2026-09-13","name":"敬一丹","nameOrig":"","country":"中国","region":"中国大陆","age":71,"fields":["传媒"],"identity":"央视主持人 · 《焦点访谈》《感动中国》主播","summary":"「敬大姐」在《焦点访谈》里用最平和的语气问最硬的问题，那是九十年代电视的体温。","bio":"1955 年 4 月生于黑龙江哈尔滨，1974 年 7 月加入中国共产党。1988 年入职中央电视台，先后主持《经济半小时》《一丹话题》《东方时空》《焦点访谈》《新闻调查》《感动中国》等栏目。\n\n1994 年，40 岁的她受孙玉胜之邀进入《东方时空》，随后改版出《焦点访谈》，她成了给舆论监督「中和锐度、提供温度」的人；九十年代该节目收视率一度达 35%。她连续三届获金话筒奖，曾任第九、十届全国政协委员与第十一届全国人大代表。\n\n2026 年 6 月在哈尔滨突发急性脑出血，转北京救治近三个月，9 月 13 日凌晨 5 时逝世，享年 71 岁。","facts":["1988 年入职央视，主持《焦点访谈》《感动中国》等栏目","连续三届获全国十佳电视节目主持人金话筒奖","第九、十届全国政协委员，第十一届全国人大代表","2026 年 6 月在哈尔滨突发急性脑出血"],"obit":true,"portrait":"assets/portraits/2026-09-13-176.webp","source":"腾讯新闻","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-09-12-175","date":"2026-09-12","name":"章金云","nameOrig":"","country":"中国","region":"中国大陆","age":84,"fields":["文艺"],"identity":"绍剧表演艺术家 · 艺名「小七龄童」，南派猴戏传人","summary":"19 岁那年他给叔父六龄童当武替，在《孙悟空三打白骨精》里一口气翻了 49 个筋斗。","bio":"1943 年生于浙江绍兴，绍剧名角七龄童（章宗信）次子、六龄童之侄。七岁随父叔学艺，故艺名「小七龄童」；11 岁登台，工武生兼老生，曾师从京剧名伶马小龙、朱宝镇。\n\n1960 年拍摄我国第一部彩色戏曲神话电影《孙悟空三打白骨精》时，19 岁的他担任叔父的武功替身，一口气连翻 49 个筋斗。他在《火焰山》《闹天宫》等猴戏中饰演孙悟空，被誉为「南猴王的正宗传人」；1975 年获绍兴地区专业文艺会演演员一等奖。\n\n2026 年 9 月 12 日中午 12 时 06 分在故乡绍兴离世，享年 84 岁；5 月查出癌症。","facts":["绍剧名角七龄童次子，艺名「小七龄童」","19 岁在《孙悟空三打白骨精》中为六龄童当武替，连翻 49 个筋斗","一级演员，工武生兼老生，被誉为「南猴王的正宗传人」","2026 年 5 月查出癌症，告别仪式 9 月 15 日举行"],"obit":true,"portrait":"assets/portraits/2026-09-12-175.webp","source":"新浪新闻","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-09-11-174","date":"2026-09-11","name":"阿斯特里德公主","nameOrig":"Princess Astrid, Mrs. Ferner","country":"挪威","region":"","age":94,"fields":["军政"],"identity":"挪威公主 · 奥拉夫五世次女，曾任挪威第一夫人","summary":"她送完弟弟哈拉尔五世的国葬，两天后在奥斯陆睡去，是奥拉夫五世最后一个离开的孩子。","bio":"1932 年 2 月 12 日生于奥斯陆，挪威国王奥拉夫五世与王储妃玛塔的次女，哈拉尔五世国王的二姐。1940 年德国入侵挪威后随家人流亡美国。1954 年母亲去世，22 岁的她担任挪威第一夫人，直至 1968 年哈拉尔结婚。\n\n1961 年她与商人约翰·马丁·芬纳恩结婚，育有五个子女，丈夫 2015 年去世。此后数十年持续承担王室公务，晚年依靠轮椅出行。2026 年 9 月 9 日她出席弟弟哈拉尔五世的国葬，两天后于 9 月 11 日凌晨在奥斯陆离世，享年 94 岁。","facts":["1954 年至 1968 年任挪威第一夫人","1961 年与约翰·马丁·芬纳恩结婚，育有五名子女","逝世前两天出席弟弟哈拉尔五世的国葬","葬礼 9 月 23 日在奥斯陆里斯的教堂举行"],"obit":null,"portrait":null,"source":"Pantheon","verified":"confirmed","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Princess_Astrid%2C_Mrs._Ferner"},{"id":"2026-09-08-184","date":"2026-09-08","name":"刘树坤","nameOrig":"","country":"中国","region":"中国大陆","age":86,"fields":["科技"],"identity":"水力学家 · 中国水利水电科学研究院教授级高工，怒江保护倡导者","summary":"2008 年他公布《保护怒江的紧急建议》，一句「只顾水能开发不可取」，让一条江暂停了改造。","bio":"1940 年 4 月生于辽宁沈阳，籍贯山东新泰。1963 年毕业于大连理工大学水利系，1981 年获中国水科院硕士学位后赴日本京都大学做访问学者，1991 年获京都大学工学博士。1983 年起任职中国水科院，历任水力学研究所所长、灾害与环境研究中心总工程师。\n\n他长期从事水灾害数值模拟与大水利战略研究，主持完成海河、黄河、淮河等流域洪泛区风险分析，与周魁一共同倡议筹建水利部减灾研究中心，提出「大水利理论」，著有《中国生态水利建设》。2008 年 2 月他公布《保护怒江的紧急建议》，主张江河的资源、环境与生态价值应同时发挥。\n\n2026 年 9 月 8 日因病逝世，享年 86 岁。","facts":["1991 年获日本京都大学工学博士","与周魁一共同倡议筹建水利部减灾研究中心","2008 年 2 月公布《保护怒江的紧急建议》","著有《中国生态水利建设》，发表论文 200 余篇"],"obit":true,"portrait":null,"source":"财新讣闻","verified":"corrected","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":null},{"id":"2026-09-08-171","date":"2026-09-08","name":"董建华","nameOrig":"","country":"中国","region":"香港","age":89,"fields":["军政"],"identity":"全国政协原副主席 · 香港特区首任行政长官","summary":"1997 年 7 月 1 日凌晨，他在宣誓台上把「香港特别行政区」这几个字第一次念了出来。","bio":"1937 年 5 月生于上海，祖籍浙江舟山，1947 年迁居香港。1960 年毕业于英国利物浦大学，1969 年返港参与家族航运事业，1979 年任东方海外（国际）有限公司主席兼行政总裁。\n\n1985 年任香港基本法咨询委员会委员，1995 年任全国人大香港特区筹委会副主任委员；1997 年 7 月就任香港特别行政区第一任行政长官，2002 年连任。卸任后任第十至十三届全国政协副主席，创立团结香港基金，曾获「一国两制」杰出贡献者国家荣誉称号与大紫荆勋章。\n\n2026 年 9 月 8 日 21 时 57 分因病在香港逝世，享年 89 岁。","facts":["1997 年 7 月就任香港特区第一任行政长官，2002 年连任","连任第十届至十三届全国政协副主席四届","获「一国两制」杰出贡献者国家荣誉称号","1979 年任东方海外（国际）有限公司主席兼行政总裁"],"obit":true,"portrait":"assets/portraits/2026-09-08-171.webp","source":"人民网讣告 / 财新讣闻","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-09-07-173","date":"2026-09-07","name":"李途纯","nameOrig":"","country":"中国","region":"中国大陆","age":66,"fields":["商业"],"identity":"太子奶品牌创始人 · 原湖南太子奶集团董事局主席","summary":"借来二十万入场券，喊出八千八百八十八万元，他用一场豪赌把一瓶乳酸菌卖到三十亿。","bio":"1960 年生于湖南临湘，清华大学经济管理学院首届EMBA。1990 年辞去国企工作南下深圳，1993 年靠印制纪念挂历掘得第一桶金，1996 年在株洲创办太子牛奶厂。\n\n1997 年，在全年销售收入不足 500 万元的情况下，他借钱包下央视黄金时段广告「标王」，砸出 8888 万元，当年拿到 8 亿元订单，「饭前饭后太子奶，天天补充乳酸菌」响彻全国；2007 年销售额达 30 亿元。2008 年资金链断裂，2010 年被批捕，拘禁 15 个月后于 2012 年获检方不起诉；2011 年三元股份与新华联以 7.15 亿元取得太子奶全部股权。\n\n2026 年 9 月 7 日在北京去世，终年 66 岁。","facts":["1997 年以 8888 万元夺得央视广告「标王」，当年获 8 亿元订单","2007 年太子奶销售额达 30 亿元，市占率一度约七成","被拘禁 15 个月后于 2012 年获检方不起诉","2011 年三元股份与新华联以 7.15 亿元取得太子奶全部股权"],"obit":true,"portrait":"assets/portraits/2026-09-07-173.webp","source":"财新讣闻","verified":"corrected","causeOfDeath":null,"wikipedia":null},{"id":"2026-09-06-172","date":"2026-09-06","name":"林行止","nameOrig":"","country":"中国","region":"香港","age":88,"fields":["传媒"],"identity":"《信报》创办人 · 政经专栏作家，「香江第一健笔」","summary":"1973 年他办起香港第一份中文财经报纸，此后每天一篇社评，写了四十八年零二十七天。","bio":"原名林山木，1940 年生于广东澄海，成年后赴港。1960 年代入《明报》任资料搜集员，1965 年赴英国剑桥工业学院攻读经济学，回港后任《明报晚报》副总编辑，主管经济版。\n\n1973 年与妻子骆友梅、罗治平创办全港首份中文财经报纸《信报财经新闻》，1977 年创办《信报财经月刊》。他长期每日撰写社论「政经短评」与《林行止专栏》，半世纪笔耕逾 2000 万字，获《健力士世界纪录》确认为全球连续撰稿时间最长的报章专栏作家。2021 年 7 月 29 日搁笔。\n\n2026 年 9 月 6 日在家人陪同下离世，享年 88 岁。","facts":["1973 年创办全港首份中文财经报纸《信报》","半世纪笔耕逾 2000 万字，获吉尼斯纪录确认为连续撰稿最久的报章专栏作家","2021 年 7 月 29 日结束「四十八年零二十七天」的专栏","2009 年获香港大学名誉社会科学博士"],"obit":true,"portrait":"assets/portraits/2026-09-06-172.webp","source":"财新讣闻","verified":"corrected","causeOfDeath":null,"wikipedia":null},{"id":"2026-09-04-170","date":"2026-09-04","name":"徐广源","nameOrig":"","country":"中国","region":"中国大陆","age":81,"fields":["社科"],"identity":"清东陵文物管理处研究室原主任 · 清代陵寝与后妃研究学者","summary":"他从地宫的泥浆里捧出香妃的头骨，也亲手整理过慈禧的遗体，微博上还有一百五十万粉丝。","bio":"1946 年农历二月初一生于河北遵化马兰峪，满族，母亲是清代守陵人的后代。1977 年进入清东陵文物保管所，后长期任清东陵文物管理处研究室主任。\n\n他先后参加裕陵、慈禧陵、容妃（香妃）等四座地宫的清理：1979 年 10 月在泥浆里用手摸出香妃的头颅骨，1984 年 1 月亲手整理慈禧遗体，前后探视过 20 座地宫。出版《清东陵史话》《清朝二十六后妃》等专著 20 余部，发表论文 60 余篇；也是微博上粉丝超 150 万的科普博主。\n\n2026 年 9 月 4 日凌晨 5 时许在遵化病逝，享年 81 岁。","facts":["1979 年在泥浆中亲手找到香妃头颅骨","1984 年参与清理慈禧内棺并整理遗体","著有《清东陵史话》等专著 20 余部、论文 60 余篇","微博粉丝超 150 万，最后一条发于 2026 年 9 月 1 日"],"obit":true,"portrait":"assets/portraits/2026-09-04-170.webp","source":"财新讣闻","verified":"corrected","causeOfDeath":null,"wikipedia":null},{"id":"2026-09-04-169","date":"2026-09-04","name":"龚爽","nameOrig":"","country":"中国","region":"中国大陆","age":37,"fields":["文艺"],"identity":"中央民族乐团青年女高音 · 金钟奖民族唱法金奖得主","summary":"《长征》里的万霞、《山海情》里的水花，她三十七岁，正是民族声乐最好的年纪。","bio":"1989 年生于湖北十堰，小学时学声乐和二胡，后毕业于中国音乐学院并取得博士研究生学位，师从男高音歌唱家阎维文、理论导师李月红。\n\n她以第十届中国音乐金钟奖民族唱法金奖、第十届与第十一届全国声乐大赛民族组银奖立住脚，同时活跃于歌剧舞台：国家大剧院《长征》中饰万霞，《山海情》饰水花，《金沙江畔》饰卓玛，《二泉》饰彩娣。她演唱的「三月桃花心中开」成为近年传唱度颇高的歌剧选段。\n\n2026 年 9 月 4 日因病医治无效逝世，终年 37 岁。","facts":["第十届中国音乐金钟奖民族唱法金奖","国家大剧院歌剧《长征》中饰万霞","中国音乐学院博士研究生，师从阎维文","2025 年 8 月仍在国家大剧院《丰收中国》音乐会献唱"],"obit":true,"portrait":"assets/portraits/2026-09-04-169.webp","source":"今日头条盘点汇编","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-09-04-167","date":"2026-09-04","name":"苏万华","nameOrig":"","country":"中国","region":"中国大陆","age":85,"fields":["科技"],"identity":"中国工程院院士 · 内燃动力工程专家，天津大学教授","summary":"他带团队做出中国第一台 32 位发动机智能控制单元，把柴油机怎么烧这件事交给了算法。","bio":"1941 年 10 月生于黑龙江佳木斯。1960 年考入天津大学内燃机专业，1968 年研究生毕业后进天津动力机厂任技术员，1977 年应史绍熙教授之邀返校任教，历任内燃机燃烧学国家重点实验室主任，2011 年当选中国工程院院士。\n\n他在国内开创内燃机燃烧控制学科方向，率先独立研发重型柴油机高压共轨智能控制燃油系统，研制出我国第一台 32 位发动机复杂功能智能控制单元；提出「混合率—反应速率协同控制」理论，探索内燃机 60%热效率路径。\n\n2026 年 9 月 4 日 10 时整在天津逝世，享年 85 岁。","facts":["2011 年当选中国工程院院士，内燃动力专家","研制我国第一台 32 位发动机复杂功能智能控制单元","两个国家「973」计划项目首席科学家","在国内开创内燃机燃烧控制学科方向"],"obit":true,"portrait":"assets/portraits/2026-09-04-167.webp","source":"天津大学讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-09-04-166","date":"2026-09-04","name":"管华诗","nameOrig":"","country":"中国","region":"中国大陆","age":87,"fields":["医药"],"identity":"中国工程院院士 · 海洋药物学家，中国海洋大学原校长","summary":"中国第一个现代海洋药物藻酸双酯钠出自他手，他把「蓝色药库」从一句口号做成了一个学科。","bio":"1939 年 8 月生于山东夏津，1964 年从山东海洋学院毕业留校任教，1993 年至 2005 年任青岛海洋大学、中国海洋大学校长，1995 年当选中国工程院院士。\n\n上世纪 80 年代，他带团队研制出我国第一个现代海洋药物藻酸双酯钠（PSS），建立中国第一个海洋特征糖库，主持编纂我国首部大型海洋药物典籍《中华海洋本草》，倡议发起「蓝色药库」战略。曾获国家技术发明奖一等奖、何梁何利科学与技术进步奖。\n\n2026 年 9 月 4 日 11 时 18 分在青岛逝世，享年 87 岁。","facts":["研制我国第一个现代海洋药物藻酸双酯钠（PSS）","主持编纂我国首部海洋药物典籍《中华海洋本草》","1995 年当选中国工程院院士，海洋药物学家","1993—2005 年任中国海洋大学（原青岛海洋大学）校长"],"obit":true,"portrait":"assets/portraits/2026-09-04-166.webp","source":"中国海洋大学讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-09-03-165","date":"2026-09-03","name":"张绪武","nameOrig":"","country":"中国","region":"中国大陆","age":98,"fields":["军政"],"identity":"全国工商联原常务副主席 · 张謇嫡孙，江苏省原副省长","summary":"祖父张謇走后一百年的第十天，这位替祖父守了一辈子史料的嫡孙也走了，孙辈里最后一个。","bio":"1928 年 3 月生于江苏南通，张謇独子张孝若的第六个孩子。1950 年从南通学院纺织科毕业后北上佳木斯，在纺织厂从技术员干到工程师，一去近三十年。\n\n1980 年代南归，历任南通市副市长、江苏省副省长，是南通争取首批沿海开放城市的关键推动者之一；1992 年至 2002 年任全国工商联常务副主席（正部长级），推动「光彩事业」；曾任第八届全国人大常委会委员、第十届全国政协常委。他主编《张謇》大型画传，著有《我的祖父张謇》。\n\n2026 年 9 月 3 日上午 10 时许在北京逝世，享年 98 周岁。","facts":["张謇独子张孝若第六子，张謇孙辈中最后离世者","1992—2002 年任全国工商联常务副主席（正部长级）","著有《我的祖父张謇》，主编《张謇》大型画传","1950 年赴佳木斯纺织厂工作近三十年"],"obit":true,"portrait":"assets/portraits/2026-09-03-165.webp","source":"人民网讣告 / 财新讣闻","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-09-02-164","date":"2026-09-02","name":"陈观泰","nameOrig":"","country":"中国","region":"香港","age":80,"fields":["影视"],"identity":"香港武打演员、导演 · 《马永贞》主演，邵氏功夫片代表人物","summary":"1972 年一部《马永贞》，让香港影坛第一次把镜头对准上海滩，也让他一夜红遍亚洲。","bio":"1945 年 9 月 24 日生于广东，自幼习武，拜入「大圣劈挂门」。1967 年以武行入行，任刘家良、唐佳班的武术指导；1969 年获东南亚国术邀请赛轻重量级冠军。\n\n1972 年主演张彻执导的《马永贞》一战成名，该片在香港影坛首开「上海滩题材」先河。此后出演《刺马》《五虎将》《洪熙官》，1976 年自组大圣影业，执导并主演《少年黄飞鸿之铁猴子》；1990 年与周星驰合演《小偷阿星》。晚年移居广东中山半隐居。\n\n2026 年 9 月 2 日清晨 5 时因脑溢血抢救无效去世，享年 80 岁。","facts":["1969 年东南亚国术邀请赛轻重量级冠军","1972 年《马永贞》首开香港「上海滩题材」先河","1976 年自组大圣影业公司，执导《少年黄飞鸿之铁猴子》","1990 年与周星驰合演《小偷阿星》"],"obit":true,"portrait":"assets/portraits/2026-09-02-164.webp","source":"今日头条盘点汇编","verified":"confirmed","causeOfDeath":"脑溢血","wikipedia":null},{"id":"2026-09-02-163","date":"2026-09-02","name":"刘兆铭","nameOrig":"","country":"中国","region":"香港","age":94,"fields":["影视"],"identity":"香港演员、舞蹈家 · 《倩女幽魂》树妖姥姥，香港现代舞开拓者","summary":"他先是香港现代舞的拓荒者，48 岁被徐克拉进《蝶变》，然后成了所有人心里的树妖姥姥。","bio":"1931 年 10 月 13 日生于香港，籍贯广东鹤山。1960 年代初赴法国戛纳罗莎娜·艾嘉华高等舞蹈学校留学，是首位为法国舞蹈家编舞的华人，曾任职比利时国家芭蕾舞团；1967 年返港从事舞蹈教育，2002 年获香港舞蹈年奖杰出成就奖。\n\n1979 年，48 岁的他受徐克之邀出演《蝶变》方红叶，从此进入影视，代表作有《倩女幽魂》树妖姥姥、83 版《射雕英雄传》一灯大师、《笑傲江湖》岳不群。2013 年获TVB万千光辉演艺人大奖。\n\n2026 年 9 月 2 日傍晚 6 时许在家人陪伴下安详离世，享年 94 岁。","facts":["首位为法国舞蹈家编舞的华人，曾任职比利时国家芭蕾舞团","48 岁出演徐克《蝶变》进入影视圈","2013 年获TVB万千光辉演艺人大奖","2025 年 10 月国庆酒会为最后一次公开亮相"],"obit":true,"portrait":"assets/portraits/2026-09-02-163.webp","source":"新浪新闻","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-09-01-168","date":"2026-09-01","name":"颜世贵","nameOrig":"","country":"中国","region":"中国大陆","age":86,"fields":["传媒"],"identity":"人民日报高级记者 · 驻江苏、北京记者站原站长","summary":"他说记者的办公室不在大楼里，在路上；四个月后妻子走了，他把自己也交了出去。","bio":"1941 年生于江苏建湖，1966 年毕业于南京师范大学中文系，1967 年进入人民日报社，先在总编室做夜班编辑，后入记者部。1980 年筹建驻江苏记者站并任首席记者，1987 年调任驻北京记者站首席记者，1992 年任站长，高级记者，享受国务院政府特殊津贴。\n\n他亲历 1975 年全国农业学大寨会议、1976 年唐山大地震、香港澳门回归等报道；1984 年采写无锡堰桥乡「一包三改」引发广泛关注。2019 年获「全国离退休干部先进个人」称号。2026 年 4 月妻子去世后他日渐消瘦，9 月 1 日下午在北京中日友好医院病逝，享年 86 岁。","facts":["1980 年筹建人民日报驻江苏记者站并任首席记者","1984 年报道无锡堰桥乡「一包三改」引发广泛关注","2019 年获「全国离退休干部先进个人」称号","1997 年当选北京市第十一届人大代表"],"obit":true,"portrait":null,"source":"财新讣闻","verified":"corrected","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":null},{"id":"2026-09-01-162","date":"2026-09-01","name":"玛拉沁夫","nameOrig":"","country":"中国","region":"中国大陆","age":97,"fields":["文艺"],"identity":"蒙古族作家 · 《敖包相会》词作者，中国作协原党组副书记","summary":"「十五的月亮升上了天空」，这句词从 1952 年的电影里一直唱到今天，写它的人走了。","bio":"1930 年 8 月生于内蒙古卓索图盟土默特旗（今辽宁阜新蒙古族自治县），蒙古族。历任内蒙古文工团创作员、《草原》主编、内蒙古文联副主席、《民族文学》主编，1989 年至 1995 年任中国作协党组副书记、书记处常务书记。\n\n著有短篇小说《科尔沁草原的人们》、长篇小说《茫茫的草原》、电影剧本《草原晨曲》《祖国啊，母亲》，写有歌词《敖包相会》。他牵头创办《民族文学》《草原》，推动建立全国少数民族文学创作会议与骏马奖。\n\n2026 年 9 月 1 日 17 时 32 分在北京逝世，享年 97 岁。","facts":["长篇小说《茫茫的草原》、短篇小说《科尔沁草原的人们》","牵头创办《民族文学》《草原》杂志","歌词《敖包相会》《草原晨曲》词作者","获中国文联终身成就电影艺术家称号"],"obit":true,"portrait":"assets/portraits/2026-09-01-162.webp","source":"多家媒体","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-09-01-161","date":"2026-09-01","name":"李廷栋","nameOrig":"","country":"中国","region":"中国大陆","age":96,"fields":["科技"],"identity":"中国科学院院士 · 区域地质与深部地质学家，中国地质科学院原院长","summary":"他把中国的区域地质志编成一部「百科全书」，也让《亚洲地质图》第一次由中国人主持绘出。","bio":"1930 年 10 月 7 日生于河北栾城，1953 年毕业于北京地质学院后进入地质部，历任中国地质科学院院长、地质矿产部副总工程师，1993 年当选中国科学院院士。\n\n他一生致力于区域地质、深部地质和综合地质编图，足迹遍及南北极地，创建中国岩石圈三维结构模型；主持编制《亚洲地质图》《亚欧地质图》，领衔出版《新一代中国区域地质志》，被誉为中国地质的「百科全书」。曾获国家自然科学奖一等奖、李四光地质科学奖荣誉奖。\n\n2026 年 9 月 1 日 12 时 35 分在北京逝世，享年 96 岁。","facts":["1993 年当选中国科学院学部委员（院士）","中国地质科学院原院长、地质矿产部副总工程师","主持编制《亚洲地质图》《亚欧地质图》","创建中国岩石圈三维结构模型，重塑大地构造格局"],"obit":true,"portrait":"assets/portraits/2026-09-01-161.webp","source":"中国地质科学院讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-09-01-160","date":"2026-09-01","name":"何勇","nameOrig":"","country":"中国","region":"中国大陆","age":57,"fields":["文艺"],"identity":"摇滚歌手 · 魔岩三杰之一，《钟鼓楼》演唱者","summary":"海魂衫、蓝白条纹、《垃圾场》，1994 年红磡那一夜之后，中国摇滚再没有那样一场演唱会。","bio":"1969 年 2 月 15 日生于北京，6 岁起随父亲何玉生学音乐。1991 年签约大地唱片，1994 年转投魔岩文化，发表首张专辑《垃圾场》（《麒麟日记》），代表作《钟鼓楼》《姑娘漂亮》。\n\n1994 年 12 月 17 日，他与窦唯、张楚赴香港红磡体育馆参加「摇滚中国乐势力」演唱会，成为华语摇滚的标志性事件。此后多年受疾病困扰，鲜少公开露面。2026 年 9 月 1 日下午因突发意外在北京去世，享年 57 岁，9 月 5 日其女儿发布讣告。","facts":["1969 年 2 月 15 日生于北京，6 岁随父亲何玉生学音乐","1994 年 12 月 17 日红磡「摇滚中国乐势力」演唱会，与窦唯、张楚同台","首张专辑《垃圾场》（《麒麟日记》）1994 年发行","代表作《钟鼓楼》《姑娘漂亮》，传唱至今"],"obit":true,"portrait":"assets/portraits/2026-09-01-160.webp","source":"多家媒体","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-08-31-159","date":"2026-08-31","name":"阿达·约纳特","nameOrig":"Ada Yonath","country":"以色列","region":"","age":87,"fields":["科技"],"identity":"以色列晶体学家 · 2009 年诺贝尔化学奖得主","summary":"所有人都说核糖体结晶不了，她试了成千上万次，最终把细胞里那台最复杂的机器拍了出来。","bio":"1939 年 6 月 22 日生于耶路撒冷，父亲是拉比，家境拮据。1962 年与 1964 年在希伯来大学分获化学学士与生物化学硕士，1968 年在魏茨曼科学研究所获 X 射线晶体学博士学位，1970 年在那里组建了以色列第一个蛋白质晶体学实验室。\n\n1970 年代末她开始挑战核糖体结晶，当时学界普遍认为这种庞大而不稳定的结构无法结晶。经年累月的尝试之后，她的研究揭示了核糖体的原子结构与工作机制。2008 年获欧莱雅—联合国教科文组织世界杰出女科学家成就奖，2009 年与拉马克里希南、施泰茨共获诺贝尔化学奖，成为首位获得科学类诺贝尔奖的中东女性。2026 年 8 月 31 日去世。","facts":["2009 年与拉马克里希南、施泰茨共获诺贝尔化学奖","1970 年在魏茨曼科学研究所组建以色列第一个蛋白质晶体学实验室","2006 年获沃尔夫化学奖，2008 年获世界杰出女科学家成就奖","首位获得科学类诺贝尔奖的中东女性"],"obit":null,"portrait":"assets/portraits/2026-08-31-159.webp","source":"Pantheon","verified":"confirmed","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Ada_Yonath"},{"id":"2026-08-30-158","date":"2026-08-30","name":"王永炎","nameOrig":"","country":"中国","region":"中国大陆","age":87,"fields":["医药"],"identity":"中国工程院院士 · 中医内科学家 · 中医脑病专家","summary":"他提出用「通腑化痰法」治中风急性期，那套诊疗与疗效评定标准在临床上用了三十多年。","bio":"1938 年 9 月 29 日生于天津，1956 年考入北京中医学院医疗系，是该校第一届毕业生。1962 年进入北京中医学院东直门医院；1997 年当选中国工程院院士并出任北京中医药大学校长，1998 至 2001 年任中国中医研究院院长，后任中国中医科学院名誉院长。\n\n他创新提出「通腑化痰法」治疗中风急性期痰热腑实证，主持制定的《中风病中医诊断与疗效评定标准》沿用三十余年；1985 年在全国率先推行「弹性学期」与大规模选修课，还主持「方剂关键科学问题的基础研究」973 项目，2014 年获中国标准化终身成就奖。2026 年 8 月 30 日 16 时 25 分在北京逝世。","facts":["1997 年当选中国工程院院士，同年出任北京中医药大学校长","主持制定的《中风病中医诊断与疗效评定标准》沿用三十余年","主持「方剂关键科学问题的基础研究」973 项目，2014 年获中国标准化终身成就奖","北京中医学院（今北京中医药大学）第一届毕业生"],"obit":true,"portrait":"assets/portraits/2026-08-30-158.webp","source":"中国中医科学院讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-08-28-156","date":"2026-08-28","name":"李维康","nameOrig":"","country":"中国","region":"中国大陆","age":79,"fields":["文艺"],"identity":"京剧表演艺术家 · 旦角 · 国家级非遗传承人","summary":"梅、程、张几派的腔被她拆开重新熔过，落成梨园公认的「金嗓」，《蝶恋花》里的杨开慧是注脚。","bio":"1947 年 2 月生于北京。12 岁登台，先后师承程玉菁、华慧麟、赵桐珊、李香匀、雪艳琴、荀令香、于玉蘅、张君秋、李玉茹等名家，1958 年考入中国戏曲学校，毕业后进入中国京剧院。\n\n她把梅兰芳、程砚秋、张君秋等流派的声腔熔于一炉，以情带唱，形成了清丽脱俗的个人风格，有「金嗓」之称。代表作包括《蝶恋花》中的杨开慧、《李清照》《恩仇恋》《秦香莲》《四郎探母》，并在电视剧《四世同堂》中饰韵梅。她曾任中国京剧院二团团长，获中国戏剧梅花奖、梅兰芳金奖大赛旦角组金奖。2026 年 8 月 28 日凌晨在北京病逝。","facts":["获中国戏剧梅花奖、梅兰芳金奖大赛旦角组金奖","国家级非物质文化遗产项目京剧代表性传承人，一级演员","《蝶恋花》饰杨开慧，另演《李清照》《恩仇恋》《四郎探母》","电视剧《四世同堂》中饰韵梅，曾任中国京剧院二团团长"],"obit":true,"portrait":"assets/portraits/2026-08-28-156.webp","source":"媒体盘点","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-08-28-155","date":"2026-08-28","name":"哈拉尔五世","nameOrig":"Harald V","country":"挪威","region":"","age":89,"fields":["军政"],"identity":"挪威国王 · 1991 年继位 · 欧洲在位最久","summary":"1991 年继承王位，在位三十五年，是欧洲最年长、也是在位最久的国家元首。","bio":"1937 年 2 月 21 日生于奥斯陆附近的斯考古姆，1957 年被立为王储，1991 年 1 月继承王位。他是第一位在挪威本土完成基础教育的国王，后赴牛津大学贝利奥尔学院学习，通晓挪威语、英语和瑞典语。\n\n在位三十五年，他以亲民著称，长期支持挪威的体育、极地科考与音乐事业，多次代表国家出访；一个多月前他还在王宫接见哈兰德、厄德高等挪威世界杯球员。晚年健康屡屡告急，曾因心脏手术与呼吸问题多次住院。2026 年 8 月，他因溶血性贫血入住奥斯陆大学医院，病情突然恶化，于 8 月 28 日上午 6 时 35 分去世。按挪威王位继承规则，53 岁的王储哈康即时继位。","facts":["1991 年 1 月继承王位，在位三十五年，为欧洲在位最久的君主","第一位在挪威本土完成基础教育的国王，曾就读牛津大学贝利奥尔学院","去世前因溶血性贫血在奥斯陆大学医院住院一周余","王储哈康于同日继位，成为挪威新国王"],"obit":null,"portrait":"assets/portraits/2026-08-28-155.webp","source":"Pantheon","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-08-27-154","date":"2026-08-27","name":"拉特科·姆拉迪奇","nameOrig":"Ratko Mladić","country":"波黑","region":"","age":84,"fields":["军政"],"identity":"波黑塞族军队司令 · 被判终身监禁的战犯","summary":"1995 年 7 月，他指挥的部队在斯雷布雷尼察处决了近八千名穆斯林男子和未成年男孩。","bio":"1942 年 3 月 12 日生于波斯尼亚东部，1965 年起在南斯拉夫人民军服役，逐步升到高阶职位。1992 年 5 月他脱离南斯拉夫人民军，出任新成立的波黑塞族共和国军总参谋长，在 1992 至 1995 年的波黑战争中指挥部队围困萨拉热窝数年。\n\n1995 年 7 月，他的部队在斯雷布雷尼察屠杀近八千名穆斯林族男子及未成年男孩，这是二战后欧洲最惨重的大屠杀。他逃亡十六年，2011 年 5 月在塞尔维亚被捕并引渡至海牙；2017 年 11 月前南刑庭裁定其种族灭绝罪、危害人类罪、战争罪成立，判处终身监禁，2021 年 6 月终审维持原判。2026 年 8 月 27 日在海牙联合国拘留所医院去世。","facts":["2017 年 11 月被前南刑庭判处终身监禁，2021 年 6 月终审维持原判","逃亡十六年，2011 年 5 月在塞尔维亚被捕并引渡至海牙","1995 年 7 月斯雷布雷尼察屠杀近八千名穆斯林男子与男孩","2026 年 8 月 27 日在海牙联合国拘留所医院病逝"],"obit":null,"portrait":null,"source":"Pantheon","verified":"confirmed","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Ratko_Mladi%C4%87"},{"id":"2026-08-25-157","date":"2026-08-25","name":"陆元鼎","nameOrig":"","country":"中国","region":"中国大陆","age":97,"fields":["科技"],"identity":"建筑学家 · 华南理工大学教授 · 民居研究奠基者","summary":"1990 年他出版《广东民居》，用「民系」把广府、客家、闽海、湘赣的屋子串成了一套理论。","bio":"1929 年 10 月生于上海，祖籍苏州。1948 年考入广州国立中山大学工学院建筑工程系，1952 年毕业后在新组建的华南工学院建筑系任教，1990 年起任博士生导师，是首批国家一级注册建筑师。\n\n他毕生研究中国传统民居。1990 年出版《广东民居》，首创以「民系」划分研究传统民居的理论与方法，揭示广府、客家、闽海、湘赣民系民居与族群文化的内在关联。1988 年他在华南工学院组织首届中国民居学术会议。主编《中国民居建筑》三卷获第十四届中国图书奖，主持的从化钱岗村广裕祠修缮获联合国教科文组织亚太地区文化遗产保护杰出奖。2026 年 8 月 25 日在广州病逝。","facts":["1990 年出版《广东民居》，首创以「民系」研究传统民居的理论与方法","1988 年在华南工学院组织首届中国民居学术会议","主编《中国民居建筑》三卷获第十四届中国图书奖","主持从化钱岗村广裕祠修缮，获联合国教科文组织亚太文化遗产保护杰出奖"],"obit":true,"portrait":"assets/portraits/2026-08-25-157.webp","source":"财新讣闻","verified":"corrected","causeOfDeath":null,"wikipedia":null},{"id":"2026-08-25-152","date":"2026-08-25","name":"多莉·帕顿","nameOrig":"Dolly Parton","country":"美国","region":"","age":80,"fields":["文艺"],"identity":"美国乡村歌手、词曲作者 · 乡村音乐「女王」","summary":"《Jolene》与《I Will Always Love You》都出自她手，后者被休斯顿唱红全球。","bio":"1946 年 1 月 19 日生于田纳西州一个十二个孩子的贫寒家庭。五岁能作曲，十岁上电视，十三岁在路易斯安那州莱克查尔斯的 Goldband 唱片录下第一支单曲《Puppy Love》。\n\n她一生创作近三千首歌，在《公告牌》乡村榜上有二十六首冠军单曲，获十座格莱美奖及录音学院终身成就奖。《Jolene》与《I Will Always Love You》都是她写的。1986 年她买下故乡的游乐园并扩建为「多莉山」，成为带动当地经济的引擎。2026 年 8 月 25 日在纳什维尔去世，此前因肾脏免疫问题住院，与癌症短暂抗争过。特朗普宣布全美降半旗一周。","facts":["十座格莱美奖、二十六首《公告牌》乡村榜冠军单曲，创作近三千首歌","十三岁在路易斯安那州莱克查尔斯录下首支单曲《Puppy Love》","1986 年在故乡扩建「多莉山」主题乐园","去世后特朗普下令全美降半旗一周致哀"],"obit":null,"portrait":"assets/portraits/2026-08-25-152.webp","source":"路易斯安那州政府行政令","verified":"confirmed","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Dolly_Parton"},{"id":"2026-08-24-151","date":"2026-08-24","name":"陈一坚","nameOrig":"","country":"中国","region":"中国大陆","age":96,"fields":["科技"],"identity":"中国工程院院士 · 歼轰-7「飞豹」总设计师","summary":"没有样机、没有参考型号，他把设计规范对接国际标准，「飞豹」成了国内最早用计算机辅助设计的机种之一。","bio":"1930 年 6 月生于福建福州，1952 年参加工作，1959 年入党。先后任国营 122 厂、112 厂设计科设计组长，601 所机身室主任，603 所副所长与总设计师，1999 年 12 月当选中国工程院院士。\n\n1982 年他被任命为歼轰-7（代号「飞豹」）总设计师，这是中国第一款歼击轰炸机，既无样机也无参考型号。他力主设计规范与国际接轨，五十多岁靠自学编写出飞机设计运算程序，使「飞豹」成为国内最早开展计算机辅助设计的机种之一。1998 年定型，1999 年获国家科技进步奖特等奖。他还为歼教 1、初教 6、强 5、运 7 等型号倾注心血。2026 年 8 月 24 日 7 时 50 分在西安逝世。","facts":["1982 年任歼轰-7「飞豹」总设计师，1998 年定型","1999 年获国家科技进步奖特等奖，同年 12 月当选中国工程院院士","曾为歼教 1、初教 6、强 5、运 7 等型号设计研制作出贡献","「飞豹」是国内最早开展计算机辅助设计的机种之一"],"obit":true,"portrait":"assets/portraits/2026-08-24-151.webp","source":"光明日报","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-08-23-153","date":"2026-08-23","name":"唐师曾","nameOrig":"","country":"中国","region":"中国大陆","age":65,"fields":["传媒"],"identity":"新华社摄影记者 · 战地记者 · 《我从战场归来》","summary":"1990 年他一个人钻进伊拉克，把海湾战争拍给中国人看，后来那些辐射让他的白血球几乎归零。","bio":"1961 年生于北京，祖籍江苏无锡，毕业于北京大学国际政治系。1983 年在中国政法大学任教，1986 年考入新华社任摄影记者。1990 年他潜入伊拉克报道海湾战争；1991 至 1993 年任新华社驻中东记者，专访过卡扎菲、阿拉法特、拉宾、沙龙、曼德拉等人。\n\n1998 年，因长期受辐射影响，他罹患再生障碍性贫血，此后二十多年与病痛共处。他提出摄影的「语像」理念：作者不对自己拍下的照片作任何提示，让读者独立解读。战地作品结集为《我从战场归来》《我钻进了金字塔》《重返巴格达》三部曲。2025 年底从新华社退休，2026 年 8 月 23 日 12 时 03 分在北京病逝。","facts":["1990 年潜入伊拉克报道海湾战争，1991 至 1993 年任新华社驻中东记者","1998 年因辐射罹患再生障碍性贫血，此后长期与病痛抗争","著有《我从战场归来》《我钻进了金字塔》《重返巴格达》战地三部曲","2025 年底从新华社退休，次年 8 月 23 日去世"],"obit":true,"portrait":"assets/portraits/2026-08-23-153.webp","source":"财新讣闻","verified":"corrected","causeOfDeath":null,"wikipedia":null},{"id":"2026-08-15-150","date":"2026-08-15","name":"马宗晋","nameOrig":"","country":"中国","region":"中国大陆","age":93,"fields":["科技"],"identity":"中科院院士 · 地质学家 · 地震预报体系奠基人","summary":"他构建的「长、中、短、临」渐进式预报模式，在中国地震预报的流程表上用了三十多年。","bio":"1933 年 1 月 4 日生于吉林长春。1955 年毕业于北京地质学院普查系，1957 年起在中国科学院地质研究所读研究生，1961 年留所工作，1966 年转入地震系统。1988 年调入地质研究所，曾任所长、名誉所长，1991 年当选中国科学院学部委员。\n\n他确立岩石节理定性、分期、配套的原则与方法，构建「长、中、短、临」渐进式地震蕴育模式与工作程序，提出全球三大构造系统与非稳态、非对称地球动力模型；还率先提出灾害的自然与社会双重属性及灾度概念，开创中国自然灾害综合研究这一领域。曾获首届李四光地质科学奖、国家科技进步奖二等奖。2026 年 8 月 15 日 8 时 35 分在北京病逝。","facts":["构建「长、中、短、临」渐进式地震蕴育模式，沿用至今","率先提出灾害的自然与社会双重属性及「灾度」概念","作为首席科学家设计中国地壳运动观测网络","获首届李四光地质科学奖、国家科技进步奖二等奖、全国劳动模范"],"obit":true,"portrait":"assets/portraits/2026-08-15-150.webp","source":"中国地震局地质研究所讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-08-15-149","date":"2026-08-15","name":"周育德","nameOrig":"","country":"中国","region":"中国大陆","age":88,"fields":["社科"],"identity":"戏曲理论家 · 中国戏曲学院原院长 · 汤显祖专家","summary":"他校点了《古柏堂戏曲集》，写了《汤显祖论稿》，把中国戏曲当成一门学问，而不只是一门手艺。","bio":"1938 年 11 月生于山东平度。1961 年 7 月毕业于杭州大学中文系，1978 年进入中国艺术研究院，师从张庚、郭汉城攻读戏曲专业研究生，1982 年获戏剧学硕士，后留院任研究员、研究生部副主任。1996 年出任中国戏曲学院院长，2001 年 8 月退休。\n\n他兼任中国戏剧家协会理事、中国戏曲学会副会长、《中国戏曲志》编委、汤显祖研究会会长。著有《中国戏曲文化》《汤显祖论稿》《昆曲与明清社会》《中国戏曲史略》，校点《古柏堂戏曲集》《消寒新咏》，其中《中国戏曲文化》获文化部第一届文化艺术科学优秀成果奖。2026 年 8 月 15 日凌晨在睡眠中去世。","facts":["1996 至 2001 年任中国戏曲学院院长，此前任中国艺术研究院研究员","著有《中国戏曲文化》《汤显祖论稿》《昆曲与明清社会》","校点《古柏堂戏曲集》《消寒新咏》，任《中国戏曲志》编委","师从张庚、郭汉城，1982 年获中国艺术研究院戏剧学硕士"],"obit":true,"portrait":"assets/portraits/2026-08-15-149.webp","source":"中国戏曲学院","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-08-14-148","date":"2026-08-14","name":"草间弥生","nameOrig":"Yayoi Kusama","country":"日本","region":"","age":97,"fields":["文艺"],"identity":"日本艺术家 · 波点与南瓜 · 文化勋章获得者","summary":"十岁起折磨她的幻视变成了无数的点，她把它们画了一辈子，最后画成了直岛海边那只黄南瓜。","bio":"1929 年 3 月 22 日生于长野县松本市一个经营种苗业的家庭。十岁左右她开始出现幻视与幻听，看到桌布上的红花爬满墙壁和柱子，整个人像要被抹掉；为从这种恐惧里逃出来，她开始画画，波点与无限网从此成了她一生的母题。\n\n1957 年她赴美，在纽约投身前卫艺术，以巨幅「无限之网」绘画、软雕塑、镜屋装置和街头身体彩绘引起注意。1973 年因健康回国，1977 年起住进东京的精神疗养院，在院旁设工作室，每天像上班一样创作。1993 年代表日本参加威尼斯双年展，2016 年获日本文化勋章。2026 年 8 月 14 日因多器官衰竭在东京一家医院去世，事务所 8 月 27 日公布。","facts":["1957 年赴美，在纽约以「无限之网」绘画与街头身体彩绘成名","1977 年起长住东京精神疗养院，在院旁设工作室持续创作","1993 年代表日本参加威尼斯双年展，2016 年获日本文化勋章","香川县直岛海边的黄南瓜雕塑成为其标志性公共作品"],"obit":null,"portrait":"assets/portraits/2026-08-14-148.webp","source":"Pantheon","verified":"confirmed","causeOfDeath":"多器官衰竭","wikipedia":"https://en.wikipedia.org/wiki/Yayoi_Kusama"},{"id":"2026-08-13-147","date":"2026-08-13","name":"马忠智","nameOrig":"","country":"中国","region":"中国大陆","age":82,"fields":["军政"],"identity":"中国证监会原党委委员 · 监事会主席（副部长级）","summary":"1992 年他负责组建国务院证券委员会办公室，中国资本市场最早那几块地砖里有一块是他铺的。","bio":"1944 年 1 月 15 日生于辽宁沈阳，高级经济师。1964 年参加银行工作，做过信贷员、科长、副处长。1984 年 7 月任中国人民银行沈阳市分行副行长，兼国家外汇管理局沈阳分局副局长。\n\n1991 年调入中国人民银行总行任证券管理办公室副主任，兼任中国证券业协会秘书长至 1998 年末。1992 年 10 月他负责组建国务院证券委员会办公室并任副主任主持工作，1995 年任主任。1997 年 9 月中国证监会成立首届党组时兼任党组成员，1998 年 11 月任国务院稽察特派员，2000 年 6 月过渡为国有重点大型企业监事会主席，2007 年 6 月退休。2026 年 8 月 13 日 10 时 38 分在北京逝世。","facts":["1992 年 10 月负责组建国务院证券委员会办公室，1995 年任主任","1998 年 11 月任国务院稽察特派员，2000 年转任国有重点大型企业监事会主席","1993 年被中国人民银行授予国家部委级「有突出贡献中青年专家」称号","著有《日本证券市场考察与思考》，主编参编证券类书籍二十余种"],"obit":true,"portrait":"assets/portraits/2026-08-13-147.webp","source":"财新讣闻","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-08-12-144","date":"2026-08-12","name":"王希季","nameOrig":"","country":"中国","region":"中国大陆","age":105,"fields":["科技"],"identity":"中科院院士 · 「两弹一星」元勋 · 空间技术专家","summary":"他提出长征一号的技术方案，主持多颗返回式卫星，让中国成为第三个掌握卫星返回技术的国家。","bio":"1921 年 7 月 26 日生于云南昆明。1942 年毕业于西南联合大学机械系，1949 年在美国弗吉尼亚理工学院获动力及燃料专业硕士学位，1950 年回国，先后任教于大连工学院、上海交通大学。1958 年他奉调上海机电设计院，才知道要做的是运载火箭和卫星，那一年他 37 岁。\n\n他是中国第一枚液体燃料探空火箭的技术负责人，提出第一枚运载火箭的技术方案，主持长征一号方案阶段与核试验取样系列火箭的研制。1968 年调入五院，任返回式系列卫星总设计师，使中国成为世界上第三个自主掌握卫星返回技术的国家。1999 年获「两弹一星功勋奖章」。2026 年 8 月 12 日 15 时 38 分在北京逝世。","facts":["中国第一枚液体燃料探空火箭技术负责人，提出长征一号运载火箭技术方案","任返回式系列卫星总设计师，中国成为第三个掌握卫星返回技术的国家","1999 年获「两弹一星功勋奖章」，为 23 位获得者之一","1950 年从美国弗吉尼亚理工学院归国，1958 年转入航天领域时年 37 岁"],"obit":true,"portrait":"assets/portraits/2026-08-12-144.webp","source":"新京报","verified":"corrected","causeOfDeath":null,"wikipedia":null},{"id":"2026-08-12-143","date":"2026-08-12","name":"朱镕基","nameOrig":"","country":"中国","region":"中国大陆","age":98,"fields":["军政"],"identity":"国务院原总理 · 第十四、十五届中央政治局常委","summary":"1998 年他说「不管前面是地雷阵还是万丈深渊」，随后主持了那场牵动千万人的财税与国企改革。","bio":"1928 年 10 月生于湖南长沙。1947 至 1951 年在清华大学电机系电机制造专业学习。1951 年起在东北工业部、国家计划委员会工作近二十年，1970 年下放国家计委「五七」干校，1975 年后在石油工业部管道局、中国社会科学院工业经济研究所任职。\n\n1979 年进入国家经济委员会，1983 年任国家经委副主任。1987 年赴上海，历任市委副书记、市长、市委书记。1991 年任国务院副总理，1992 年起任第十四、十五届中央政治局常委，1998 年 3 月至 2003 年 3 月任国务院总理，任内推动分税制、金融与国企改革，应对亚洲金融危机。2026 年 8 月 12 日 11 时 06 分在北京逝世。","facts":["1998 年 3 月至 2003 年 3 月任国务院总理","1987 至 1991 年历任上海市委副书记、市长、市委书记","任内推动分税制、金融体制与国企改革，应对亚洲金融危机","1928 年 10 月生于湖南长沙，1951 年毕业于清华大学电机系"],"obit":true,"portrait":"assets/portraits/2026-08-12-143.webp","source":"人民网·中国共产党新闻网讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-08-11-142","date":"2026-08-11","name":"郭兰英","nameOrig":"","country":"中国","region":"中国大陆","age":97,"fields":["文艺"],"identity":"歌剧表演艺术家 · 《我的祖国》原唱","summary":"「一条大河波浪宽」，1956 年她为《上甘岭》配唱，这几句从此成了几代中国人的合唱。","bio":"1930 年 12 月 31 日生于山西平遥，四岁被卖入戏班，十三岁在太原、张家口登台唱晋剧，青衣、花旦、刀马旦皆能。1946 年她离开戏班参加华北联大文工团，1948 年在石家庄首演《白毛女》中的喜儿，从此转向新歌剧。\n\n1953 年她在《小二黑结婚》中饰小芹，1956 年为电影《上甘岭》配唱《我的祖国》。1963 年她举办个人独唱音乐会，开民族声乐独唱会的先例。1986 年在广东番禺创办郭兰英艺术学校。2019 年被授予「人民艺术家」国家荣誉称号。2026 年 8 月 11 日 17 时 14 分在广州病逝，遗愿不设灵堂、不举行追悼会。","facts":["1956 年为电影《上甘岭》配唱《我的祖国》，另有《南泥湾》《人说山西好风光》","2019 年获「人民艺术家」国家荣誉称号与「最美奋斗者」称号","四岁入戏班，十三岁成名于晋剧舞台，1948 年首演《白毛女》喜儿","1986 年在广东番禺创办郭兰英艺术学校，任校长"],"obit":true,"portrait":"assets/portraits/2026-08-11-142.webp","source":"腾讯新闻","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-08-11-141","date":"2026-08-11","name":"约翰·欧文","nameOrig":"John Irvin","country":"英国","region":"","age":86,"fields":["影视"],"identity":"英国电影导演 · 剧版《锅匠、裁缝、士兵、间谍》","summary":"他让亚历克·吉尼斯在镜头前把一句已经说完的回答再咽回去，那七小时拿下两座 BAFTA。","bio":"1940 年 5 月 7 日生于默西塞德郡沃勒西，先后就读达勒姆学校和伦敦电影学校，1963 年起以纪录片起家。1979 年他为 BBC 执导约翰·勒卡雷《锅匠、裁缝、士兵、间谍》的七小时电视剧，亚历克·吉尼斯主演，拿下两座 BAFTA。\n\n1980 年代他转向好莱坞，接连拍了《战争猛犬》《Ghost Story》《魔鬼司令》《汉堡高地》《近亲》。1990 年代后有《罗宾汉》《当号角吹响》《Shiner》《月亮和星星》，最后一部剧情片是 2016 年讲曼德拉早年游击生涯的《曼德拉的枪》。他三度获 BAFTA 提名。2026 年 8 月 11 日在英格兰他嫂子家中、家人陪伴下去世。","facts":["1979 年为 BBC 执导七小时剧版《锅匠、裁缝、士兵、间谍》，获两座 BAFTA","1980 年代在好莱坞拍《战争猛犬》《魔鬼司令》《汉堡高地》","三度获 BAFTA 提名，职业生涯跨 1963 至 2016 年","最后一部剧情片为 2016 年的《曼德拉的枪》"],"obit":null,"portrait":"assets/portraits/2026-08-11-141.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/John_Irvin"},{"id":"2026-08-10-140","date":"2026-08-10","name":"罗锦鳞","nameOrig":"","country":"中国","region":"中国大陆","age":89,"fields":["影视"],"identity":"戏剧导演 · 中戏教授 · 古希腊戏剧引入者","summary":"1986 年他把父亲罗念生译的《俄狄浦斯王》搬上中国舞台，古希腊悲剧第一次在这里正式公演。","bio":"1937 年 1 月 5 日生于北京，祖籍四川威远。父亲罗念生是中国古希腊文学翻译的奠基人。1956 年他考入中央戏剧学院导演系，受欧阳予倩「不懂戏曲，难成中国导演」的影响，系统研习戏曲身段与工尺谱，1961 年留校任教，在中戏讲台站了六十余年，曾任导演系主任、副院长。\n\n1986 年他执导父亲翻译的《俄狄浦斯王》，这是中国舞台第一部正式公演的古希腊悲剧，并赴希腊德尔菲国际古希腊戏剧节演出。此后又排了《安提戈涅》《特洛亚妇女》《鸟》等十余部。1989 年创排河北梆子《美狄亚》，用戏曲帮腔对应古希腊歌队，海外巡演二百五十余场。2026 年 8 月 10 日 16 时在河北病逝。","facts":["1986 年执导《俄狄浦斯王》，为中国舞台首部正式公演的古希腊悲剧","1989 年创排河北梆子《美狄亚》，海外巡演二百五十余场","曾任中央戏剧学院导演系主任、副院长，享受国务院特殊津贴","2009 年获希腊雅典州政府「希腊文化大使」称号"],"obit":true,"portrait":"assets/portraits/2026-08-10-140.webp","source":"搜狐文化","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-08-10-139","date":"2026-08-10","name":"秦焰","nameOrig":"","country":"中国","region":"中国大陆","age":72,"fields":["文艺"],"identity":"中国铁路文工团话剧演员 · 金牌配角","summary":"他是《狂飙》里藏在赵立冬背后的何黎明，也是《编辑部的故事》里那个上门推销冰箱的莫怀远。","bio":"1954 年 9 月 20 日生于北京。初中毕业被分配到北京电子管厂当工人，1976 年后进厂宣传队演节目，1979 年考入北京市文工团成为专业话剧演员，1984 年底调入中国铁路文工团话剧团。舞台上是当仁不让的主角，与陈佩斯搭档过《托儿》，独角戏《我爱抬杠》被同行视作标杆，2006 年获第五届中国话剧金狮奖表演奖。\n\n1983 年他在《城南旧事》里演宋妈的侄子，1991 年以《编辑部的故事》中的冰箱推销员莫怀远进入影视圈。此后是《红高粱》里的黑眼、《知否知否应是绿肥红瘦》里一直病着的老皇帝、《狂飙》里的何黎明、《庆余年第二季》里的戴公公。2026 年 8 月 10 日病逝。","facts":["2006 年获第五届中国话剧金狮奖表演奖，1991 年获第二届中国话剧振兴奖","独角戏《我爱抬杠》被视作话剧界标杆，与陈佩斯合演舞台喜剧《托儿》","《狂飙》饰何黎明，《庆余年第二季》饰戴公公，《知否》饰老皇帝","15 岁进北京电子管厂当工人，1979 年考入北京市文工团"],"obit":true,"portrait":"assets/portraits/2026-08-10-139.webp","source":"媒体讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-08-10-138","date":"2026-08-10","name":"王湛","nameOrig":"","country":"中国","region":"中国大陆","age":80,"fields":["军政"],"identity":"教育部原副部长 · 江苏省原副省长","summary":"从南通师专的校长做到教育部副部长，又回江苏当副省长，最后在省人大常委会副主任任上退下来。","bio":"1946 年 1 月生于江苏南通。1966 年毕业于南京师范学院中文系，1981 年获山东大学文学硕士学位。他早年在南通师范专科学校任教，后任校长；1987 年任南通市副市长，1991 年任江苏省政府副秘书长，1995 年任省教委主任，1997 年任省委宣传部部长。\n\n2000 年 3 月调任教育部副部长、党组成员，兼任国家语言文字工作委员会主任，2001 年起兼任教育部总督学。2004 年 2 月回江苏任副省长，2006 年 1 月任江苏省人大常委会副主任。2026 年 8 月 10 日 14 时 49 分在南京病逝。","facts":["2000 年 3 月至 2004 年 2 月任教育部副部长，兼国家语委主任","1987 年任南通市副市长，1997 年任江苏省委宣传部部长","2006 年 1 月任江苏省人大常委会副主任，2010 年起任江苏省文联主席","中共十五大代表、第十届全国人大代表"],"obit":true,"portrait":"assets/portraits/2026-08-10-138.webp","source":"澎湃新闻","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-08-09-145","date":"2026-08-09","name":"唐·尼尔森","nameOrig":"Don Nelson","country":"美国","region":"","age":86,"fields":["体育"],"identity":"NBA 教练 · 「跑轰」体系开创者","summary":"2007 年他带西部第八的勇士扳倒 67 胜的小牛；「砍鲨战术」和「控球前锋」也都是他弄出来的。","bio":"1940 年 5 月 15 日生于密歇根州马斯基，爱荷华大学毕业。1962 年被芝加哥和风队选中，1964 年加盟波士顿凯尔特人，在绿军 11 个赛季五夺 NBA 总冠军，1978 年球队退役他的 19 号球衣。\n\n1976 年退役后转任教练，先后执教密尔沃基雄鹿、金州勇士、纽约尼克斯、达拉斯小牛，31 个赛季累计 1335 胜 1063 负，长期是 NBA 历史胜场第一，直到 2022 年被波波维奇超越。他让中锋拉到外线、让前锋持球组织，以「Nellieball」推动跑轰与小球潮流；2007 年率勇士完成黑八奇迹；也是「砍鲨战术」的发明者。2009 年在勇士选中库里。2026 年 8 月 9 日上午去世。","facts":["球员时代随凯尔特人五夺 NBA 总冠军，19 号球衣 1978 年退役","教练生涯 1335 胜，2022 年前为 NBA 历史胜场第一","1983、1985、1992 年三度当选年度最佳教练，2012 年入选名人堂","2007 年率勇士完成黑八奇迹，首轮淘汰 67 胜的小牛"],"obit":null,"portrait":"assets/portraits/2026-08-09-145.webp","source":"财新讣闻","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Don_Nelson"},{"id":"2026-08-08-146","date":"2026-08-08","name":"奥田硕","nameOrig":"Okuda Hiroshi","country":"日本","region":"","age":93,"fields":["商业"],"identity":"丰田汽车前社长 · 日本经团联首任会长","summary":"他是丰田史上第一位「外姓社长」，把「三河门罗主义」的内向经营扳向全球，还推成了普锐斯。","bio":"1932 年 12 月 29 日生于三重县津市，1955 年一桥大学商学部毕业即进入丰田汽车销售公司，在丰田做满四十年后于 1995 年出任社长，是近三十年来首位非丰田家族出身的社长，1999 年至 2006 年任董事长。\n\n他就任时丰田内部弥漫着「不怎么努力也能维持生计」的气氛，他要打破的是被称为「三河门罗主义」的内向型经营：在欧美与亚洲大举建厂，力推混合动力等环保技术，主导推出普锐斯、威姿，并推行重视股东利益的经营策略，为丰田此后成为全球最大车企铺路。2002 年出任合并后的日本经济团体联合会首任会长。2026 年 8 月 8 日去世。","facts":["1995 年成为丰田史上首位非丰田家族出身的社长，1999 至 2006 年任董事长","2002 年出任合并后的日本经济团体联合会首任会长","主导推出普锐斯、威姿，推动丰田在欧美与亚洲大举建厂","2012 年起任日本国际协力银行行长，1996 年获蓝绶奖章"],"obit":null,"portrait":"assets/portraits/2026-08-08-146.webp","source":"财新讣闻","verified":"corrected","causeOfDeath":null,"wikipedia":null},{"id":"2026-08-07-137","date":"2026-08-07","name":"岸惠子","nameOrig":"Keiko Kishi","country":"日本","region":"","age":93,"fields":["影视"],"identity":"日本演员、作家 · 《请问芳名》真知子","summary":"她把长围巾从头顶缠到肩头，全日本的年轻女人跟着学，那种缠法被叫作「真知子卷」。","bio":"1932 年 8 月 11 日生于横滨，高中时通过松竹选拔，1951 年签约，同年以中村登的《我家真欢乐》首登银幕。1953 至 1954 年的《请问芳名》三部曲让她成为国民级明星，片中围巾的缠法引发「真知子卷」风潮。\n\n此后她与小津安二郎合作《早春》、与丰田四郎合作《雪国》、与小林正树合作《怪谈》；与市川昆的合作从 1960 年延续到 2001 年，共八部，包括《弟弟》《细雪》。1957 年她嫁给法国导演伊夫·钱皮并移居巴黎，1975 年离婚。2002 年凭《妈妈》获第 25 届日本电影学院奖最佳女主角。2026 年 8 月 7 日因衰老在横滨家中去世。","facts":["1953 至 1954 年主演《请问芳名》三部曲，掀起「真知子卷」围巾风潮","与市川昆合作四十年共八部影片，含《弟弟》《恶魔的手球歌》《细雪》","2002 年凭《妈妈》获第 25 届日本电影学院奖最佳女主角","8 月 7 日去世，距 8 月 11 日的 94 岁生日仅四天"],"obit":null,"portrait":"assets/portraits/2026-08-07-137.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Keiko_Kishi"},{"id":"2026-08-05-136","date":"2026-08-05","name":"黎彼得","nameOrig":"","country":"中国","region":"香港","age":76,"fields":["文艺"],"identity":"香港填词人、演员 · 周星驰御用配角","summary":"「命里有时终须有，命里无时莫强求」——庙街看相佬的一句话，被他写成了《浪子心声》。","bio":"1950 年 5 月 13 日生于香港，原名黎成就。九岁丧父，读到小学五年级辍学，十岁起跟着母亲在中环卖报纸，后来做过杂工、加油站站员和司机。叔父是粤剧名伶靓次伯，他自小在戏棚进出。\n\n1976 年起与许冠杰合作填词，六年间七张专辑，《浪子心声》《半斤八两》《梨涡浅笑》《财神到》全用粤语口语写市井，他因此被叫作「鬼马词人」，与黄霑、卢国沾、郑国江同列香港第一代粤语词人。\n\n演员这一面，他是周星驰的御用配角：《逃学威龙》《鹿鼎记》，以及《唐伯虎点秋香》里那位「左青龙右白虎」的华府私塾先生。2026 年 3 月中风卧床，8 月 5 日病逝。","facts":["累计填词逾 300 首，与黄霑、卢国沾、郑国江同列香港第一代粤语词人","1976 至 1982 年与许冠杰合作七张专辑，合填《浪子心声》《半斤八两》","《唐伯虎点秋香》饰华府私塾先生，《逃学威龙》《鹿鼎记》亦为配角","2026 年 3 月中风后长期卧床，8 月 5 日病逝"],"obit":true,"portrait":"assets/portraits/2026-08-05-136.webp","source":"百度百科","verified":"confirmed","causeOfDeath":"中风","wikipedia":null},{"id":"2026-08-01-135","date":"2026-08-01","name":"文森特·帕斯托雷","nameOrig":"Vincent Pastore","country":"美国","region":"","age":80,"fields":["影视"],"identity":"美国演员 · 《黑道家族》「大普西」扮演者","summary":"《黑道家族》里那个被扔进海里的「大普西」，四十二岁才入行的前夜店老板，死在布朗克斯的公寓里。","bio":"1946 年 7 月 14 日生于纽约布朗克斯。他在美国海军服役、随舰去过越南，退伍后经营酒吧和夜店二十年，42 岁才从佩斯大学拿到戏剧学位入行，1988 年以《黑玫瑰》首登银幕。\n\n因为一张矮壮的爱尔兰—意大利裔面孔，他几乎专演黑帮角色：斯科塞斯的《好家伙》、德·帕尔马的《情枭的黎明》、电视电影《Gotti》。1999 年在《黑道家族》中饰萨尔瓦托雷·「大普西」·邦彭谢罗，这个角色第二季成了 FBI 线人，被同伙带上游艇处决。\n\n2026 年 8 月 1 日，邻居因三天联系不上他上门查看，发现他已在家中去世。","facts":["1999 年起在《黑道家族》中饰萨尔瓦托雷·「大普西」·邦彭谢罗","42 岁前经营酒吧与夜店二十年，1988 年以《黑玫瑰》首登银幕","曾在美国海军服役，随舰参与越南战争","8 月 1 日被邻居发现死于布朗克斯家中，警方称无犯罪迹象"],"obit":null,"portrait":"assets/portraits/2026-08-01-135.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Vincent_Pastore"},{"id":"2026-07-25-梁材远","date":"2026-07-25","name":"梁材远","nameOrig":"Leung Choi-yuen","country":"中国","region":"","age":75,"fields":["影视"],"identity":"香港电视监制 · 《誓不低头》《茶是故乡浓》","summary":"港剧的警匪与豪门之外，是他辟出的一条乡间小路：茶山、酒坊、宗族与人情。","bio":"1950 年 12 月生于香港，香港浸会学院历史系硕士。1975 年入无线电视，在《欢乐今宵》做见习编剧与资料搜集，1978 年重返无线任编导，参与《抉择》《网中人》《火玫瑰》等剧。\n\n1985 年升任监制，1988 年与编审韦家辉合作的《誓不低头》直面司法冤案，收视轰动全港。1990 年代中期他升任戏剧组制作部经理，策划《情浓大地》《茶是故乡浓》《酒是故乡醇》。2004 年重回一线，《汇通天下》《紫禁惊雷》《造王者》接连出街。2020 年 1 月退休，《大酱园》为收官之作。\n\n2026 年 7 月 25 日在沙田威尔斯亲王医院病逝，享年 75 岁。","facts":["在无线电视服务三十六年，1975 年由《欢乐今宵》见习编剧起步。","1988 年监制《誓不低头》，为当年 TVB 收视冠军。","策划《茶是故乡浓》《酒是故乡醇》，被视作港剧乡土题材开路人。","2020 年退休，《大酱园》为其最后一部监制作品。"],"obit":null,"portrait":null,"source":"香港01、星岛头条、TVB 新闻","verified":"added","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":null},{"id":"2026-07-24-张玉台","date":"2026-07-24","name":"张玉台","nameOrig":"","country":"中国","region":"","age":80,"fields":["军政"],"identity":"国务院发展研究中心原主任 · 中国科协原党组书记","summary":"从半导体所的实习研究员到国务院智囊的掌门人，他把技术员的算术做成了国家的账本。","bio":"1945 年 8 月生于山东郯城。1970 年起任中国科学院半导体研究所研究实习员，后调国家科委办公厅，历任正处级秘书、副主任。\n\n1988 年任中国科学院副秘书长，兼任学部联合办公室主任、中国科学报社社长兼总编辑。1995 年任中国科协书记处书记、党组书记，1996 年至 2004 年任中国科协副主席、书记处第一书记，任内推动全民科学素质工作。2004 年 10 月转入国务院发展研究中心，历任党组书记、副主任、主任，2011 年 3 月卸任。\n\n他是中共第十六届、十七届中央委员会委员。2026 年 7 月 24 日在北京逝世，享年 80 岁。","facts":["1996 年至 2004 年任中国科协副主席、书记处第一书记、党组书记。","2004 年至 2011 年任国务院发展研究中心党组书记、主任。","是中共第十六届、十七届中央委员会委员。","早年在中国科学院半导体研究所从事研究工作。"],"obit":null,"portrait":"assets/portraits/2026-07-24-张玉台.webp","source":"新华社、北京日报","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-07-24-吐依贡·阿合买德","date":"2026-07-24","name":"吐依贡·阿合买德","nameOrig":"","country":"中国","region":"","age":80,"fields":["影视"],"identity":"维吾尔族演员、导演 · 电影《阿凡提》主演","summary":"他骑着毛驴替百姓出气，把一句「阿凡提」说成了几代中国人的童年记忆。","bio":"1946 年生于新疆。1964 年毕业于中央戏剧学院，同年分配至新疆歌舞团。1974 年进入天山电影制片厂。\n\n1980 年，他在电影《阿凡提》中饰演那位骑毛驴、斗财主、替百姓伸张正义的民间智者，影片获首届全国少数民族题材电影腾龙奖故事片三等奖，他本人获优秀男演员奖。1982 年进北京电影学院导演系进修，首部执导作品《光棍之家》获第 9 届中国电影金鸡奖导演处女作奖提名。2003 年出演《库尔班大叔上北京》，获华表奖最佳男演员提名与金凤凰奖。\n\n曾任新疆电影家协会主席。2026 年 7 月 24 日在乌鲁木齐逝世，享年 80 岁。","facts":["1980 年在电影《阿凡提》中饰演阿凡提，获腾龙奖优秀男演员奖。","执导处女作《光棍之家》获第 9 届金鸡奖导演处女作奖提名。","《库尔班大叔上北京》为其赢得华表奖最佳男演员提名。","曾任新疆电影家协会主席，获新疆德艺双馨终身成就奖。"],"obit":null,"portrait":null,"source":"北京日报、中国网、极目新闻","verified":"added","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":null},{"id":"2026-07-23-卜励德","date":"2026-07-23","name":"卜励德","nameOrig":"Nicholas Platt","country":"美国","region":"","age":90,"fields":["军政"],"identity":"美国资深外交官 · 亚洲协会前会长","summary":"三十六岁那年他随尼克松来华，对总统说自己为这趟行程准备了十年。","bio":"1934 年生于纽约，在哈佛与约翰斯·霍普金斯大学接受教育，1960 年代进入美国国务院，成为最早一批中国问题专家。1972 年他以国务院中国问题专家的身份随尼克松访华，是「上海公报」发表当晚少数在场的美方工作人员之一。\n\n1973 年至 1974 年他任美国驻华联络处政治处主任，是联络处首批官员。此后历任美国驻赞比亚、菲律宾、巴基斯坦大使。1992 年至 2004 年出任美国亚洲协会会长，任内二十多次访华，推动中美之间的学术与文化交流。\n\n2026 年 7 月 23 日在纽约逝世，享年 90 岁，死因为心脏急剧衰竭。美国驻华大使馆发文表示哀悼。","facts":["1972 年随尼克松访华，是「上海公报」发表时在场的美方工作人员。","1973 年至 1974 年任美国驻华联络处政治处主任。","曾任美国驻赞比亚、菲律宾、巴基斯坦三国大使。","1992 年至 2004 年任美国亚洲协会会长，任内二十多次访华。"],"obit":null,"portrait":"assets/portraits/2026-07-23-卜励德.webp","source":"观察者网、澎湃新闻、美国驻华大使馆","verified":"added","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Nicholas_Platt"},{"id":"2026-07-23-134","date":"2026-07-23","name":"陆建勋","nameOrig":"","country":"中国","region":"中国大陆","age":97,"fields":["科技"],"identity":"中国工程院院士 · 舰船通信学科开拓者与奠基人之一","summary":"他给中国第一艘核潜艇装上顺风耳，又把洲际导弹试验的海上通信大动脉接通。","bio":"陆建勋 1929 年 9 月 11 日生于北京，原籍浙江杭州。1947 年考入清华大学电机工程系，1950 年报名参军，成为海军司令部通信处接收的第一名大学生，1953 年 9 月加入中国共产党。\n\n他主持「900 号工程」，研制核潜艇瞬间超快速通信系统；在洲际导弹试验的「七一八工程」中牵头搭建船与船、船与岸的远程通信体系。1983 年至 1994 年任中国船舶工业总公司第七研究院院长兼党组书记，1995 年当选中国工程院院士。\n\n2010 年，81 岁的他出任「极低频探地工程」首席科学家，荣立海军一等功。2026 年 7 月 23 日在北京逝世，享年 97 岁。","facts":["我国舰船通信学科开拓者与奠基人之一，扎根该领域 70 余年","主持 900 号工程，为第一艘核潜艇研制瞬间超快速通信系统","1983 至 1994 年任第七研究院院长兼党组书记，1995 年当选院士","荣立海军一等功，获「终身奉献海洋」纪念奖章"],"obit":true,"portrait":"assets/portraits/2026-07-23-134.webp","source":"澎湃新闻","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-07-19-张岂之","date":"2026-07-19","name":"张岂之","nameOrig":"","country":"中国","region":"","age":100,"fields":["社科"],"identity":"思想史家 · 西北大学名誉校长","summary":"从《中国思想通史》的助手到《宋明理学史》的主编，他在西安守了七十四年讲台。","bio":"1926 年 10 月生于江苏南通。1946 年考入北京大学哲学系，1950 年考入清华大学文科研究所读研究生，1952 年被时任西北大学校长的侯外庐聘至西北大学任教。\n\n他协助侯外庐整理《中国思想通史》，与侯外庐、邱汉生共同主编《宋明理学史》，独著、主编《中国思想史》《中国历史》《中华人文精神》等二十余部，是侯外庐学派的主要传承者与创新者。历任西北大学历史系主任、副校长、校长、名誉校长，1994 年起受聘清华大学双聘教授，培养研究生五百余名。\n\n2026 年 7 月 19 日 17 时 24 分在西安逝世，享年 100 岁。","facts":["1952 年由侯外庐聘至西北大学，此后执教七十余年。","与侯外庐、邱汉生共同主编《宋明理学史》，获郭沫若历史学荣誉奖。","主编《中国历史》六卷，获国家级教学成果一等奖。","1994 年起受聘清华大学双聘教授，培养研究生五百余名。"],"obit":null,"portrait":"assets/portraits/2026-07-19-张岂之.webp","source":"西北大学讣告、光明日报、中国教育报","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-07-16-鲁道夫·马库斯","date":"2026-07-16","name":"鲁道夫·马库斯","nameOrig":"Rudolph A. Marcus","country":"美国","region":"","age":102,"fields":["科技"],"identity":"理论化学家 · 1992 年诺贝尔化学奖得主","summary":"电子从一个分子跃到另一个分子要付多少代价，他用一条抛物线算清了。","bio":"1923 年 7 月 21 日生于加拿大蒙特利尔一个犹太移民家庭。1946 年在麦吉尔大学获博士学位，其间参与拓展单分子反应速率理论，即后来的 RRKM 理论。1958 年入美国籍，1978 年起执教加州理工学院。\n\n1950 年代中期他提出电子转移理论：反应速率与驱动力之间不是直线关系，而是抛物线，驱动力过大反而变慢。这个反直觉的预言在 1980 年代被实验证实，从此成为理解光合作用、呼吸作用乃至萤火虫发光的共同语言，他因此独享 1992 年诺贝尔化学奖。\n\n2026 年 7 月 16 日在帕萨迪纳家中去世，距 103 岁生日只差 5 天。","facts":["1992 年因电子转移反应理论独享诺贝尔化学奖。","参与构建 RRKM 单分子反应速率理论，其中的 M 即其姓氏首字母。","1978 年起执教加州理工学院，1989 年获美国国家科学奖章。","去世时距 103 岁生日仅差 5 天，晚年仍在发表论文。"],"obit":null,"portrait":"assets/portraits/2026-07-16-鲁道夫·马库斯.webp","source":"加州理工学院讣告、纽约时报、波士顿环球报","verified":"added","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Rudolph_A._Marcus"},{"id":"2026-07-16-133","date":"2026-07-16","name":"谢贤","nameOrig":"","country":"中国","region":"香港","age":89,"fields":["影视"],"identity":"香港演员 · 粤语片首席小生 · 金像奖史上最年长最佳男主角","summary":"他一生挂在嘴边的是「表演必须继续下去」，85 岁那年凭《杀出个黄昏》成了金像奖最年长影帝。","bio":"谢贤原名谢家钰，1936 年 8 月 9 日生于香港，家中排行第四。1953 年考入演员训练班，次年拍第一部电影《楼下闩水喉》，1950 年代末升为粤语片首席小生，1960 年在香港第一部《神雕侠侣》里演杨过。\n\n1967 年他创办谢氏兄弟影片公司，自编自导《窄梯》《明日天涯》。1978 年入 TVB 主演《萧十一郎》，1980 年因《千王之王》里的罗四海被叫了一辈子「四哥」。2001 年在《少林足球》里演反派强雄。\n\n2019 年他获第 38 届香港电影金像奖终身成就奖，2022 年凭《杀出个黄昏》首次获最佳男主角，以 85 岁创下最年长纪录。2026 年 7 月 16 日因肺炎在养和医院逝世，享年 89 岁。","facts":["1960 年在香港首部《神雕侠侣》中饰演杨过，为第一代杨过","1980 年《千王之王》饰罗四海，「四哥」由此得名","2022 年凭《杀出个黄昏》获金像奖最佳男主角，85 岁创最年长纪录","2019 年获第 38 届香港电影金像奖终身成就奖"],"obit":true,"portrait":"assets/portraits/2026-07-16-133.webp","source":"腾讯新闻","verified":"confirmed","causeOfDeath":"肺炎","wikipedia":null},{"id":"2026-07-15-132","date":"2026-07-15","name":"沙玉华","nameOrig":"","country":"中国","region":"中国大陆","age":95,"fields":["影视"],"identity":"一级演员 · 87 版《红楼梦》刘姥姥扮演者 · 铁路文工团话剧演员","summary":"那句「老刘老刘，食量大如牛」，让一个乡下老太太在大观园里活了将近四十年。","bio":"沙玉华 1930 年 11 月 13 日出生，1948 年起跟随解放军在各地演出，1956 年进入中国铁路文工团。同一年，她凭独幕戏《火车开来的时候》里的王大娘一角，获第一届全国话剧观摩演出会演员二等奖。\n\n在铁路文工团，她在《红岩》《高山下的花环》等话剧里塑造过多个老太太形象，舞台经验三十余年。1983 年剧组筹备时她已五十多岁，导演王扶林让她念那句「老刘老刘，食量大如牛」，鼓着腮帮子的样子当场定下了角色。\n\n1987 年《红楼梦》播出，她的刘姥姥被观众称作「沙玉华之后再无刘姥姥」。此后还出演《十二次列车》《一地鸡毛》等影视作品。2026 年 7 月 15 日凌晨在北京逝世，享年 95 岁。","facts":["1956 年凭《火车开来的时候》获第一届全国话剧观摩演出会演员二等奖","接演刘姥姥时已 54 岁，此前有三十余年话剧舞台经验","87 版《红楼梦》中刘姥姥被她演成公认无法超越的版本","同剧演员陈洪海、欧阳奋强于 7 月 15 日发文证实其去世"],"obit":true,"portrait":"assets/portraits/2026-07-15-132.webp","source":"南方娱乐网","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-07-13-131","date":"2026-07-13","name":"施南生","nameOrig":"","country":"中国","region":"香港","age":75,"fields":["影视"],"identity":"香港电影制片人 · 电影工作室联合创办人 · 新艺城七人组唯一女性","summary":"香港电影的大内总管：徐克在镜头后面，她在预算、发行与海外市场之间调度。","bio":"施南生 1951 年 8 月 8 日生于上海，在香港长大，后赴英国北伦敦理工大学主修电脑与统计学。回港后先后任职无线电视、香港电台、丽的电视，做制作与行政。\n\n1981 年她加入新艺城任行政总监，是「新艺城七人组」里唯一的女性，管预算、发行与海外推广；1984 年与徐克共创电影工作室，监制《英雄本色》《倩女幽魂》《黄飞鸿》。2001 年起任寰亚综艺集团副主席，出品《无间道》。\n\n她被美国《综艺》评为全球最具影响力 50 位电影人之一，做过柏林、戛纳电影节主竞赛评委；2025 年 4 月与徐克同获第 43 届香港电影金像奖终身成就奖。2026 年 7 月 13 日在香港养和医院逝世，享年 75 岁。","facts":["1984 年与徐克共创电影工作室，监制《英雄本色》《倩女幽魂》《黄飞鸿》","新艺城七人组中唯一的女性，主管预算、发行与海外推广","2001 年起任寰亚综艺集团副主席，为《无间道》出品人之一","2025 年与徐克同获第 43 届香港电影金像奖终身成就奖"],"obit":true,"portrait":"assets/portraits/2026-07-13-131.webp","source":"南方娱乐网","verified":"confirmed","causeOfDeath":"癌症","wikipedia":null},{"id":"2026-07-12-130","date":"2026-07-12","name":"王连洲","nameOrig":"","country":"中国","region":"中国大陆","age":87,"fields":["商业"],"identity":"「基金业之父」 · 证券法、信托法、证券投资基金法起草工作小组组长","summary":"他用十余年啃下三部金融法律，自己总结成十二个字：风风雨雨、坎坎坷坷、曲曲折折。","bio":"王连洲是山东冠县人，1964 年毕业于山东财经学院财政金融专业，先在中国人民银行总行印制局工作，参与组织出版新中国第一部《中国历代货币》图录。\n\n1983 年 10 月他调任全国人大财经委员会，历任办公室财金组组长、办公室副主任等职。1992 年起任《证券法》起草工作小组组长，随后又主持《信托法》《证券投资基金法》起草，三部法律被视为中国资本市场的四梁八柱。\n\n2000 年退休后，他担任华夏基金、华宝信托等机构独立董事，兼清华大学中国经济研究中心副主任，2018 年获公募基金「金基金」行业杰出贡献奖。2026 年 7 月 12 日在北京逝世，享年 87 岁。","facts":["1992 年起任《证券法》起草工作小组组长，该法 1998 年 12 月通过","主持《信托法》《证券投资基金法》起草，三部法律合称四梁八柱","退休后任华夏基金首批独立董事，一任 11 年","2018 年获公募基金「金基金」行业杰出贡献奖"],"obit":true,"portrait":"assets/portraits/2026-07-12-130.webp","source":"南方娱乐网","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-07-11-林赛·格雷厄姆","date":"2026-07-11","name":"林赛·格雷厄姆","nameOrig":"Lindsey Graham","country":"美国","region":"","age":71,"fields":["军政"],"identity":"美国联邦参议员 · 参议院预算委员会主席","summary":"前一天他还在基辅宣布对俄制裁已谈成，第二天夜里倒在国会山的家中。","bio":"1955 年生于南卡罗来纳州，父母在他不到两岁时相继去世。空军律师出身，1994 年当选联邦众议员，2002 年当选联邦参议员并三度连任，生前任参议院预算委员会主席。\n\n他是华盛顿最不加掩饰的鹰派，伊拉克、阿富汗、乌克兰、伊朗，几乎每一场美国海外干预背后都有他的声音。2016 年他激烈反对特朗普，此后却成为后者在国会最亲近的盟友。去世前两天他刚结束第十次访乌，在基辅与泽连斯基共同宣布两党已就对俄制裁达成共识。\n\n2026 年 7 月 11 日晚在华盛顿家中因主动脉夹层去世，终年 71 岁。","facts":["1994 年当选联邦众议员，2002 年起任联邦参议员并三度连任。","生前任参议院预算委员会主席，是特朗普在国会最亲近的盟友之一。","去世前两日在基辅与泽连斯基共同宣布对俄制裁共识。","死因为动脉粥样硬化性心血管疾病引发主动脉夹层。"],"obit":null,"portrait":"assets/portraits/2026-07-11-林赛·格雷厄姆.webp","source":"央视新闻、中国新闻网、环球人物","verified":"added","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Lindsey_Graham"},{"id":"2026-07-08-安·维德科姆","date":"2026-07-08","name":"安·维德科姆","nameOrig":"Ann Widdecombe","country":"英国","region":"","age":78,"fields":["军政"],"identity":"英国前保守党议员 · 改革英国党发言人","summary":"她在议会管过监狱，也在电视舞池里跳过华尔兹，最后死于自家厨房的一把铁锤。","bio":"1947 年 10 月生于萨默塞特，在伯明翰大学读拉丁语。1987 年至 2010 年任保守党下院议员，代表梅德斯通选区，1992 年至 1997 年在约翰·梅杰政府中主管监狱事务。她以社会保守立场闻名，反对堕胎，2001 年竞选保守党党魁未果。\n\n离开议会后她成了电视常客，2010 年参加英国广播公司的明星舞蹈真人秀，2018 年参加《名人老大哥》。2019 年加入法拉奇的脱欧党并当选欧洲议会议员，2023 年转入改革英国党，任移民与司法发言人。\n\n2026 年 7 月 8 日她在德文郡海托尔的家中遭袭，7 月 9 日被园丁发现死亡，享年 78 岁。","facts":["1987 年至 2010 年任保守党下院议员，代表梅德斯通选区。","1992 年至 1997 年在梅杰政府中主管监狱事务。","2019 年代表脱欧党当选欧洲议会议员，后任改革英国党发言人。","是近年第三位遇害的英国议会人士，前两位为柯克斯与颜敏时。"],"obit":null,"portrait":"assets/portraits/2026-07-08-安·维德科姆.webp","source":"新华社、BBC、卫报","verified":"added","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Ann_Widdecombe"},{"id":"2026-07-08-129","date":"2026-07-08","name":"邦妮·泰勒","nameOrig":"Bonnie Tyler","country":"英国","region":"","age":75,"fields":["文艺"],"identity":"威尔士歌手 · 《心之全蚀》原唱","summary":"那副被声带手术磨哑的嗓子，把一首抒情摇滚唱成了每逢日食就被重播的声音。","bio":"邦妮·泰勒原名 Gaynor Hopkins，1951 年生于威尔士尼斯一个矿工家庭。1976 年以《Lost in France》成名；1977 年声带结节手术后嗓音变得沙哑，这反而成了往后四十年的标志。\n\n1983 年，制作人 Jim Steinman 为她写下《Total Eclipse of the Heart》，这首力量型抒情曲登上多国榜首。她三度获格莱美提名，2013 年代表英国参加欧洲歌唱大赛，2023 年获颁 MBE 勋章。\n\n2026 年 5 月 6 日她因肠穿孔在葡萄牙法鲁接受紧急手术，术后并发症让她一度陷入诱导昏迷。7 月 8 日晚她在法鲁的医院去世，享年 75 岁。","facts":["《心之全蚀》1983 年登多国榜首，流媒体播放突破 10 亿次","1977 年声带结节手术后嗓音变沙哑，成为其标志音色","三度获格莱美提名，2013 年代表英国参加欧洲歌唱大赛","2026 年 5 月肠穿孔手术后昏迷近两月，7 月 8 日病逝于法鲁"],"obit":null,"portrait":"assets/portraits/2026-07-08-129.webp","source":"Pantheon","verified":"confirmed","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Bonnie_Tyler"},{"id":"2026-07-05-李崇善","date":"2026-07-05","name":"李崇善","nameOrig":"","country":"中国","region":"","age":86,"fields":["文艺"],"identity":"京剧老生 · 谭富英亲传弟子","summary":"《磐石湾》里那身军装让全国记住了他，而他真正的根在谭派的骨子老戏里。","bio":"1952 年考入北京私立艺培戏曲学校，1962 年正式拜入谭富英门下，专工谭派老生，同时得余派老生王少楼、李盛藻等传授，此后长期在北京京剧院任一级演员。\n\n他的传统戏底子极厚，《龙凤呈祥》《失空斩》《乌盆记》《四郎探母》《赵氏孤儿》都是看家戏。让他在全国走红的却是现代戏：在谢晋等人执导的京剧戏曲电影《磐石湾》中饰演民兵连长陆长海，一身军装、一段唱腔，成了一代人的戏曲记忆。\n\n他是北京市第七、八、九届人大代表，北京市劳动模范。2026 年 7 月 5 日因病在北京逝世，享年 86 岁。","facts":["1962 年正式拜谭富英为师，专工谭派老生。","京剧电影《磐石湾》中饰陆长海，是其最广为人知的角色。","常演剧目包括《失空斩》《四郎探母》《赵氏孤儿》等。","为北京市第七至第九届人大代表、北京市劳动模范。"],"obit":null,"portrait":"assets/portraits/2026-07-05-李崇善.webp","source":"北京京剧院讣告、中新社、川观新闻","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-07-03-128","date":"2026-07-03","name":"刘海珊","nameOrig":"","country":"中国","region":"中国大陆","age":93,"fields":["其他"],"identity":"上海建设机器厂钳工 · 新中国「0001 号」高级技师 · 全国劳动模范","summary":"从踏三轮车到在人民大会堂接过第 0001 号高级技师证书，他用小机床啃下了大部件的硬骨头。","bio":"刘海珊 1933 年生于江苏海安，15 岁到上海谋生，靠踏三轮车度日。1958 年进入上海建设机器厂当翻砂工，1960 年改行做钳工，白天在车间加工工件，夜里上夜校补机械制图与文化课，48 岁才拿到大专文凭。\n\n设备简陋的年代，他带班组用「以小攻大」的办法加工超出机床能力的巨型部件，1974 年为上海飞机制造厂攻克机翼与机身连接的「梳状件」，一生完成 140 余项技术革新，其中国家重点项目 28 项。\n\n1989 年他在人民大会堂被评为全国劳动模范并发言，同年 12 月接过编号 0001 的高级技师证书，这是新中国第一本。2026 年 7 月 3 日他在上海瑞金医院逝世，享年 93 岁。","facts":["1989 年获劳动部颁发的编号 0001 高级技师证书，为新中国第一本","累计完成 140 余项技术革新，含 28 项国家重点项目","1974 年攻克上海飞机制造厂机翼与机身连接件加工难题","1986 年获全国技术革新能手称号与五一劳动奖章"],"obit":true,"portrait":"assets/portraits/2026-07-03-128.webp","source":"南方娱乐网","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-07-02-127","date":"2026-07-02","name":"沈之荃","nameOrig":"","country":"中国","region":"中国大陆","age":95,"fields":["科技"],"identity":"中国科学院院士 · 高分子化学家 · 中国稀土催化聚合学科创建者之一","summary":"她把稀土化合物放进聚合反应釜，为中国合成橡胶工业开出一条没有先例的催化路线。","bio":"沈之荃 1931 年 5 月生于上海，1952 年毕业于沪江大学化学系，先后在苏州大学、中国科学院长春应用化学研究所工作，1980 年起任教于浙江大学化学系与高分子科学与工程学系，1995 年当选中国科学院院士。\n\n她主攻过渡金属与稀土络合催化聚合。她参与研制的三元镍系顺丁橡胶工艺，成为中国五个万吨级顺丁橡胶生产装置的聚合基础；她首开稀土化合物催化聚合之先，做出稀土顺丁橡胶、异戊橡胶等品种，把一条中国特有的催化路线立成了学科。\n\n她获国家科技进步特等奖、国家自然科学二等奖与何梁何利基金奖，1998 年被评为第二届中国「十大女杰」。2026 年 7 月 2 日在杭州逝世，享年 95 岁。","facts":["三元镍系顺丁橡胶工艺成为中国五个万吨级生产装置的聚合基础","首开稀土化合物催化聚合先河，研制出稀土顺丁橡胶与异戊橡胶","1995 年当选中国科学院院士，1998 年获第二届中国「十大女杰」称号","曾获国家科技进步特等奖、国家自然科学二等奖与何梁何利基金奖"],"obit":true,"portrait":null,"source":"浙江大学","verified":"confirmed","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":null},{"id":"2026-07-01-梁珊","date":"2026-07-01","name":"梁珊","nameOrig":"","country":"中国","region":"","age":81,"fields":["影视"],"identity":"香港演员 · 「御用恶女」","summary":"港片里最难缠的几张脸都由她来演：刁太、吕魔头，观众恨得牙痒又记得牢。","bio":"1945 年生于广州，1961 年进入香港演艺界，其后辗转丽的电视、无线电视、亚洲电视。1979 年加入无线，主演长篇剧《天虹》，此后在 1979 年郑少秋版《楚留香》中饰石观音、1982 年版《天龙八部》中饰刀白凤，也在《我和春天有个约会》中演姚小蝶的继母梅兰仙。\n\n真正让她出圈的是电影里的反派：《精装追女仔》中张敏的母亲刁太，《富贵逼人》系列里那位电视台高层吕魔头，泼辣刁蛮演得入木三分，「御用恶女」由此叫开。1999 年她淡出幕前移居加拿大。\n\n2026 年 7 月 1 日离世，享年 81 岁，其子宇澄对外证实。","facts":["1961 年入行，先后效力丽的电视、无线电视与亚洲电视。","1979 年加入无线，主演长篇剧《天虹》。","在《精装追女仔》中饰张敏母亲刁太，在《富贵逼人》中饰吕魔头。","1999 年淡出移居加拿大，2014 年回港转演舞台剧。"],"obit":null,"portrait":"assets/portraits/2026-07-01-梁珊.webp","source":"中国新闻网、澎湃新闻、香港商报","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-06-30-应宝麟","date":"2026-06-30","name":"应宝麟","nameOrig":"","country":"中国","region":"","age":82,"fields":["影视"],"identity":"滇剧一级演员 · 《陈翔六点半》「妹爷」","summary":"一句「你妹的」让他在短视频里红了十年，也让一位滇剧老生被年轻人记住了。","bio":"应宝麟（亦作应宝林）生于云南昆明，1944 年生，早年在云南省滇剧院唱滇剧近五十年，工文武老生，曾获全国戏曲观摩主演一等奖，后为云南省话剧院一级演员。\n\n2003 年他在张纪中版《天龙八部》中饰枯荣大师，被影视观众记住，此后参演《福星高照猪八戒》的太上老君、《花腰新娘》的村长、《湄公河大案》等。2015 年他加入网络短剧《陈翔六点半》，成为常驻角色「妹爷」，一句口头禅「你妹的」让他成了年轻观众眼里的网红老戏骨，也出演了多部系列网络电影。与他长期搭档演夫妻的「吴妈」吴艳杰，已于今年 5 月病逝。\n\n2026 年 6 月 30 日，他去世，享年 82 岁，《陈翔六点半》官方发布消息悼念。","facts":["2003 年张纪中版《天龙八部》中饰演枯荣大师","在云南省滇剧院唱滇剧近五十年，工文武老生","2015 年加入《陈翔六点半》，一句「你妹的」走红网络"],"obit":null,"portrait":"assets/portraits/2026-06-30-应宝麟.webp","source":"《陈翔六点半》官方发布／南方都市报、光明网","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-06-27-于小华","date":"2026-06-27","name":"于小华","nameOrig":"Siu Wah Yuk","country":"中国香港","region":"","age":78,"fields":["影视"],"identity":"TVB 国语配音组资深配音员 · 冯程程、小龙女之声","summary":"冯程程和小龙女说的那些话，其实出自同一副嗓子，她藏在话筒后面四十年。","bio":"于小华 1948 年 4 月生于香港，早年是电影演员，七十年代在香港影坛既演过文艺片也跑过龙套。1980 年她加入 TVB 普通话配音组，从台前转到幕后，是 TVB 所有女配音员中资历最老的一位。\n\n她的声音是内地观众认识港剧的入口：1980 年《上海滩》里赵雅芝的冯程程，1995 年《神雕侠侣》里李若彤的小龙女，《大时代》里蓝洁瑛的罗慧玲，《鉴证实录》里陈慧珊的聂宝言，《天龙八部》里雪梨的马夫人，一直到《新闻女王》里的方太太。她曾说，自己不觉得是在给角色配音，而是在演绎她们的人生。\n\n2026 年 6 月 27 日下午 5 时左右，她因癌症在香港病逝，享年 78 岁。李若彤发文悼念。","facts":["1980 年为《上海滩》中赵雅芝饰演的冯程程配音","1995 年为《神雕侠侣》中李若彤饰演的小龙女配音","是 TVB 女配音员中资历最老的一位，配音生涯横跨四十年"],"obit":null,"portrait":"assets/portraits/2026-06-27-于小华.webp","source":"TVB 国语配音组业内确认／都市快报、新民晚报","verified":"added","causeOfDeath":"癌症","wikipedia":null},{"id":"2026-06-26-126","date":"2026-06-26","name":"王洛林","nameOrig":"","country":"中国","region":"中国大陆","age":88,"fields":["社科"],"identity":"中国经济学家 · 中国社科院原副院长、党组副书记（正部长级）","summary":"他接父亲王亚南的班做经济学，也替厦门大学和中国社科院各看了一段路。","bio":"王洛林 1938 年 6 月生于湖北黄冈，父亲王亚南是《资本论》中文全译本首译者之一、新中国成立后厦门大学首任校长。他 1960 年起在甘肃师范大学政教系任教，1961 年转入厦门大学经济系，历任助教、讲师、副教授、系副主任。\n\n1984 年任厦门大学副校长，1989 年任党委书记、副校长，1993 年调入中国社会科学院任副院长，1998 至 2004 年任副院长、党组副书记。他是第十三、十四、十六届中央候补委员，第十五届中央委员。\n\n他的研究集中在国际贸易、国际投资、世界经济和宏观经济，并任第十届全国政协经济委员会副主任。2026 年 6 月 26 日，他因病在北京逝世，享年 88 岁。","facts":["第十三、十四、十六届中央候补委员，第十五届中央委员","1989 至 1993 年任厦门大学党委书记、副校长","1993 年起任中国社科院副院长，1998 至 2004 年任党组副书记"],"obit":true,"portrait":"assets/portraits/2026-06-26-126.webp","source":"界面新闻","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-06-26-125","date":"2026-06-26","name":"崔崑","nameOrig":"","country":"中国","region":"中国大陆","age":101,"fields":["科技"],"identity":"中国工程院院士 · 模具钢领域奠基人，人称「钢铁院士」","summary":"一件衬衣穿三十年的人，把一辈子的积蓄捐给了上千个素不相识的学生。","bio":"崔崑 1925 年 7 月生于山东济南，1944 年步行八十一日穿越封锁线到大后方，考进武汉大学机械系，1948 年毕业留校。1956 年调入华中工学院，1958 年赴莫斯科钢铁学院进修，后创建该校金属材料及热处理专业。\n\n他是我国模具钢领域的奠基人，首创含铌高强韧性基体钢，此后研发出易切削精密模具钢等系列钢种。1997 年当选中国工程院院士，曾获全国科学大会奖 1 项、国家技术发明奖 4 项。\n\n年逾八旬，他用七年写完两百万字的《钢的成分、组织与性能》，业内称其为钢铁材料的「百科全书」。他与夫人朱慧楠把毕生积蓄捐出，设助学金资助千余名学生。2026 年 6 月 26 日，他在武汉逝世。","facts":["首创含铌高强韧性基体钢，构建我国自主模具钢体系","1997 年当选中国工程院院士，1981 年成为我国首批博士生导师","八旬后用七年写成 200 万字《钢的成分、组织与性能》"],"obit":true,"portrait":"assets/portraits/2026-06-26-125.webp","source":"华中科技大学讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-06-25-苗金凤","date":"2026-06-25","name":"苗金凤","nameOrig":"","country":"中国香港","region":"","age":80,"fields":["影视"],"identity":"香港资深演员 · 《真情》越南婆、《女人俱乐部》黄兰","summary":"粤语片里柔弱的女主角，转到电视里成了港剧第一贵妇，一路演到自己息影为止。","bio":"苗金凤原名林慧珊，1945 年 10 月生于香港，17 岁入行，最初以本名拍电影，第一部粤语片《双凤仇》便让她一炮而红，此后改用艺名。六十年代粤语片黄金期她长期担纲女主角，形象多是温柔柔弱的少女，《一水隔天涯》《珍珠泪》是代表作。\n\n转战电视后戏路大开：在《烈火雄心》里演李子雄角色的母亲，在《真情》里演越南妇人莫少芬，《第三类法庭》里演强势母亲，因贵气被称为「港剧第一贵妇」。2005 年后逐步淡出，2013 年应 TVB 之邀复出拍《女人俱乐部》饰黄兰，此后再度息影，仅 2015 年演过舞台剧《杜老志》。\n\n2026 年 6 月 25 日下午 3 时许，她因病在将军澳医院离世，享年 80 岁。","facts":["1960 年凭首部粤语片《双凤仇》一举成名","因气质贵气被观众称为「港剧第一贵妇」","2013 年复出参演 TVB 剧集《女人俱乐部》，饰黄兰"],"obit":null,"portrait":"assets/portraits/2026-06-25-苗金凤.webp","source":"家属委托田启文公布／中国新闻网、香港商报","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-06-25-李凤英","date":"2026-06-25","name":"李凤英","nameOrig":"","country":"中国","region":"","age":77,"fields":["影视"],"identity":"北京京剧院青衣 · 87 版《红楼梦》薛姨妈","summary":"一句反复念叨的「我的儿」，她把薛姨妈演成了几代观众心里的国民好姨妈。","bio":"李凤英毕业于北京戏校，后进入北京市京剧团，主攻青衣，演过《红灯记》的李铁梅，也演过《二进宫》《玉堂春》。\n\n1987 年，选角导演李志新在北京京剧院一眼看中她，带她见王扶林导演，试戏后定下《红楼梦》里的薛姨妈——这是她第一次拍电视剧。她把这位温和慈厚的长辈演成国民好姨妈，剧中反复出现的「我的儿」成了几代观众的记忆点。此后演过 1988 年《庄妃轶事》的孝端文皇后，在《隋唐演义》里客串，《三国演义》中演只出场一次的卞夫人，另参演《宰相刘罗锅》。\n\n2026 年 6 月 25 日，她因病在北京辞世，享年 77 岁；消息由剧中薛蟠的扮演者陈洪海于 6 月 30 日发祭文公布。","facts":["87 版《红楼梦》饰薛姨妈，台词「我的儿」成为经典记忆点","94 版《三国演义》客串卞夫人，即曹丕生母","原为北京京剧院青衣，主演过《二进宫》《玉堂春》"],"obit":null,"portrait":"assets/portraits/2026-06-25-李凤英.webp","source":"家属及同剧组演员祭文／环球网、南方都市报","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-06-25-万绍芬","date":"2026-06-25","name":"万绍芬","nameOrig":"","country":"中国","region":"","age":96,"fields":["军政"],"identity":"江西省委原书记 · 新中国第一位女性省委书记","summary":"新中国第一位女性省委书记，这个头衔她没用来装饰门面，而是用来兑付责任。","bio":"万绍芬 1930 年 8 月生于江西南昌，1948 年入国立中正大学经济系，参加地下党外围组织与学生运动，1949 年 5 月参加革命工作，1952 年 7 月加入中国共产党。1970 年后历任江西省劳动局副局长、省妇联主任、省委常委兼组织部部长。\n\n1985 年 6 月任江西省委书记，成为新中国第一位女性省委书记。1988 年调任中华全国总工会副主席、党组副书记，同年 12 月起任中央统战部副部长，均为正部长级。1995 年卸任，后连任两届全国人大常委会委员。她是中共第十二、十三届中央委员，第十四届中央纪委委员。\n\n2026 年 6 月 25 日，她因病在北京逝世，享年 96 岁，新华社 7 月 16 日发布讣告。","facts":["1985 年 6 月任江西省委书记，是新中国第一位女性省委书记","曾任中华全国总工会副主席、中央统战部副部长，均为正部长级","系中共第十二届、十三届中央委员"],"obit":null,"portrait":"assets/portraits/2026-06-25-万绍芬.webp","source":"新华社讣告／人民日报","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-06-18-124","date":"2026-06-18","name":"弗朗索瓦·恩格勒","nameOrig":"François Englert","country":"比利时","region":"","age":93,"fields":["科技"],"identity":"比利时理论物理学家 · 2013 年诺贝尔物理学奖得主","summary":"1964 年他和布劳特写下那几页论文时，还没有人知道宇宙的质量从哪儿来。","bio":"恩格勒 1932 年 11 月生于布鲁塞尔埃特贝克，父母是 1924 年从波兰迁来的犹太人。德军占领比利时后，他隐去犹太身份，躲藏在多家孤儿院与儿童之家。1959 年获布鲁塞尔自由大学物理学博士。\n\n1964 年，他与罗伯特·布劳特提出基本粒子通过与遍布宇宙的场相互作用获得质量的机制，彼得·希格斯同期独立提出同一设想。2012 年，CERN 的 ATLAS 与 CMS 实验找到了那个粒子，理论被证实。\n\n2013 年，他与希格斯共获诺贝尔物理学奖。他晚年仍关注基础物理，也公开谈过少年时藏身的经历。2026 年 6 月 18 日，他在于克勒去世。","facts":["1964 年与罗伯特·布劳特提出布劳特—恩格勒—希格斯机制","2013 年与彼得·希格斯共获诺贝尔物理学奖","二战期间以犹太裔身份藏身比利时多家孤儿院","另获沃尔夫物理学奖、樱井奖、阿斯图里亚斯亲王奖"],"obit":null,"portrait":"assets/portraits/2026-06-18-124.webp","source":"Pantheon","verified":"confirmed","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Fran%C3%A7ois_Englert"},{"id":"2026-06-17-卡洛·金茨堡","date":"2026-06-17","name":"卡洛·金茨堡","nameOrig":"Carlo Ginzburg","country":"意大利","region":"","age":87,"fields":["社科"],"identity":"微观史学开创者 · 《奶酪与蛆虫》作者","summary":"一个说「世界由奶酪生出、天使是蛆虫」的磨坊主，被他写成了整部近代早期心态史。","bio":"1939 年生于都灵。父亲莱奥内·金茨堡是反法西斯出版人，1944 年死于法西斯监狱；母亲娜塔莉亚·金茨堡是著名作家。他在比萨高等师范学校师从坎蒂莫里，后任教于博洛尼亚大学与加州大学洛杉矶分校。\n\n1976 年的《奶酪与蛆虫》以一名被宗教裁判所处死的磨坊主重建 16 世纪农民的思想世界，成为微观史学的奠基之作；此前的《夜间的战斗》研究 16 世纪弗留利的本南丹蒂。\n\n2026 年 6 月 17 日逝于博洛尼亚，享年 87 岁。","facts":["1976 年《奶酪与蛆虫》被视为微观史学的开山之作。","父母莱奥内与娜塔莉亚均为意大利著名知识分子。","2010 年获国际巴尔赞奖历史学奖。"],"obit":null,"portrait":"assets/portraits/2026-06-17-卡洛·金茨堡.webp","source":"安莎社、意大利《晚邮报》、《共和国报》讣告","verified":"added","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Carlo_Ginzburg"},{"id":"2026-06-17-亚历山大·萨莫库佳耶夫","date":"2026-06-17","name":"亚历山大·萨莫库佳耶夫","nameOrig":"Александр Самокутяев","country":"俄罗斯","region":"","age":56,"fields":["科技"],"identity":"俄罗斯宇航员 · 两次联盟号飞船指令长","summary":"331 天在轨，两次驾联盟号上天，他是国际空间站长期乘组中第一个离世的人。","bio":"1970 年生于奔萨。1992 年毕业于切尔尼戈夫高等军事航空学校，曾在俄空军任飞行员，2003 年入选宇航员队。\n\n2011 年 4 月，他作为联盟 TMA-21 指令长首飞，在国际空间站远征 27 乘组任飞行工程师，驻留 164 天；2014 年再以联盟 TMA-14M 指令长执行远征 41/42 任务，累计在轨 331 天，获授俄罗斯联邦英雄。\n\n2017 年退役，2020 年 9 月起任国家杜马奔萨州选区议员。2026 年 6 月 17 日去世，享年 56 岁。","facts":["累计在轨 331 天，完成两次太空行走，获俄罗斯联邦英雄称号。","2020 年起任国家杜马议员，代表奔萨州选区。","是国际空间站长期考察组中第一位离世的成员。"],"obit":null,"portrait":null,"source":"塔斯社、俄罗斯国家航天集团（Roscosmos）","verified":"added","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":null},{"id":"2026-06-16-黛薇·雀丝","date":"2026-06-16","name":"黛薇·雀丝","nameOrig":"Daveigh Chase","country":"美国","region":"","age":35,"fields":["影视"],"identity":"《星际宝贝》莉萝配音 · 《七夜怪谈》莎玛拉","summary":"那个为莉萝配音的嗓音留在了无数童年里，她自己只活到 35 岁。","bio":"1990 年生于拉斯维加斯，在俄勒冈州奥尔巴尼长大。2002 年，11 岁的她为迪士尼《星际宝贝》女主角莉萝配音，并因此获得安妮奖；同年她在《七夜怪谈西洋篇》里饰演莎玛拉·摩根，次年拿下 MTV 电影奖最佳反派。\n\n2006 至 2011 年，她在 HBO 剧集《三栖大丈夫》中出演 32 集，此后因药瘾与法律问题淡出银幕。\n\n2026 年 6 月 16 日病逝于洛杉矶一家医院，年仅 35 岁。洛杉矶郡法医其后认定死因为艾滋病。","facts":["2003 年凭《七夜怪谈西洋篇》莎玛拉一角获 MTV 最佳反派奖。","《星际宝贝》2002 年上映时她 11 岁，此后多年持续配音。","曾为宫崎骏《神隐少女》英文版主角千寻配音。"],"obit":null,"portrait":"assets/portraits/2026-06-16-黛薇·雀丝.webp","source":"洛杉矶郡法医报告、BBC、《洛杉矶时报》、中央社","verified":"added","causeOfDeath":"脑膜炎","wikipedia":"https://en.wikipedia.org/wiki/Daveigh_Chase"},{"id":"2026-06-16-罗伯特·瑟曼","date":"2026-06-16","name":"罗伯特·瑟曼","nameOrig":"Robert Thurman","country":"美国","region":"","age":84,"fields":["社科"],"identity":"哥伦比亚大学印藏佛学教授 · 美国藏学奠基人","summary":"他先做了西方第一位藏传佛教僧侣，又用四十年的讲台让藏学进入美国大学。","bio":"1941 年生于纽约，1965 年在印度由达赖喇嘛剃度为僧，成为西方第一位藏传佛教僧侣，数年后还俗。1972 年获哈佛大学梵文与印度学博士学位，1989 年起任哥伦比亚大学宗喀巴讲席教授。\n\n他把宗喀巴的《菩提道次第广论》等著作译介给英语世界，2000 年出版《维摩诘经》新译本，1987 年参与创办西藏之家。\n\n2026 年 6 月 16 日逝于纽约州伍德斯托克，享年 84 岁。","facts":["1965 年在印度受戒，是西方第一位藏传佛教僧侣。","1997 年被《时代》周刊列入全美 25 位最具影响力人物。","1987 年参与创办西藏之家，长期任该机构主席。"],"obit":null,"portrait":null,"source":"美联社讣告、哥伦比亚大学宗教学系","verified":"added","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Robert_Thurman"},{"id":"2026-06-16-卡米洛·鲁伊尼","date":"2026-06-16","name":"卡米洛·鲁伊尼","nameOrig":"Camillo Ruini","country":"意大利","region":"","age":95,"fields":["宗教"],"identity":"意大利主教团主席 · 罗马教区代理主教","summary":"二十年里，意大利天主教会的每一句公开表态，几乎都要经过他的手。","bio":"1931 年生于意大利萨索洛，1954 年晋铎。1986 年出任意大利主教团秘书长，1991 年起同时担任主教团主席与罗马教区代理主教，是约翰·保罗二世与本笃十六世两朝最有权势的意大利枢机。\n\n他被叫作「Don Camillo」，1990 年代至 2000 年代主导意大利天主教会的公共议程，深度介入意大利政治重组。\n\n2026 年 6 月 16 日逝于罗马，享年 95 岁。6 月 18 日，教宗良十四世在圣伯多禄大殿为其主持葬礼。","facts":["1991 年获册封为枢机，领圣阿涅塞堂区衔。","1986 至 2008 年间先后执掌意大利主教团与罗马教区。","曾深度介入意大利 1990 年代政治重组，史称「鲁伊尼时代」。"],"obit":null,"portrait":"assets/portraits/2026-06-16-卡米洛·鲁伊尼.webp","source":"安莎社、梵蒂冈新闻网、罗马教区公报","verified":"added","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Camillo_Ruini"},{"id":"2026-06-14-菲利普·斯特恩","date":"2026-06-14","name":"菲利普·斯特恩","nameOrig":"Philippe Stern","country":"瑞士","region":"","age":87,"fields":["商业"],"identity":"百达翡丽前主席 · 斯登家族第三代掌门人","summary":"石英危机里他押注机械表，替一个家族品牌守住了「没人真正拥有」的独立。","bio":"菲利普·斯特恩 1938 年生于日内瓦，是斯登家族第三代。1932 年其祖父夏尔与叔父让收购百达翡丽，父亲亨利一手搭起品牌的国际分销体系。1966 年正式进入公司，1977 年出任首席执行官，1993 年至 2009 年任总裁。\n\n上任时正值石英危机的谷底，他拒绝为降成本转产石英表，坚持机械制表与家族独立，推进生产垂直整合，1996 年把总部迁至日内瓦 Plan-les-Ouates，同年推出「没人能拥有百达翡丽，只不过为下一代保管而已」的广告语。2009 年他主持创立「百达翡丽印记」，同年把管理权交给儿子泰瑞。\n\n2026 年 6 月 14 日，他安详离世，享年 87 岁，品牌于次日对外公布。","facts":["1977 年出任百达翡丽首席执行官，1993 年至 2009 年任总裁","2009 年主导创立「百达翡丽印记」品质标准","在位期间坚持家族独立，拒绝将品牌出售给大型奢侈品集团"],"obit":null,"portrait":null,"source":"百达翡丽品牌公告／界面新闻","verified":"added","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":null},{"id":"2026-06-13-123","date":"2026-06-13","name":"张克芃","nameOrig":"","country":"中国","region":"中国大陆","age":54,"fields":["文艺"],"identity":"黑豹乐队前主唱 · 94 版《三国演义》张苞饰演者","summary":"他唱了八年黑豹，最出名的角色却是《三国演义》里那个早早战死的张苞。","bio":"张克芃 1972 年 4 月生于北京，又名张大棚、大鹏，1995 年毕业于中国戏曲学院表演系，专攻京剧铜锤花脸。1991 年他先在电影《西行平妖》里演猪八戒，1994 年在央视《三国演义》里演张飞之子张苞。\n\n2005 年秦勇离队，他接任黑豹乐队主唱，一待八年；这段时期乐队没有推出新专辑，主要唱老歌。2013 年因音乐理念不合离开，张淇接任。\n\n离开后他做过云南卫视《中国情歌汇》音乐总监，也常与老皮匠乐队同台。近年身体一直不好，2025 年 8 月还在阿勒泰坐着轮椅登台唱《花祭》。2026 年 6 月 13 日凌晨，他因病离世，终年 54 岁。","facts":["2005 年接替秦勇任黑豹乐队主唱，2013 年因理念不合离队","1995 年毕业于中国戏曲学院表演系，专攻京剧铜锤花脸","1991 年在《西行平妖》中饰猪八戒，94 版《三国演义》饰张苞"],"obit":true,"portrait":null,"source":"黑豹乐队官方讣告","verified":"confirmed","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":null},{"id":"2026-06-12-122","date":"2026-06-12","name":"陈敏儿","nameOrig":"","country":"中国","region":"香港","age":65,"fields":["影视"],"identity":"香港演员、主持 · 1979 年无线艺训班出身的当家花旦","summary":"她给自己办过一场生前告别会，把想说的话都说完，然后安静地走了。","bio":"陈敏儿 1959 年生于香港，1979 年入读第八期无线电视艺员训练班，与后来的丈夫廖启智同届。凭清丽形象与口才，她在八十年代成为TVB当家花旦。\n\n她与刘德华合演《猎鹰》担正女主角，另演出《天降财神》《神勇CID》《男儿本色》，多次饰演教师、社工、律师一类角色。1987 年与廖启智结婚，育有三子，幼子三岁患血癌、五岁病逝。\n\n廖启智 2021 年因胃癌离世后，她低调生活。作为慢性病患者，她 2025 年做了一场大手术，术前向两个儿子交代后事，办了「生前告别会」，说若死亡来临她「OK」。2026 年 6 月 12 日上午，她在威尔斯亲王医院病逝。","facts":["1979 年入读第八期无线电视艺员训练班，与廖启智同届","与刘德华合演《猎鹰》任女主角，另演出《天降财神》《男儿本色》","2025 年动大手术前举办「生前告别会」，向家人交代后事"],"obit":true,"portrait":"assets/portraits/2026-06-12-122.webp","source":"港媒","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-06-09-吴文忻","date":"2026-06-09","name":"吴文忻","nameOrig":"Natalie Ng","country":"中国香港","region":"","age":51,"fields":["影视"],"identity":"1998 年港姐季军 · TVB 演员，《功夫足球》","summary":"港姐季军、抗癌四年，她把自己的病房写成日记，一直写到最后一页才停笔。","bio":"吴文忻 1974 年 10 月生于香港，1998 年参选香港小姐获季军入行，成为 TVB 艺人，拍过《街市的童话》《情迷大话王》《功夫足球》等剧集，也做过节目主持。\n\n2022 年她确诊乳腺癌，2024 年公开复发，2025 年恶化至第四期，癌细胞转移至尾龙骨与肝脏，2026 年又扩散到脑部。治疗期间她被人骗走全部积蓄，卖掉出嫁时的金器筹药费，仍婉拒好友募捐。她把自己的抗癌过程拍成日记，还办了一场生前追思会，说这样便克服了对死亡的恐惧。2025 年她推出人生第一首歌《重生》，凭此获新城劲爆颁奖礼「劲爆我撑新人」奖。\n\n2026 年 6 月 9 日清晨，她在医院睡梦中离世，终年 51 岁。","facts":["1998 年香港小姐竞选获季军，参赛编号 6 号","2025 年推出单曲《重生》，获新城劲爆颁奖礼新人奖","抗癌期间被骗光积蓄，变卖出嫁金器支付医药费"],"obit":null,"portrait":"assets/portraits/2026-06-09-吴文忻.webp","source":"家属及好友发布的讣告／中国新闻网、香港文汇网","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-06-08-河野洋平","date":"2026-06-08","name":"河野洋平","nameOrig":"河野洋平","country":"日本","region":"","age":89,"fields":["军政"],"identity":"日本前内阁官房长官 · 「河野谈话」发表者","summary":"一份承认强征「慰安妇」并谢罪的谈话，让他在历史的账本上留下了自己的名字。","bio":"河野洋平 1937 年生于神奈川县，其父河野一郎亦是政界重镇。1967 年首次当选众议员，此后历任内阁官房长官、外务大臣、众议院议长，也当过自民党总裁，却始终与首相之位差一步。\n\n1993 年 8 月，以内阁官房长官身份发表「河野谈话」，代表日本政府首次承认军方直接参与朝鲜半岛、中国等地设置「慰安所」并强征当地妇女，表示道歉与反省。与「村山谈话」一道，它成为日本战后历史认知的基石。他反对首相参拜靖国神社，坚持一个中国原则。2006 年起任日本国际贸易促进协会会长，此后几乎每年率团访华。\n\n2026 年 6 月 8 日，他因胰腺癌去世，享年 89 岁。弥留之际他流着泪说，想再去一次中国。","facts":["1993 年发表「河野谈话」，承认日军强征「慰安妇」并谢罪","2006 年起任日本国际贸易促进协会会长，此后几乎每年访华","长期反对日本首相参拜靖国神社，坚持一个中国原则"],"obit":null,"portrait":"assets/portraits/2026-06-08-河野洋平.webp","source":"新华社／人民日报、中国新闻网","verified":"added","causeOfDeath":"胰腺癌","wikipedia":null},{"id":"2026-06-08-周爱卿","date":"2026-06-08","name":"周爱卿","nameOrig":"","country":"中国","region":"","age":89,"fields":["医药"],"identity":"儿科学专家 · 中国先心病介入治疗开创者之一","summary":"在鸡蛋大小的心脏里硬开出一条通路，他为无数先心病孩子争回了完整的一生。","bio":"周爱卿 1961 年从上海第二医学院儿科系毕业，此后近六十年都在新华医院小儿心血管领域工作，是新华医院小儿心血管专业开创者之一，曾任上海儿童医学中心心内科主任。\n\n上世纪八十年代初，他率先在国内开展婴儿紫绀型先心病的临床研究，1981 年首次系统报道新生儿完全性大动脉转位球囊房隔造口术，此后陆续开展十余项国内首创的介入诊疗技术。1986 年至 1989 年，他领衔研制国产球囊扩张导管，填补国内空白。他主编了我国首部先心病介入诊疗专著《心导管术——先天性心脏病诊断与治疗》。\n\n他常说「儿童不是缩小版的成人」。2026 年 6 月 8 日 19 时 54 分，他在上海逝世，享年 89 岁。","facts":["1981 年国内首次系统报道新生儿球囊房隔造口术","领衔研制国产球囊扩张导管，填补国内技术空白","获中国儿科医师终身成就奖、中国介入心脏病学终身成就奖"],"obit":null,"portrait":"assets/portraits/2026-06-08-周爱卿.webp","source":"上海交通大学医学院附属新华医院讣告","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-06-06-张治中","date":"2026-06-06","name":"张治中","nameOrig":"","country":"中国","region":"","age":70,"fields":["影视"],"identity":"山西省话剧院一级演员 · 94 版《三国演义》马谡","summary":"挥泪斩马谡那一场，他把悔恨与不甘全留在眼眶里，四十年后仍被人反复回看。","bio":"张治中 1957 年 2 月生于山西万荣，1979 年考入山西省戏剧学校话剧班，1983 年进入山西省话剧院，在舞台上站了四十余年，主演二十余部话剧、五十余部电视剧及小品。\n\n观众最熟悉他两个电视剧角色：94 版《三国演义》的马谡与 98 版《水浒传》的晁盖。前者在「挥泪斩马谡」一场里把悔恨、不甘演到骨子里，后者是从智取生辰纲到曾头市中箭落幕的托塔天王。话剧方面，他在《立秋》中饰许凌翔、《元朝帝师八思巴》中饰八思巴，2000 年获中国戏剧梅花奖，次年获中国话剧金狮奖。他还是中共十七大代表，享受国务院政府特殊津贴。\n\n2026 年 6 月 6 日下午，他因病在太原逝世，享年 70 岁。","facts":["94 版《三国演义》饰马谡，98 版《水浒传》饰晁盖","2000 年凭话剧《元朝帝师八思巴》获中国戏剧梅花奖","主演的话剧《立秋》在海峡两岸演出逾百场"],"obit":null,"portrait":"assets/portraits/2026-06-06-张治中.webp","source":"山西省话剧院讣告／澎湃新闻、光明网","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-06-03-121","date":"2026-06-03","name":"钟景辉","nameOrig":"","country":"中国","region":"香港","age":89,"fields":["文艺"],"identity":"香港戏剧教育家 · 香港演艺学院戏剧学院创院院长","summary":"周润发当年差点被艺训班刷掉，是他投了那一票；香港舞台剧半个班底，也是他带出来的。","bio":"钟景辉 1937 年 3 月生于香港，祖籍广东台山，美国奥克拉荷马浸会大学学士、耶鲁大学戏剧学院艺术硕士。1967 年加入TVB任高级编导，同年升任节目部经理。\n\n1971 年他向无线提议开办一年制艺员训练班，并亲自带首四期；周润发面试表现生涩差点落选，他投了关键一票。1983 至 2001 年，他出任香港演艺学院戏剧学院创院院长，1984 年创立香港戏剧协会。\n\n舞台上他执导逾八十部戏，八度获香港舞台剧奖最佳男主角、四度获最佳导演，2013 年获银紫荆星章；电视上他演过《甜孙爷爷》《律政强人》《使徒行者》，也为《寻找他乡的故事》配旁白。2016 年确诊大肠癌后淡出。","facts":["1971 年提议开办TVB艺员训练班，兼任首四期导师","1983 至 2001 年任香港演艺学院戏剧学院创院院长","八度获香港舞台剧奖最佳男主角、四度获最佳导演，2013 年获银紫荆星章"],"obit":true,"portrait":"assets/portraits/2026-06-03-121.webp","source":"港媒 / 界面新闻","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-06-02-黄大炜","date":"2026-06-02","name":"黄大炜","nameOrig":"David Wong","country":"美国","region":"","age":61,"fields":["文艺"],"identity":"歌手、音乐人 · 《你把我灌醉》作曲原唱","summary":"《你把我灌醉》在华语乐坛唱了三十多年，作曲的那个人自己在夏威夷安静地走了。","bio":"黄大炜 1964 年 9 月生于香港，母亲是张闾蘅，外公是张学良的弟弟张学森，幼年在夏威夷长大。大学时老师送他一把吉他，他靠自学摸出演奏与创作。1988 年推出首张专辑《David 黄》出道，1990 年的《让每个人都心碎》让他站稳脚跟，1994 年专辑《手下留情》里的《你把我灌醉》成为华语流行乐的传唱经典。\n\n他唱、作、编俱能，曾以《秋天 1944》获金曲奖最佳编曲人奖。2025 年 12 月底他离开台湾迁居夏威夷，亲人说他在生命最后一个月仍期待带着音乐重新出发。\n\n2026 年 6 月 2 日（檀香山时间，即北京时间 6 月 3 日），他在檀香山姐姐家中离世，享年 61 岁，家属通过律师声明对外公布。","facts":["1990 年《让每个人都心碎》同名主打歌成为其代表作之一","《你把我灌醉》曾被张惠妹、黄小琥、萧敬腾等人翻唱","曾以《秋天 1944》获金曲奖最佳编曲人奖"],"obit":null,"portrait":"assets/portraits/2026-06-02-黄大炜.webp","source":"家属律师声明／中央社、界面新闻","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-06-01-魏宗万","date":"2026-06-01","name":"魏宗万","nameOrig":"","country":"中国","region":"","age":89,"fields":["影视"],"identity":"国家一级演员 · 94 版《三国演义》司马懿","summary":"他把鹰视狼顾演成一眼定格的阴影，三十多年过去，提起司马懿仍是他那张脸。","bio":"魏宗万 1938 年 11 月生于上海，早年在上海汽轮机厂当钳工，三次备考才考进上海戏剧学院，1963 年毕业进入上海人民艺术剧院，在话剧舞台上扎根二十余年，44 岁才正式转向影视。\n\n1983 年他凭《一个和八个》首登大银幕，1993 年以《三毛从军记》里的老鬼获金鸡奖最佳男配角。1994 年在《三国演义》中演司马懿，1998 年在《水浒传》中演高俅，两个反派一正一邪，都成了难以替换的荧幕形象。他一生不接商业代言、不参加综艺，认定演员的价值只在角色里。\n\n2026 年 6 月 1 日，他因病在上海华东医院逝世，享年 89 岁，告别仪式于 6 月 5 日在龙华殡仪馆举行。","facts":["1983 年凭电影《一个和八个》首次登上大银幕","1993 年以《三毛从军记》老鬼一角获金鸡奖最佳男配角","侯宝林曾赠他四句话：恰到好处，留有余地；宁可不够，切勿过头"],"obit":null,"portrait":"assets/portraits/2026-06-01-魏宗万.webp","source":"上海话剧艺术中心讣告／人民日报、澎湃新闻","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-05-31-陈宝存","date":"2026-05-31","name":"陈宝存","nameOrig":"Francisco Xavier Chan Pou Chun","country":"中国澳门","region":"","age":89,"fields":["宗教"],"identity":"天主教澳门教区司铎 · 六座堂区本堂神父","summary":"晋铎六十余载，他在澳门六座堂区之间搬来搬去，一句「去哪里服务，就去那里」。","bio":"1937 年 3 月 5 日生于澳门，翌年 4 月 21 日在望德圣母堂领洗，1964 年 6 月 28 日晋铎。此后六十余年，他的牧职足迹踏遍澳门：望德堂、圣安多尼堂、主教座堂、嘉模圣母堂、花地玛堂、圣老楞佐堂，多为主任司铎。\n\n除堂区工作，他还任圣母军神师、若望廿三世社会服务中心主任，1981 年起兼任明爱辖下所有安老院的牧灵神师，1991 至 1992 年间出任圣善学校校长。2014 年改任圣安多尼堂副主任司铎，2018 年 8 月 31 日正式荣休。教友记得他勤勉、谦逊、爱听人说话。\n\n2026 年 5 月 31 日，他在澳门协和医院病逝，89 岁。","facts":["1964 年 6 月 28 日晋铎，服务逾六十年","历任澳门六座堂区主任或副主任司铎","1981 年起兼任明爱安老院牧灵神师","殡葬弥撒于 2026 年 6 月 13 日举行"],"obit":null,"portrait":null,"source":"天主教澳门教区讣告、教区《号角报》","verified":"added","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":null},{"id":"2026-05-31-菅原洋一","date":"2026-05-31","name":"菅原洋一","nameOrig":"菅原洋一","country":"日本","region":"","age":92,"fields":["文艺"],"identity":"歌手 · 探戈歌谣代表，〈今天就此别过〉原唱","summary":"他把探戈的低音唱成日本歌谣，红白歌会连着二十二年为他留了位置。","bio":"1933 年 8 月 21 日生于兵库县加古川市。中学时迷上探戈，国立音乐大学声乐专攻科首席毕业，之后在探戈茶馆里唱歌，被乐队长早川真平看中，1958 年以探戈歌手出道。\n\n1967 年〈不想知道〉卖出八十万张，他第一次登上 NHK 红白歌会，此后连续 22 年出场，是白组的台柱。1968 年〈谁都不在〉获日本唱片大赏歌唱奖，1970 年〈今天就此别过〉拿下日本唱片大赏。晚年他仍坚持真唱真奏的「新古典音乐会」，2026 年 4 月还坐着轮椅在东京上野登台。\n\n2026 年 5 月 31 日上午 9 时 26 分，他因恶性淋巴瘤在东京的医院去世，92 岁。","facts":["1967 年〈不想知道〉销量突破八十万张","连续 22 年登上 NHK 红白歌会","1970 年以〈今天就此别过〉获日本唱片大赏","去世前一个月仍在东京上野开演唱会"],"obit":null,"portrait":"assets/portraits/2026-05-31-菅原洋一.webp","source":"日本歌手协会讣告、朝日新闻","verified":"added","causeOfDeath":"淋巴瘤","wikipedia":null},{"id":"2026-05-31-120","date":"2026-05-31","name":"顾诵芬","nameOrig":"","country":"中国","region":"中国大陆","age":96,"fields":["科技"],"identity":"两院院士 · 飞机空气动力学家、「歼-8 之父」","summary":"为了弄清歼-8 抖振的来由，他瞒着家人坐上教练机，三次跟到天上去看。","bio":"顾诵芬 1930 年 2 月生于江苏苏州，父亲是国学大师顾廷龙。1937 年日军轰炸北平，7 岁的他立志设计飞机，10 岁生日收到叔叔送的一架航模。1951 年从上海交通大学航空系毕业。\n\n他接手的第一个任务是歼教-1 的气动力设计，国内没有先例，他骑车去北航图书馆抄录国外文献。1964 年歼-8 上马，他先任副总设计师管气动力，后任总设计师；为查清发动机喷流引起的抖振，他瞒着家人乘教练机三次升空贴近观察。\n\n他奠定了我国亚音速与超音速飞机气动力设计的基石，是航空界唯一的中科院、工程院双院士，2020 年度国家最高科学技术奖得主。2026 年 5 月 31 日 21 时 11 分，他在北京逝世。","facts":["我国航空界唯一的中科院、工程院双院士，1991 年当选学部委员","主持歼教-1、歼-8、歼-8Ⅱ气动力与总体设计","2020 年度国家最高科学技术奖得主，另获国家科技进步特等奖"],"obit":true,"portrait":"assets/portraits/2026-05-31-120.webp","source":"新华社","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-05-30-郑琇月","date":"2026-05-30","name":"郑琇月","nameOrig":"","country":"中国台湾","region":"","age":69,"fields":["文艺"],"identity":"台语歌手 · 〈白色的爱〉原唱","summary":"一首〈白色的爱〉唱遍全台，而她最懂的，是歌里那些进工厂养家的女工。","bio":"生于新北市，十几岁便半工半读，在味王公司当包装女工。哥哥替她报名陈和平综艺团的歌唱比赛，她拿了冠军，被月球唱片看中，从此进歌坛，曾与凤飞飞同台。\n\n1977 年她推出首张专辑《一个女工的故事》，唱的是自己的来路，意外成了那个年代女工的代言歌，后来还被改编成同名电影。她唱红〈白色的爱〉〈牛犁歌〉〈六月茉莉〉〈可爱的花蕊〉，与林礼涵、杨三郎、周添旺、吴晋淮等台语歌谣大家合作。婚后她淡出歌坛，与丈夫在北投经营温泉会馆，女儿何以奇也做了歌手。\n\n2026 年 5 月 30 日凌晨，她因肺腺癌去世，享寿 69 岁。","facts":["〈白色的爱〉为同名电视剧主题曲，1979 年唱红全台","1977 年推出首张专辑《一个女工的故事》","出道前在味王公司当包装女工，半工半读","女儿何以奇继承衣钵，亦是出道歌手"],"obit":null,"portrait":null,"source":"杨贵媚、龙千玉社交媒体证实，三立、中时、TVBS 报道","verified":"added","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":null},{"id":"2026-05-30-胡里奥·勒帕克","date":"2026-05-30","name":"胡里奥·勒帕克","nameOrig":"Julio Le Parc","country":"阿根廷","region":"","age":97,"fields":["文艺"],"identity":"动力艺术、欧普艺术家 · GRAV 共同创办人","summary":"他让观众走进作品，伸手拨动光影——艺术从此不只是「看」，还可以被触碰。","bio":"1928 年 9 月 23 日生于阿根廷门多萨的帕尔米拉，十三岁离家到布宜诺斯艾利斯学画。1958 年拿到法国政府奖学金赴巴黎，从此没有真正离开。1960 年他与莫雷莱等人共同创立「视觉艺术研究小组」（GRAV），把光、运动、反射和观众的脚步当作材料。\n\n1966 年他在威尼斯双年展获绘画大奖，两年后因参与五月风暴被驱逐出法国，仍继续做他的光影实验。作品被纽约现代艺术博物馆、蓬皮杜中心、泰特现代美术馆收藏。泰特原定 6 月 11 日开幕的大型回顾展，他没能等到。\n\n2026 年 5 月 30 日，他在巴黎去世，97 岁。","facts":["1960 年参与创立视觉艺术研究小组 GRAV","1966 年获威尼斯双年展绘画大奖","作品藏于纽约现代艺术博物馆、蓬皮杜与泰特","泰特回顾展在其身后 12 天开幕"],"obit":null,"portrait":"assets/portraits/2026-05-30-胡里奥·勒帕克.webp","source":"家属确认（其子 Yamil Le Parc）、泰特现代美术馆","verified":"added","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Julio_Le_Parc"},{"id":"2026-05-29-埃德加·莫兰","date":"2026-05-29","name":"埃德加·莫兰","nameOrig":"Edgar Morin","country":"法国","region":"","age":104,"fields":["社科"],"identity":"哲学家、社会学家 · 复杂性思维提出者","summary":"他用「复杂性」三个字提醒世人：把事物拆成零件来理解，就永远理解不了它。","bio":"1921 年生于巴黎，原名 Edgar Nahoum。二战期间加入抵抗运动，用「莫兰」这个化名活动，此后一生沿用。1950 年进入法国国家科学研究中心，后来做到研究主任，在哲学、社会学、人类学与生物学之间来回穿行。\n\n他把毕生思考写成六卷《方法》，主张知识不能切片，现实是由关系、反馈与不确定性织成的整体，由此提出「复杂性思维」与「多重危机」两个今天被反复借用的说法。著作逾百部，译成三十余种语言，获三十八所大学荣誉博士。\n\n2026 年 5 月 29 日，他在巴黎去世，距 105 岁生日只差四十天。","facts":["六卷本《方法》为复杂性思想奠基之作","提出「多重危机」概念，认为各场危机彼此纠缠","获三十八所大学颁授荣誉博士学位","二战期间参加法国抵抗运动，用化名莫兰"],"obit":null,"portrait":"assets/portraits/2026-05-29-埃德加·莫兰.webp","source":"Le Monde 讣闻、法国国家科学研究中心","verified":"added","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Edgar_Morin"},{"id":"2026-05-29-刘红梅","date":"2026-05-29","name":"刘红梅","nameOrig":"","country":"中国","region":"","age":61,"fields":["影视"],"identity":"中央戏剧学院教授、演员 · 音乐剧教育拓荒者","summary":"荧幕上她只演了几场配角，讲台上她却把中国音乐剧的第一批学生带了出来。","bio":"1965 年 12 月生。从小习武，拿过少儿武术冠军，后来改学舞蹈，因这身功底被李连杰挑中，在《方世玉》里演骆冰、《太极张三丰》里演刘瑾的妹妹。央视版《水浒传》里她是蒋门神之妻，镜头不多，却让人记住了那张脸。\n\n1991 年她从中戏表演系毕业留校，一教三十余年。她是中戏音乐剧专业的拓荒者之一，曾任音乐剧系主任、表演系党支部书记，把《西区故事》《为你疯狂》搬进课堂，也用音乐剧讲巴金的《家》。孙红雷、靳东、张新成都是她的学生。2025 年她获北京市三八红旗奖章。\n\n2026 年 5 月 29 日清晨，她因病在北京去世，61 岁。","facts":["1991 年毕业于中戏表演系并留校任教","曾任中央戏剧学院音乐剧系主任、表演系党支部书记","学生有孙红雷、靳东、张新成等一批演员","出演央视版《水浒传》蒋门神之妻"],"obit":null,"portrait":"assets/portraits/2026-05-29-刘红梅.webp","source":"中央戏剧学院官网资料、北青娱见、澎湃新闻","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-05-29-刘洵","date":"2026-05-29","name":"刘洵","nameOrig":"Lau Shun","country":"中国香港","region":"","age":87,"fields":["影视"],"identity":"京剧演员、香港电影配角 · 人称千面如来","summary":"贴上胡子是黄麒英，摘下胡子是李莲英——一张脸在正邪之间来回，人唤千面如来。","bio":"1939 年 4 月 10 日生于北京，六岁入京剧科班，受李万春、盖叫天等前辈指点，1958 年毕业后进中国京剧院任教二十余年。1980 年南下香港，在香港演艺学院任讲师，转而钻研粤剧，罗家英、汪明荃等名角都曾随他学艺。\n\n1986 年他为徐克《刀马旦》做戏曲指导，顺手客串一角，四十七岁才以新人身份入影坛。此后在近百部港片里演配角：1990 年《笑傲江湖》的太监古今福让他提名第 10 届香港电影金像奖最佳男配角，《新龙门客栈》的贾廷、《九品芝麻官》的李莲英、《黄飞鸿》的黄麒英，正邪两副面孔都立得住。\n\n2026 年 5 月 29 日下午，他在香港离世，87 岁。","facts":["1990 年凭《笑傲江湖》提名香港金像奖最佳男配角","香港演艺学院中国戏曲课程统筹及艺术指导","罗家英、汪明荃等粤剧名角的戏曲老师","2019 年获香港演艺学院荣誉院士"],"obit":null,"portrait":"assets/portraits/2026-05-29-刘洵.webp","source":"罗家英社交媒体讣告、香港演艺学院背景资料","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-05-28-119","date":"2026-05-28","name":"阿卜杜拉布·曼苏尔·哈迪","nameOrig":"Abdrabbuh Mansur Hadi","country":"也门","region":"","age":80,"fields":["军政"],"identity":"也门前总统 · 2012 至 2022 年在位，客死于利雅得","summary":"在萨利赫的影子里当了十七年副总统，又被推上总统席，最后客死利雅得。","bio":"哈迪 1945 年 9 月生于也门南部阿比扬省的部族家庭，先后在埃及纳赛尔高等军事学院和苏联伏龙芝军事学院学习，参加过 1967 年南也门独立斗争，在南也门军队中历任装甲部队参谋、后勤事务副总参谋长。\n\n1990 年南北也门统一后他任总统委员会顾问，1994 年 5 月出任国防部长，同年 10 月起任副总统。2011 年也门政治动荡，萨利赫交权，2012 年 2 月他以唯一候选人身份当选总统。\n\n2014 年 9 月胡塞武装攻占萨那，他出走沙特；2015 年沙特等国发起「果断风暴」军事行动。2022 年 4 月，他把权力移交给新成立的总统领导委员会。2026 年 5 月 28 日，他在利雅得去世，终年 80 岁。","facts":["1994 年任也门国防部长，同年 10 月起任副总统","2012 年 2 月作为唯一候选人当选总统，2022 年 4 月移交权力","2014 年胡塞武装攻占萨那后出走沙特，长期居于利雅得"],"obit":null,"portrait":"assets/portraits/2026-05-28-119.webp","source":"Pantheon","verified":"confirmed","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Abdrabbuh_Mansur_Hadi"},{"id":"2026-05-28-118","date":"2026-05-28","name":"安云武","nameOrig":"","country":"中国","region":"中国大陆","age":78,"fields":["文艺"],"identity":"京剧老生 · 马连良亲传弟子、央视《西游记》「福星」饰演者","summary":"他是马连良的亲传弟子，也在《西游记》里当过那个笑呵呵给人添寿的福星。","bio":"安云武 1948 年 6 月生于北京，1958 年考入北京市戏曲学校，受余叔岩弟子王少楼开蒙学谭余派；1962 年得校长马连良亲授《审头刺汤》并完成首演，1975 年拜师马最良，又向叶盛长、王金璐等马派名家求教。\n\n他是北京京剧院一级演员，工老生，唱念兼容南麒北马，代表剧目有《四郎探母》《乌龙院》《海瑞罢官》。1993 年获梅兰芳金奖大赛老生组提名奖，2017 年获第 24 届全球中华文化艺术薪传奖。\n\n观众更熟悉他在央视版《西游记》里客串的那个「福星」。晚年他长期从事京剧教学。2026 年 5 月 28 日 20 时 42 分，他因病在北京逝世，享年 78 岁。","facts":["1958 年考入北京市戏曲学校，1962 年得马连良亲授《审头刺汤》","代表剧目《四郎探母》《乌龙院》《海瑞罢官》，1993 年获梅兰芳金奖大赛提名奖","2017 年获第 24 届全球中华文化艺术薪传奖"],"obit":true,"portrait":"assets/portraits/2026-05-28-118.webp","source":"北京京剧院 / 极目新闻","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-05-26-尹衍樑","date":"2026-05-26","name":"尹衍樑","nameOrig":"","country":"中国台湾","region":"","age":76,"fields":["商业"],"identity":"润泰集团总裁 · 大润发创办人","summary":"他把「信用」当本钱，从格子布、预铸工法做到大润发，最后把九成五的财产签给了公益。","bio":"1950 年生于台北，祖籍山东日照。少年时是让人头疼的叛逆孩子，一度被送进感化院，后来一路读到博士。26 岁接手父亲的润泰纺织，把它做成横跨地产、金融、零售、生技的集团。\n\n1996 年他创立大润发量贩体系，1997 年上海开出大陆首店，2009 年以 404 亿元营收超过家乐福，成为中国大陆零售业冠军。1989 年设光华教育基金会，1994 年捐资推动北京大学工商管理学院更名组建光华管理学院并任创始董事长，2012 年出资新台币 30 亿元创办唐奖。\n\n2026 年 5 月 26 日凌晨，他在台北荣民总医院去世，76 岁。家属遵其遗愿，不设灵堂、不举行公祭。","facts":["1996 年创立大润发，1997 年上海开首店","2012 年出资新台币 30 亿元创办唐奖","北京大学光华管理学院创始董事长","曾立遗嘱捐出 95% 财产做公益"],"obit":null,"portrait":"assets/portraits/2026-05-26-尹衍樑.webp","source":"润泰集团声明、北京大学光华管理学院讣告","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-05-25-桑尼·罗林斯","date":"2026-05-25","name":"桑尼·罗林斯","nameOrig":"Sonny Rollins","country":"美国","region":"","age":95,"fields":["文艺"],"identity":"美国爵士萨克斯风手 · 「萨克斯巨人」","summary":"1956 年那张《Saxophone Colossus》，让次中音萨克斯从此有了自己的标高。","bio":"罗林斯 1930 年生于纽约哈莱姆。少年时学钢琴，后改中音萨克斯，再转向次中音。1949 年因持械抢劫入狱十个月，出狱后戒毒，五十年代初与迈尔斯·戴维斯、塞隆尼斯·孟克、查理·帕克合作，几年间录下《Tenor Madness》《Saxophone Colossus》，成为硬波普的代表人物。\n\n1959 年至 1961 年，他两度退出舞台，深夜到威廉斯堡大桥上独自练习，桥上的风声足以盖过音量而不扰人，复出后推出《The Bridge》。他拒绝被归入波普一支，把卡利普索、拉丁、放克一并纳入自己的语汇。2012 年因肺纤维化停止公开演出，此后仍每日练琴。","facts":["1956 年录制专辑《Saxophone Colossus》，成为硬波普的标杆","曾在威廉斯堡大桥上独自练琴近三年，以免扰邻","2011 年获肯尼迪中心荣誉奖，是爵士乐界的最高礼遇之一","一生发行唱片逾 60 张，两度获格莱美奖"],"obit":null,"portrait":"assets/portraits/2026-05-25-桑尼·罗林斯.webp","source":"罗林斯官网家属声明、美联社、Paste Magazine","verified":"added","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Sonny_Rollins"},{"id":"2026-05-19-巴尼·弗兰克","date":"2026-05-19","name":"巴尼·弗兰克","nameOrig":"Barney Frank","country":"美国","region":"","age":86,"fields":["军政"],"identity":"美国政治家 · 前联邦众议员，金融监管改革主导者","summary":"在这个国家最讲权力的地方，他先承认自己是谁，再去改写华尔街的规则。","bio":"弗兰克 1940 年生于新泽西州贝永，在犹太裔工人家庭长大，哈佛大学毕业后任波士顿市长幕僚，1972 年当选马萨诸塞州众议员，1981 年进入联邦众议院，代表波士顿郊区选区长达三十二年。\n\n1987 年，他成为美国首位自愿公开同性恋身份的联邦众议员，2012 年又成为首位在任内结婚的同性恋议员。2007 年至 2011 年任众议院金融服务委员会主席，金融危机后与参议员多德共同起草 2010 年《多德—弗兰克华尔街改革与消费者保护法》，收紧对银行的监管。2026 年 4 月因充血性心力衰竭进入临终关怀，5 月 19 日在缅因州奥甘奎特家中去世。","facts":["1981 年至 2013 年任联邦众议员，代表马萨诸塞州第四选区","1987 年成为首位自愿公开同性恋身份的美国联邦众议员","2010 年《多德—弗兰克法案》共同起草人","在任内推动设立美国消费者金融保护局"],"obit":null,"portrait":"assets/portraits/2026-05-19-巴尼·弗兰克.webp","source":"纽约时报讣闻、美联社、家属确认","verified":"added","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Barney_Frank"},{"id":"2026-05-18-铃木敏文","date":"2026-05-18","name":"铃木敏文","nameOrig":"鈴木敏文","country":"日本","region":"","age":93,"fields":["商业"],"identity":"日本企业家 · 7-ELEVEn 日本事业奠基人","summary":"他把美国的杂货铺搬进日本的街角，然后改造成一座 24 小时运转的生活基础设施。","bio":"铃木敏文 1932 年生于长野县埴科郡坂城町，1956 年毕业于中央大学经济学部，先入东京出版贩卖（今东贩），1963 年转入伊藤洋华堂。1973 年主导与美国的南方公司签约成立 York Seven，翌年在东京丰洲开出日本第一家 7-Eleven。\n\n他推翻大店才好的成见，用密集开店、共同配送和单品管理重写了日本零售的效率标准，又陆续把 ATM、公共事业费代缴、快递代收塞进小小的店铺，让便利店成为社区基础设施。2016 年因人事风波辞去会长，转任名誉顾问。2026 年 5 月 18 日因心力衰竭在东京去世，公司于 5 月 25 日发布讣告。","facts":["1974 年在东京丰洲开设日本第一家 7-Eleven 门店","主导 7-Eleven 反向收购美国南方公司","推行单品管理与共同配送，奠定便利店经营范式","1992 年起任伊藤洋华堂社长、7-Eleven 日本会长"],"obit":null,"portrait":"assets/portraits/2026-05-18-铃木敏文.webp","source":"柒和伊控股讣告、朝日新闻、日视新闻","verified":"added","causeOfDeath":"心力衰竭","wikipedia":null},{"id":"2026-05-15-埃德蒙·费尔普斯","date":"2026-05-15","name":"埃德蒙·费尔普斯","nameOrig":"Edmund Phelps","country":"美国","region":"","age":92,"fields":["社科"],"identity":"美国经济学家 · 2006 年诺贝尔经济学奖得主","summary":"他证明了通胀换不来就业，从此各国央行多了一条不肯让步的底线。","bio":"费尔普斯 1933 年生于美国伊利诺伊州埃文斯顿，在纽约哈得孙河畔长大，大学时由人文学科转向经济学，1959 年在耶鲁大学获博士学位，师从诺奖得主詹姆斯·托宾。1971 年起执教哥伦比亚大学，此后半个世纪以哥大为主要学术基地。\n\n1967 年与 1968 年的两篇论文，动摇了通胀可以永久换取低失业的菲利普斯曲线信念。他提出，一旦预期被正确预见，失业率终将回到由结构性因素决定的自然水平。1970 年代的滞胀验证了这一判断，通胀目标制由此成为各国央行的框架。他于 2006 年获诺贝尔经济学奖，晚年转向经济活力研究，《大繁荣》是这一阶段的代表作。","facts":["2006 年获诺贝尔经济学奖，表彰其对宏观经济政策跨期权衡的分析","1968 年提出自然失业率理论，被视为通胀目标制的思想源头","曾任哥伦比亚大学资本主义与社会研究中心创始主任","曾被聘为中国人民大学荣誉教授、获清华大学荣誉博士学位"],"obit":null,"portrait":"assets/portraits/2026-05-15-埃德蒙·费尔普斯.webp","source":"金融时报讣闻、诺贝尔奖官网悼念、哥伦比亚大学","verified":"added","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Edmund_Phelps"},{"id":"2026-05-10-李继熊","date":"2026-05-10","name":"李继熊","nameOrig":"","country":"中国","region":"","age":95,"fields":["社科"],"identity":"保险教育家 · 中国保险学科奠基人","summary":"中国大陆第一个「国际保险」专业、第一个保险系，都是他在教研室里一点点办起来的。","bio":"1931 年生于江苏苏州。1948 年进入保险业做实务，1955 年入中央财政干部学校保险专修班，次年起留校任教，此后七十年只做一件事：把保险当成一门学科来教。\n\n1980 年他主持创建全国首个「国际保险」专业，1986 年推动成立国内第一个保险系并任主任，1993 年引进英国精算课程体系、设立保险精算研究所。他主编《保险概论》《海上保险》，搭起中国保险学的教材骨架，2017 年获「中国金融学科终身成就奖」，还被国际保险学会评为全球十大保险教育研究杰出贡献专家。\n\n2026 年 5 月 10 日上午 8 时，他因病在北京去世，95 岁。","facts":["1980 年主持创建全国首个「国际保险」专业","1986 年推动成立国内第一个保险系","主编《保险概论》《海上保险》等教材","2017 年获中国金融学科终身成就奖"],"obit":null,"portrait":"assets/portraits/2026-05-10-李继熊.webp","source":"中央财经大学保险学院、中国精算研究院讣告","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-05-09-116","date":"2026-05-09","name":"苏哲子","nameOrig":"","country":"中国","region":"中国大陆","age":90,"fields":["科技"],"identity":"中国工程院院士 · 外贸 155 毫米自行炮武器系统总设计师","summary":"他提出「五化一体」，让中国的大口径火炮第一次整套卖到十几个国家。","bio":"苏哲子 1935 年 12 月生于陕西咸阳，1959 年从北京工业学院毕业，分配到国营第六七四厂，先做我国第一代轻型坦克，再做大口径 152 毫米自行加榴炮。\n\n此后他主持研制外贸 155 毫米自行炮与轮式自走炮武器系统，率先提出信息化、数字化、自动化、机械化、自行化「五化一体」的设计理念，在国内首次做出体系复杂、射程远、昼夜可战、信息化程度高的炮兵火力系统，打破了西方在自行炮主战装备领域的垄断。\n\n这套装备成了国际军贸市场上的「明星产品」，出口十多个国家，累计创汇近 30 亿美元。他 2005 年当选中国工程院院士，曾获全国科学大会奖、国家科技进步一等奖 2 项、二等奖 1 项。","facts":["外贸 155 毫米自行炮、自走炮武器系统总设计师，产品出口十余国","曾获国家科技进步一等奖 2 项、二等奖 1 项及全国科学大会奖","1959 年北京工业学院毕业，参与第一代轻型坦克与 152 毫米自行加榴炮研制"],"obit":true,"portrait":"assets/portraits/2026-05-09-116.webp","source":"中国兵器工业集团讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-05-08-铃木光司","date":"2026-05-08","name":"铃木光司","nameOrig":"鈴木光司","country":"日本","region":"","age":68,"fields":["文艺"],"identity":"日本作家 · 《午夜凶铃》系列作者，贞子的创造者","summary":"一盒录像带，七天期限，一口井。他让全世界的电视机都变得可疑。","bio":"铃木光司 1957 年生于静冈县滨松市，庆应义塾大学法文系毕业。1990 年以《乐园》获日本奇幻小说大奖优秀奖出道。1991 年出版《Ring》，写一盒被诅咒的录像带与七日的期限，与续作《螺旋》《Loop》《生日》组成系列，成为畅销书。\n\n1998 年中田秀夫将其搬上银幕，贞子从电视屏幕里爬出的画面成为影史经典，也带起了被称作 J-Horror 的日本恐怖片浪潮，好莱坞两度翻拍。1996 年他以《螺旋》获吉川英治文学新人奖。2025 年他出版十六年来首部长篇恐怖小说《Ubiquitous》。2026 年 5 月 8 日下午在东京一家医院病逝。","facts":["1991 年出版《Ring》，「贞子」成为全球性恐怖符号","1996 年以《螺旋》获第 17 届吉川英治文学新人奖","2013 年《Edge》英译本获雪莉·杰克逊奖长篇小说奖","2022 年获布拉姆·斯托克奖终身成就奖"],"obit":null,"portrait":"assets/portraits/2026-05-08-铃木光司.webp","source":"读卖新闻、NHK、朝日新闻、KADOKAWA 公告","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-05-08-费斯图斯·莫哈埃","date":"2026-05-08","name":"费斯图斯·莫哈埃","nameOrig":"Festus Mogae","country":"博茨瓦纳","region":"","age":86,"fields":["军政"],"identity":"博茨瓦纳政治家 · 第三任总统，抗艾先行者","summary":"在一个被艾滋病拖垮的国度，他第一个站出来说：我们检测，我们治疗。","bio":"莫哈埃 1939 年生于博茨瓦纳中部塞罗韦，曾赴英国求学，专业为经济学。1966 年国家独立后进入政府部门，长期在财政与发展规划部任职，后历任财政部长、副总统，1998 年接任总统，执政至 2008 年。\n\n任内博茨瓦纳是非洲经济增长最快的国家之一，钻石收入被投向基础设施与教育。更受称道的是他对艾滋病的公开应对：在感染率一度居全球前列时，他推动建立非洲大陆最早的国家免费抗病毒治疗项目，使艾滋病相关死亡大幅下降，这一模式后来被多国仿效。2008 年获易卜拉欣非洲领导力奖。2026 年 5 月 8 日晨在哈博罗内去世，博茨瓦纳宣布全国哀悼三日。","facts":["1998 年至 2008 年任博茨瓦纳第三任总统","推动建立非洲首个国家免费抗艾滋病治疗项目","2008 年获易卜拉欣非洲领导力奖","去世后博茨瓦纳宣布为期三天的全国哀悼"],"obit":null,"portrait":"assets/portraits/2026-05-08-费斯图斯·莫哈埃.webp","source":"博茨瓦纳总统府公告、新华网、南部非洲发展共同体唁电","verified":"added","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Festus_Mogae"},{"id":"2026-05-07-115","date":"2026-05-07","name":"因葵","nameOrig":"","country":"中国","region":"香港","age":60,"fields":["文艺"],"identity":"香港填词人 · 太极乐队御用词人，本名陆谦游","summary":"他给太极写了四十年的词，第一首《红色跑车》在电台响起时，他才二十岁。","bio":"因葵本名陆谦游，1965 年 7 月 30 日生于香港北角，中意混血。中学时与太极乐队主音雷有辉同班，1985 年把《红色跑车》的曲和词一并交出去，从此进入词坛，也成了太极的「御用填词人」。\n\n他为太极写下六十多首词，包括《迷途》《禁区》《全人类高歌》，概念大碟《迷》里大半歌词出自他手；也为张学友《只愿一生爱一人》、张国荣《绝不可以》、陈百强《幻像》、李克勤《回首》填词。1999 年郑秀文那首《插曲》拿下十大劲歌金曲「金曲金奖」。\n\n他还与陈辉阳、余力姬组成前卫组合「余力机构」，拿过叱咤乐坛生力军组合金奖。晚年他身体状况不佳，2026 年 5 月 7 日离世，终年 60 岁。","facts":["为太极乐队写下逾六十首词，《迷途》《禁区》《全人类高歌》在列","1999 年为郑秀文填词的《插曲》获十大劲歌金曲「金曲金奖」","与陈辉阳、余力姬组成「余力机构」，获叱咤乐坛生力军组合金奖"],"obit":true,"portrait":"assets/portraits/2026-05-07-115.webp","source":"香港01","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-05-06-特德·特纳","date":"2026-05-06","name":"特德·特纳","nameOrig":"Ted Turner","country":"美国","region":"","age":87,"fields":["传媒"],"identity":"CNN 创办人 · 特纳广播公司创始人","summary":"他把新闻从每天三个固定时段里拽出来，改成一条永不关灯、二十四小时亮着的频道。","bio":"1938 年生于俄亥俄州辛辛那提。父亲留下一家户外广告公司，他把它一路做成特纳广播公司，旗下陆续有了 TBS、TNT、卡通频道与特纳经典电影。1980 年 6 月 1 日，CNN 开播，成为全球第一家 24 小时滚动播出的新闻频道。\n\n1991 年海湾战争，巴格达的直播画面让 CNN 成为全世界都记住的名字，同年《时代》周刊把他评为年度人物。他也是帆船手，赢过美洲杯；买下大片西部牧场养野牛；1997 年向联合国捐出 10 亿美元。他说话从不设防，绰号「南方大嘴」。2026 年 5 月 6 日，他在佛罗里达的家中去世，87 岁。","facts":["1980 年创办 CNN，为全球第一家 24 小时新闻频道","1991 年获《时代》周刊年度风云人物","1997 年向联合国捐赠 10 亿美元","旗下曾有 TBS、TNT、卡通频道与特纳经典电影"],"obit":null,"portrait":"assets/portraits/2026-05-06-特德·特纳.webp","source":"CNN 公告、Turner Enterprises 家属声明、新华网","verified":"added","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Ted_Turner"},{"id":"2026-05-06-114","date":"2026-05-06","name":"陈毓川","nameOrig":"","country":"中国","region":"中国大陆","age":92,"fields":["科技"],"identity":"中国工程院院士 · 矿床地质学家、成矿系列理论奠基人","summary":"他把全国的矿脉画成一张图谱，八十岁后又拉起数千人的队伍，去编一部《中国矿产地质志》。","bio":"陈毓川 1934 年 12 月生于浙江平湖，1959 年毕业于苏联顿涅茨理工大学地质勘查系，从地质部矿床地质研究所研究组长做起，历任地矿部地矿司司长、中国地质科学院院长、地质矿产部总工程师，1997 年当选中国工程院院士。\n\n他参与创立并完善「成矿系列」理论，把零散的矿床放回区域地质演化的框架里解释，据此推进全国成矿规律研究与矿产预测评价，推动南岭钨锡矿等找矿突破，并长期指导野外勘查。\n\n2010 年前后，年近八十的他接下《中国矿产地质志》研编，汇集全国数百家单位、数千名地质工作者，要把中国的矿产家底摸清。他常说，做地质研究要到大自然里去读那本「无字天书」。","facts":["1959 年毕业于苏联顿涅茨理工大学，1997 年当选中国工程院院士","参与创立并完善「成矿系列」理论，推动南岭钨锡矿等找矿突破","2010 年前后主持《中国矿产地质志》研编，集合数千名地质工作者"],"obit":true,"portrait":"assets/portraits/2026-05-06-114.webp","source":"中国地质科学院讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-05-05-李洪九","date":"2026-05-05","name":"李洪九","nameOrig":"이홍구","country":"韩国","region":"","age":91,"fields":["军政"],"identity":"韩国政治家 · 第 28 任国务总理、前驻美大使","summary":"学者出身的总理，在卢泰愚、金泳三、金大中三朝都被倚重，却始终像个讲台上的教授。","bio":"李洪九 1934 年生于开城，入读首尔大学法学院后中途退学赴美，在埃默里大学主修哲学，后于耶鲁大学获政治学硕士与博士学位。1969 年回国，在首尔大学政治学系任教二十年，是韩国研究西方政治思想史的代表学者，1986 年任韩国政治学会会长。\n\n1988 年出任国土统一院长官，由此进入政界，历任总统政治事务特别助理、驻英国大使。1994 年任副总理兼统一部长官，同年 12 月被金泳三任命为第 28 任国务总理，1995 年 12 月离任。1998 年至 2000 年任驻美国大使。他著有《政治学概论》《马克思主义百年》，2014 年获日本旭日大绶章。","facts":["1994 年 12 月至 1995 年 12 月任韩国第 28 任国务总理","1998 年至 2000 年任驻美国大使，此前曾任驻英国大使","历任国土统一院长官、统一副总理兼统一部长官","曾获日本旭日大绶章、埃默里大学与谢菲尔德大学名誉博士"],"obit":null,"portrait":"assets/portraits/2026-05-05-李洪九.webp","source":"朝鲜日报、中央日报（韩国）报道，韩联社","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-05-04-大野雄二","date":"2026-05-04","name":"大野雄二","nameOrig":"大野雄二","country":"日本","region":"","age":84,"fields":["文艺"],"identity":"日本作曲家 · 《鲁邦三世》主题曲作者","summary":"那段前奏一响，爵士乐就从东京的俱乐部里跑出来，钻进了一部动画片。","bio":"大野雄二 1941 年生于静冈县热海市，小学开始学钢琴，高中时自学爵士乐，庆应义塾大学在读期间加入轻音乐社，以藤家虹二五重奏成员身份开始职业演奏。此后历经白木秀雄五重奏、自组三重奏，乐团解散后转向作曲。\n\n他为《犬神家一族》《人性的证明》等影片配乐，1977 年起接手《鲁邦三世》第二季，写出那首带女声合唱、急速又哀切的《鲁邦三世主题曲》，此后近半世纪一直为这个系列供曲。他也是日本融合爵士的重要推手，2006 年组建 Lupintic Five。2026 年 5 月 4 日晨因衰老在东京自宅睡梦中离世，事务所于 5 月 13 日公布。","facts":["1977 年起为《鲁邦三世》系列配乐，历时近半个世纪","为《犬神家一族》《人性的证明》等影片配乐","《草帽歌》随电影《人性的证明》在中国广为流传","2006 年组建 Yuji Ohno & Lupintic Five"],"obit":null,"portrait":"assets/portraits/2026-05-04-大野雄二.webp","source":"所属事务所 Office Augusta 公告、朝日新闻、共同社","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-05-04-二宫和弘","date":"2026-05-04","name":"二宫和弘","nameOrig":"二宮和弘","country":"日本","region":"","age":79,"fields":["体育"],"identity":"日本柔道选手 · 蒙特利尔奥运会 93 公斤级金牌","summary":"190 厘米的身高配上大外刈，他在蒙特利尔把 93 公斤级的金牌留在了日本。","bio":"二宫和弘 1946 年生于福冈市，博多高中毕业后入天理大学，随后进入 1964 年东京奥运会中量级冠军冈野功开设的正气塾深造。1972 年进入福冈县警，同年在全日本柔道锦标赛获第三名。\n\n1976 年蒙特利尔奥运会，他在男子 93 公斤级（轻重量级）决赛中夺冠，成为该级别日本唯一的奥运金牌得主，另曾获 1973 年世界锦标赛无差别级金牌。此后长期担任福冈县警首席师范，2000 年悉尼奥运会出任柔道裁判，并曾任九州柔道协会会长。身高 190 厘米的他以大幅度的大外刈著称。2026 年 5 月 4 日因误咽性肺炎与肾功能衰竭在福冈市内医院去世。","facts":["1976 年蒙特利尔奥运会柔道男子 93 公斤级金牌","1973 年世界柔道锦标赛无差别级冠军","2000 年悉尼奥运会担任柔道比赛裁判","曾任福冈县警首席师范、九州柔道协会会长"],"obit":null,"portrait":null,"source":"朝日新闻、共同社、时事通信、西日本新闻","verified":"added","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":null},{"id":"2026-05-02-117","date":"2026-05-02","name":"谷薇丽","nameOrig":"","country":"中国","region":"香港","age":73,"fields":["影视"],"identity":"香港电影监制 · 《秋天的童话》《纵横四海》幕后推手","summary":"《秋天的童话》的统筹、《纵横四海》的监制，她的名字从不出现在海报中央。","bio":"谷薇丽祖籍山东，香港大学英文及翻译系毕业，从丽的电视助理编导做起。1983 年加入新艺城，1985 年转投德宝电影公司，负责行政监制、制作预算与拍摄进度。\n\n德宝时期高志森、冯世雄、于仁泰的电影多由她监制，包括《痴心的我》《富贵逼人》，她还是《秋天的童话》的统筹。1991 年她与吴宇森、张家振合组新里程电影公司，头炮《纵横四海》要在两个半月内赶完贺岁档，她统筹完成，此后还有《辣手神探》《我爱扭纹柴》。\n\n九十年代中她退出电影圈转向慈善，与梁宪孙医生共同发起香港血癌基金，任会长逾二十年。弟弟是导演谷德昭，侄女是演员谷祖琳。2026 年 5 月 2 日，她在睡梦中离世。","facts":["监制或统筹《秋天的童话》《富贵逼人》系列、《纵横四海》《辣手神探》","1991 年与吴宇森、张家振合组新里程电影公司","香港血癌基金委员会会长，任职逾二十年；胞弟为导演谷德昭"],"obit":true,"portrait":"assets/portraits/2026-05-02-117.webp","source":"香港01","verified":"corrected","causeOfDeath":null,"wikipedia":null},{"id":"2026-05-01-亚历克斯·扎纳尔迪","date":"2026-05-01","name":"亚历克斯·扎纳尔迪","nameOrig":"Alex Zanardi","country":"意大利","region":"","age":59,"fields":["体育"],"identity":"意大利赛车手 · 两届 CART 冠军、残奥四金","summary":"两条腿留在赛道上的人，用一双手把自己重新推上了残奥会的领奖台。","bio":"扎纳尔迪 1966 年生于博洛尼亚，十三岁用父亲的零件拼出第一辆卡丁车。1991 年进入一级方程式，先后效力乔丹、莲花、威廉姆斯等车队，四十余场分站赛只拿过一分。转战美国 CART 系列赛后，于 1997、1998 年连续夺得年度总冠军。\n\n2001 年在德国劳西茨赛道发生严重事故，双腿截肢，心脏一度停跳七次。他改装赛车操控装置重返赛道，随后转向手轮车，在 2012 年伦敦与 2016 年里约残奥会共获四金二银。2020 年 6 月，他在手轮车比赛中与卡车相撞，头部重伤，此后再未完全康复。2026 年 5 月 1 日卒于博洛尼亚。","facts":["1997、1998 年连续夺得 CART 系列赛年度总冠军","2001 年劳西茨赛道事故后双腿截肢，一年半后重返赛道","2012 年伦敦残奥会获手轮车 H4 级公路赛与计时赛双金","共获四枚残奥金牌、两枚银牌，另获劳伦斯最佳复出奖"],"obit":null,"portrait":"assets/portraits/2026-05-01-亚历克斯·扎纳尔迪.webp","source":"家属声明、美联社、意大利媒体","verified":"added","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Alex_Zanardi"},{"id":"2026-04-30-格奥尔格·巴泽利茨","date":"2026-04-30","name":"格奥尔格·巴泽利茨","nameOrig":"Georg Baselitz","country":"德国","region":"","age":88,"fields":["文艺"],"identity":"德国新表现主义画家 · 「倒置绘画」开创者","summary":"从 1969 年起他把画倒过来画，让人先看见颜色和笔触，再认出画里的人。","bio":"1938 年 1 月 23 日生于萨克森州德意志巴塞利茨村，原名汉斯-格奥尔格·布鲁诺·克恩，后以出生地为艺名。1956 年入东柏林美术与应用艺术学院，因不完成指定画题被以「社会政治不成熟」为由开除，1957 年转学西柏林。\n\n1963 年首场个展与《桶中的大夜晚》引发争议，一度被检察院以伤风败俗起诉。1969 年起，他把人物与风景倒置作画，迫使观众先看结构而非内容，这成为他此后半个多世纪的签名。1970 年代末又转向木雕与青铜，9 米高的《零大教堂》陈列于法兰西学院门前。\n\n他与基弗、里希特、伊门多夫同列德国战后艺术的核心人物，2021 年蓬皮杜中心为他举办大型回顾展。2026 年 4 月 30 日在奥地利萨尔茨堡去世，享年 88 岁。","facts":["1969 年起倒置作画，成为战后绘画最具辨识度的手法之一。","1963 年《桶中的大夜晚》曾遭德国检察院以伤风败俗起诉。","2021 年巴黎蓬皮杜中心为其举办创作生涯回顾展。","2013 年起定居萨尔茨堡，逝于当地，遗作展在威尼斯开幕。"],"obit":null,"portrait":"assets/portraits/2026-04-30-格奥尔格·巴泽利茨.webp","source":"Thaddaeus Ropac 画廊讣告、卫报、法新社、The Art Newspaper","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-04-29-克雷格·文特尔","date":"2026-04-29","name":"克雷格·文特尔","nameOrig":"J. Craig Venter","country":"美国","region":"","age":79,"fields":["科技"],"identity":"基因组学家 · 人类基因组草图私人测序主导者","summary":"他用霰弹枪法把测序从慢工变成闪电战，也让「人造生命」不再只是比喻。","bio":"1946 年 10 月 14 日生于美国犹他州盐湖城，越南战争期间曾在海军服役。后在加州大学圣地亚哥分校取得生物化学学士与生理学、药理学博士学位，1984 年在 NIH 有了自己的实验室。\n\n1992 年创办非营利性的基因组研究所（TIGR），1995 年完成流感嗜血杆菌的全基因组测序。1998 年创立塞莱拉基因组公司，以「全基因组霰弹枪法」与公共人类基因组计划竞速，2001 年双方几乎同时公布人类基因组工作草图。此后他主持全球海洋取样考察，2010 年造出世界首个人工合成细胞。\n\n2026 年 4 月 29 日，因近期确诊癌症、治疗中出现意外副作用，在圣地亚哥短暂住院后去世，享年 79 岁。他是 2007、2008 年两届《时代》周刊全球百大影响力人物。","facts":["1995 年完成流感嗜血杆菌全基因组测序，为此类工作首例。","2001 年与公共人类基因组计划几乎同时公布人类基因组工作草图。","2010 年培育出全球首个人工合成细胞。","2007、2008 年两度入选《时代》周刊全球百大影响力人物。"],"obit":null,"portrait":"assets/portraits/2026-04-29-克雷格·文特尔.webp","source":"J. Craig Venter Institute 与 Stowers Institute 讣告、NPR、加州大学圣地亚哥分校、澎湃新闻","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-04-24-113","date":"2026-04-24","name":"吴咸中","nameOrig":"","country":"中国","region":"中国大陆","age":101,"fields":["医药"],"identity":"中国工程院院士 · 中西医结合外科奠基人、首届国医大师","summary":"他把急腹症从「手术一统天下」里拉出来，用「以法为突破口、抓法求理」蹚出一条中西医结合的路。","bio":"1925 年农历八月生于辽宁新民，满族。1948 年进入天津中央医院，即今天的天津医科大学总医院。曾任天津市南开医院院长、天津医学院院长、中国中西医结合学会会长。\n\n他在全国首倡「以法为突破口、抓法求理」的中医理论研究新思路，创立并完善中西医结合诊疗急腹症的新体系，改变「手术一统天下」的外科模式。1975 年创建中国第一个中西医结合研究所。\n\n1996 年当选中国工程院院士，是首届国医大师、国家级非遗代表性传承人。他把中医、西医、中西医结合三支力量比作「海陆空」而非「魏蜀吴」。2026 年 4 月 24 日 9 时 32 分在天津逝世，享年 101 岁。","facts":["1975 年创建中国第一个中西医结合研究所。","成果 1982 年被世界卫生组织认定为世界医学领先项目。","2003 年「通里攻下法在腹部外科的应用」获国家科技进步二等奖。","1996 年当选中国工程院院士，为首届国医大师。"],"obit":true,"portrait":"assets/portraits/2026-04-24-113.webp","source":"中国医学科学院","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-04-23-曼弗雷德·雷茨","date":"2026-04-23","name":"曼弗雷德·雷茨","nameOrig":"Manfred T. Reetz","country":"德国","region":"","age":83,"fields":["科技"],"identity":"有机化学家 · 酶定向进化奠基人之一","summary":"他让化学家在试管里给酶做育种，从此分子也能被一代代挑选出来。","bio":"曼弗雷德·T·雷茨是国际著名有机化学家，德国科学院院士、欧洲科学院院士，曾长期担任德国马克斯-普朗克煤炭化学研究所所长，任期达二十年。\n\n他是酶定向进化领域的开拓者之一，把定向进化与不对称催化结合起来，推动生物催化从理论走向工业实践，2018 年获国际生物催化终身成就奖（Biocat Award）。2017 年起受聘中国科学院天津工业生物技术研究所特聘教授，并获中国科学院国际杰出科学家称号，为国内培养了一批生物催化领域的人才。\n\n2026 年 4 月 23 日病逝，享年 83 岁。天津工业生物技术研究所发布讣告，称其以学术远见推动这一领域从理论走向广泛实践。","facts":["曾任德国马克斯-普朗克煤炭化学研究所所长二十年。","2018 年获国际生物催化终身成就奖（Biocat Award）。","2017 年起任中科院天津工业生物技术研究所特聘教授。","德国科学院院士、欧洲科学院院士、中科院国际杰出科学家。"],"obit":null,"portrait":"assets/portraits/2026-04-23-曼弗雷德·雷茨.webp","source":"中国科学院天津工业生物技术研究所讣告、澎湃新闻","verified":"added","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Manfred_T._Reetz"},{"id":"2026-04-22-黄毅诚","date":"2026-04-22","name":"黄毅诚","nameOrig":"","country":"中国","region":"","age":99,"fields":["军政"],"identity":"原能源部部长 · 新中国唯一一任能源部部长","summary":"他只当了五年部长，此后三十三年再没设过这个部，煤油核电第一次坐进同一间屋子。","bio":"1926 年 10 月生于湖北枣阳。1939 年 3 月参加革命，在河南确山任新四军宣传员，后入延安自然科学院学习，1945 年 8 月入党。\n\n新中国成立后，历任沈阳第一机械总厂二分厂厂长、哈尔滨汽轮机厂副厂长兼总工程师、北京重型电机厂厂长兼总工程师，主持了我国第一台 2.5 万至 20 万千瓦汽轮机的设计制造。1979 年调入国家计委，1982 年任副主任，主抓能源、交通与基础建设，推动节能与压油，为华能、神华等企业腾出了启动资金。\n\n1988 年国务院撤销煤炭、石油、水利电力、核工业四部，组建新中国第一个也是唯一一个能源部，他出任首任部长至 1993 年，主持编制能源工业「八五」计划。2026 年 4 月 22 日在北京逝世，享年 99 岁。","facts":["1988 至 1993 年任能源部部长，是该部唯一一任部长。","主持我国首台 2.5 万至 20 万千瓦汽轮机的设计制造。","国家计委任内推动节能压油，为华能等能源企业组建腾出资金。","曾任第八届全国人大常委会委员、财经委员会副主任委员。"],"obit":null,"portrait":"assets/portraits/2026-04-22-黄毅诚.webp","source":"新华社（4 月 30 日发布）、人民日报、澎湃新闻","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-04-19-112","date":"2026-04-19","name":"戴汝为","nameOrig":"","country":"中国","region":"中国大陆","age":94,"fields":["科技"],"identity":"中国科学院院士 · 控制论与人工智能专家","summary":"他把「模式识别」带回中国，提出语义—句法方法，成了汉王手写识别的理论底座。","bio":"1932 年 12 月 31 日生于云南石屏。1955 年毕业于北京大学数学力学系，随即被选派到中科院力学所，成为钱学森归国后指导的第一位学生，1958 年参与完成《工程控制论》中文版翻译。\n\n1970 年代初他最早在国内开展模式识别研究，1980 年赴普渡大学随傅京孙把统计与句法模式识别结合，提出「语义—句法模式识别」，成为汉王手写识别的理论基础；他主持的手写数字识别系统用于邮政信函自动分拣，获国家科技进步一等奖。\n\n1990 年代与钱学森共同构建「开放的复杂巨系统」方法论，1991 年当选中国科学院学部委员。2026 年 4 月 19 日 10 时 11 分在北京逝世，享年 94 岁。","facts":["1955 年被选派至中科院力学所，是钱学森回国后指导的第一位学生。","1958 年参与完成《工程控制论》中文版翻译。","手写数字识别系统用于邮政信函自动分拣，获国家科技进步一等奖。","1991 年当选中国科学院学部委员（院士）。"],"obit":true,"portrait":"assets/portraits/2026-04-19-112.webp","source":"中科院自动化所讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-04-18-山崎和佳奈","date":"2026-04-18","name":"山崎和佳奈","nameOrig":"山崎和佳奈 / Yamazaki Wakana","country":"日本","region":"","age":61,"fields":["影视"],"identity":"日本声优 · 《名侦探柯南》毛利兰配音 30 年","summary":"那句「新一」她喊了三十年，最后一个剧场版成了没来得及告别的遗作。","bio":"1965 年 3 月 21 日生于神奈川县横滨市，在京都长大。同志社大学工学部毕业后进欧姆龙软件公司做 ATM 开发，周末到青二塾大阪校学配音，两年后辞职赴东京，1990 年加入青二 Production。\n\n1996 年《名侦探柯南》开播，她成为毛利兰的第一代声优，此后近三十年一集未缺，是日本动画史上为单一角色配音时间最长的声优之一。此外还配过《海贼王》的诺琪高、《橘子酱男孩》的秋月茗子、《战国无双》的宁宁，并长期担任电视节目与东京迪士尼园区的解说，2025 年获第 19 届声优奖富山敬·高桥和枝赏。\n\n2026 年 2 月 16 日因健康原因停止全部工作，毛利兰改由冈村明美代配。她于 4 月 18 日病逝，享年 61 岁，事务所青二 Production 直到 5 月 15 日才发布讣告。正在上映的剧场版《名侦探柯南：高速公路的堕天使》成为遗作。","facts":["1996 年起为毛利兰配音近三十年，几乎没有缺席过一集。","2025 年获第 19 届声优奖富山敬·高桥和枝赏。","4 月 18 日病逝，事务所在 5 月 15 日才对外发布讣告。","遗作剧场版《高速公路的堕天使》已完成全部配音。"],"obit":null,"portrait":"assets/portraits/2026-04-18-山崎和佳奈.webp","source":"青二 Production 讣告、朝日新闻、中央社、澎湃新闻","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-04-18-111","date":"2026-04-18","name":"叶君","nameOrig":"","country":"中国","region":"中国大陆","age":43,"fields":["影视"],"identity":"纪录片导演 · 《我在故宫修文物》导演","summary":"他用三集片子把故宫的修复师推成主角，又从《水浒传》的章回体里找到了剪这些慢日常的办法。","bio":"1983 年生于湖北。2002 年以黄石市高考文科状元身份考入清华大学，后获清华研究生学位，先后供职于上海电视台、央视与爱奇艺。\n\n他执导的三集纪录片《我在故宫修文物》第一次系统梳理中国文物修复的历史源流，把故宫的修复师推到镜头前；拍摄团队常态只有五人，剪辑时他从《水浒传》的章回体结构里找到叙事办法。参与编导的《如果国宝会说话》每集五分钟讲一件文物。\n\n《我在故宫修文物》获中国最具影响力十大纪录片、中国高校影视学会学院奖最佳纪录片，豆瓣评分 9.4。2026 年 4 月 18 日，他因急性胃出血在住处去世，年仅 43 岁。","facts":["2002 年以黄石市高考文科状元身份考入清华大学。","《我在故宫修文物》豆瓣评分 9.4，在 Bilibili 爆红。","参与编导《如果国宝会说话》，每集五分钟讲一件文物。","死因为急性胃出血，发病时独自在住处。"],"obit":true,"portrait":"assets/portraits/2026-04-18-111.webp","source":"清华大学影视传播研究中心讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-04-17-纳塔莉·贝伊","date":"2026-04-17","name":"纳塔莉·贝伊","nameOrig":"Nathalie Baye","country":"法国","region":"","age":77,"fields":["影视"],"identity":"法国演员 · 四届凯撒奖得主、威尼斯影后","summary":"四座凯撒奖、八十部电影，她惯于把情绪压到最低，再让它自己溢出来。","bio":"1948 年 7 月 6 日生于法国厄尔省马尼维尔。1970 年代进入影坛，先与特吕弗合作《日以作夜》，再凭戈达尔的《人人为己》拿下 1981 年凯撒奖最佳女配角。\n\n1982 年再获最佳女配角、1983 年以《线民》封后，2006 年凭《小上尉》第二次获最佳女演员，四座凯撒奖之外，1999 年还以《情事》捧回威尼斯电影节沃尔皮杯。她一生出演约八十部影片，从《美国之夜》《各自逃生》到斯皮尔伯格的《猫鼠游戏》，晚年又在《唐顿庄园：新世代》里演一位法国贵族。\n\n2026 年 4 月 17 日，因路易体痴呆并发症在巴黎家中去世，享年 77 岁。家属次日向法新社公布消息，总统马克龙撰文悼念，称她是法国电影史不可或缺的存在。","facts":["四获法国凯撒奖，1981 至 1983 年连续三年获奖。","1999 年凭《情事》获威尼斯电影节最佳女演员。","在《猫鼠游戏》中饰演莱昂纳多·迪卡普里奥的母亲。","女儿为演员劳拉·斯梅特，其父是歌手约翰尼·哈里戴。"],"obit":null,"portrait":"assets/portraits/2026-04-17-纳塔莉·贝伊.webp","source":"家属向法新社公布、The Hollywood Reporter、The Hindu、百度百科","verified":"added","causeOfDeath":"路易体痴呆","wikipedia":"https://en.wikipedia.org/wiki/Nathalie_Baye"},{"id":"2026-04-17-110","date":"2026-04-17","name":"刘庭尧","nameOrig":"","country":"中国","region":"中国大陆","age":90,"fields":["影视"],"identity":"长影演员剧团原团长 · 电影演员、金凤凰奖得主","summary":"45 岁才调入长影当专业演员，51 岁凭《田野又是青纱帐》拿下第一届金凤凰奖。","bio":"1936 年 3 月生于辽宁凤城。1964 年起在白城地区的吉剧团、京剧团、话剧团、文工团任团长、导演、演员，创作、执导三十多部戏剧作品，舞台与编导的底子是在这里打下的。\n\n1981 年调入长春电影制片厂成为专业电影演员，1989 年出任长影演员剧团团长。他出演《雁鸣湖畔》《佩剑将军》《智斗美女蛇》《田野又是青纱帐》《疯狂的小镇》《重庆谈判》《七七事变》等二十多部影视作品，并在其中三部兼任副导演。\n\n1987 年凭《田野又是青纱帐》获中国电影表演艺术学会第一届学会奖「金凤凰奖」。2026 年 4 月 17 日上午 11 时 53 分在长春去世，终年 90 岁。","facts":["1989 年出任长影演员剧团团长。","1987 年获中国电影表演艺术学会第一届学会奖「金凤凰奖」。","在白城地区创作、执导三十多部戏剧作品。","出演《重庆谈判》《七七事变》《疯狂的小镇》等二十余部影片。"],"obit":true,"portrait":"assets/portraits/2026-04-17-110.webp","source":"媒体讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-04-15-109","date":"2026-04-15","name":"江图","nameOrig":"","country":"中国","region":"香港","age":89,"fields":["影视"],"identity":"香港演员 · 「亚视传奇绿叶」、反派专业户","summary":"一副金框眼镜加一撇八字胡，让他在亚视演了三十多年反派，最后一部戏是《叔·叔》。","bio":"原名蔡志祥，1936 年生于香港，出身粤剧世家：母亲冯侠华是粤剧女须生，舅父冯侠魂、舅母楚岫云都是名伶。他十九岁随舅父到佛山粤剧团登台。\n\n1964 年以艺名「江涛」加入新联影业拍黑白粤语片；1971 年投身电视圈，1978 年重返丽的，此后在亚视服务三十余年，2010 年因听力退化淡出。代表作《民间传奇》《书剑恩仇录》《陆小凤》，形象多为金框眼镜加八字胡。\n\n2019 年他复出参演电影《叔·叔》，饰年老同志「超仔」，成为遗作。一生未婚，生前立遗嘱把财产捐给慈善机构，并托付古天乐、田启文处理后事。2026 年 4 月 15 日因心脏病去世，享年 89 岁。","facts":["1964 年以艺名「江涛」加入新联影业，1971 年投身电视圈。","效力丽的／亚视三十余年，2010 年因听力退化淡出。","2019 年《叔·叔》饰演超仔，为银幕遗作。","2023 年获香港演艺人协会颁发杰出演艺大奖。"],"obit":true,"portrait":"assets/portraits/2026-04-15-109.webp","source":"香港01","verified":"confirmed","causeOfDeath":"心脏病","wikipedia":null},{"id":"2026-04-13-108","date":"2026-04-13","name":"冯煜芳","nameOrig":"","country":"中国","region":"中国大陆","age":63,"fields":["科技"],"identity":"中国工程院院士 · 导弹弹头与战斗部技术专家","summary":"1987 年他放弃家里已具规模的工厂去造导弹，后来他的论证约八成装到了部队上。","bio":"1963 年 1 月生于浙江余姚。1987 年从国防科技大学本科毕业，父亲办的工厂当时已颇具规模，不少人劝他回乡子承父业，他选择进入导弹武器研制领域。\n\n他长期从事地地弹道导弹核弹头与常规弹头的装备论证，主持建立某型装备技术研究体系，提出的论证均获立项研制，其中约八成已装备部队；以第一完成人获国家科技进步二等奖四项、国家技术发明二等奖一项。\n\n他是火箭军研究院研究员，专业技术三级、少将军衔，2017 年当选中国工程院院士。他说：火箭军的强大就是我前进的方向。2026 年 4 月 13 日逝世，享年 63 岁。","facts":["1987 年国防科技大学本科毕业，2008 年获航天科技集团一院博士。","以第一完成人获国家科技进步二等奖四项、技术发明二等奖一项。","2017 年当选中国工程院院士，为专业技术少将军衔。","主持论证的装备约八成已列装部队。"],"obit":true,"portrait":"assets/portraits/2026-04-13-108.webp","source":"网易新闻汇编","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-04-13-107","date":"2026-04-13","name":"伊恩·沃森","nameOrig":"Ian Watson","country":"英国","region":"","age":82,"fields":["文艺"],"identity":"英国科幻作家 · 《嵌入》作者、战锤 40K 小说首作","summary":"斯皮尔伯格的《人工智能》用了他的故事；战锤 40K 的第一部小说也出自他的手。","bio":"1943 年 4 月 20 日生于英国圣奥尔本斯，牛津大学贝利奥尔学院英国文学毕业，先后在坦桑尼亚与东京教英语，1970 年回英在伯明翰理工学院教未来学，1976 年辞职专事写作。\n\n1973 年首部长篇《嵌入》获约翰·W·坎贝尔纪念奖，1975 年《约拿工具包》获英国科幻协会奖。1990 年他为《战锤 40K》写下第一部小说《审判官》，几乎单枪匹马定义了那个世界观的语调；他还为库布里克筹划的《人工智能》写过故事。\n\n晚年定居西班牙希洪，2024 年被欧洲科幻协会授予欧洲科幻大师称号。2026 年 4 月 13 日去世，享年 82 岁。友人按他的遗愿说：不要买花，买书。","facts":["1973 年《嵌入》获约翰·W·坎贝尔纪念奖。","1975 年《约拿工具包》获英国科幻协会奖。","1990 年写出战锤 40K 首部小说《审判官》。","2024 年获欧洲科幻协会授予的欧洲科幻大师称号。"],"obit":null,"portrait":null,"source":"Pantheon","verified":"corrected","portraitStatus":"no-source","causeOfDeath":null},{"id":"2026-04-12-106","date":"2026-04-12","name":"阿莎·波斯勒","nameOrig":"Asha Bhosle","country":"印度","region":"","age":92,"fields":["文艺"],"identity":"印度回放歌手 · 宝莱坞八十年女声、录制逾万首歌","summary":"她在宝莱坞唱了八十年，录下一万两千多首歌，最后因一场胸部感染住进孟买医院。","bio":"1933 年 9 月 8 日生于马哈拉施特拉邦桑格利，姐姐是拉塔·曼吉什卡。十岁时为 1943 年马拉地语电影《Majha Bal》录下第一首歌，1948 年进入印地语电影。\n\n她的嗓音几乎什么都能装：抒情慢歌、民歌、舞曲、爵士。一生录制逾一万二千首歌，覆盖二十多种语言，吉尼斯世界纪录认证她为录音最多的艺术家；与英国音乐人 Boy George 的合作让她在西方成名。\n\n两获国家电影奖、七次 Filmfare 最佳女回放歌手，2000 年获达达萨赫布·法尔克奖，另获莲花赐勋章，两度获格莱美提名。2026 年 4 月 12 日在孟买因心脏骤停后多器官衰竭去世，享年 92 岁。","facts":["一生录制逾一万二千首歌，吉尼斯认证为录音最多的艺术家。","十岁为 1943 年马拉地语电影《Majha Bal》录下第一首歌。","2000 年获达达萨赫布·法尔克奖，另获莲花赐勋章。","葬礼在孟买希瓦吉公园以国葬规格举行，总理莫迪发文悼念。"],"obit":null,"portrait":"assets/portraits/2026-04-12-106.webp","source":"Pantheon","verified":"corrected","causeOfDeath":"心脏骤停","wikipedia":"https://en.wikipedia.org/wiki/Asha_Bhosle"},{"id":"2026-04-11-郭道晖","date":"2026-04-11","name":"郭道晖","nameOrig":"","country":"中国","region":"","age":98,"fields":["社科"],"identity":"法学家 · 「法治三老」之一、《中国法学》原总编辑","summary":"他把「刀制」与「水治」讲成一句人人都懂的话，法治从此换了写法。","bio":"1928 年 8 月生于湖南长沙，祖籍湘阴，曾祖父郭仑焘与郭嵩焘、郭昆焘并称「湘阴郭氏三杰」。1947 年考入清华大学电机工程系，1948 年入党从事地下工作，也是朱镕基的入党介绍人。\n\n1979 年，51 岁的他转入全国人大常委会法制工作委员会，任国家法组组长、研究室副主任，参与「八二宪法」草案讨论的秘书工作。1987 年起任中国法学会研究部主任，1989 至 1998 年主编《中国法学》，推动「权利本位」与人权议题成为学界共识。\n\n他首倡权利推定理论，原创性地提出「社会权力」这一法学范畴，又以「刀制」与「水治」之喻辨析法制与法治，著有《法的时代精神》等二十余部、四百余万字。与江平、李步云并称「中国法治三老」。2026 年 4 月 11 日 5 时 33 分在北京逝世，享年 98 岁。","facts":["与江平、李步云并称「中国法治三老」，为其中最年长、最长寿者。","1979 年转入全国人大常委会法工委，参与「八二宪法」草案讨论的秘书工作。","1989 至 1998 年任《中国法学》总编辑。","首倡权利推定理论，原创性提出「社会权力」法学范畴。"],"obit":null,"portrait":"assets/portraits/2026-04-11-郭道晖.webp","source":"中国法学会讣告、新华社、澎湃新闻、南方周末","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-04-11-105","date":"2026-04-11","name":"约翰·诺兰","nameOrig":"John Nolan","country":"英国","region":"","age":87,"fields":["影视"],"identity":"英国演员 · 诺兰兄弟的叔叔、《疑犯追踪》反派","summary":"他是诺兰兄弟的叔叔，在《蝙蝠侠》里坐过韦恩企业的董事会，也在《疑犯追踪》里演了最安静的那个反派。","bio":"1938 年 5 月 22 日生于伦敦，是克里斯托弗与乔纳森·诺兰的叔叔。伦敦戏剧中心早期学生，早年在里奇蒙剧院演《罗密欧与朱丽叶》，由此进入皇家莎士比亚剧团。\n\n影视作品逾五十部。他在侄子的《追随》《蝙蝠侠：侠影之谜》《黑暗骑士崛起》《敦刻尔克》中客串，最被记住的是韦恩企业董事道格拉斯·弗雷德里克斯；在《疑犯追踪》中饰前军情六处特工约翰·格里尔，累计二十八集。\n\n遗作为 2024 年剧集《沙丘：预言》。2026 年 4 月 11 日在斯特拉特福德去世，享年 87 岁。克里斯托弗·诺兰说：我的叔叔约翰是我认识的第一个艺术家。","facts":["在《疑犯追踪》中饰反派约翰·格里尔，累计出演二十八集。","参演《追随》《蝙蝠侠：侠影之谜》《黑暗骑士崛起》《敦刻尔克》。","遗作为 2024 年剧集《沙丘：预言》。","妻子为演员金·哈特曼，两人 1975 年结婚。"],"obit":null,"portrait":"assets/portraits/2026-04-11-105.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":null},{"id":"2026-04-10-104","date":"2026-04-10","name":"郑振邦","nameOrig":"","country":"中国","region":"香港","age":null,"fields":["影视"],"identity":"香港电影监制 · 港日合拍片推手、《星月童话》制片","summary":"他抵押自己的房子拍完《92 黑玫瑰对黑玫瑰》，又把张国荣和常盘贵子凑进了《星月童话》。","bio":"1980 年代后期入行。早年赴日本留学，毕业于日本工学院映像系，因日语流利，在谭咏麟、成龙赴日拍片时担任剧组翻译。\n\n回港后历任场记、副导演、制片、策划、统筹、执行导演至监制，最重的一条线是港日合作：张国荣与常盘贵子《星月童话》、金城武《不夜城》、郭富城与藤原纪香《雷霆战警》都由他幕后推动。拍《92 黑玫瑰对黑玫瑰》时，他为支持制作抵押了自己的房产。\n\n近年监制《老笠》《四大名捕大结局》《荡寇风云》。他是张国荣生前密友，也曾任周海媚的经纪人。2026 年 4 月 10 日离世，消息由田启文证实。","facts":["推动《星月童话》《不夜城》《雷霆战警》等港日合拍片。","拍摄《92 黑玫瑰对黑玫瑰》时抵押房产支持剧组运作。","早年曾任《灵幻先生》《魔域飞龙》制片。","死讯由香港演艺人协会田启文向媒体证实。"],"obit":true,"portrait":"assets/portraits/2026-04-10-104.webp","source":"香港01","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-04-10-103","date":"2026-04-10","name":"温成林","nameOrig":"","country":"中国","region":"中国大陆","age":62,"fields":["影视"],"identity":"电视剧导演 · 北京电视艺术中心、《刁蛮公主逍遥王》","summary":"《中国家庭》《刁蛮公主逍遥王》的导演，在 62 岁这年倒在了心梗上，追悼会定在八宝山竹厅。","bio":"生于北京，从业三十余年。1995 年执导三十集电视剧《古都深巷》开启导演生涯，1997 年执导《中国家庭》获全国电视协会优秀奖。\n\n此后作品风格多变：《喜鹊东南飞》《刁蛮公主逍遥王》《似水浮生》《幸福来了你就喊》《娶你不后悔》《咱爸咱妈六十年》《以母亲的名义》，多为家庭伦理与年代题材。他是中国广电联合会电视剧导演专业委员会会员，长期在北京电视艺术中心工作。\n\n2026 年 4 月 10 日上午 11 时 31 分因突发心梗抢救无效去世，享年 62 岁；4 月 12 日追悼会在北京八宝山殡仪馆主仪式楼竹厅举行。","facts":["1995 年以《古都深巷》开启导演生涯，该剧共三十集。","1997 年《中国家庭》获全国电视协会优秀奖。","代表作另有《喜鹊东南飞》《似水浮生》《养母》。","追悼会于 2026 年 4 月 12 日在北京八宝山殡仪馆举行。"],"obit":true,"portrait":"assets/portraits/2026-04-10-103.webp","source":"中广联电视剧导演委员会讣告","verified":"confirmed","causeOfDeath":"心梗","wikipedia":null},{"id":"2026-04-09-102","date":"2026-04-09","name":"阿非利卡·班巴塔","nameOrig":"Afrika Bambaataa","country":"美国","region":"","age":68,"fields":["文艺"],"identity":"美国 DJ 与制作人 · 嘻哈文化奠基者、祖鲁联盟创立者","summary":"1982 年那首《Planet Rock》把卡夫特的电子声接上布朗克斯的鼓机，电放克从此有了名字。","bio":"本名兰斯·泰勒，1957 年 4 月 17 日生于纽约南布朗克斯，牙买加与巴巴多斯移民之子，少年时是街头帮派「黑桃帮」的头目之一。\n\n1973 年他把帮派改组为环球祖鲁联盟，用《十五条信仰原则》和嘻哈和平宣言把街区暴力换成派对、涂鸦与霹雳舞。1982 年与 Arthur Baker、Soulsonic Force 合作的《Planet Rock》采样卡夫特《Trans-Europe Express》、配上 TR-808，成为电放克范本。\n\n他晚年被多名男性指控性侵未成年人，本人否认，2025 年在纽约一桩民事诉讼中缺席败诉。2026 年 4 月 9 日在宾夕法尼亚因前列腺癌去世，享年 68 岁。","facts":["1982 年《Planet Rock》采样卡夫特并配 TR-808，奠定电放克。","1973 年创立环球祖鲁联盟，以嘻哈和平宣言取代帮派暴力。","与 DJ Kool Herc、Grandmaster Flash 并称嘻哈三大奠基者。","2025 年 5 月在纽约一桩性侵民事诉讼中缺席败诉。"],"obit":null,"portrait":"assets/portraits/2026-04-09-102.webp","source":"Pantheon","verified":"corrected","causeOfDeath":"前列腺癌","wikipedia":"https://en.wikipedia.org/wiki/Afrika_Bambaataa"},{"id":"2026-04-08-101","date":"2026-04-08","name":"马里奥·阿多夫","nameOrig":"Mario Adorf","country":"德国","region":"","age":95,"fields":["影视"],"identity":"德国演员 · 《锡鼓》里奥斯卡的父亲","summary":"他把反派当成剧本里最有趣的角色：拒过《教父》，演过《温内图》的桑特，也演过《锡鼓》里的父亲。","bio":"1930 年 9 月 8 日生于苏黎世，母亲德国人、父亲意大利人，在德国埃菲尔山区的迈恩长大，学过犯罪学后转投戏剧。\n\n1957 年凭《黑夜煞星》获德国电影奖最佳新演员，1963 年在《温内图》第一部里演反派桑特，从此以奸角闻名；后出演《丧失名誉的卡塔琳娜·布鲁姆》《罗拉》，并在 1979 年《锡鼓》中饰奥斯卡的父亲。他曾拒绝《教父》的邀约。\n\n从影近七十年，参演影视逾二百部，合作过法斯宾德、施隆多夫、比利·怀尔德、佩金帕。2004 年获德国电影奖荣誉奖。2026 年 4 月 8 日在巴黎寓所病逝，享年 95 岁。","facts":["1957 年凭《黑夜煞星》获德国电影奖最佳新演员。","1963 年在《温内图》第一部中饰演反派桑特。","1979 年《锡鼓》获奥斯卡最佳外语片，他在片中饰奥斯卡之父。","2004 年获德国电影奖荣誉奖，2016 年获卢卡诺影展荣誉奖。"],"obit":null,"portrait":"assets/portraits/2026-04-08-101.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Mario_Adorf"},{"id":"2026-04-07-100","date":"2026-04-07","name":"米尔恰·卢塞斯库","nameOrig":"Mircea Lucescu","country":"罗马尼亚","region":"","age":80,"fields":["体育"],"identity":"罗马尼亚足球教练 · 两度执教国家队、联盟杯冠军","summary":"执教最后一场是 0 比 1 输给土耳其、无缘世界杯；十二天后，他在布加勒斯特去世，享年 80 岁。","bio":"1945 年生于布加勒斯特。球员时代是布加勒斯特迪纳摩的边锋，随队七夺联赛冠军，1970 年以队长身份出战墨西哥世界杯。\n\n1981 年出任罗马尼亚队主帅，1984 年率队首进欧洲杯决赛圈；此后辗转国际米兰、加拉塔萨雷与基辅迪纳摩，2004 年起在顿涅茨克矿工十二年，拿八次乌超冠军与 2009 年欧洲联盟杯。执教四十七年，共获三十八座奖杯。\n\n2024 年 8 月，七十九岁的他时隔三十八年重返国家队；2026 年 3 月 26 日球队 0 比 1 负土耳其、无缘世界杯，3 月 29 日他在训练前会议突发心梗，4 月 2 日辞职，4 月 7 日晚在布加勒斯特去世。","facts":["球员时代为罗马尼亚队出场六十余次，1970 年世界杯任队长。","执教生涯四十七年，共获三十八座奖杯，出战 1668 场比赛。","2009 年率顿涅茨克矿工夺得欧洲联盟杯。","曾执教国际米兰、加拉塔萨雷、贝希克塔斯与基辅迪纳摩。"],"obit":null,"portrait":"assets/portraits/2026-04-07-100.webp","source":"Pantheon","verified":"confirmed","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Mircea_Lucescu"},{"id":"2026-04-06-099","date":"2026-04-06","name":"刘玉清","nameOrig":"","country":"中国","region":"中国大陆","age":103,"fields":["医药"],"identity":"中国工程院院士 · 心血管放射影像学主要创建人","summary":"他给「大动脉炎」定了名，也让放射科医生第一次被要求先做临床医生、再看片子。","bio":"1923 年生于河北丰润，1948 年从原国立沈阳医学院毕业，1950 年到北京协和医院放射科进修，1956 年调入后来的阜外医院。\n\n他创建「X 射线—临床—心电图」三结合的心脏 X 线诊断方法，提出「大动脉炎」这一命名，率先引进数字减影血管造影，开展心血管磁共振临床应用，倡导打通技术与临床壁垒的「大影像」学科体系。1994 年当选中国工程院院士。\n\n他主持制定我国首部《医学影像学住院医师培训规范及实施方案》，八旬以后仍每天到放射科参加读片会。2026 年 4 月 6 日在北京逝世，享年 103 岁。","facts":["1994 年当选中国工程院院士，为医药卫生学部首批院士之一。","提出「大动脉炎」命名，系统开展大动脉炎放射学研究。","主持制定我国首部《医学影像学住院医师培训规范及实施方案》。","曾获国家科学技术进步奖二等奖、第四届光华工程科技奖。"],"obit":true,"portrait":"assets/portraits/2026-04-06-099.webp","source":"中国医学科学院阜外医院讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-04-05-陈丽华","date":"2026-04-05","name":"陈丽华","nameOrig":"","country":"中国","region":"","age":85,"fields":["商业"],"identity":"富华国际集团创始人 · 中国紫檀博物馆馆长","summary":"从家具修理厂到金宝街，她挣下的钱最后大多变成了紫檀与老城门。","bio":"1941 年 4 月生于北京，叶赫那拉氏第八代后裔，正黄旗世家出身。高中辍学后开过家具修理厂，因自幼与祖传硬木家具为伴，练出一双辨别紫檀、黄花梨的眼力。1981 年移居香港，靠一批明清旧家具换来第一桶金，转而投向房地产。\n\n1988 年在香港创立富华国际集团，1990 年代回京投资，代表作是长安俱乐部与金宝街改造——730 米的旧街拆建为高端商业地标，也开创了「市政带危改」的开发模式。2001 年她以 55 亿元登上福布斯中国内地富豪榜第 6 位，此后多次位居各类女富豪榜首。\n\n1999 年建成中国紫檀博物馆，收藏、复原紫檀雕刻与十六座老北京城门，2011 年「紫檀雕刻技艺」列入国家级非遗名录。2026 年 4 月 5 日 20 时 50 分在北京逝世，享年 85 岁。","facts":["2001 年以 55 亿元位列福布斯中国内地富豪榜第 6 位，成为内地女首富。","1999 年创办中国首家紫檀主题的私立博物馆。","金宝街改造开创「市政带危改」模式，街道全长 730 米。","丈夫为 86 版《西游记》唐僧扮演者迟重瑞。"],"obit":null,"portrait":"assets/portraits/2026-04-05-陈丽华.webp","source":"富华国际集团、北京侨商会讣告，新华社、澎湃新闻、光明网","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-04-04-郑小娟","date":"2026-04-04","name":"郑小娟","nameOrig":"","country":"中国","region":"","age":86,"fields":["文艺"],"identity":"工笔人物画家 · 湖南美术出版社原社长","summary":"她画了六十年湖南田埂上的女人，也把湖南的工笔画一路推到了全国。","bio":"1940 年 12 月生于湖南长沙金井。1958 年考入湖南文艺学院美术系，1963 年毕业于湖南师范学院美术系，先后做过中学美术教师、文化馆美术干部与出版社美术编辑。\n\n她以工笔人物画立身，《山雀》《晒辣椒》《赶歌图》《大地之爱》等连续入选第 4 至 9 届全国美展，被中国美术馆、中国国家博物馆、中国国家画院收藏。1984 至 1990 年任湖南美术出版社社长兼总编辑，主编《中国当代女画家》《中国工笔画 1900—1997》《中国当代线描艺术》，为这一画种留下系统的文献底账。\n\n1991 年，她被导演丁荫楠选中，在电影《周恩来》中出演邓颖超。2026 年 4 月 4 日 7 时 42 分在长沙逝世，享年 86 岁。","facts":["作品连续入选第 4 至 9 届全国美展，多件被中国美术馆、中国国家博物馆收藏。","1984 至 1990 年任湖南美术出版社社长兼总编辑。","在丁荫楠执导的电影《周恩来》中饰演邓颖超。","与丈夫姜坤并称艺坛伉俪，2024 年湖南美术馆为二人举办专题展。"],"obit":null,"portrait":"assets/portraits/2026-04-04-郑小娟.webp","source":"湖南省美术家协会讣告、湖南日报、环球网","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-04-03-李道瑜","date":"2026-04-03","name":"李道瑜","nameOrig":"Andy Lee Do-yu","country":"中国","region":"香港","age":71,"fields":["影视"],"identity":"香港演员 · 《古惑仔》系列洪兴军师陈耀","summary":"「白纸扇」陈耀话不多，可他在洪兴的每一次开口，都在改这个社团的走向。","bio":"1955 年生于香港，原名李道渝。1977 年毕业于无线电视第六期艺员训练班，在电视剧里演了几年小角色后转投电影，因一身冷峻江湖气，常年出演警察与黑帮。\n\n1996 年在《古惑仔之人在江湖》中饰洪兴社「白纸扇」陈耀，此后在六部续集与外传里回归，戏份不多却次次左右剧情，成了这个系列最耐看的配角之一。港产片式微后他淡出幕前转做生意，最后一部电影是 2008 年的《我老婆是赌圣》，2023 年客串 TVB 剧集《一舞倾城》。\n\n2026 年 4 月 3 日因醉酒摔倒撞伤后脑、脑出血在香港逝世。家属 4 月 4 日公布消息，多家媒体初报为 58 岁，后经香港电影工作者总会发言人田启文核实其生于 1955 年，终年 71 岁。","facts":["1977 年毕业于无线电视第六期艺员训练班。","在《古惑仔》系列七部影片中饰演洪兴军师陈耀。","2023 年客串《一舞倾城》，为幕前遗作。","逝世年龄初被误报为 58 岁，经田启文核实更正为 71 岁。"],"obit":null,"portrait":"assets/portraits/2026-04-03-李道瑜.webp","source":"光明网、澎湃新闻、星洲网、明报（经田启文核实）","verified":"added","causeOfDeath":null,"wikipedia":null},{"id":"2026-03-30-098","date":"2026-03-30","name":"昌·桑托基","nameOrig":"Chan Santokhi","country":"苏里南","region":"","age":67,"fields":["军政"],"identity":"苏里南前总统 · 进步改革党主席","summary":"他当检察官时查过那桩十二月谋杀案，当上总统后又把债务谈完，2025 年平静交出权力。","bio":"昌德里卡佩尔萨德·桑托基 1959 年生于苏里南莱利多普，在荷兰接受警察培训，回国后长期在司法系统任职，2005 年至 2018 年任司法警察部长，并任进步改革党主席。\n\n他早年以检察官身份参与调查 1982 年的十二月谋杀案，那场针对反对派的处决发生在德西·鲍特瑟军政权时期。2020 年他当选苏里南总统，任内主导债务重组，2025 年大选后把权力交给反对派领袖珍妮弗·西蒙斯，卸任后仍任国民议会议员。\n\n2026 年 3 月 30 日在帕拉马里博的学术医院去世，享年 67 岁，据报道为心脏骤停；4 月 7 日苏里南为其举行国葬。","facts":["2020—2025 年任苏里南总统，进步改革党主席","2005—2018 年任苏里南司法警察部长","早年参与调查 1982 年十二月谋杀案","2026 年 4 月 7 日苏里南为其举行国葬"],"obit":null,"portrait":"assets/portraits/2026-03-30-098.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Chan_Santokhi"},{"id":"2026-03-28-097","date":"2026-03-28","name":"利亚明·泽鲁阿勒","nameOrig":"Liamine Zéroual","country":"阿尔及利亚","region":"","age":84,"fields":["军政"],"identity":"阿尔及利亚前总统 · 独立战争老兵","summary":"1995 年他赢下阿尔及利亚第一次多党总统选举，四年后自己提前把权力交了出去。","bio":"利亚明·泽鲁阿勒 1941 年生于阿尔及利亚东部巴特纳。1957 年，十六岁的他加入民族解放军参加独立战争，独立后继续在军中任职，先后赴开罗、苏联、法国受训，1988 年出任陆军总司令，1990 年因反对军队改组方案退出军界，出任驻罗马尼亚大使。\n\n1993 年他被任命为国防部长，1994 年 1 月由最高安全委员会推举为国家元首，1995 年赢得阿尔及利亚历史上首次多党总统选举，在内战最激烈的年代执政，推动与反对派的谈判。1998 年他宣布提前卸任，1999 年 4 月交权。\n\n2026 年 3 月 28 日在阿尔及尔穆罕默德·塞吉尔·内卡奇军事医院去世，享年 84 岁。","facts":["1994—1999 年任阿尔及利亚总统","1995 年赢得该国首次多党总统选举","独立战争老兵，1988 年出任陆军总司令","1998 年宣布提前卸任，1999 年交权"],"obit":null,"portrait":"assets/portraits/2026-03-28-097.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Liamine_Z%C3%A9roual"},{"id":"2026-03-26-096","date":"2026-03-26","name":"让-皮埃尔·费伊","nameOrig":"Jean-Pierre Faye","country":"法国","region":"","age":100,"fields":["社科"],"identity":"法国哲学家 · 作家 · 马蹄铁理论提出者","summary":"他提出马蹄铁理论：极左和极右不是一条直线的两端，而是弯过来彼此靠近的两个尖端。","bio":"让-皮埃尔·费伊 1925 年生于巴黎，青年时代因战争迁居西南边境，1947 年获法学与经济学学位，1950 年通过哲学教师资格会考。他曾是先锋文学刊物《原样》编委，后另创《变化》，1964 年以小说《水闸》获勒诺多文学奖。\n\n1972 年他出版《极权主义语言》，研究国家与意识形态如何滥用语言，并提出马蹄铁理论：政治光谱的极左与极右并非截然对立，而会彼此靠近、呈现相似特征。1983 年他与德里达等人共同撰写蓝皮书报告，促成国际哲学学院成立，后来又激烈批评德里达在海德格尔问题上的立场。\n\n2026 年 3 月 26 日在图卢兹去世，享年 100 岁。","facts":["1964 年以小说《水闸》获勒诺多文学奖","1972 年出版《极权主义语言》，提出马蹄铁理论","1983 年参与促成国际哲学学院成立","长期批评海德格尔思想中的反犹主义问题"],"obit":null,"portrait":null,"source":"Pantheon","verified":"corrected","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Jean-Pierre_Faye"},{"id":"2026-03-25-095","date":"2026-03-25","name":"李幼平","nameOrig":"","country":"中国","region":"中国大陆","age":91,"fields":["科技"],"identity":"中国工程院院士 · 核武器电子学开创者","summary":"1964 年他放弃了去英国留学，一纸调令把他送进青海的 221 基地，去造核弹的遥测系统。","bio":"李幼平 1935 年 5 月生于福建泉州，1953 年考入南京工学院无线电专业，1956 年入党。1963 年他入选高教部赴英留学名单，次年 10 月一纸调令把他送进青海 221 基地，从此投身核武器电子学。\n\n1965 年他提出九院应自行研制核武器专用再入遥测系统，放弃通用米波方案，此后二十余年主持设计我国第一代核弹遥测系统，是我国核武器电子学事业的主要开创者。晚年在网络体系结构、内容元数据国家标准等方面继续工作。曾任中国工程物理研究院科技委常务副主任、主任，1999 年当选中国工程院院士。\n\n2026 年 3 月 25 日在北京去世，享年 91 岁。","facts":["1999 年当选中国工程院院士，长期任职中物院","我国第一代核弹遥测系统的奠基人","1964 年放弃赴英留学，调往青海 221 基地","曾任中国工程物理研究院科技委主任"],"obit":true,"portrait":"assets/portraits/2026-03-25-095.webp","source":"中国工程物理研究院讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-03-25-094","date":"2026-03-25","name":"亚历山大·克鲁格","nameOrig":"Alexander Kluge","country":"德国","region":"","age":94,"fields":["影视"],"identity":"德国导演 · 作家 · 新德国电影奠基人之一","summary":"处女作拿银狮，两年后拿金狮，他和二十多个年轻导演一起宣告旧电影已经死了。","bio":"亚历山大·克鲁格 1932 年生于德国哈尔伯施塔特，13 岁时目睹家乡在空袭中几乎全毁。他学法律、历史和教堂音乐，1956 年获法学博士，做过律师，也在法兰克福社会研究所当法律顾问，因而与阿多诺相熟。\n\n1958 年他给弗里茨·朗做助手，转入电影。1962 年他与二十多位年轻导演共同签署《奥伯豪森宣言》。1966 年处女作《告别昨日》获威尼斯银狮奖，1968 年《马戏团帐篷顶下的艺人》获金狮奖。1977 年他出版《1945 年 4 月 8 日对哈尔伯施塔特的空袭》，把报道、照片和回忆拼在一起。晚年他经营电视制作公司。\n\n2026 年 3 月 25 日在慕尼黑家中去世，享年 94 岁。","facts":["1962 年为《奥伯豪森宣言》签署人之一","1966 年《告别昨日》获威尼斯电影节银狮奖","1968 年《马戏团帐篷顶下的艺人》获金狮奖","1977 年出版《1945 年 4 月 8 日对哈尔伯施塔特的空袭》"],"obit":null,"portrait":"assets/portraits/2026-03-25-094.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Alexander_Kluge"},{"id":"2026-03-24-093","date":"2026-03-24","name":"魏正耀","nameOrig":"","country":"中国","region":"中国大陆","age":90,"fields":["科技"],"identity":"中国工程院院士 · 军事信息技术专家","summary":"他的名字几十年不能见报，四座国家科技进步一等奖的年份是 1985、1998、1999、2001。","bio":"魏正耀 1936 年生于上海，祖籍浙江慈溪。1951 年，十五岁的他参军入伍，先被安排学外语，在解放军外国语学院就读，又到北京大学西语系进修。\n\n此后半个多世纪，他在军事信息技术这条不公开的战线上工作，历任总参谋部某部助理研究员、副研究员、研究员，总参谋部某研究所研究员，中国人民解放军网络空间部队某研究所研究员，主持多项国家级重大研究项目，1999 年当选中国工程院院士。他先后在 1985 年、1998 年、1999 年、2001 年四次获国家科学技术进步奖一等奖，并获军队科技进步奖，荣立个人一等功。\n\n2026 年 3 月 24 日在北京去世，享年 90 岁。","facts":["1999 年当选中国工程院院士，任职网络空间部队某研究所","1985、1998、1999、2001 年四获国家科技进步一等奖","1951 年十五岁参军，曾在解放军外国语学院学习","长期在军事信息技术领域从事保密研究"],"obit":true,"portrait":"assets/portraits/2026-03-24-093.webp","source":"中国工程院讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-03-24-092","date":"2026-03-24","name":"比鲁特·加尔迪卡斯","nameOrig":"Birutė Galdikas","country":"加拿大","region":"","age":79,"fields":["科技"],"identity":"加拿大灵长类学家 · 红毛猩猩研究权威","summary":"她在婆罗洲的沼泽里守了五十多年，替世界上最沉默的一种猿类做记录、当辩护人。","bio":"比鲁特·加尔迪卡斯 1946 年生于德国威斯巴登，父母是立陶宛难民，她在多伦多长大，先后在英属哥伦比亚大学与加州大学洛杉矶分校学习。她是路易斯·利基选中的三位女性灵长类研究者之一，与珍·古道尔、戴安·佛西并称利基的三位天使。\n\n1971 年她进入印尼婆罗洲丹戎普丁保护区，建立后来以利基命名的研究站，此后五十余年持续观察野生红毛猩猩，是这一物种最重要的野外观测者。1986 年她创办国际红毛猩猩基金会，救助失去母猿的幼崽并推动雨林保护。\n\n2026 年 3 月 24 日因肺癌与肺纤维化在洛杉矶去世，享年 79 岁，距八十岁生日还有七周。","facts":["1971 年在婆罗洲丹戎普丁建立红毛猩猩研究站","1986 年创办国际红毛猩猩基金会","与珍·古道尔、戴安·佛西并称利基的三位天使","死因为肺癌与肺纤维化并发症，在洛杉矶"],"obit":null,"portrait":null,"source":"Pantheon","verified":"corrected","portraitStatus":"no-source","causeOfDeath":"肺癌","wikipedia":"https://en.wikipedia.org/wiki/Birut%C4%97_Galdikas"},{"id":"2026-03-23-091","date":"2026-03-23","name":"吴德馨","nameOrig":"","country":"中国","region":"中国大陆","age":90,"fields":["科技"],"identity":"中国科学院院士 · 半导体与集成电路开拓者","summary":"她做的开关晶体管装进了为两弹一星配套的计算机，也为后来的大规模集成电路铺了路。","bio":"吴德馨 1936 年 12 月生于河北乐亭，1961 年从清华大学无线电电子工程系毕业，是该校第一批半导体专业毕业生，随后进入中国科学院半导体研究所，1986 年调入中国科学院微电子中心，1991 年至 1997 年任中心主任。\n\n她在半导体所承担平面型高速开关晶体管课题，解决了提高开关速度的关键问题，使器件速度达到当时国际同类水平，为两弹一星配套的 109 丙计算机提供核心器件。在微电子中心，她主持研制出国内首批 4K、16K位动态随机存储器，开发出双层多晶硅和差值氧化工艺，扭转了我国大规模集成电路成品率长期低下的局面。\n\n2026 年 3 月 23 日在北京去世，享年 90 岁。","facts":["1991 年当选中国科学院学部委员（院士）","为两弹一星配套的 109 丙计算机提供核心器件","主持研制国内首批 4K、16K位动态随机存储器","第九届、第十届全国人大常委会委员"],"obit":true,"portrait":"assets/portraits/2026-03-23-091.webp","source":"中科院微电子所讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-03-22-090","date":"2026-03-22","name":"利昂内尔·若斯潘","nameOrig":"Lionel Jospin","country":"法国","region":"","age":88,"fields":["军政"],"identity":"法国前总理 · 社会党第一书记 · 多元左翼缔造者","summary":"他给法国人改出一周三十五小时工作制，也在 2002 年那场初选里被极右翼挤出了决选。","bio":"利昂内尔·若斯潘 1937 年生于巴黎近郊默东，先后就读巴黎政治学院与国家行政学院，早年做外交官，1971 年加入社会党，1981 年接替密特朗出任社会党第一书记。\n\n1988 年至 1992 年任国民教育部长。1997 年他整合社会党、共产党与绿党组成多元左翼，赢得国民议会选举后出任总理，与总统希拉克形成左右共治，五年任内推行每周三十五小时工作制、全民医疗保障、民事结合契约，并通过公投把总统任期由七年缩短为五年。2002 年总统选举首轮，他因左翼票源分散位列第三被淘汰，随后退出政坛前沿。\n\n2026 年 3 月 22 日去世，享年 88 岁。","facts":["1997—2002 年任法国总理，与希拉克左右共治","任内推行每周 35 小时工作制与全民医疗保障","1981—1988 年、1995—1997 年两度任社会党第一书记","2002 年总统选举首轮被极右翼候选人挤出决选"],"obit":null,"portrait":"assets/portraits/2026-03-22-090.webp","source":"Pantheon","verified":"corrected","causeOfDeath":"手术并发症","wikipedia":"https://en.wikipedia.org/wiki/Lionel_Jospin"},{"id":"2026-03-20-089","date":"2026-03-20","name":"罗伯特·穆勒","nameOrig":"Robert Mueller","country":"美国","region":"","age":81,"fields":["军政"],"identity":"美国前联邦调查局局长 · 通俄门特别检察官","summary":"九一一前八天接手联邦调查局，十六年后以特别检察官身份把一份 448 页的报告交到国会。","bio":"罗伯特·穆勒 1944 年生于纽约，普林斯顿本科毕业后获纽约大学法学博士。越战期间他作为海军陆战队军官服役，获铜星勋章和紫心勋章。\n\n2001 年 9 月，他在九一一袭击前八天出任联邦调查局局长，任内把联邦调查局改造成以反恐为核心的情报执法机构，任期延至 2013 年，成为仅次于胡佛的在任最久局长。2017 年他被任命为特别检察官，调查俄罗斯干预 2016 年美国大选以及特朗普是否妨碍司法，2019 年交出 448 页报告，认定俄方确有干预，但未就总统是否犯罪作出结论。2021 年他确诊帕金森病。\n\n2026 年 3 月 20 日晚去世，享年 81 岁。","facts":["2001—2013 年任美国联邦调查局局长","2017—2019 年任调查通俄门的特别检察官","越战老兵，获铜星勋章与紫心勋章","2021 年确诊帕金森病，2025 年对外公开"],"obit":null,"portrait":"assets/portraits/2026-03-20-089.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Robert_Mueller"},{"id":"2026-03-20-088","date":"2026-03-20","name":"孙玉","nameOrig":"","country":"中国","region":"中国大陆","age":89,"fields":["科技"],"identity":"中国工程院院士 · 国防通信奠基人","summary":"从第一颗原子弹试验的遥控发端机，到三峡工程的通信网，他都在总设计的签字栏里。","bio":"孙玉 1936 年 4 月生于黑龙江肇东，1962 年从清华大学毕业，进入中国电子科技集团第五十四研究所，历任副总工程师、副所长、首席专家组长，1995 年当选中国工程院院士。\n\n他是中国国防通信事业的奠基人之一，参与我国第一颗原子弹试验遥控系统发端机研制、第一代火箭试验遥控系统研制，主持第一代洲际导弹飞行安全控制系统总体设计。他也主持研制了我国第一代远程数字散射传输系统、第一代用户数字程控交换机、第一代综合业务数字网和宽带综合业务数字网，并完成三峡工程通信网总体设计，被称为综合数字通信网的拓荒者。\n\n2026 年 3 月 20 日在北京去世，享年 89 岁。","facts":["1995 年当选中国工程院院士，长期在五十四所工作","参与我国第一颗原子弹试验遥控系统发端机研制","主持完成三峡工程通信网总体设计","曾任全军战略通信系统总设计师一职"],"obit":true,"portrait":"assets/portraits/2026-03-20-088.webp","source":"中国电科五十四所讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-03-20-087","date":"2026-03-20","name":"J·迈克尔·毕晓普","nameOrig":"J. Michael Bishop","country":"美国","region":"","age":90,"fields":["科技"],"identity":"病毒学家 · 1989 年诺贝尔生理学或医学奖得主","summary":"他和瓦穆斯证明：那些能致癌的基因，原本就住在每一个正常细胞的基因组里。","bio":"迈克尔·毕晓普 1936 年生于宾夕法尼亚州约克，在只有两间教室的乡村学校读完小学。1957 年毕业于葛底斯堡学院，1962 年获哈佛医学院医学博士，随后在马萨诸塞总医院实习，并到国立卫生研究院做病毒学研究。\n\n1968 年他到加州大学旧金山分校任教，与哈罗德·瓦穆斯合作研究劳斯肉瘤病毒，1970 年代发现所谓病毒癌基因其实来自宿主细胞自身的原癌基因，把癌症重新定义为一种基因疾病。这项成果让他与瓦穆斯共享 1989 年诺贝尔生理学或医学奖。1998 年至 2009 年他出任该校校长，主持了米申湾校区的扩建。\n\n2026 年 3 月 20 日在旧金山去世，享年 90 岁。","facts":["1989 年与哈罗德·瓦穆斯共获诺贝尔生理学或医学奖","发现逆转录病毒癌基因的细胞起源","1998—2009 年任加州大学旧金山分校校长","1982 年获拉斯克基础医学研究奖"],"obit":null,"portrait":"assets/portraits/2026-03-20-087.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/J._Michael_Bishop"},{"id":"2026-03-19-086","date":"2026-03-19","name":"查克·诺里斯","nameOrig":"Chuck Norris","country":"美国","region":"","age":86,"fields":["影视"],"identity":"美国动作演员 · 空手道冠军 · 《德州巡警》主演","summary":"在罗马斗兽场和李小龙对打的那几分钟，让他从此不必再向任何人证明自己会功夫。","bio":"查克·诺里斯 1940 年生于俄克拉荷马州瑞安，1958 年加入美国空军，在驻韩基地开始练唐手道，退役后参加空手道比赛，连续多年保持全胜。\n\n1972 年，他在李小龙的《猛龙过江》里出演空手道高手科尔，罗马斗兽场那场对决成了功夫片的经典段落。此后他主演《以眼还眼》《三角洲部队》等动作片，1993 年至 2001 年主演电视剧《德州巡警》，成为美国电视上最持久的硬汉形象，也因网络迷因被年轻一代重新认识。他还创立了武术流派春谷道。\n\n2026 年 3 月 19 日在夏威夷因病住院后去世，享年 86 岁，家属称其离世突然。","facts":["1972 年在《猛龙过江》中与李小龙演对手戏","1993—2001 年主演电视剧《德州巡警》","1958 年加入美国空军，在驻韩基地开始习武","创立武术流派春谷道（Chun Kuk Do）"],"obit":null,"portrait":"assets/portraits/2026-03-19-086.webp","source":"Pantheon","verified":"confirmed","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Chuck_Norris"},{"id":"2026-03-18-085","date":"2026-03-18","name":"广中平祐","nameOrig":"Heisuke Hironaka","country":"日本","region":"","age":94,"fields":["科技"],"identity":"数学家 · 菲尔兹奖得主 · 奇点解消问题解决者","summary":"三十一岁在家里想通了奇点怎么消解，1970 年拿到菲尔兹奖，此后半生仍在这道题上打转。","bio":"广中平祐 1931 年生于日本山口县，家中共十五个孩子，他排行第七。1950 年考入京都大学理学部，1957 年赴哈佛大学师从扎里斯基，1960 年获博士。\n\n1964 年他发表《在特征零的域上代数簇的奇点解消》，证明任意维数的代数簇都能通过一系列变换消去奇点，把此前只做到三维的结果推向一般情形，1970 年获菲尔兹奖，是继小平邦彦后第二位获此奖的日本人。1976 年起兼任京都大学教授，1983 年至 1985 年任京都大学数理解析研究所所长，1996 年至 2002 年任山口大学校长。1975 年获文化勋章，时年 44 岁。\n\n2026 年 3 月 18 日在东京家中去世，享年 94 岁。","facts":["1970 年获菲尔兹奖，为第二位获奖的日本数学家","1964 年发表特征零域上代数簇奇点解消论文","1996—2002 年任山口大学校长","1975 年获文化勋章，为昭和出生者中第一人"],"obit":null,"portrait":"assets/portraits/2026-03-18-085.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Heisuke_Hironaka"},{"id":"2026-03-15-084","date":"2026-03-15","name":"莱恩·戴顿","nameOrig":"Len Deighton","country":"英国","region":"","age":97,"fields":["军政"],"identity":"英国间谍小说家 · 《伊普克雷斯档案》作者","summary":"《伊普克雷斯档案》把间谍从跑车和赌场拉回办公室政治，也让迈克尔·凯恩一炮而红。","bio":"莱恩·戴顿 1929 年生于伦敦马里波恩，父母在富人家当司机和厨娘。他在皇家空军服役后进入皇家艺术学院，做过广告插画师，为两百多本书设计封面，还发明了把菜谱画成连环画的烹饪条。\n\n1962 年，他抱着玩票的心态写出《伊普克雷斯档案》，四千册首印当天售罄。书里的间谍没有名字、没有跑车，只有办公室倾轧和背叛，与邦德式的浪漫分道扬镳。此后他写了《柏林葬礼》《十亿美元大脑》，以及以伯纳德·萨姆森为主角的九部系列，还有《轰炸机》《SS-GB》等二战题材小说和若干饮食书。\n\n2026 年 3 月 15 日在根西岛去世，享年 97 岁。","facts":["1962 年处女作《伊普克雷斯档案》首印当天售罄","该作 1965 年被改编为电影，迈克尔·凯恩主演","著有以伯纳德·萨姆森为主角的九部间谍小说","另著《轰炸机》《SS-GB》等二战题材作品及多本饮食书"],"obit":null,"portrait":"assets/portraits/2026-03-15-084.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Len_Deighton"},{"id":"2026-03-14-083","date":"2026-03-14","name":"尤尔根·哈贝马斯","nameOrig":"Jürgen Habermas","country":"德国","region":"","age":96,"fields":["社科"],"identity":"德国哲学家 · 法兰克福学派第二代代表","summary":"他花一辈子证明，人与人之间除了权力和金钱，还能靠讲道理达成共识。","bio":"哈贝马斯 1929 年生于德国，患有先天性唇腭裂，童年几度手术，这让他对沟通问题格外敏感。他先后在哥廷根、苏黎世、波恩求学，1950 年代成为阿多诺在法兰克福社会研究所的助手。\n\n1961 年以《公共领域的结构转型》取得教授资格，1964 年接任霍克海默在法兰克福大学的哲学与社会学教席；1971 年赴施塔恩贝格任马克斯·普朗克学会研究所所长，1983 年回法兰克福，1994 年荣休。1981 年出版的《交往行为理论》被视为二十世纪下半叶最重要的哲学著作之一，他提出的公共领域、交往理性、商谈伦理成为人文社科的通用词汇。\n\n2026 年 3 月 14 日在施塔恩贝格去世，享年 96 岁。","facts":["1962 年出版《公共领域的结构转型》","1981 年出版《交往行为理论》","1971—1983 年任马克斯·普朗克学会研究所所长","法兰克福学派第二代核心人物，著作逾 50 部"],"obit":null,"portrait":"assets/portraits/2026-03-14-083.webp","source":"Pantheon","verified":"confirmed","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/J%C3%BCrgen_Habermas"},{"id":"2026-03-13-082","date":"2026-03-13","name":"菲尔·坎贝尔","nameOrig":"Phil Campbell","country":"英国","region":"","age":64,"fields":["文艺"],"identity":"威尔士吉他手 · 摩托头乐队在任最久成员","summary":"他那把带着布鲁斯味道的吉他，在摩托头的轰鸣里替莱米压了三十二年阵脚。","bio":"菲尔·坎贝尔 1961 年生于威尔士庞特普里德，早年组过几支乐队，1984 年加入摩托头，与莱米·基尔米斯特一道走完乐队剩下的三十年。\n\n他是队史在任最久的吉他手，把朋克的粗粝和布鲁斯的推弦塞进重金属里，随队演出了《Ace of Spades》《Orgasmatron》《1916》等专辑中的曲目。2015 年乐队因莱米去世而解散，此后他与三个儿子组成菲尔·坎贝尔与私生子乐队继续巡演。\n\n2026 年 3 月 13 日在一场复杂大手术后于重症监护中去世，享年 64 岁，家属称他走得安详。","facts":["1984—2015 年任摩托头乐队吉他手，队史在任最久","2015 年乐队解散后组建菲尔·坎贝尔与私生子乐队","曾随队演出《Ace of Spades》等经典曲目","死因为复杂大手术后的并发症，家属公布"],"obit":null,"portrait":"assets/portraits/2026-03-13-082.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null},{"id":"2026-03-13-081","date":"2026-03-13","name":"保罗·埃尔利希","nameOrig":"Paul R. Ehrlich","country":"美国","region":"","age":93,"fields":["科技"],"identity":"美国生态学家 · 《人口炸弹》作者","summary":"1968 年他写下《人口炸弹》，说养活全人类的战役已经结束，这本书让他被赞美也被骂了半个世纪。","bio":"保罗·埃利希 1932 年生于费城，1957 年获堪萨斯大学博士，1959 年起执教斯坦福大学，长期研究蝴蝶种群的遗传与动态。1964 年他与彼得·雷文合作发表协同演化论文，为这一领域奠基，并参与推动斯坦福将贾斯珀岭设为保护区。\n\n1968 年，他与妻子安妮合著的《人口炸弹》成为畅销书，书中断言人口增长将导致大规模饥荒，推动了美国环保运动，也让他此后数十年不断与人辩论人口与资源的边界。他共同创办零人口增长组织，获克拉福德奖、泰勒环境成就奖和麦克阿瑟奖。\n\n2026 年 3 月 13 日因癌症并发症在帕洛阿尔托去世，享年 93 岁。","facts":["1968 年出版《人口炸弹》，成为当年畅销书","1964 年与彼得·雷文发表协同演化奠基论文","1968 年共同创办零人口增长组织","曾获克拉福德奖与泰勒环境成就奖"],"obit":null,"portrait":"assets/portraits/2026-03-13-081.webp","source":"Pantheon","verified":"corrected","causeOfDeath":"癌症","wikipedia":"https://en.wikipedia.org/wiki/Paul_R._Ehrlich"},{"id":"2026-03-11-080","date":"2026-03-11","name":"萨利赫·穆斯林","nameOrig":"Salih Muslim","country":"叙利亚","region":"","age":75,"fields":["军政"],"identity":"叙利亚库尔德政治家 · 民主联盟党前联席主席","summary":"他在科巴尼出生，在埃尔比勒的医院去世，遗体越过边境口岸，葬回故乡。","bio":"萨利赫·穆斯林 1951 年生于叙利亚阿勒颇省科巴尼附近的村庄，1970 年赴伊斯坦布尔技术大学读化学工程，1977 年毕业。2003 年卡米什利事件后，他因致信巴沙尔·阿萨德被捕入狱七个月。\n\n他是叙利亚民主联盟党的创始成员，2010 年至 2017 年任该党联席主席，2022 年至 2024 年再度出任。内战期间他长期在海外为库尔德自治方案游说，其子在打击伊斯兰国的战斗中阵亡。晚年任党内总统委员会成员。\n\n2026 年 3 月 11 日因长期肾病在埃尔比勒一家医院去世，享年 75 岁，遗体运回科巴尼安葬。","facts":["叙利亚民主联盟党创始成员，两度任联席主席","1977 年毕业于伊斯坦布尔技术大学化学工程专业","其子在打击伊斯兰国的战斗中阵亡","死因为长期肾病引发的并发症，病逝于埃尔比勒"],"obit":null,"portrait":"assets/portraits/2026-03-11-080.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Salih_Muslim"},{"id":"2026-03-10-079","date":"2026-03-10","name":"苏珊·哈克","nameOrig":"Susan Haack","country":"英国","region":"","age":80,"fields":["社科"],"identity":"哲学家 · 基础融贯论提出者 · 迈阿密大学教授","summary":"她把认识论写成一张填字游戏：线索当证据，纵横交叉的答案彼此印证，谁也不靠谁打底。","bio":"苏珊·哈克 1945 年生于英格兰白金汉郡，先后在牛津与剑桥受教育，1972 年获剑桥大学哲学博士。1990 年起任教于迈阿密大学，2000 年同时获任法学教授。\n\n她研究逻辑哲学、认识论、科学哲学与法哲学，1993 年在《证据与探究》中提出基础融贯论，用填字游戏作比：经验证据像横向线索，答案之间的自洽像纵向校验，试图绕开基础论与融贯论各自的困境。她自称新古典实用主义者，承接皮尔士传统，也以《理性地捍卫科学》一书为科学的可靠性辩护，并把证据与证明问题带进法庭。\n\n2026 年 3 月 10 日在迈阿密去世，享年 80 岁。","facts":["1993 年出版《证据与探究》，提出基础融贯论","1978 年出版《逻辑哲学》，主张逻辑多元论","1990 年起任教于迈阿密大学，2000 年获任法学教授","以皮尔士的新古典实用主义为思想资源"],"obit":null,"portrait":null,"source":"Pantheon","verified":"corrected","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Susan_Haack"},{"id":"2026-03-08-078","date":"2026-03-08","name":"安东尼·莱格特","nameOrig":"Anthony James Leggett","country":"英国","region":"","age":87,"fields":["科技"],"identity":"英国理论物理学家 · 2003 年诺贝尔物理学奖得主","summary":"他解释了几毫开尔文下氦-3 为什么会无摩擦地流动，顺手拿下 2003 年的诺贝尔物理学奖。","bio":"安东尼·莱格特 1938 年生于伦敦，在牛津先读古典学与哲学，1959 年拿到古典学学位，随后改读物理，1964 年获博士学位。\n\n1972 年前后，他借用并拓展 BCS 超导理论，说明氦-3 原子在极低温下如何两两配对，形成自旋与轨道角动量都不为零的库珀对，从而成为超流体。这一理论预言了氦-3 超流体的多相结构，后来被实验证实。2003 年他与阿布里科索夫、金茨堡共享诺贝尔物理学奖。1967 年至 1983 年执教于萨塞克斯大学，之后转往伊利诺伊大学厄巴纳-香槟分校，晚年关注量子力学基础与宏观量子现象。\n\n2026 年 3 月 8 日在美国去世，享年 87 岁。","facts":["2003 年与阿布里科索夫、金茨堡共获诺贝尔物理学奖","1970 年代提出氦-3 超流配对理论","1967—1983 年任教于萨塞克斯大学，后任伊利诺伊大学教授","2004 年获封爵士，为英国皇家学会会员"],"obit":null,"portrait":"assets/portraits/2026-03-08-078.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Anthony_James_Leggett"},{"id":"2026-03-07-077","date":"2026-03-07","name":"乔·麦克唐纳","nameOrig":"Country Joe McDonald","country":"美国","region":"","age":84,"fields":["文艺"],"identity":"美国民谣摇滚歌手 · 伍德斯托克反战歌曲作者","summary":"在伍德斯托克，他先领着几十万人喊出那四个字母，再唱一首让人笑着反战的歌。","bio":"乔·麦克唐纳 1942 年生于华盛顿，在美国海军服役后进入伯克利，1965 年与巴里·梅尔顿组建乡村乔与鱼乐队，成为旧金山迷幻摇滚场景的代表之一。\n\n1969 年伍德斯托克音乐节上，他先领着几十万人喊出拼字母的脏话口号，再唱《I-Feel-Like-I'm-Fixin'-to-Die Rag》，这首带黑色幽默的反越战歌谣成了整个反战运动的合唱曲。此后半个多世纪他出版四十余张个人专辑，长期参与反战、环保和退伍军人权益活动。\n\n2026 年 3 月 7 日因帕金森病并发症在伯克利家中去世，享年 84 岁。","facts":["1965 年参与创建乡村乔与鱼乐队","1969 年在伍德斯托克音乐节演唱反越战歌曲","半世纪来出版个人专辑超过四十张","死因为帕金森病并发症，由家属确认"],"obit":null,"portrait":"assets/portraits/2026-03-07-077.webp","source":"Pantheon","verified":"corrected","causeOfDeath":"帕金森病","wikipedia":"https://en.wikipedia.org/wiki/Country_Joe_McDonald"},{"id":"2026-03-05-076","date":"2026-03-05","name":"熊大闰","nameOrig":"","country":"中国","region":"中国大陆","age":88,"fields":["科技"],"identity":"中国科学院院士 · 恒星对流理论开创者","summary":"他绕开教科书里的混合长理论，另造了一套恒星对流的算法，学界直接把它叫作「熊氏对流理论」。","bio":"熊大闰 1938 年 9 月生于江西吉安，祖籍南昌。1962 年从北京大学地球物理系毕业，同年分配到紫金山天文台工作，此后六十余年都在那里工作。\n\n他不满意传统的混合长理论，用流体力学方程和湍流理论另建了一套非局部、非定常的恒星对流统计理论，学界称为熊氏对流理论。这套理论被用于太阳对流区结构、大质量恒星演化和恒星脉动的计算，结果比传统理论与观测更相符。他先后获中国科学院自然科学一等奖、国家自然科学二等奖、王丹萍科学技术奖与何梁何利基金奖，1991 年当选中国科学院学部委员，曾任台学术委员会主任、《天文学报》主编。\n\n2026 年 3 月 5 日在南京去世，享年 88 岁。","facts":["1991 年当选中国科学院学部委员（院士）","独创熊氏对流理论，摆脱传统混合长理论框架","曾获中国科学院自然科学一等奖、国家自然科学二等奖","曾任第九届、第十届全国政协委员"],"obit":true,"portrait":"assets/portraits/2026-03-05-076.webp","source":"中科院紫金山天文台讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-03-05-075","date":"2026-03-05","name":"托尼·霍尔","nameOrig":"Tony Hoare","country":"英国","region":"","age":92,"fields":["科技"],"identity":"计算机科学家 · 快速排序发明者 · 图灵奖得主","summary":"他发明的快速排序让全世界的机器多跑了几十年，也造出了 null，后来自己称之为十亿美元的错误。","bio":"托尼·霍尔 1934 年生于锡兰科伦坡，父亲在英国殖民地行政部门任职。他在牛津读的是古典学，之后才转向统计学与计算机。1959 年至 1960 年在莫斯科国立大学做机器翻译研究时，为给俄语单词排序想出了快速排序，这个算法至今仍是被使用最广的排序方法之一。\n\n他参与制定 ALGOL 60，提出用于程序证明的霍尔逻辑、操作系统的管程概念与并发通信的顺序进程。1965 年设计语言时引入空引用，2009 年他公开道歉，称这是自己的十亿美元错误。1980 年获图灵奖，2000 年受封爵士。晚年任教于牛津，并在剑桥微软研究院任研究员。\n\n2026 年 3 月 5 日在剑桥去世，享年 92 岁。","facts":["1960 年前后提出快速排序算法，至今广泛使用","1980 年获 ACM 图灵奖，表彰其对编程语言设计的贡献","提出霍尔逻辑与顺序进程（CSP），奠定程序验证与并发通信基础","2000 年获封爵士，晚年任职于牛津与微软研究院"],"obit":null,"portrait":"assets/portraits/2026-03-05-075.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Tony_Hoare"},{"id":"2026-03-05-074","date":"2026-03-05","name":"安东尼奥·洛博·安图内斯","nameOrig":"António Lobo Antunes","country":"葡萄牙","region":"","age":83,"fields":["文艺"],"identity":"葡萄牙小说家 · 卡蒙斯文学奖得主","summary":"他当了十年精神科医生，然后用三十多部小说，把独裁、殖民战争和破碎的家庭重写了一遍。","bio":"安东尼奥·洛博·安图内斯 1942 年生于里斯本，父亲是神经科医生。他依父命读医，专攻精神病学，1971 年至 1973 年以军医身份在安哥拉服役，这段战争经验成了他日后写作的底色。\n\n1979 年他以长篇小说《象的记忆》登上文坛，此后出版二十余部作品，《远航船》《审查官手记》《世界尽头的土地上》《沿着流过的河水》等已有中译本。他惯用复调、长句和不断切换的视角，把萨拉查独裁与殖民战争留下的创伤拆成碎片。曾获奥地利欧洲文学国家奖、耶路撒冷文学奖、卡蒙斯文学奖，多年被视为诺贝尔文学奖热门人选。\n\n2026 年 3 月 5 日在里斯本去世，享年 83 岁。","facts":["1971—1973 年以军医身份在安哥拉服役","1979 年以《象的记忆》登上文坛，出版作品二十余部","2007 年获葡语文学最高奖卡蒙斯文学奖","2005 年获耶路撒冷文学奖，2000 年获奥地利欧洲文学国家奖"],"obit":null,"portrait":"assets/portraits/2026-03-05-074.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":null},{"id":"2026-03-05-002","date":"2026-03-05","name":"简·拉波泰尔","nameOrig":"Jane Lapotaire","country":"英国","region":"","age":81,"fields":["影视"],"identity":"英国演员 · 凭《Piaf》拿下托尼奖与奥利弗奖","summary":"1978 年，她把皮雅芙的一生唱进《Piaf》，一座托尼奖和一座奥利弗奖一起落进她手里。","bio":"1944 年 12 月 26 日生于萨福克郡伊普斯威奇，1965 年登台出道。1970 年她与劳伦斯·奥利弗一同创建青年维克剧院，1974 年加入皇家莎士比亚剧团。\n\n1978 年她在帕姆·吉姆斯的话剧《Piaf》中饰演伊迪丝·皮雅芙，从伦敦西区演到百老汇，拿下托尼奖与奥利弗奖两座最佳女主角。1992 年她在肯尼思·布拉纳版《哈姆雷特》中演王后格特鲁德。\n\n晚年她为电视观众熟悉，是在《唐顿庄园》和《王冠》里演库拉金公爵夫人与巴滕贝格的爱丽丝公主。2026 年 3 月 5 日她在伯恩茅斯去世，享年 81 岁。","facts":["凭《Piaf》同时获得托尼奖与奥利弗奖最佳女主角","1970 年与劳伦斯·奥利弗共同创建青年维克剧院","《王冠》中饰演巴滕贝格的爱丽丝公主","去世前数周获授 CBE 勋衔，表彰其艺术成就"],"obit":null,"portrait":"assets/portraits/2026-03-05-002.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Jane_Lapotaire"},{"id":"2026-03-01-073","date":"2026-03-01","name":"达维兹·奥德松","nameOrig":"Davíð Oddsson","country":"冰岛","region":"","age":78,"fields":["军政"],"identity":"冰岛前总理 · 独立党主席 · 央行前行长","summary":"他把冰岛交给自由市场十三年，也在 2008 年把那场崩盘的账一起收下。","bio":"达维兹·奥德松生于 1948 年，冰岛大学法律系毕业。1982 年至 1991 年任雷克雅未克市长，任内主导市政厅兴建与佩兰热水塔改造。1991 年出任独立党主席，同年起任总理，连续执政至 2004 年，是冰岛任职时间最长的总理，任内推行私有化、金融市场自由化与税制改革。\n\n2004 年至 2005 年转任外交部长，2005 年出任冰岛中央银行行长。2008 年金融危机中冰岛三大银行相继倒闭，他拒绝辞职，但被舆论视为危机责任人之一，2009 年随新政府上台去职，同年起担任《晨报》总编辑直至去世。","facts":["1991—2004 年任冰岛总理，是该国任职最久的政府首脑","1982—1991 年任雷克雅未克市长","2005—2009 年任冰岛中央银行行长，任内遭遇金融危机","2009 年起任冰岛《晨报》总编辑"],"obit":null,"portrait":"assets/portraits/2026-03-01-073.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Dav%C3%AD%C3%B0_Oddsson"},{"id":"2026-02-28-072","date":"2026-02-28","name":"阿里·哈梅内伊","nameOrig":"Ali Khamenei","country":"伊朗","region":"","age":86,"fields":["军政"],"identity":"伊朗最高领袖 · 1981—1989 年任总统","summary":"1981 年那次暗杀让他右臂终身瘫痪；四十五年后，他在美以空袭中身亡，德黑兰哀悼四十天。","bio":"1939 年生于伊朗马什哈德，早年在库姆神学院随霍梅尼学习。1981 年 6 月遭针对性暗杀，右臂瘫痪。1981 年至 1989 年任伊朗总统，1989 年霍梅尼去世后由专家会议推举为最高领袖。\n\n在任三十余年，他掌握军队、司法与媒体，对外支持地区武装力量，核问题谈判在他任内反复起落。2026 年 2 月 28 日上午，美国与以色列对伊朗发动空袭，当时他正与高级助手会面，伊朗国家媒体随后确认其身亡，政府宣布自 3 月 1 日起全国哀悼四十天。年 86 岁。","facts":["1981 年 6 月遇刺，右臂终身瘫痪","1981—1989 年任伊朗总统，1989 年起任最高领袖","2026 年 2 月 28 日在美以空袭中身亡","伊朗宣布自 3 月 1 日起全国哀悼四十天"],"obit":null,"portrait":"assets/portraits/2026-02-28-072.webp","source":"Pantheon","verified":"confirmed","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Ali_Khamenei"},{"id":"2026-02-27-071","date":"2026-02-27","name":"沈渔邨","nameOrig":"","country":"中国","region":"中国大陆","age":102,"fields":["医药"],"identity":"中国工程院院士 · 中国现代精神病学开拓者","summary":"她建起中国第一个精神生化实验室，又跑到海淀农村把精神病人的家庭随访做到六百万人口。","bio":"1924 年 1 月 6 日生于浙江杭州，1944 年考入西南联大医预专业，1946 年入北京大学医学院，1948 年入党，1951 年赴苏联莫斯科第一医学院，1955 年获医学副博士学位。1997 年当选中国工程院院士。\n\n1960 年代初创建我国精神病学界第一个现代神经生化实验室，率先创立人工冬眠新疗法。1974 年在北京海淀首创农村精神疾病家庭社会防治康复模式，即「海淀模式」。1980 年代组织新中国第一次大范围精神疾病流行病学调查，主编《精神病学》教材五版。2026 年 2 月 27 日 20 时 46 分在北京逝世，享年 102 岁。","facts":["创建我国精神病学界第一个现代神经生化实验室","1974 年首创农村精神疾病防治的「海淀模式」","组织完成新中国第一次大范围精神疾病流行病学调查","主编《精神病学》教材，五版沿用三十年"],"obit":true,"portrait":"assets/portraits/2026-02-27-071.webp","source":"北京大学第六医院讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-02-27-070","date":"2026-02-27","name":"方岱宁","nameOrig":"","country":"中国","region":"中国大陆","age":68,"fields":["科技"],"identity":"中国科学院院士 · 材料与结构力学专家","summary":"他研究极端高温下材料怎么不塌，主持做出的测试仪器跟着型号飞行器一起上了天。","bio":"1958 年 4 月生于江西南昌，祖籍浙江宁波。1982 年、1986 年在南京工业大学获学士、硕士学位并留校任教，1993 年获以色列理工学院博士学位。\n\n1995 至 2009 年任清华大学工程力学系教授；2009 至 2015 年任北京大学讲席教授、工学院副院长；2015 年起任北京理工大学教授，2015 至 2018 年任副校长。2013 年当选中国科学院院士，2022 年当选美国国家工程院外籍院士。他拓展铁电铁磁材料变形与断裂理论，建立力电磁热多场多尺度计算方法，主持研制多类超高温测试仪器。2026 年 2 月 27 日因病去世，享年 68 岁。","facts":["2013 年当选中国科学院院士，2022 年当选美国国家工程院外籍院士","主持研制多类超高温力学测试仪器","拓展铁电铁磁材料变形与断裂理论","2005、2010、2017 年三次获国家自然科学奖二等奖"],"obit":true,"portrait":"assets/portraits/2026-02-27-070.webp","source":"中国科学院学部","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-02-27-069","date":"2026-02-27","name":"尼尔·萨达卡","nameOrig":"Neil Sedaka","country":"美国","region":"","age":86,"fields":["文艺"],"identity":"美国歌手 · 词曲作者，布里尔大楼时期代表人物","summary":"他写《分手太难》，也写《日历女孩》，六十年代的电台一开口就是他的旋律。","bio":"1939 年 3 月 13 日生于纽约布鲁克林，父亲是土耳其裔，母亲有波兰与俄国犹太血统。八岁学钢琴，入朱利亚德音乐学院预备班学古典，后来转向流行。与作词人霍华德·格林菲尔德合作，成为布里尔大楼写作班底的一员。\n\n1959 年《日历女孩》、1960 年《分手太难》、1961 年《甜蜜十六岁生日快乐》接连上榜；1970 年代以《雨中笑声》等曲再起，一生写下数百首歌。1985 年日本动画《机动战士 Z 高达》两首片头曲也翻唱自他的作品。2026 年 2 月 27 日在洛杉矶一家医院去世，享年 86 岁。","facts":["1959—1961 年接连推出《日历女孩》《分手太难》等热门单曲","与作词人霍华德·格林菲尔德长期合作","1970 年代以《雨中笑声》再度走红","一生写下数百首歌曲，曾入朱利亚德预备班学古典"],"obit":null,"portrait":"assets/portraits/2026-02-27-069.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Neil_Sedaka"},{"id":"2026-02-27-068","date":"2026-02-27","name":"姜中宏","nameOrig":"","country":"中国","region":"中国大陆","age":95,"fields":["科技"],"identity":"中国科学院院士 · 光学玻璃与激光玻璃专家","summary":"他拉出中国第一根钕玻璃棒，让国产激光玻璃装进神光装置，也破了国外的技术禁运。","bio":"1930 年 8 月 7 日生于广东台山，1953 年毕业于华南工学院化学系，进中国科学院仪器馆工作。1964 年进入新成立的中科院光学精密机械研究所上海分所，即上海光机所。1999 年当选中国科学院院士。\n\n他主导研制成功我国第一根钕玻璃棒并实现激光输出，提出并发展玻璃形成相图模型，先后研制成功三种钕玻璃材料，打破国外对激光钕玻璃的技术封锁和禁运，用于我国高能激光系统与神光系列装置。获国家科技进步奖一等奖、中科院科技进步奖特等奖。九秩之年捐出积蓄设立「中宏奖助学金」。2026 年 2 月 27 日 11 时 24 分在上海华东医院逝世，享年 95 岁。","facts":["主导研制我国第一根钕玻璃棒并实现激光输出","研制三种钕玻璃材料，用于神光系列激光装置","1999 年当选中国科学院院士","获国家科技进步奖一等奖、中科院特等奖"],"obit":true,"portrait":"assets/portraits/2026-02-27-068.webp","source":"中科院上海光机所讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-02-27-067","date":"2026-02-27","name":"周尔均","nameOrig":"","country":"中国","region":"中国大陆","age":93,"fields":["军政"],"identity":"国防大学原政治部主任 · 少将，周恩来侄子","summary":"他是周恩来的侄子，却与妻子约定公开场合见到七伯要装作不认识，这条默契守了一辈子。","bio":"1932 年 10 月生于浙江绍兴，1949 年 6 月入伍，1953 年 12 月入党。历任学员、见习干事、秘书、副科长、通讯社副社长、研究员、处长，国防大学办公室主任、政治部副主任、党委常委、纪委副书记、政治部主任。1988 年恢复军衔制后首批授少将，正军职。\n\n他参加过解放大西南战役与对越自卫反击战，是第八届全国人大代表，获胜利功勋荣誉章。晚年任周恩来思想生平研究分会顾问，与夫人邓在军策划电视片《百年恩来》，2023 年出版《百年不了情——我与伯父周恩来相处的日子》。2026 年 2 月 27 日在北京逝世，享年 93 岁。","facts":["1988 年恢复军衔制后首批授少将，正军职","国防大学原党委常委、纪委副书记、政治部主任","与夫人邓在军策划电视片《百年恩来》","1932 年生于浙江绍兴，1949 年入伍"],"obit":true,"portrait":"assets/portraits/2026-02-27-067.webp","source":"新京报","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-02-26-066","date":"2026-02-26","name":"高铭暄","nameOrig":"","country":"中国","region":"中国大陆","age":98,"fields":["社科"],"identity":"中国人民大学荣誉一级教授 · 刑法学奠基人","summary":"1954 年他进刑法起草小组，二十五年的三十八稿之后，新中国第一部刑法才出来。","bio":"1928 年 5 月生于浙江玉环，1947 年考入浙江大学，两年后转入北京大学法律系，1951 年毕业，后入中国人民大学法律系读研究生并留校任教，教龄逾七十年。\n\n1954 年他被抽调进刑法起草小组，历时二十五年、三十八稿，1979 年 7 月 1 日《中华人民共和国刑法》通过，他是唯一全程参与的学者。主编七部刑法学教材、著有八部专著，《刑法学》成为几代法科生的必读书。2015 年获国际社会防卫学会「切萨雷·贝卡里亚」奖，为亚洲第一人；2019 年获「人民教育家」国家荣誉称号。2026 年 2 月 26 日 11 时 47 分在北京逝世，享年 98 岁。","facts":["唯一全程参与 1979 年刑法典起草的学者","新中国第一位刑法学专业博士生导师","2015 年获「切萨雷·贝卡里亚」奖，为亚洲第一人","2019 年获「人民教育家」国家荣誉称号"],"obit":true,"portrait":"assets/portraits/2026-02-26-066.webp","source":"今日头条盘点汇编","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-02-25-065","date":"2026-02-25","name":"安东尼奥·特赫罗","nameOrig":"Antonio Tejero","country":"西班牙","region":"","age":93,"fields":["军政"],"identity":"西班牙国民警卫队中校 · 23-F 政变主谋","summary":"1981 年 2 月 23 日，他举着手枪冲进议会，那一声枪响成了西班牙民主最险的一夜。","bio":"1932 年生于西班牙，国民警卫队中校。1981 年 2 月 23 日，在议会表决首相任命时，他带两百余名警备队员闯入众议院，朝天花板开枪，把三百多名议员扣为人质近十八小时，政变因国王出面表态而失败。\n\n他因军事叛乱罪被判三十六年监禁，服刑部分后获假释，此后长期住在阿尔西拉，鲜少露面。2026 年 2 月 25 日去世，享年 93 岁——恰在 23-F 四十五周年两天后，也是西班牙政府解密 23-F 相关档案的同一天。","facts":["1981 年 2 月 23 日持枪闯入众议院，扣押议员近十八小时","以军事叛乱罪被判处三十六年监禁","国王胡安·卡洛斯出面表态后政变失败","死于 23-F 四十五周年两天后"],"obit":null,"portrait":null,"source":"Pantheon","verified":"corrected","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Antonio_Tejero"},{"id":"2026-02-24-064","date":"2026-02-24","name":"游飚","nameOrig":"","country":"中国","region":"香港","age":57,"fields":["影视"],"identity":"香港演员 · TVB 绿叶，有「御用烂仔」之称","summary":"在 TVB 演了二十三年小混混，《大时代》里一个人分饰三角，观众叫不出名字却认得那张脸。","bio":"1968 年 8 月 25 日生于福建厦门，籍贯香港。1989 年考入 TVB 第三期艺员训练班，在无线效力二十三年，参演近两百部剧集，多为小混混、赌徒、黑社会等底层角色，被观众称作「御用烂仔」，在《大时代》里一人分饰三角。\n\n2012 年因月薪仅一万零五百港元离巢，转行经营自己在 2004 年创办的环保工程公司，主营除甲醛，还邀来失业的好友黄文标做销售。2026 年 2 月 12 日在办公室见客时突发不适，送院证实脑出血，昏迷至 2 月 24 日晚不治，终年 57 岁。","facts":["1989 年考入 TVB 第三期艺员训练班，效力二十三年","参演近两百部剧集，多演小混混等底层角色","2012 年离巢后创办除甲醛环保工程公司","2026 年 2 月 12 日脑出血，昏迷十二天后去世"],"obit":true,"portrait":"assets/portraits/2026-02-24-064.webp","source":"今日头条盘点汇编","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-02-23-063","date":"2026-02-23","name":"罗伯特·卡拉丁","nameOrig":"Robert Carradine","country":"美国","region":"","age":71,"fields":["影视"],"identity":"美国演员 · 《菜鸟大反攻》刘易斯","summary":"他演了《菜鸟大反攻》里那个不合群的刘易斯，后来又在《莉琪的异想世界》里当了慈父。","bio":"1954 年 3 月 24 日生于好莱坞，父亲约翰·卡拉丁、兄长凯斯与同父异母兄长大卫都是演员，女儿埃弗也是演员。1971 年在《伯南扎》里首次上电视，1972 年在约翰·韦恩的《牛仔》里进入电影。\n\n1984 年《菜鸟大反攻》里的刘易斯·斯科尔尼克让他广为人知，此后出演《逃离洛杉矶》《红一纵队》。2001 至 2004 年在《莉琪的异想世界》里演山姆·麦圭尔，成为一代青少年的银幕父亲。家人公开他与躁郁症抗争近二十年的经历。2026 年 2 月 23 日在洛杉矶去世，享年 71 岁。","facts":["1984 年《菜鸟大反攻》饰演刘易斯·斯科尔尼克","2001—2004 年在《莉琪的异想世界》演山姆·麦圭尔","出身卡拉丁演员家族，父亲约翰、兄长凯斯与大卫","家人公开他与躁郁症抗争近二十年"],"obit":null,"portrait":"assets/portraits/2026-02-23-063.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Robert_Carradine"},{"id":"2026-02-21-062","date":"2026-02-21","name":"威利·科隆","nameOrig":"Willie Colón","country":"美国","region":"","age":75,"fields":["文艺"],"identity":"美国萨尔萨长号手 · 制作人，Fania 元老","summary":"他在布朗克斯把波多黎各的节奏和爵士缝在一起，长号一响，萨尔萨才有了纽约口音。","bio":"1950 年 4 月 28 日生于纽约布朗克斯，波多黎各移民家庭。少年时学长号，1960 年代末与歌手埃克托·拉沃在 Fania 唱片合作，专辑封面上的黑帮形象比风气早了十年。\n\n1978 年与鲁本·布拉德斯的《Siembra》成为史上销量最高的萨尔萨唱片之一。一生制作四十多张专辑，全球销量超过三千万张，写过《Tiburón》《El gran varón》等名曲，并长期参与纽约市政与波多黎各议题。2026 年 2 月 21 日去世，享年 75 岁，死因未公开。","facts":["1978 年与鲁本·布拉德斯合作《Siembra》","制作四十多张专辑，全球销量超过三千万张","Fania 唱片时期纽约萨尔萨场景的关键人物","长年参与纽约市政与波多黎各社会议题"],"obit":null,"portrait":"assets/portraits/2026-02-21-062.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Willie_Col%C3%B3n"},{"id":"2026-02-21-061","date":"2026-02-21","name":"丹·西蒙斯","nameOrig":"Dan Simmons","country":"美国","region":"","age":77,"fields":["文艺"],"identity":"美国科幻作家 · 《海伯利安》作者","summary":"他当小学老师时把故事一天一段讲给学生听，讲出来的那部东西后来叫《海伯利安》。","bio":"1948 年 4 月 4 日生于伊利诺伊州皮奥里亚，1970 年毕业于瓦巴什学院英文系，1971 年获圣路易斯华盛顿大学教育学硕士，在密苏里、纽约、科罗拉多做小学教师十六年。1985 年首部长篇《迦梨之歌》获世界奇幻奖。\n\n1989 年的《海伯利安》获雨果奖与轨迹奖，续作《海伯利安的陨落》《安迪密恩》《安迪密恩的觉醒》合称海伯利安诗篇；《伊利昂》获轨迹奖。2007 年的《极地恶灵》2018 年被 AMC 改编为剧集。2026 年 2 月 21 日在科罗拉多州朗蒙特家中因中风去世，享年 77 岁。","facts":["《海伯利安》1989 年出版，获雨果奖与轨迹奖","首部长篇《迦梨之歌》获世界奇幻奖","《极地恶灵》2018 年被 AMC 改编为剧集","做小学教师十六年后才转为全职写作"],"obit":null,"portrait":"assets/portraits/2026-02-21-061.webp","source":"Pantheon","verified":"corrected","causeOfDeath":"中风","wikipedia":"https://en.wikipedia.org/wiki/Dan_Simmons"},{"id":"2026-02-20-060","date":"2026-02-20","name":"比尔·马泽罗斯基","nameOrig":"Bill Mazeroski","country":"美国","region":"","age":89,"fields":["体育"],"identity":"美国棒球运动员 · 海盗队二垒手，棒球名人堂成员","summary":"1960 年世界大赛第七场，他打出了史上唯一一支终结系列赛的再见本垒打。","bio":"1936 年生于西弗吉尼亚州惠灵，在俄亥俄州蒂尔顿斯维尔长大。1956 至 1972 年效力匹兹堡海盗队，十七个赛季以守备见长，拿过八次金手套，多次入选全明星。\n\n1960 年 10 月 13 日下午 3 点 36 分，他在福布斯球场把洋基投手拉尔夫·特里的球打过砖墙，让海盗队 35 年来首次夺冠，这是世界大赛史上唯一一支第七场再见本垒打。2001 年入选国家棒球名人堂，2022 年入选海盗队名人堂首批。2026 年 2 月 20 日在宾夕法尼亚州兰斯代尔去世，享年 89 岁。","facts":["1960 年世界大赛第七场再见本垒打，史上唯一","八次获金手套奖，多次入选全明星阵容","2001 年入选国家棒球名人堂","十七个赛季全部效力匹兹堡海盗队"],"obit":null,"portrait":"assets/portraits/2026-02-20-060.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Bill_Mazeroski"},{"id":"2026-02-19-059","date":"2026-02-19","name":"埃里克·戴恩","nameOrig":"Eric Dane","country":"美国","region":"","age":53,"fields":["影视"],"identity":"美国演员 · 《实习医生格蕾》马克·斯隆医生","summary":"「麦克斯特米」这个外号跟了他二十年，最后是渐冻症把他从这个称呼里带走。","bio":"1972 年 11 月 9 日生于旧金山，高中毕业后到洛杉矶闯演艺圈，九十年代在《圣女魔咒》《罗斯安》等剧里跑龙套。2006 年加入《实习医生格蕾》演马克·斯隆医生，演到 2012 年，2021 年回归。\n\n此后出演《马利与我》《情人节》《舞娘俱乐部》《末日孤舰》，并在《亢奋》里演卡尔·雅各布斯。2025 年 4 月公开确诊肌萎缩侧索硬化，随后到华盛顿游说国会支持 ALS 研究。2026 年 2 月 19 日在洛杉矶因呼吸衰竭去世，年 53 岁，死因证明书列渐冻症为次要原因。","facts":["2006—2012 年在《实习医生格蕾》演马克·斯隆医生","在《亢奋》中饰演卡尔·雅各布斯","2025 年 4 月公开确诊渐冻症，赴华盛顿游说国会","死因证明书列渐冻症导致的呼吸衰竭"],"obit":null,"portrait":"assets/portraits/2026-02-19-059.webp","source":"Pantheon","verified":"corrected","causeOfDeath":"渐冻症","wikipedia":"https://en.wikipedia.org/wiki/Eric_Dane"},{"id":"2026-02-19-058","date":"2026-02-19","name":"周炳琨","nameOrig":"","country":"中国","region":"中国大陆","age":90,"fields":["科技"],"identity":"中国科学院院士 · 激光与光电子学奠基人","summary":"1984 年他在斯坦福做出当时效率最高的半导体激光泵浦固体激光器，为固体激光开了新路。","bio":"1936 年 3 月 2 日生于成都，1956 年毕业于清华大学无线电系并留校任教，1960 至 1962 年在苏联列宁格勒电工学院进修，1983 至 1984 年在美国斯坦福大学任访问教授。1991 年当选中国科学院院士，2001 年当选第三世界科学院院士。\n\n1980 年主编的《激光原理》获第一届国家优秀教材奖。1984 年在斯坦福期间研制出高效率、长寿命、窄线宽、频率稳定的半导体激光泵浦固体激光器。曾任中国光学学会理事长、863 计划光电子器件与集成技术专家组组长。2026 年 2 月 19 日 0 时 54 分在北京逝世，享年 90 岁。","facts":["1984 年在国际上率先研制半导体激光泵浦固体激光器","主编《激光原理》，获第一届国家优秀教材奖","曾任 863 计划光电子器件与集成技术专家组组长","1991 年当选中国科学院院士，2001 年当选第三世界科学院院士"],"obit":true,"portrait":"assets/portraits/2026-02-19-058.webp","source":"清华大学讣告","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-02-18-057","date":"2026-02-18","name":"扬·蒂曼","nameOrig":"Jan Timman","country":"荷兰","region":"","age":74,"fields":["体育"],"identity":"荷兰国际象棋特级大师 · 九次全国冠军，前世界第二","summary":"八十年代他被叫作西方最好的棋手，九次拿下荷兰冠军，始终差一步够不到世界冠军。","bio":"1951 年 12 月 14 日生于阿姆斯特丹，八岁随父学棋，十二岁在一次车轮战中逼和前世界冠军尤伟。1971 年获国际大师称号，1974 年成为特级大师，1974 至 1996 年间九次获荷兰全国冠军。\n\n1982 年 1 月世界排名第二，是当时最强的非苏联棋手，绰号西方最佳。他多次进入世界冠军候选人赛，1993 年争夺世界冠军头衔时负于卡尔波夫。他也是多产的国际象棋作家，任《新国际象棋》杂志荣誉主编。2026 年 2 月 18 日在阿纳姆去世，享年 74 岁。","facts":["1974—1996 年间九次获荷兰全国冠军","1982 年世界排名第二，绰号西方最佳","1993 年世界冠军对抗赛负于卡尔波夫","《新国际象棋》杂志荣誉主编，著有多部棋书"],"obit":null,"portrait":null,"source":"Pantheon","verified":"corrected","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Jan_Timman"},{"id":"2026-02-17-056","date":"2026-02-17","name":"杰西·杰克逊","nameOrig":"Jesse Jackson","country":"美国","region":"","age":84,"fields":["军政"],"identity":"美国民权运动领袖 · 牧师，两次竞选总统","summary":"金遇刺那晚他就在场，后来两次竞选总统，那句「我也是个人物」喊了五十年。","bio":"1941 年 10 月 8 日生于南卡罗来纳州格林维尔，原名 Jesse Louis Burns。1959 年靠体育奖学金入伊利诺伊大学，后转北卡罗来纳农业技术学院；1963 年加入南方基督教领导联盟，成为马丁·路德·金的助手，1968 年 4 月 4 日金遇刺时在场。\n\n1971 年创立人道联合组织，后为彩虹/PUSH 联盟。1984 年、1988 年两次角逐民主党总统提名，推动民主党修改代表选举规则。2000 年获总统自由勋章。晚年患进行性核上性麻痹，2023 年卸任联盟主席。2026 年 2 月 17 日在芝加哥去世，享年 84 岁。","facts":["1968 年马丁·路德·金遇刺时在场","1984、1988 两度竞选民主党总统提名","1971 年创立人道联合组织，后为彩虹/PUSH 联盟","2000 年获总统自由勋章，晚年患进行性核上性麻痹"],"obit":null,"portrait":"assets/portraits/2026-02-17-056.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Jesse_Jackson"},{"id":"2026-02-17-055","date":"2026-02-17","name":"何塞·范·当","nameOrig":"José van Dam","country":"比利时","region":"","age":85,"fields":["文艺"],"identity":"比利时男低中音歌唱家 · 卡拉扬最倚重的歌手之一","summary":"卡拉扬偏爱的那把低音，从《唐璜》唱到梅西安的圣方济各，半个世纪没换过。","bio":"1940 年 8 月 25 日生于布鲁塞尔，本名 Joseph van Damme，在布鲁塞尔皇家音乐学院学声乐与歌剧，曾靠夜总会驻唱维持学业。1960 年在列日以《塞维利亚的理发师》中的巴西利奥登台，1961 至 1965 年在巴黎歌剧院。\n\n他擅长莫扎特、威尔第、瓦格纳与法国歌剧，1971 年在卡拉扬手下首次与柏林爱乐合作，1983 年首演梅西安《阿西西的圣方济各》主角。一生塑造一百五十多个角色，唱片屡获大奖，被封为男爵。2026 年 2 月 17 日去世，享年 85 岁。","facts":["1940 年生于布鲁塞尔，本名 Joseph van Damme","1983 年首演梅西安《阿西西的圣方济各》主角","塑造过一百五十多个歌剧角色，被封男爵","卡拉扬时代长期与柏林爱乐乐团合作"],"obit":null,"portrait":"assets/portraits/2026-02-17-055.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":null},{"id":"2026-02-16-054","date":"2026-02-16","name":"弗雷德里克·怀斯曼","nameOrig":"Frederick Wiseman","country":"美国","region":"","age":96,"fields":["影视"],"identity":"美国纪录片导演 · 直接电影代表人物","summary":"六十年来他不加旁白、不做采访，只把医院、学校、福利局原样放在镜头里。","bio":"1930 年 1 月 1 日生于波士顿，毕业于威廉姆斯学院与耶鲁法学院，早年教法律，1964 年为雪莉·克拉克的《冷酷的世界》担任制片。1967 年首作《提提卡失序记事》记录精神病院监狱里的生存状态，获曼海姆影展最佳纪录片奖。\n\n此后近六十年拍出约五十部纪录片：《医院》《高中》《福利》《动物园》《公共住房》《在伯克利》《国家美术馆》，以及 2023 年的封镜之作《特鲁瓦格罗餐厅》。不用旁白、不做采访是他的规矩。2014 年获威尼斯电影节终身成就金狮奖，2016 年获奥斯卡终身成就奖。2026 年 2 月 16 日在马萨诸塞州剑桥家中去世，享年 96 岁。","facts":["1967 年首作《提提卡失序记事》","一生拍出约五十部纪录片，坚持不用旁白与采访","2014 年获威尼斯电影节终身成就金狮奖","2016 年获奥斯卡终身成就荣誉奖"],"obit":null,"portrait":"assets/portraits/2026-02-16-054.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Frederick_Wiseman"},{"id":"2026-02-15-053","date":"2026-02-15","name":"罗伯特·杜瓦尔","nameOrig":"Robert Duvall","country":"美国","region":"","age":95,"fields":["影视"],"identity":"美国演员 · 奥斯卡影帝，《教父》中的汤姆·哈根","summary":"他演《教父》里那个军师，演《现代启示录》里那个冲浪狂上校，六十年只演普通人的重量。","bio":"1931 年 1 月 5 日生于加州圣地亚哥，海军少将之子，在普林斯匹亚学院主修戏剧，后到纽约学表演。1962 年在《杀死一只知更鸟》里演布·拉德利，戏份不多却难忘。\n\n1972 年《教父》的汤姆·哈根、1979 年《现代启示录》的基尔戈上校让他两度获奥斯卡提名；1983 年凭《怜情蜜意》获奥斯卡最佳男主角，还拿过两个艾美、四个金球。1997 年自编自导自演《传教士》。他一生演警察、农民、退伍兵，被评论界称作美国的奥利弗。2026 年 2 月 15 日在弗吉尼亚州米德尔堡的农场去世，享年 95 岁。","facts":["1983 年凭《怜情蜜意》获奥斯卡最佳男主角","《现代启示录》获英国电影学院奖最佳男配角","共获七次奥斯卡提名、两个艾美奖、四个金球奖","1997 年自编自导自演《传教士》"],"obit":null,"portrait":"assets/portraits/2026-02-15-053.webp","source":"Pantheon","verified":"confirmed","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Robert_Duvall"},{"id":"2026-02-13-052","date":"2026-02-13","name":"罗伊·梅德韦杰夫","nameOrig":"Roy Medvedev","country":"俄罗斯","region":"","age":100,"fields":["社科"],"identity":"俄罗斯历史学家 · 《让历史来审判》作者","summary":"他把苏联的档案翻成《让历史来审判》，一生坚持自己是马克思主义者，不是叛徒。","bio":"1925 年 11 月 14 日生于第比利斯，孪生兄弟若列斯是生物学家、同为苏联持不同政见者；父亲 1930 年代死于劳改营。1951 年毕业于列宁格勒大学。\n\n《让历史来审判》1960 年代以地下出版物流传，1972 年英文版问世，成为苏联内部批判斯大林主义最重要的著作。他因此被禁居莫斯科、著作只能在境外出版，却始终自称马克思主义者，主张回到列宁。1989 年恢复党籍与公职，曾任戈尔巴乔夫顾问，一生著作逾五十部。2026 年 2 月 13 日在莫斯科近郊家中因心力衰竭去世，享年 100 岁。","facts":["《让历史来审判》1972 年英文出版，批判斯大林主义","1960 年代起著作只能经地下出版物与境外出版流传","1989 年恢复党籍，曾任戈尔巴乔夫顾问","一生著作超过五十部，孪生兄弟若列斯亦为异议者"],"obit":null,"portrait":null,"source":"Pantheon","verified":"corrected","portraitStatus":"no-source","causeOfDeath":"心力衰竭","wikipedia":"https://en.wikipedia.org/wiki/Roy_Medvedev"},{"id":"2026-02-11-051","date":"2026-02-11","name":"詹姆斯·范德比克","nameOrig":"James Van Der Beek","country":"美国","region":"","age":48,"fields":["影视"],"identity":"美国演员 · 《恋爱时代》道森","summary":"他演的那个爱皱眉的少年，让一整代人以为青春期就该在码头上说个没完。","bio":"1977 年 3 月 8 日生于康涅狄格州柴郡，13 岁因踢球脑震荡停赛一年，转而在学校排演的《油脂》里找到出路。1998 年至 2003 年在 WB 剧集《恋爱时代》中演道森·里里，1999 年主演电影《校园蓝调》。\n\n此后他在《别相信公寓 23 号里的 B》里演自己，在《CSI：网络犯罪》里演 FBI 探员，2018 年参演《姿态》第一季。2023 年确诊结直肠癌，2024 年公开病情，随后仍参与拍摄。2026 年 2 月 11 日在得州奥斯汀去世，年 48 岁，遗有六个子女。","facts":["1998—2003 年主演《恋爱时代》","1999 年主演电影《校园蓝调》","2023 年确诊结直肠癌，2024 年公开病情","去世时留下妻子与六个子女，年 48 岁"],"obit":null,"portrait":"assets/portraits/2026-02-11-051.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/James_Van_Der_Beek"},{"id":"2026-02-11-050","date":"2026-02-11","name":"巴德·科特","nameOrig":"Bud Cort","country":"美国","region":"","age":77,"fields":["影视"],"identity":"美国演员 · 《哈洛与慕德》中的哈洛","summary":"他演了一个痴迷死亡的少年，爱上七十九岁的老太太，那部片子成了一代人的暗号。","bio":"本名 Walter Edward Cox，1948 年 3 月 29 日生于纽约州新罗谢尔，在纽约大学蒂施艺术学院学过舞台美术，师从斯特拉·阿德勒。1970 年在《陆军野战医院》里演一个小角色，同年主演奥特曼的《空中怪客》，获金桂冠奖提名。\n\n1971 年《哈洛与慕德》让他成为 1970 年代反主流文化的符号，获金球奖与英国电影学院奖提名。此后出演《热》《怒犯天条》《水中生活》等，并为 DC 动画宇宙的玩具人配音。2026 年 2 月 11 日在康涅狄格州诺沃克的养老机构因肺炎并发症去世，享年 77 岁。","facts":["1971 年《哈洛与慕德》获金球奖与英国电影学院奖提名","本名 Walter Edward Cox，为避开重名取艺名","为 DC 动画宇宙的玩具人一角配音","晚年长期患病，最终死于肺炎并发症"],"obit":null,"portrait":"assets/portraits/2026-02-11-050.webp","source":"Pantheon","verified":"corrected","causeOfDeath":"肺炎","wikipedia":"https://en.wikipedia.org/wiki/Bud_Cort"},{"id":"2026-02-11-049","date":"2026-02-11","name":"塞斯·诺特博姆","nameOrig":"Cees Nooteboom","country":"荷兰","region":"","age":92,"fields":["文艺"],"identity":"荷兰作家 · 诗人、旅行文学作家","summary":"他被叫作欧洲最后的知识分子作家，一辈子在路上，写的是记忆、离开和回不去的地方。","bio":"1933 年 7 月 31 日生于海牙，1954 年出版处女作《菲利普与其他》，此后写小说、诗、游记与艺术评论。1980 年的《仪式》获美国飞马奖，1991 年的《下一个故事》让他真正进入国际视野。\n\n他大半生住在西班牙梅诺卡岛，足迹遍及世界，被视为最具世界公民意识的作家，获福门托奖、奥地利国家欧洲文学奖等。作品译成三十多种语言，中译本有《狐狸在夜晚来临》《西班牙星光之路》。2026 年 2 月 11 日在梅诺卡岛去世，享年 92 岁。","facts":["1980 年《仪式》获美国飞马奖","1991 年《下一个故事》带来国际突破","获福门托奖与奥地利国家欧洲文学奖","作品译成三十多种语言，长居梅诺卡岛"],"obit":null,"portrait":"assets/portraits/2026-02-11-049.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Cees_Nooteboom"},{"id":"2026-02-08-048","date":"2026-02-08","name":"张中一","nameOrig":"","country":"中国","region":"中国大陆","age":74,"fields":["影视"],"identity":"中国电视剧导演 · 94 版《三国演义》分集导演","summary":"「卧龙吊孝」「姜维之死」「三分归晋」都出自他手，为一场戏的纸钱剪了一天一夜。","bio":"中国电视剧导演，累计拍摄电视剧五百余部集，作品包括《孙武》《格萨尔王》《裸情恨》，曾获星光奖、金剑奖。1994 年版《三国演义》设五位分集导演，他负责第 45 至 52 集、第 78 至 84 集。\n\n「卧龙吊孝」一场，他让剧组女同志剪了一天一夜纸钱，用四幅帛画串起周瑜一生，还打破汉代礼节让角色撞棺；「姜维之死」改成剑穿腹部把人钉在柱上，配雷雨强化悲壮。他曾公开批评不背台词、靠绿幕抠图的演员。抗癌五年几乎不曾对人提起，2026 年 2 月 8 日下午因病去世，享年 74 岁。","facts":["94 版《三国演义》五位分集导演之一，负责第 45—52、78—84 集","执导「卧龙吊孝」「姜维之死」「三分归晋」","累计拍摄电视剧五百余部集，获星光奖、金剑奖","抗癌五年，几乎不曾对外提及自己的病情"],"obit":true,"portrait":"assets/portraits/2026-02-08-048.webp","source":"多家媒体","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-02-07-047","date":"2026-02-07","name":"约翰·弗拉纳根","nameOrig":"John Flanagan","country":"澳大利亚","region":"","age":81,"fields":["文艺"],"identity":"澳大利亚奇幻作家 · 《皇家骑士》系列作者","summary":"为了让不爱读书的儿子翻书，他写了一个游侠学徒的故事，结果卖了两千多万册。","bio":"1944 年 5 月 22 日生于悉尼，毕业于韦弗利学院，先做广告创意总监，1978 年辞职做自由撰稿，写过电视情景喜剧剧本。为鼓励 12 岁的儿子迈克尔阅读，他把一个少年游侠学徒的故事写成短篇，2004 年扩展成长篇《戈兰的废墟》，开启《皇家骑士》系列。\n\n该系列与其姊妹篇《兄弟帮》系列被译成数十种语言，全球销量超过两千万册，另著有成人小说《灰色袭击者》。2026 年 2 月 7 日因非霍奇金淋巴瘤并发症去世，享年 81 岁；消息由版权代理公司与企鹅兰登在 4 月公布。","facts":["《皇家骑士》首作《戈兰的废墟》2004 年出版","全球销量超过两千万册，译成数十种语言","曾任广告创意总监，并为电视情景喜剧写剧本","死因为非霍奇金淋巴瘤并发症，终年 81 岁"],"obit":null,"portrait":"assets/portraits/2026-02-07-047.webp","source":"Pantheon","verified":"corrected","causeOfDeath":"淋巴瘤","wikipedia":"https://en.wikipedia.org/wiki/John_Flanagan_(Scottish_footballer)"},{"id":"2026-02-05-046","date":"2026-02-05","name":"托马什·瓦沙里","nameOrig":"Tamás Vásáry","country":"匈牙利","region":"","age":92,"fields":["文艺"],"identity":"匈牙利钢琴家 · 指挥家，李斯特与肖邦的诠释者","summary":"八岁登台弹莫扎特，此后六十多年，他的肖邦和李斯特被当作匈牙利钢琴学派最后一条直接血脉。","bio":"1933 年 8 月 11 日生于匈牙利德布勒森，八岁公开演奏莫扎特协奏曲，十二岁入布达佩斯李斯特音乐学院，师从赫尔纳迪，后任柯达伊的视唱练耳助教。1948 年获李斯特钢琴比赛首奖，1956 年离开匈牙利，先居瑞士，1970 年起定居伦敦。\n\n他在皇家节日大厅的首演打开了国际生涯，此后每年演出约百场，为德意志留声机公司录制大量肖邦、李斯特、舒曼作品。后转向指挥，任北方小交响乐团、伯恩茅斯小交响乐团音乐总监，并长期指挥匈牙利广播交响乐团。曾获科苏特奖。2026 年 2 月 5 日在布达佩斯去世，享年 92 岁。","facts":["1948 年获布达佩斯李斯特钢琴比赛首奖","1956 年离开匈牙利，先后定居瑞士与伦敦","曾任北方小交响乐团、伯恩茅斯小交响乐团音乐总监","获匈牙利科苏特奖与法国艺术与文学骑士勋章"],"obit":null,"portrait":"assets/portraits/2026-02-05-046.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":null},{"id":"2026-02-03-045","date":"2026-02-03","name":"赛义夫·伊斯兰·卡扎菲","nameOrig":"Saif al-Islam Gaddafi","country":"利比亚","region":"","age":53,"fields":["军政"],"identity":"利比亚政治人物 · 卡扎菲次子，基金会主席","summary":"一度被视为卡扎菲的接班人，出狱后还想竞选总统，最终在津坦家中被四名蒙面枪手打死。","bio":"1972 年 6 月 25 日生于的黎波里，卡扎菲次子。在法塔赫大学读工程，后赴奥地利依马德大学与伦敦政治经济学院求学，通阿拉伯语、英语、德语，长期主持卡扎菲国际慈善与发展基金会，在西方以改革面孔出现。\n\n2011 年利比亚内战后被津坦武装俘获，2011 年起遭国际刑事法院以危害人类罪通缉，2015 年被的黎波里法院缺席判处死刑，2017 年获释。2021 年曾登记参加总统选举，2026 年再度成为 4 月大选的候选人。2026 年 2 月 3 日在西北部城市津坦的住所遭四名武装人员枪击身亡，年 53 岁，葬于家族根据地拜尼沃利德。","facts":["伦敦政治经济学院博士，通阿拉伯语、英语、德语","2011 年起被国际刑事法院通缉，2015 年被缺席判死刑","2026 年 2 月 3 日在津坦家中遭四名枪手射杀","死后葬于家族根据地拜尼沃利德老马纳斯拉公墓"],"obit":null,"portrait":null,"source":"Pantheon","verified":"corrected","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Saif_al-Islam_Gaddafi"},{"id":"2026-02-02-044","date":"2026-02-02","name":"袁惟仁","nameOrig":"","country":"中国","region":"台湾","age":57,"fields":["文艺"],"identity":"台湾音乐制作人 · 词曲作者，「凡人二重唱」成员","summary":"《征服》《梦醒了》《旋木》都出自他手，最后八年他躺在台东的床上，歌还在电台里唱。","bio":"1968 年 6 月 24 日生于台湾，早年与莫凡组成「凡人二重唱」，1993、1994 连续两年获金曲奖最佳演唱组奖。转型制作人后为那英写下《征服》《梦一场》，为王菲写《旋木》《执迷不悔》，并担任 S.H.E、动力火车、齐秦、刘若英等人的专辑制作人。2007 至 2010 年任《超级星光大道》评审。\n\n2018 年 10 月在上海因跌倒致脑溢血，手术中发现脑部肿瘤；2020 年在家中再度跌倒，2022 年被医生判定为植物人。2026 年 2 月 2 日在台东家中去世，终年 57 岁，家属称「他走得平静，从此自由」，遗体运回台北与父亲合葬。","facts":["1993、1994 连续两年获金曲奖最佳演唱组奖","为那英写下《征服》《梦一场》，为王菲写《旋木》","2018 年脑溢血后长期卧床，2022 年被判为植物人","S.H.E 曾发行《听袁惟仁弹吉他》向他致意"],"obit":true,"portrait":"assets/portraits/2026-02-02-044.webp","source":"今日头条盘点汇编","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-02-01-043","date":"2026-02-01","name":"丽塔·聚斯穆特","nameOrig":"Rita Süssmuth","country":"德国","region":"","age":88,"fields":["军政"],"identity":"德国基民盟政治家 · 联邦议院首位女议长","summary":"她从家庭部长做到联邦议院议长，把男女平等写进基民盟不愿碰的议程，一干就是十年。","bio":"1937 年 2 月 17 日生于伍珀塔尔，社会学与心理学博士，34 岁起任教育学教授，曾在多特蒙德工业大学任讲座教授。\n\n1985 年进入科尔内阁，出任联邦青年、家庭与卫生部长；1986 年起兼管妇女事务，成为德国首位联邦妇女部长。1987 年至 2002 年为联邦议院议员，1988 年至 1998 年任议长，是这个职位上的第一位女性，任期近十年，在历任议长中排第三。她长期推动男女平等与家庭形象改革，也常因此与自家党团相左。2026 年 2 月 1 日在诺伊斯去世，享年 88 岁。","facts":["1988—1998 年任联邦议院议长，任期近十年","德国首位联邦妇女部长，1986 年起兼管妇女事务","1937 年生于伍珀塔尔，社会学博士，34 岁任教育学教授"],"obit":null,"portrait":"assets/portraits/2026-02-01-043.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Rita_S%C3%BCssmuth"},{"id":"2026-01-31-042","date":"2026-01-31","name":"法特希·卡米尔","nameOrig":"Fathi Kameel","country":"科威特","region":"","age":70,"fields":["体育"],"identity":"科威特足球运动员 · 1980 年亚洲杯冠军成员、前锋","summary":"1980 年亚洲杯冠军、1982 年世界杯阵容里的前锋，科威特人叫他「深色骑士」。","bio":"法特希·卡米尔（全名法特希·卡米尔·马塔尔·马尔祖克）1955 年 5 月 23 日生于科威特城，1971 至 1985 年整个职业生涯都效力于塔达蒙俱乐部，随队夺得 1974 年科威特甲级联赛冠军。因肤色与球风，他被球迷称作「深色骑士」。\n\n1973 至 1984 年他代表科威特国家队出战，1976 年亚洲杯以三球并列最佳射手；1980 年帮助球队夺得亚洲杯冠军，同年参加莫斯科奥运会；1982 年世界杯预选赛他对新西兰攻入一球，助球队首次打进决赛圈，并在西班牙的三场小组赛中全部出场。\n\n2026 年 1 月 31 日，他因长期患病去世，享年 70 岁。","facts":["1980 年随科威特队夺得亚洲杯冠军","1982 年世界杯小组赛三场全部出场","1976 年亚洲杯以 3 球并列最佳射手","职业生涯始终效力塔达蒙俱乐部，1974 年获科威特甲级联赛冠军"],"obit":null,"portrait":null,"source":"Pantheon","verified":"corrected","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Fathi_Kameel"},{"id":"2026-01-28-041","date":"2026-01-28","name":"董韫美","nameOrig":"","country":"中国","region":"中国大陆","age":90,"fields":["科技"],"identity":"中国科学院院士 · 计算机软件事业先驱，BCY 语言研制者","summary":"六十年代他主持做出中国最早的实用高级程序语言 BCY，让国产机器有了自己的编译器。","bio":"董韫美 1936 年 3 月 4 日生于云南昆明，1956 年毕业于东北人民大学（今吉林大学）数学系，同年进入中科院计算技术研究所。1978 至 1980 年赴斯坦福大学访学，1985 年转入中国科学院软件研究所，1993 年当选中国科学院学部委员。\n\n60 年代初，他主持研制出国内最早的实用高级程序语言 BCY，并在 119 机、109 机等机器上实现编译程序。他找到后来被称为「LL 文法」的条件和生成语法矩阵的方法，研制出汉字字形设计系统 CCDS，还实现国内首个可复用软件设计系统。\n\n2026 年 1 月 28 日，他在北京逝世，享年 90 岁。","facts":["主持研制国内最早的实用高级程序语言 BCY","找到后来被国际称为「LL 文法」的条件与语法矩阵生成方法","研制汉字字形设计系统 CCDS，实现国内首个可复用软件设计系统","1993 年当选中国科学院学部委员，2013 年获 CCF 终身成就奖"],"obit":true,"portrait":"assets/portraits/2026-01-28-041.webp","source":"澎湃新闻","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-01-25-040","date":"2026-01-25","name":"李海瓒","nameOrig":"Lee Hae-chan","country":"韩国","region":"","age":73,"fields":["军政"],"identity":"韩国前国务总理 · 共同民主党前党首","summary":"从街头的学生运动到国务总理府，他七次当选议员，最后倒在越南出差的任上。","bio":"李海瓒 1952 年 7 月 10 日生于忠清南道青阳郡，毕业于首尔大学社会学系。1972 年因反对朴正熙「十月维新」投身学生运动，1974 年首次入狱；1980 年又因「金大中内乱阴谋」事件被监禁四年。\n\n1988 年他 36 岁当选国会议员，此后七次当选。1998 年在金大中政府出任教育部长官，2004 年 6 月至 2006 年 3 月任国务总理，后因铁路罢工期间打高尔夫球的丑闻辞职。2018 年他出任共同民主党党首，率党在第 21 届国会选举中拿下 180 席。\n\n1 月 23 日在胡志明市突发心肌梗塞，25 日去世，享年 73 岁。","facts":["2004 年 6 月至 2006 年 3 月任韩国国务总理","七次当选国会议员，1988 年首次当选时为当届最年轻议员","2018 年任共同民主党党首，率党在国会选举中获 180 席","被视作总统李在明的政治导师，身后获追授无穷花章"],"obit":null,"portrait":"assets/portraits/2026-01-25-040.webp","source":"Pantheon","verified":"confirmed","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Lee_Hae-chan"},{"id":"2026-01-25-039","date":"2026-01-25","name":"李未","nameOrig":"","country":"中国","region":"中国大陆","age":82,"fields":["科技"],"identity":"中国科学院院士 · 计算机科学家，北京航空航天大学原校长","summary":"他是大陆第一位在英国拿到计算机科学博士的留学生，后来把北航推向了研究型大学。","bio":"李未 1943 年 6 月生于北京，1961 至 1966 年就读于北京大学数学力学系，1968 年起在北京航空学院（今北京航空航天大学）任教。1979 至 1983 年赴英国爱丁堡大学学习，获计算机科学博士学位，是大陆第一位在英国取得该学位的留学生。\n\n他是国际上最早研究并发程序语言结构操作语义模型的学者之一，在国内率先倡导海量信息计算研究，在国际上提出群体软件工程概念。他创建软件开发环境国家重点实验室并任首届主任。\n\n2002 年 1 月至 2009 年 5 月任北航校长。2026 年 1 月 25 日在北京逝世，享年 82 岁。","facts":["2002 年 1 月至 2009 年 5 月任北京航空航天大学校长","创建软件开发环境国家重点实验室并任首届主任","在国际上提出群体软件工程概念，被列入国家规划","曾任 863 计划专家组副组长、973 计划首席科学家"],"obit":true,"portrait":"assets/portraits/2026-01-25-039.webp","source":"中国科协已故院士名录","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-01-24-038","date":"2026-01-24","name":"戴维·阿布拉菲亚","nameOrig":"David Abulafia","country":"英国","region":"","age":76,"fields":["社科"],"identity":"英国历史学家 · 剑桥大学地中海史荣休教授","summary":"他把地中海写成了一个人的传记，《伟大的海》让英国学术院把奖章挂到他胸前。","bio":"戴维·阿布拉菲亚 1949 年 12 月 12 日生于伦敦特威克纳姆，在剑桥大学国王学院取得博士学位，1974 年起成为冈维尔与凯斯学院研究员，整个学术生涯都在剑桥度过，2003 至 2005 年任历史系主任，2017 年以地中海史荣休教授身份退休。\n\n他研究中世纪地中海的经济、宗教与社会史，尤其关注意大利、西班牙与黎凡特。2011 年出版的《伟大的海：地中海人类史》获英国学术院奖章，2019 年的《无边的海：海洋人类史》获沃尔夫森历史奖。2023 年他获授大英帝国司令勋章。\n\n2026 年 1 月 24 日，他在剑桥去世，享年 76 岁。","facts":["《伟大的海》获英国学术院奖章，《无边的海》获沃尔夫森历史奖","2003 至 2005 年任剑桥大学历史系主任","2023 年获授大英帝国司令勋章（CBE）","英国人文社会科学院与欧洲科学院院士"],"obit":null,"portrait":"assets/portraits/2026-01-24-038.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":null},{"id":"2026-01-24-037","date":"2026-01-24","name":"孙燕","nameOrig":"","country":"中国","region":"中国大陆","age":96,"fields":["医药"],"identity":"中国工程院院士 · 肿瘤内科学主要奠基人与开拓者","summary":"他提出「祛邪—扶正—强化治疗—扶正」的路径，让中国的肿瘤内科从无到有。","bio":"孙燕 1929 年 2 月生于河北乐亭，1956 年毕业于北京协和医学院、获医学博士学位，1959 年进入中国医学科学院肿瘤医院，历任内科主任、新药临床研究中心主任，1999 年当选中国工程院院士。\n\n他是我国肿瘤内科的主要奠基人与开拓者，率先倡导综合治疗理念，在国内最早开展抗肿瘤新药研发与临床转化。他用现代医学方法研究中医药在肿瘤治疗中的作用，提出「祛邪—扶正—强化治疗—扶正」的综合治疗模式，并主持开发贞芪扶正系列产品。\n\n他还是中国临床肿瘤学会（CSCO）发起人之一。2026 年 1 月 24 日在北京逝世，享年 96 岁。","facts":["1999 年当选中国工程院院士","中国临床肿瘤学会（CSCO）发起人之一，编写肿瘤学著作四十余部","提出「祛邪—扶正—强化治疗—扶正」肿瘤综合治疗模式","获国家科学技术进步奖一等奖、中国医师奖"],"obit":true,"portrait":"assets/portraits/2026-01-24-037.webp","source":"中国科协已故院士名录","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-01-20-036","date":"2026-01-20","name":"里法特·阿萨德","nameOrig":"Rifaat al-Assad","country":"叙利亚","region":"","age":88,"fields":["军政"],"identity":"叙利亚前副总统 · 1982 年哈马行动的指挥官","summary":"他被叫作「哈马屠夫」，流亡四十年，最后死在迪拜，始终没等到一场审判。","bio":"里法特·阿萨德 1937 年 8 月 22 日生于叙利亚拉塔基亚省卡尔达哈村，是前总统哈菲兹·阿萨德最小的弟弟。1970 年他协助兄长发动「纠正运动」夺取政权，随后掌管准军事部队「防卫连」。\n\n1982 年他指挥对哈马市穆斯林兄弟会起义的镇压，持续三周的军事行动造成大量平民死亡，各方统计从一万余人到四万余人不等，他因此被外界称为「哈马屠夫」。1984 年他被任命为副总统，同年因趁兄长病重试图夺权失败而流亡，1998 年被解除副总统职务。2020 年法国法院认定他挪用国家资金购置房产，判处四年监禁。\n\n2026 年 1 月，他在迪拜去世，享年 88 岁。","facts":["1984 年至 1998 年任叙利亚副总统","1982 年指挥「防卫连」镇压哈马起义","2020 年被法国法院判处四年监禁并没收在法财产","在瑞士被以战争罪立案，至死未受审"],"obit":null,"portrait":"assets/portraits/2026-01-20-036.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Rifaat_al-Assad"},{"id":"2026-01-19-035","date":"2026-01-19","name":"瓦伦蒂诺·加拉瓦尼","nameOrig":"Valentino Garavani","country":"意大利","region":"","age":93,"fields":["文艺"],"identity":"意大利时装设计师 · 华伦天奴品牌创始人","summary":"他让一种红有了名字——「Valentino 红」，然后让整个好莱坞穿上了它。","bio":"瓦伦蒂诺·加拉瓦尼 1932 年 5 月生于意大利帕维亚省沃盖拉，少年时移居巴黎，在巴黎时装公会学习，先后师从雅克·法斯、巴伦夏嘉、让·德赛与居伊·拉罗什。\n\n1959 年他开设自己的时装屋，1960 年与詹卡洛·贾梅蒂在罗马共同创立华伦天奴公司。受西班牙之旅启发，他做出招牌的「华伦天奴红」与「嘉年华礼服」，1970 年成为首位在纽约开设专卖店的意大利设计师，把意大利手工艺、法国高级定制与美国成衣缝在一起。\n\n2008 年他退休，谢幕时所有模特身着红裙。2026 年 1 月 19 日在罗马家中去世，享年 93 岁。","facts":["1960 年与詹卡洛·贾梅蒂共同创立华伦天奴品牌","1970 年成为首位在纽约开店的意大利时装设计师","创造招牌色「Valentino 红」，2008 年退休","2000 年获美国时装设计师协会终身成就奖"],"obit":null,"portrait":"assets/portraits/2026-01-19-035.webp","source":"Pantheon","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-01-19-034","date":"2026-01-19","name":"杨振华","nameOrig":"","country":"中国","region":"中国大陆","age":90,"fields":["文艺"],"identity":"相声表演艺术家 · 「沈阳相声」非遗代表性传承人","summary":"《假大空》让他在 1978 年拿了一等奖，也把讽刺重新放回了相声的台面上。","bio":"杨振华 1936 年生于辽宁沈阳，1953 年从沈阳铁路中学毕业，当过交警大队的民警和文书。1957 年他拜杨海荃为师，1962 年进入沈阳铁西区曲艺团任相声队队长，1966 年转入沈阳市曲艺团。\n\n1978 年他表演的《假大空》获文化部庆祝建国三十年献礼演出创作、表演一等奖。1981 年他到张家口组建「杨振华相声艺术团」，以传统相声为底首创「吉他相声」。他的段子以讽刺见长，《下棋》《动物世界》《你以为你是谁》通过广播电视流传甚广。\n\n2014 年他获第八届中国曲艺牡丹奖终身成就奖。2026 年 1 月 19 日在沈阳逝世，享年 90 岁。","facts":["1978 年《假大空》获文化部创作、表演一等奖","2014 年获第八届中国曲艺牡丹奖终身成就奖","以传统相声为底首创「吉他相声」","晚年仍在沈阳小剧场带徒，说演到演不动为止"],"obit":true,"portrait":"assets/portraits/2026-01-19-034.webp","source":"维基百科逝世人物列表","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-01-19-033","date":"2026-01-19","name":"丁国瑜","nameOrig":"","country":"中国","region":"中国大陆","age":95,"fields":["科技"],"identity":"中国科学院院士 · 新构造与地震构造学奠基人、国家地震局原副局长","summary":"邢台、海城、龙陵，每一次大地震的现场都有他；他给中国的地壳画出了一张破裂网络。","bio":"丁国瑜 1931 年 9 月生于河北高阳，1952 年毕业于北京大学地质学系，同年进入北京地质学院任教，1955 至 1959 年在苏联莫斯科地质勘探学院攻读副博士，师从新构造学奠基人尼古拉耶夫。\n\n1970 年他调入中央地震工作办公室震情分析组，此后一直在国家地震系统工作，1981 年起任国家地震局副局长。他提出中国地壳现代破裂网络与地震活动关系模型，编制首幅中国活断层滑动速率图，还曾任坦赞铁路工程建设地震工作专家组组长。\n\n1980 年当选中国科学院学部委员。2026 年 1 月 19 日在北京逝世，享年 95 岁。","facts":["1981 年起任国家地震局副局长，曾任中国地震学会理事长","编制首幅中国活断层滑动速率图与现代板内运动图","曾任坦赞铁路工程建设地震工作专家组组长","获国家科技进步奖二等奖、何梁何利科学与技术进步奖"],"obit":true,"portrait":"assets/portraits/2026-01-19-033.webp","source":"中国科协已故院士名录","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-01-18-032","date":"2026-01-18","name":"梁栋材","nameOrig":"","country":"中国","region":"中国大陆","age":94,"fields":["科技"],"identity":"中国科学院院士 · 分子生物物理学家、蛋白质晶体学开拓者","summary":"他带着一群人在原子尺度上给猪胰岛素画出了中国第一张结构图，一步跨进国际第一梯队。","bio":"梁栋材 1932 年 5 月 29 日生于广东广州，1955 年毕业于中山大学化学系，1956 至 1960 年在苏联科学院元素有机化合物研究所留学，1965 年赴牛津大学，师从诺贝尔奖得主霍奇金学习蛋白质晶体学。\n\n60 年代初他测定一批有机物晶体结构，并建立我国首个晶体结构分析计算程序库；60 年代末作为负责人之一参与完成猪胰岛素结构测定，测出 2.5 埃分辨率结构，后又把精度推到 1.2 埃。1983 年任中国科学院生物物理研究所所长。\n\n他是中共十二届中央候补委员、第十三、十四届中央委员。2026 年 1 月 18 日在北京逝世，享年 94 岁。","facts":["曾任中国共产党第十三届、第十四届中央委员会委员","牵头测定 2.5 埃分辨率猪胰岛素晶体结构","1983 年任中国科学院生物物理研究所所长","获国家自然科学奖二等奖、何梁何利科学与技术进步奖"],"obit":true,"portrait":"assets/portraits/2026-01-18-032.webp","source":"中国科协已故院士名录","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-01-17-031","date":"2026-01-17","name":"龚知本","nameOrig":"","country":"中国","region":"中国大陆","age":91,"fields":["科技"],"identity":"中国工程院院士 · 大气光学及应用研究开创者","summary":"他把激光在大气湍流里跑偏的误差，从几十微弧度压到 1 微弧度以内。","bio":"龚知本 1935 年 12 月 28 日生于江苏太仓，1960 年参加工作，先后在中国科学院地球物理所、大气物理所从事研究，1971 年进入安徽光学精密机械研究所筹建大气光学研究室，此后五十余年扎根科学岛。\n\n他是我国大气光学及其应用研究的开创者。他带领团队建成激光大气传输及相位校正实验系统，把无校正时几十微弧度的激光跟踪误差降到小于 1 微弧度；牵头研制出我国第一台 L625 大气探测激光雷达等设备；创建具有国际先进水平的合肥激光试验场。\n\n他曾任安徽光机所所长，2003 年当选中国工程院院士。2026 年 1 月 17 日在合肥逝世，享年 91 岁。","facts":["2003 年当选中国工程院院士，曾任安徽光机所所长","创建具有国际先进水平的合肥激光试验场","牵头研制我国第一台 L625 大气探测激光雷达","获三项全国科学大会奖、三项国家科技进步二等奖"],"obit":true,"portrait":"assets/portraits/2026-01-17-031.webp","source":"中国科协已故院士名录","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-01-17-030","date":"2026-01-17","name":"魏宝文","nameOrig":"","country":"中国","region":"中国大陆","age":91,"fields":["科技"],"identity":"中国科学院院士 · 重离子加速器事业奠基人、核物理学家","summary":"他带人建成了中国第一台大型重离子加速器，让兰州在世界核物理的地图上有了坐标。","bio":"魏宝文 1935 年 11 月生于河南禹州，1957 年毕业于北京大学核物理专业，1958 年调往兰州物理研究室，即后来的中国科学院近代物理研究所，师从杨澄中。\n\n60 年代他带队耗时五年完成 2 至 9 兆电子伏单能中子源研制，以及 9 至 12 兆电子伏中子对锂－6、锂－7 的非弹性碰撞截面测量，澄清了各国数据分歧。此后他领导建成我国第一台大型重离子加速器，提出续建重离子冷却储存环构想。1986 至 1994 年任近代物理所所长，1995 年当选中国科学院院士。\n\n晚年推动重离子肿瘤治疗研究。2026 年 1 月 17 日在兰州逝世，享年 91 岁。","facts":["我国第一台重离子加速器大科学装置工程总工程师","1995 年当选中国科学院院士，曾任近代物理所所长、兰州分院院长","完成 9-12MeV 中子对锂的非弹性碰撞截面测量","推动首台重离子治疗示范装置建设，获国家科技进步一等奖"],"obit":true,"portrait":"assets/portraits/2026-01-17-030.webp","source":"中国科协已故院士名录","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-01-17-029","date":"2026-01-17","name":"罗杰·艾勒斯","nameOrig":"Roger Allers","country":"美国","region":"","age":76,"fields":["影视"],"identity":"美国动画导演 · 《狮子王》联合导演","summary":"1994 年他把《哈姆雷特》搬进非洲草原，一句「Hakuna Matata」传唱三十年。","bio":"罗杰·艾勒斯 1949 年 6 月 29 日生于纽约州拉伊，在亚利桑那州斯科茨代尔长大，毕业于亚利桑那州立大学美术系。早年他在 Lisberger 工作室参与《芝麻街》，1986 年加入迪士尼。\n\n他在《小美人鱼》《美女与野兽》《阿拉丁》中担任故事板画师与故事总监。1994 年与罗伯·明科夫联合执导《狮子王》，这是他的导演处女作，也是当年全球票房最高的电影。2006 年执导《丛林大反攻》，2007 年短片《卖火柴的小女孩》获奥斯卡提名。\n\n2026 年 1 月 17 日，他在家中因病去世，终年 76 岁。","facts":["1994 年与罗伯·明科夫联合执导《狮子王》","参与《美女与野兽》《阿拉丁》《小美人鱼》故事创作","2006 年执导索尼首部动画长片《丛林大反攻》","2007 年短片《卖火柴的小女孩》获奥斯卡提名"],"obit":null,"portrait":"assets/portraits/2026-01-17-029.webp","source":"Pantheon","verified":"confirmed","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Roger_Allers"},{"id":"2026-01-17-028","date":"2026-01-17","name":"格拉迪斯·韦斯特","nameOrig":"Gladys West","country":"美国","region":"","age":95,"fields":["科技"],"identity":"美国数学家 · GPS 卫星测地模型的奠基者之一","summary":"她在海军实验室里算出地球的形状，半个世纪后，全世界的手机都用这份答案找路。","bio":"格拉迪斯·韦斯特 1930 年 10 月 27 日生于弗吉尼亚州萨瑟兰的佃农社区，靠奖学金进入弗吉尼亚州立学院，1952 年获数学学士、1955 年获硕士。\n\n1956 年她进入美国海军达尔格伦试验场任数学家，是那里第四位黑人雇员。她参与海军军械研究计算机项目，1978 年担任海洋监视卫星 Seasat 的项目经理，其后主持 GEOSAT 卫星的计算机模型，通过分析地球重力场与潮汐建立精确的大地水准面模型，为 GPS 提供了定位基础。\n\n1998 年退休后她继续深造，2000 年获弗吉尼亚理工博士。2026 年 1 月 17 日去世，享年 95 岁。","facts":["1956 年入职美国海军达尔格伦试验场，为该处第四位黑人雇员","1978 年任海洋监视卫星 Seasat 项目经理，主持 GEOSAT 计算模型","2000 年以 70 岁之龄获弗吉尼亚理工博士学位","2018 年入选美国空军太空与导弹先驱名人堂"],"obit":null,"portrait":"assets/portraits/2026-01-17-028.webp","source":"Pantheon","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-01-16-027","date":"2026-01-16","name":"路易莎·迪奥戈","nameOrig":"Luísa Diogo","country":"莫桑比克","region":"","age":67,"fields":["军政"],"identity":"莫桑比克前总理 · 该国首位女性政府首脑","summary":"2004 年她成为莫桑比克第一位女总理，把这个国家的财政从一堆烂账里一点点理了出来。","bio":"路易莎·迪奥戈 1958 年 4 月 11 日生于莫桑比克太特省马戈埃区。1983 年毕业于蒙德拉内大学经济系，1992 年获伦敦大学亚非学院金融经济硕士学位。1980 年她还是学生时就进入财政部，1989 年升任国家预算局局长。\n\n1999 年她出任计划与财政部长，2004 年 2 月被任命为总理兼计划与财政部长，成为该国首位女总理，2005 年连任，2010 年 1 月卸任，任内推行税制与公共财政改革。\n\n卸任后她曾任世界银行执行董事、贝卢拉内工业园总裁。2026 年 1 月 16 日在葡萄牙病逝，享年 67 岁，莫桑比克政府宣布两天国丧。","facts":["2004 年 2 月至 2010 年 1 月任莫桑比克总理，为该国首位女总理","1999 年至 2005 年任计划与财政部长","毕业于伦敦大学亚非学院，获金融经济硕士","卸任后曾任世界银行执行董事、贝卢拉内工业园总裁"],"obit":null,"portrait":"assets/portraits/2026-01-16-027.webp","source":"Pantheon","verified":"confirmed","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Lu%C3%ADsa_Diogo"},{"id":"2026-01-15-026","date":"2026-01-15","name":"陶玉玲","nameOrig":"","country":"中国","region":"中国大陆","age":91,"fields":["文艺"],"identity":"电影表演艺术家 · 「二妹子」与「春妮」的扮演者，八一厂演员剧团原团长","summary":"《柳堡的故事》里那个梳麻花辫的「二妹子」，让一首《九九艳阳天》唱了快七十年。","bio":"陶玉玲 1934 年 10 月生于江苏镇江，1949 年考入华东军政大学文艺系，1952 年分配到华东军区艺术剧院任演员，长期在南京军区前线话剧团工作。\n\n1957 年她在《柳堡的故事》中饰演二妹子，一夜之间家喻户晓；1964 年在《霓虹灯下的哨兵》里演春妮。1978 年调入八一电影制片厂，历任演员、故事片室副主任、演员剧团团长，参演过《二泉映月》《任长霞》等片。她抗癌三十余年，先后患五种癌症。\n\n2015 年获百花奖终身成就奖，2016 年获金鸡奖终身成就奖。2026 年 1 月 15 日在北京逝世，享年 91 岁。","facts":["1957 年《柳堡的故事》饰二妹子，1964 年《霓虹灯下的哨兵》饰春妮","曾任八一电影制片厂故事片室副主任兼演员剧团团长","2015 年获百花奖终身成就奖，2016 年获金鸡奖终身成就奖","生前抗癌三十余年，先后罹患五种癌症"],"obit":true,"portrait":"assets/portraits/2026-01-15-026.webp","source":"维基百科逝世人物列表","verified":"corrected","causeOfDeath":null,"wikipedia":null},{"id":"2026-01-15-025","date":"2026-01-15","name":"希腊与丹麦的伊莲妮公主","nameOrig":"Princess Irene of Greece and Denmark","country":"希腊","region":"","age":83,"fields":["军政"],"identity":"希腊-丹麦公主 · 西班牙王后索菲娅之妹、钢琴演奏者","summary":"生在开普敦的流亡路上，终身未嫁，最后在姐姐的马德里王宫里安静走完八十三年。","bio":"伊莲妮 1942 年 5 月 11 日生于南非开普敦。父母保罗王储与弗雷德里卡因纳粹入侵希腊流亡在外，1946 年王室返回雅典，次年父亲即位为保罗一世。她是西班牙王后索菲娅的妹妹、希腊末代国王康斯坦丁二世的姐姐。\n\n1967 年军政府政变后王室再度流亡，她与母亲前往印度修习冥想与瑜伽。1981 年起她定居西班牙，2018 年取得西班牙国籍，创办世界和谐基金会，把欧盟的富余食品转赠发展中国家。\n\n她终身未婚、无子女。2026 年 1 月 15 日在马德里萨苏埃拉宫去世，享年 83 岁。","facts":["1942 年 5 月 11 日生于南非开普敦，是保罗一世最小的女儿","2018 年取得西班牙国籍，定居马德里萨苏埃拉宫逾四十年","创办世界和谐基金会，把欧盟余粮转赠发展中国家","终身未婚无子女，葬礼于 2026 年 1 月 19 日在雅典举行"],"obit":null,"portrait":null,"source":"Pantheon","verified":"corrected","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Princess_Irene_of_Greece_and_Denmark"},{"id":"2026-01-14-024","date":"2026-01-14","name":"聂卫平","nameOrig":"","country":"中国","region":"中国大陆","age":74,"fields":["体育"],"identity":"围棋九段 · 「棋圣」称号获得者，中国围棋协会名誉主席","summary":"前三届中日围棋擂台赛十一连胜，他把「聂旋风」刮成了一个国家的集体记忆。","bio":"聂卫平 1952 年 8 月生于辽宁沈阳，籍贯河北深州，1973 年入选国家围棋集训队，1982 年被授予九段，职业生涯六次夺得全国个人赛冠军。\n\n1984 至 1987 年前三届中日围棋擂台赛，他作为主将连续击败多位日本超一流棋手，创下十一连胜，三度率队夺冠，1988 年被授予「棋圣」称号。1989 年首届应氏杯决赛他以 2 比 3 负于曹薰铉，与世界冠军擦肩。\n\n退役后他任国家围棋队总教练，培养出常昊等世界冠军，1999 年创办聂卫平围棋道场。2013 年确诊直肠癌，术后仍活跃于棋坛与解说。2026 年 1 月 14 日在北京逝世，享年 74 岁。","facts":["1988 年被授予「棋圣」称号，六次获全国个人赛冠军","前三届中日围棋擂台赛创下 11 连胜","1999 年创办聂卫平围棋道场，培养出柯洁等棋手","2013 年确诊直肠癌，术后仍参与围棋推广"],"obit":true,"portrait":"assets/portraits/2026-01-14-024.webp","source":"多家媒体","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-01-14-023","date":"2026-01-14","name":"梁小龙","nameOrig":"","country":"中国","region":"香港","age":75,"fields":["影视"],"identity":"香港武打演员 · 「陈真」与「火云邪神」的扮演者","summary":"他先演了最早的陈真，又在《功夫》里做火云邪神，一句「天下武功，唯快不破」传了二十年。","bio":"梁小龙 15 岁以替身入行，1972 年在街头打架时被吴思远看中进入演艺圈。1981 年《大侠霍元甲》、1982 年《陈真》里他演霍元甲的徒弟陈真，剧集引进内地后风靡一时，与李小龙、成龙、狄龙并称「四小龙」。\n\n80 年代末他息影赴内地经商，十几年后受周星驰三次邀约复出，在 2004 年《功夫》中出演「火云邪神」，那句「天下武功，唯快不破」成了影迷口头禅。\n\n2026 年 1 月 14 日下午 4 时，他因心脏衰竭离世。家属委托香港动作特技演员公会公告，澄清他生于 1951 年 8 月 9 日、祖籍广东顺德，享年 75 岁，并非流传的 77 岁。","facts":["1981 年《大侠霍元甲》、1982 年《陈真》中饰演陈真","2004 年在周星驰电影《功夫》中饰「火云邪神」","死因为心脏衰竭，抢救约六小时后不治","家属澄清实际生于 1951 年，非百科所记的 1948 年"],"obit":true,"portrait":null,"source":"多家媒体","verified":"confirmed","portraitStatus":"no-source","causeOfDeath":"心脏衰竭","wikipedia":null},{"id":"2026-01-14-022","date":"2026-01-14","name":"左铁镛","nameOrig":"","country":"中国","region":"中国大陆","age":90,"fields":["科技"],"identity":"中国工程院院士 · 材料与循环经济专家、北京工业大学原校长","summary":"他创建了全国第一个「资源环境与循环经济」交叉学科，把材料学带进了循环经济的语境里。","bio":"左铁镛 1936 年 9 月生于北京，籍贯辽宁铁岭，1958 年从东北工学院毕业，此后在中南工业大学任教三十余年，历任教授、副校长，1991 至 1996 年任国家教委科技司司长，1996 年回到高校出任北京工业大学校长。\n\n他研究难熔金属材料、稀土功能材料与铝镁合金加工，上世纪 90 年代率先开拓生态环境材料方向，倡导以节约资源为核心的循环经济研究，创建了全国首个「资源环境与循环经济」交叉学科。1995 年当选中国工程院院士。任北工大校长期间，学校进入「211 工程」。\n\n2026 年 1 月 14 日，他在北京病逝，享年 90 岁。","facts":["1995 年当选中国工程院院士","曾任中南工业大学副校长、国家教委科技司司长、中国科协副主席","创建全国首个「资源环境与循环经济」交叉学科","获国家技术发明奖二等奖、光华工程科技奖"],"obit":true,"portrait":"assets/portraits/2026-01-14-022.webp","source":"中国科协已故院士名录","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-01-13-021","date":"2026-01-13","name":"斯科特·亚当斯","nameOrig":"Scott Adams","country":"美国","region":"","age":68,"fields":["文艺"],"identity":"美国漫画家 · 《呆伯特》作者","summary":"他把格子间里的荒唐画成一条漫画，两千家报纸连载；2023 年那些报纸又一起把它撤了。","bio":"1957 年 6 月 8 日生于纽约州温德姆，哈威特学院经济学学士、加州大学伯克利分校 MBA，在太平洋贝尔等公司做了十七年白领。他一边上班一边清晨起来画漫画，1989 年《呆伯特》开始由报业辛迪加发行。\n\n漫画主角是一个系歪领带的工程师，被无能上司和荒唐制度围困，成了九十年代办公室文化的共同语言，最高峰时在 65 个国家、两千多家报纸连载，衍生出二十多本书。\n\n2023 年他因在视频节目里发表种族主义言论，多家报纸与发行商宣布停载。2025 年 5 月他公开患转移性前列腺癌，2026 年 1 月 13 日在加州普莱森顿家中去世，享年 68 岁。","facts":["1989 年开始连载《呆伯特》，最高峰逾两千家报纸","衍生著作二十余本，两本登《纽约时报》畅销榜首","2023 年因种族主义言论被多家报纸停载","2025 年 5 月公开患转移性前列腺癌"],"obit":null,"portrait":"assets/portraits/2026-01-13-021.webp","source":"Pantheon","verified":"confirmed","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Scott_Adams_(American_football)"},{"id":"2026-01-13-020","date":"2026-01-13","name":"彼得·杜斯伯格","nameOrig":"Peter Duesberg","country":"德国","region":"","age":89,"fields":["科技"],"identity":"德裔美国分子生物学家 · 首个癌基因发现者，后成艾滋病否认论代表","summary":"他先找到了第一个癌基因，后来用三十年坚称 HIV 不致病，两件事都写进了教科书。","bio":"1936 年 12 月 2 日生于德国明斯特，在法兰克福大学取得博士学位，1960 年代到加州大学伯克利分校任教。1970 年他与彼得·沃格特在劳氏肉瘤病毒中发现 Src 基因，这是人类找到的第一个癌基因，1986 年他当选美国国家科学院院士。\n\n1987 年起他公开主张 HIV 并不导致艾滋病，认为抗病毒药物比疾病本身更危险。这套说法被学界反复否定，却影响了南非等地的公共卫生政策，他的后半生也从荣誉转向争议。\n\n2026 年 1 月 13 日，他因肾衰竭在加州拉法耶特去世，享年 89 岁。","facts":["1970 年与沃格特发现首个癌基因 Src","1986 年当选美国国家科学院院士","1987 年起公开主张 HIV 不导致艾滋病","2026 年 1 月 13 日因肾衰竭去世"],"obit":null,"portrait":"assets/portraits/2026-01-13-020.webp","source":"Pantheon","verified":"corrected","causeOfDeath":"肾衰竭","wikipedia":"https://en.wikipedia.org/wiki/Peter_Duesberg"},{"id":"2026-01-13-019","date":"2026-01-13","name":"克劳德特·科尔文","nameOrig":"Claudette Colvin","country":"美国","region":"","age":86,"fields":["军政"],"identity":"美国民权运动先驱 · 15 岁拒绝在蒙哥马利公交车上让座","summary":"1955 年 3 月，15 岁的她说了一句「这是我的宪法权利」，然后被警察从车上拖走。","bio":"1939 年 9 月 5 日生于阿拉巴马州伯明翰，在蒙哥马利长大。1955 年 3 月 2 日，15 岁的她在放学回家的公交车上被要求给一名白人乘客让座，她拒绝了，被警察强行带下车逮捕——这比罗莎·帕克斯早了九个月。\n\n她成为「布劳德诉盖尔」案的四名原告之一，1956 年联邦法院据此裁定公交种族隔离违宪。但民权组织认为她太年轻、家庭状况不适合做运动的门面，她的名字因此长期被略过。\n\n1969 年起她在曼哈顿一家护理院做护理助理，一做三十五年。2021 年她的少年案底被撤销。2026 年 1 月 13 日她在得克萨斯州去世，享年 86 岁。","facts":["1955 年 3 月 2 日被捕，比罗莎·帕克斯早九个月","是「布劳德诉盖尔」案四名原告之一","在曼哈顿做护理助理三十五年，2004 年退休","2021 年她的少年案底获法院撤销"],"obit":null,"portrait":"assets/portraits/2026-01-13-019.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Claudette_Colvin"},{"id":"2026-01-11-018","date":"2026-01-11","name":"路易斯·布鲁斯","nameOrig":"Louis E. Brus","country":"美国","region":"","age":82,"fields":["科技"],"identity":"美国化学家 · 量子点发现者、2023 年诺贝尔化学奖得主","summary":"1983 年他把一瓶硫化镉溶液忘在台面上，第二天发现晶体变了颜色——量子点就此出现。","bio":"1943 年 8 月 10 日生于俄亥俄州克利夫兰，在莱斯大学读完本科，后在哥伦比亚大学取得博士，先后在海军研究实验室和贝尔实验室工作，1996 年起回到哥伦比亚大学任化学教授。\n\n1983 年他在贝尔实验室研究半导体表面的化学反应，把硫化镉微粒分散在溶液里，隔夜发现晶体略微长大、吸收的光也变了波长。顺着这个偶然现象，他发现粒子越小发出的光越偏蓝，这类胶体半导体纳米晶后来被称作量子点。\n\n2023 年他与阿列克谢·埃基莫夫、蒙吉·巴文迪共同获得诺贝尔化学奖。2026 年 1 月 11 日他在纽约州哈德逊河畔黑斯廷斯的家中去世，享年 82 岁。","facts":["1983 年在贝尔实验室偶然发现胶体半导体纳米晶","2023 年与埃基莫夫、巴文迪共获诺贝尔化学奖","曾任哥伦比亚大学化学教授，此前在贝尔实验室工作"],"obit":null,"portrait":"assets/portraits/2026-01-11-018.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Louis_E._Brus"},{"id":"2026-01-10-017","date":"2026-01-10","name":"鲍勃·威尔","nameOrig":"Bob Weir","country":"美国","region":"","age":78,"fields":["文艺"],"identity":"美国音乐人 · 感恩而死乐队创始吉他手","summary":"十七岁那年他抱着吉他加入一支还叫「术士」的乐队，此后六十年没有真正下台。","bio":"1947 年 10 月 16 日生于旧金山，被 Weir 家收养，在湾区长大。17 岁他辍学加入杰里·加西亚领的乐队，1965 年这支乐队变成感恩而死，他是创始成员里最年轻的一个。\n\n他写或合写了《Sugar Magnolia》《Truckin'》等曲目。加西亚 1995 年去世后，他继续以 RatDog、Furthur、Dead & Company 的名义巡演。\n\n2025 年 7 月他确诊癌症，8 月仍在金门公园与 Dead & Company 连开三场告别演出。2026 年 1 月 10 日他因癌症引发的肺部问题在加州米尔谷去世，享年 78 岁。","facts":["1965 年参与创立感恩而死，任吉他手与主唱","合写《Sugar Magnolia》《Truckin'》等曲目","2024 年获肯尼迪中心荣誉奖","2025 年 8 月在金门公园举行三场告别演出"],"obit":null,"portrait":"assets/portraits/2026-01-10-017.webp","source":"Pantheon","verified":"corrected","causeOfDeath":"癌症","wikipedia":"https://en.wikipedia.org/wiki/Bob_Weir"},{"id":"2026-01-10-016","date":"2026-01-10","name":"赵学煌","nameOrig":"","country":"中国","region":"台湾","age":69,"fields":["影视"],"identity":"台湾演员 · 琼瑶剧里的「父亲专业户」","summary":"车祸之后他在轮椅上又演了一个瘫痪父亲，那部戏让他第一次入围金钟奖。","bio":"1956 年 12 月 27 日生于澎湖，在眷村长大。1980 年他以《摘星梦》出道，1984 年在《一剪梅》里演哑仆福星，1990 年代因琼瑶剧《望夫崖》《鬼丈夫》走红，演的多是儒雅的父亲。\n\n2000 年 6 月，他在北京拍《双面情人》期间遭遇车祸，颈椎第 5、6 节断裂，胸部以下永久瘫痪。2005 年他应导演梁修身之邀复出，在《再见，忠贞二村》里演一位瘫痪的退役连长，全程轮椅出演且不用替身，凭此入围第 40 届金钟奖最佳男主角。\n\n2025 年 11 月底他因泌尿系统感染并发脑炎住进加护病房，2026 年 1 月 10 日凌晨去世，享年 69 岁。","facts":["1990 年代凭琼瑶剧《望夫崖》《鬼丈夫》走红","2000 年车祸致颈椎断裂、胸部以下瘫痪","2005 年轮椅出演《再见，忠贞二村》入围第 40 届金钟奖"],"obit":true,"portrait":"assets/portraits/2026-01-10-016.webp","source":"维基百科逝世人物列表","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-01-10-015","date":"2026-01-10","name":"埃里希·冯·丹尼肯","nameOrig":"Erich von Däniken","country":"瑞士","region":"","age":90,"fields":["文艺"],"identity":"瑞士作家 · 《众神的战车》作者，古代外星人说法的推销者","summary":"1968 年他写下一句「也许是外星人干的」，六十年里卖出数千万册，也惹恼了整门考古学。","bio":"1935 年 4 月 14 日生于瑞士阿尔高州措芬根，在弗里堡的耶稣会寄宿学校读书，19 岁离校后做过侍者、酒保和达沃斯的酒店经理，没受过任何考古或历史训练。\n\n1968 年他的第一本书《众神的战车？》出版，主张远古文明的技术来自外星访客，金字塔、印加遗迹和洞穴壁画都被他当作证据。书被译成三十多种语言、卖出数千万册，他此后写了数十本续作，还在瑞士因特拉肯参与创办神秘公园。考古学界与科学家长期批评他的论证是拼凑与误读，但这套说法已经进入流行文化的底层。\n\n2026 年 1 月 10 日他在瑞士乌恩特塞恩的医院去世，享年 90 岁。","facts":["1968 年《众神的战车？》出版，译成三十余种语言","著作全球销量数千万册，续作数十本","在瑞士因特拉肯参与创办神秘公园"],"obit":null,"portrait":"assets/portraits/2026-01-10-015.webp","source":"Pantheon","verified":"confirmed","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Erich_von_D%C3%A4niken"},{"id":"2026-01-09-014","date":"2026-01-09","name":"汉斯·赫尔曼","nameOrig":"Hans Herrmann","country":"德国","region":"","age":97,"fields":["体育"],"identity":"德国赛车手 · 1970 年为保时捷夺得首个勒芒全场冠军","summary":"一个学出来的糕点师，1970 年在勒芒替保时捷捧回第一个全场冠军，然后就此收车。","bio":"1928 年 2 月 23 日生于斯图加特，学的是糕点师，本打算接手母亲的咖啡馆。1952 年他驾一辆保时捷 356 在纽博格林第一次上场就赢了，1953 年成为德国跑车冠军，随后进入奔驰厂队。\n\n他在 1953 至 1962 年间参加 19 场 F1 分站，一次登上领奖台；耐力赛才是他的主场，职业生涯拿下 80 多场全场与组别冠军，绝大多数是为保时捷。\n\n1970 年他与理查德·阿特伍德驾驶 917 K 拿下勒芒 24 小时全场冠军，这是保时捷的第一个勒芒总冠军，也是他的最后一场比赛。2026 年 1 月 9 日他去世，享年 97 岁。","facts":["1970 年与阿特伍德驾 917 K 夺勒芒 24 小时全场冠军","职业生涯逾 80 场全场与组别冠军","1953 年德国跑车冠军，19 场 F1 分站一次登台"],"obit":null,"portrait":null,"source":"Pantheon","verified":"corrected","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Hans_Herrmann"},{"id":"2026-01-09-013","date":"2026-01-09","name":"T·K·卡特","nameOrig":"T. K. Carter","country":"美国","region":"","age":69,"fields":["影视"],"identity":"美国演员 · 《怪形》里踩着轮滑的厨子 Nauls","summary":"《怪形》里那个踩着轮滑、拎着菜刀的厨子，在片场外演了六十年配角。","bio":"1956 年 12 月 18 日生于纽约，在加州长大，12 岁开始说单口喜剧。1970 年代他从小屏幕起步，演过《好时光》《杰斐逊一家》，1982 年在约翰·卡朋特《怪形》里演踩着轮滑的厨子 Nauls。\n\n此后他在《暴走列车》《多米诺》这类片子里辗转，小屏幕上是《Punky Brewster》《The Sinbad Show》《Moesha》的常客；1996 年为《空中大灌篮》配音，2000 年在《The Corner》里演一个吸毒者。\n\n2026 年 1 月 9 日他被发现死于加州杜阿尔特家中，享年 69 岁，警方称无可疑之处，死因未公布。","facts":["1982 年在约翰·卡朋特《怪形》中饰演厨子 Nauls","1996 年为《空中大灌篮》担任配音","1970 年代凭《好时光》《杰斐逊一家》起步，从艺逾五十年"],"obit":null,"portrait":"assets/portraits/2026-01-09-013.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/T._K._Carter"},{"id":"2026-01-08-012","date":"2026-01-08","name":"简水生","nameOrig":"","country":"中国","region":"中国大陆","age":97,"fields":["科技"],"identity":"中国科学院院士 · 中国光纤通信主要奠基人","summary":"他建了 JN 函数和 IK 函数，把贝塞尔函数补齐一角，也把中国光纤通信从零拉起。","bio":"1929 年 10 月 25 日生于江西萍乡。1950 年考入北京铁道学院（今北京交通大学），1957 年赴莫斯科电信工程学院读研，1960 年回国任教，1987 年创建北方交通大学光波技术研究所并任所长。\n\n他首创「消除螺旋效应的屏蔽理论」和「准均匀铠装防护方法」，建立 JN 与 IK 函数，丰富了贝塞尔函数理论；研制出小同轴电缆、系列石英传像光纤、偏振保持单模光纤等；把漏泄波导综合光缆用于列车定位。\n\n在国际上他首次提出光路交换总体构思。1995 年当选中国科学院院士。2026 年 1 月 8 日他在北京逝世，享年 97 岁。","facts":["建立 JN 与 IK 函数，丰富贝塞尔函数理论","创建北方交通大学光波技术研究所并任所长","研制出中国第一根偏振保持单模光纤","1995 年当选中国科学院院士"],"obit":true,"portrait":"assets/portraits/2026-01-08-012.webp","source":"中国科协已故院士名录","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-01-07-011","date":"2026-01-07","name":"格伦·霍尔","nameOrig":"Glenn Hall","country":"加拿大","region":"","age":94,"fields":["体育"],"identity":"加拿大冰球守门员 · NHL 传奇「Mr. Goalie」","summary":"他从 1955 年到 1962 年连续首发 502 场，中间一次没歇，而且始终不戴面罩。","bio":"1931 年 10 月 3 日生于萨斯喀彻温省洪堡，1952 年起为底特律红翼、芝加哥黑鹰、圣路易斯蓝调效力 18 个赛季。1955 年 10 月到 1962 年 11 月，他连续首发 502 场常规赛，这个纪录至今无人接近，而他从头到尾不戴面罩。\n\n他是蝴蝶式守门技术的先驱，三次获得 Vezina 奖，1961 年助黑鹰夺得斯坦利杯。冰球圈的旧话说他每场比赛前都会呕吐，然后喝一杯橙汁上场。\n\n1973 年他入选冰球名人堂，退役后在卡尔加里火焰任守门教练，1989 年随队再夺一座斯坦利杯。2026 年 1 月 7 日他在斯托尼普莱恩的医院去世，享年 94 岁。","facts":["1955 至 1962 年连续首发 502 场，创 NHL 纪录","三次获 Vezina 奖，1961 年随黑鹰夺斯坦利杯","生涯始终不戴面罩，1973 年入选冰球名人堂"],"obit":null,"portrait":null,"source":"Pantheon","verified":"corrected","portraitStatus":"no-source","causeOfDeath":null},{"id":"2026-01-06-010","date":"2026-01-06","name":"贝拉·塔尔","nameOrig":"Béla Tarr","country":"匈牙利","region":"","age":70,"fields":["影视"],"identity":"匈牙利电影导演 · 长镜头与「慢电影」的代表人物","summary":"他用七个半小时的黑白长镜头拍完《撒旦探戈》，把电影拖回时间本身。","bio":"1955 年 7 月 21 日生于匈牙利佩奇。16 岁他用超 8 毫米摄影机拍了一部关于吉普赛人的纪录片，1977 年以《家庭公寓》开始执导，1982 年《积木人生》获洛迦诺电影节特别提及。\n\n1988 年的《诅咒》让他进入国际视野，也确立了他与作家克拉斯纳霍尔凯的长期合作。1994 年《撒旦探戈》问世，七个半小时的黑白长镜头被视为 1990 年代最重要的影片之一；2011 年《都灵之马》获柏林电影节评审团大奖。\n\n此后他宣布息影，转向电影教育，2024 年获东京国际电影节终身成就奖。2026 年 1 月 6 日凌晨他在长期重病后去世，享年 70 岁。","facts":["《撒旦探戈》片长七个半小时，1994 年首映","2011 年《都灵之马》获柏林电影节评审团大奖","2024 年获东京国际电影节终身成就奖","2025 年任北京国际电影节「注目未来」单元评审团主席"],"obit":null,"portrait":"assets/portraits/2026-01-06-010.webp","source":"Pantheon","verified":"confirmed","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/B%C3%A9la_Tarr"},{"id":"2026-01-06-009","date":"2026-01-06","name":"周立伟","nameOrig":"","country":"中国","region":"中国大陆","age":94,"fields":["科技"],"identity":"中国工程院院士 · 宽束电子光学奠基人、夜视技术专家","summary":"他为国家擦亮了「黑夜之眼」，让中国微光夜视从一片空白走到有自己的学派。","bio":"1932 年 9 月生于上海。1953 年考入北京工业学院（今北京理工大学）仪器系，1958 年毕业留校任教，1962 年赴苏联列宁格勒乌里扬诺夫电工学院，获物理数学副博士学位。\n\n他创建了宽电子束聚焦与成像的理论与技术体系，建立静态与动态成像电子光学及其像差理论，打破国外技术垄断，为中国微光夜视装备奠定基础，专著《宽束电子光学》获三项国家级图书奖。\n\n1999 年当选中国工程院院士，此前已当选俄罗斯圣彼得堡工程科学院外籍院士。2026 年 1 月 6 日 21 时 42 分他在北京逝世，享年 94 岁。","facts":["创建宽电子束聚焦与成像的理论技术体系","专著《宽束电子光学》获三项国家级图书奖","1999 年当选中国工程院院士","曾获全国科学大会奖、国家科技进步奖"],"obit":true,"portrait":"assets/portraits/2026-01-06-009.webp","source":"中国科协已故院士名录","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-01-06-008","date":"2026-01-06","name":"伊迪丝·弗兰尼根","nameOrig":"Edith M. Flanigen","country":"美国","region":"","age":96,"fields":["科技"],"identity":"美国化学家 · 沸石与分子筛的工业化学先驱","summary":"她在实验室里造出人造祖母绿，又顺手改写了石油炼制的底层工艺。","bio":"1929 年 1 月 28 日生于纽约州布法罗，1952 年从锡拉丘兹大学取得硕士后进入联合碳化物公司，1956 年转入分子筛研究组。她在这里合成出人造祖母绿，更重要的成果是沸石——一种按分子大小筛分物质的晶体材料。\n\n她参与发明两百多种材料、持有 109 项专利，其中包括可工业化生产 Zeolite Y 的方法，这种沸石至今仍是石油炼制的支柱。1992 年获珀金奖章，2002 年入选美国发明家名人堂，2014 年从奥巴马手中接过国家技术奖章。\n\n2026 年 1 月 6 日她在布法罗去世，享年 96 岁。","facts":["持有 109 项专利，参与发明逾 200 种材料","开发出 Zeolite Y 的工业化生产方法","2014 年获美国国家技术奖章，2002 年入选发明家名人堂"],"obit":null,"portrait":null,"source":"Pantheon","verified":"corrected","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Edith_M._Flanigen"},{"id":"2026-01-05-007","date":"2026-01-05","name":"奥尔德里奇·艾姆斯","nameOrig":"Aldrich Ames","country":"美国","region":"","age":84,"fields":["军政"],"identity":"前中情局反情报官员 · 冷战末期最致命的双面间谍","summary":"为了钱，他把十名线人的名字交给克格勃，那些人是被从后脑开枪处决的。","bio":"1941 年 5 月 26 日生于威斯康星州里弗福尔斯。他在中情局干了 31 年，1969 年起接手苏联方向的情报工作，最终成为反情报组苏联分部负责人。\n\n1985 年他被克格勃策反，此后九年向苏联和俄罗斯出售机密，交出三十多名英美线人的身份，其中至少十人被处决。他从中获得超过 250 万美元，买下现金支付的房子和捷豹，薪水与开销的落差最终引来调查。\n\n1994 年 2 月他被捕，同年认罪，被判终身监禁不得假释，时任中情局局长伍尔西因这起案子辞职。2026 年 1 月 5 日他死于马里兰州坎伯兰的联邦惩教所，享年 84 岁。","facts":["1985 至 1994 年间向苏联和俄罗斯出售情报","至少 10 名西方线人因他暴露被处决","获酬逾 250 万美元，1994 年认罪被判终身监禁"],"obit":null,"portrait":null,"source":"Pantheon","verified":"confirmed","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":null},{"id":"2026-01-03-006","date":"2026-01-03","name":"迪米塔尔·佩内夫","nameOrig":"Dimitar Penev","country":"保加利亚","region":"","age":80,"fields":["体育"],"identity":"保加利亚足球名宿 · 1994 年世界杯四强主帅","summary":"1993 年 11 月 17 日，巴黎王子公园，他的球队在最后一分钟把法国队踢出了世界杯。","bio":"1945 年 7 月 12 日生于保加利亚米罗维亚内村。球员时代踢中后卫，1964 年转投中央陆军，此后十三年出场 329 次，七夺联赛冠军。他为国家队出战 90 场，参加三届世界杯，两度当选保加利亚足球先生。\n\n退役后执教，1989 年首次接手国家队。1993 年 11 月 17 日，保加利亚在巴黎 2 比 1 逆转法国，把对手挡在美国世界杯门外；次年他率队打进四强，最终获第四名，这是保加利亚足球史上最好成绩。\n\n2003 年他曾短期执教中国甲 A 的辽宁队。2026 年 1 月 3 日他在长期患病后去世，享年 80 岁。","facts":["球员时代为中央陆军出场 329 次，七夺联赛冠军","国家队 90 场出战，参加三届世界杯","1994 年率保加利亚获世界杯第四名","2003 年短暂执教辽宁队，一胜四负后下课"],"obit":null,"portrait":"assets/portraits/2026-01-03-006.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Dimitar_Penev"},{"id":"2026-01-03-005","date":"2026-01-03","name":"伊娃·施洛斯","nameOrig":"Eva Schloss","country":"奥地利","region":"","age":96,"fields":["文艺"],"identity":"大屠杀幸存者、作家 · 安妮·弗兰克的继姐妹","summary":"她在奥斯维辛活了下来，沉默四十年后，开始替安妮·弗兰克把话讲完。","bio":"1929 年 5 月 11 日生于维也纳。1938 年奥地利被纳粹吞并后，一家人辗转逃到阿姆斯特丹，住在默弗德广场，与弗兰克家隔街相望，她和安妮·弗兰克同岁，常一起玩。\n\n1942 年全家转入地下，1944 年 5 月被出卖，押往奥斯维辛-比克瑙，父亲和哥哥没能活下来。战后她与母亲回到阿姆斯特丹，母亲后来嫁给安妮的父亲奥托·弗兰克，她因此成了安妮的继姐妹。\n\n此后四十年她不谈这段经历，直到 1980 年代才开始写作和演讲，出版《伊娃的故事》等回忆录，1990 年参与创办英国安妮·弗兰克信托。2026 年 1 月 3 日她在伦敦一家护理院去世，享年 96 岁。","facts":["1944 年被押往奥斯维辛-比克瑙，父亲与哥哥遇难","母亲战后改嫁奥托·弗兰克，她成为安妮的继姐妹","1990 年参与创办英国安妮·弗兰克信托"],"obit":null,"portrait":"assets/portraits/2026-01-03-005.webp","source":"Pantheon","verified":"corrected","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Eva_Schloss"},{"id":"2026-01-01-004","date":"2026-01-01","name":"赫西·莱文森·塔夫脱","nameOrig":"Hessy Levinsons Taft","country":"德国","region":"","age":91,"fields":["科技"],"identity":"化学教授 · 幼时被纳粹选作「理想雅利安婴儿」的犹太女孩","summary":"1935 年，戈培尔亲手挑中她的照片当「完美雅利安婴儿」，而她是犹太人。","bio":"1934 年 5 月 17 日生于柏林，父母是从拉脱维亚来的犹太歌剧演员。六个月大时父母带她去摄影师汉斯·巴林处拍照，巴林瞒着他们把照片送去纳粹宣传部门主办的「最美丽的雅利安婴儿」评选。\n\n照片被宣传部长戈培尔选中，登上《Sonne ins Haus》封面，又印成明信片在德国各地流传。一家人后来迁居美国，她在巴纳德学院读本科、在哥伦比亚大学取得化学博士，长期在圣约翰大学教化学。\n\n2014 年她公开讲述这张照片，说这是对纳粹种族学最漂亮的一次反驳。2026 年 1 月 1 日她在旧金山家中去世，享年 91 岁。","facts":["六个月大的照片被戈培尔选为「理想雅利安婴儿」","照片登上纳粹杂志 1935 年 1 月号封面并印成明信片","哥伦比亚大学化学博士，长年任圣约翰大学化学教授"],"obit":null,"portrait":null,"source":"Pantheon","verified":"confirmed","portraitStatus":"no-source","causeOfDeath":null,"wikipedia":"https://en.wikipedia.org/wiki/Hessy_Levinsons_Taft"},{"id":"2026-01-01-003","date":"2026-01-01","name":"袁祥仁","nameOrig":"","country":"中国","region":"香港","age":69,"fields":["影视"],"identity":"香港演员、武术指导 · 「袁家班」核心成员","summary":"十块钱一本《如来神掌》，他把港片最后一点江湖气卖给了周星驰。","bio":"1957 年生于香港的武术世家，父亲袁小田是中国电影史上第一位武术指导，兄长是袁和平。1960 年代末他以助理武术指导身份入行，参与张彻《报仇》《游侠儿》的动作设计。\n\n1970 年代末他与袁和平创办和平电影公司，「袁家班」由此成形。1991 年他担任《黄飞鸿》武术指导，拿下第 11 届香港电影金像奖最佳动作指导。\n\n台前他专演乞丐、酒鬼和反串老太太：《武状元苏乞儿》里传「睡梦罗汉拳」的洪日庆，《功夫》里向阿星推销《如来神掌》的乞丐。2026 年 1 月 1 日他因病在香港伊利沙伯医院去世，享年 69 岁。","facts":["1991 年凭《黄飞鸿》获第 11 届香港电影金像奖最佳动作指导","《功夫》中向周星驰推销《如来神掌》的乞丐","1998 年央视版《水浒传》的动作设计之一","遗作《红嫁衣》2025 年上映，拍摄时已坐轮椅"],"obit":true,"portrait":"assets/portraits/2026-01-01-003.webp","source":"维基百科逝世人物列表","verified":"confirmed","causeOfDeath":null,"wikipedia":null},{"id":"2026-01-01-001","date":"2026-01-01","name":"科林·麦克唐纳","nameOrig":"Colin McDonald","country":"英国","region":"","age":95,"fields":["体育"],"identity":"英格兰足球运动员 · 伯恩利与英格兰队 1958 年世界杯门将","summary":"1958 年世界杯上他打满英格兰四场，其中一场零封了最终的冠军巴西。","bio":"1930 年 10 月生于兰开夏郡贝里，1948 年以业余身份加盟伯恩利，1954 年 4 月才踢上一线队首秀，此后七年是球队的绝对一号，共为伯恩利出场 201 次。\n\n1958 年瑞典世界杯他打满英格兰四场，对巴西一役零封，赛后与哈里·格雷格同被评为赛事最佳门将，当年金球奖列第 11。他一生只有 8 顶国家队鸭舌帽，1959 年一次腿伤终结了球员生涯。\n\n2026 年 1 月 1 日他在贝里去世，享年 95 岁，生前是英格兰队最年长的在世国脚。","facts":["1958 年世界杯打满英格兰四场比赛，对巴西零封","伯恩利生涯出场 201 次，被视为队史最佳门将","1958 年金球奖评选第 11 名，共获 8 顶国家队鸭舌帽"],"obit":null,"portrait":null,"source":"Pantheon","verified":"confirmed","portraitStatus":"no-source","causeOfDeath":null}];
